window.BraidData.sources["BraidKit"] = {"module":"BraidKit","files":[{"path":"Sources/BraidKit/BraidKit.swift","lines":13,"bytes":323,"header":{"lines":[1,10],"what":[8,9],"pin":null,"in":null,"out":null},"marks":[],"first":1015,"scopes":[],"text":"//\n//  BraidKit.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The library's front door: re-exports the records (BraidCore) and the AII lanes\n//        (BraidThread) so a consumer imports BraidKit alone.\n//\n\n@_exported import BraidCore\n@_exported import BraidThread\n"},{"path":"Sources/BraidKit/Build/Corpus/CorpusSources.swift","lines":118,"bytes":7192,"header":{"lines":[1,15],"what":[8,14],"pin":null,"in":null,"out":null},"marks":[],"first":1015,"scopes":[["E","CorpusSourceSpec",null,"public",21,21,[21,50],52,null,-1,0,["dataset","directory","lane","app"]],["i","init",["parsing"],"public",28,28,[28,45],42,null,0,0],["v","description",null,"public",44,44,[44,35],51,null,0,0],["S","SourceRead",null,"public",57,57,[57,35],62,[54,56],-1,0],["E","CorpusSources",null,"public",64,64,[64,26],118,null,-1,0,[]],["f","read",["_","slug","limit","datasetsRoot","demoRoot"],"public static",68,68,[68,137],86,[65,67],4,0],["f","snapshot",["dataset","node","limit","datasetsRoot"],"public static",89,89,[89,151],97,[88,88],4,0],["f","snapshot",["directory","slug"],"public static",100,100,[100,87],117,[99,99],4,0]],"text":"//\n//  CorpusSources.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Where a Thread's documents come from, as `braid thread create --corpus` names them:\n//        `dataset:<name or path>#<node>` (one node of a braid dataset on the T9, in feeding order,\n//        optionally the first N), `dir:<path>` (a folder of .txt files, one document each, paragraphs\n//        as partitions), `aii:<aii>/<lane>` (Braid's corpus deposited in a lane, exported through\n//        BraidThread) and `app:<aii>/<app>` (the records an app filed in its own lane with\n//        AIIInstance.remember). Each becomes a CorpusSnapshot; `read` is the one dispatch every\n//        caller goes through.\n//\n\nimport BraidCore\nimport BraidThread\nimport Foundation\n\npublic enum CorpusSourceSpec: Equatable, Sendable {\n    case dataset(nameOrPath: String, node: String)\n    case directory(URL)\n    case lane(String)\n    /// The records an app filed in its own lane: `home/notes`.\n    case app(String)\n\n    public init(parsing text: String) throws {\n        if text.hasPrefix(\"dataset:\") {\n            let body = String(text.dropFirst(8))\n            guard let hash = body.lastIndex(of: \"#\") else { throw BraidFailure.usage(\"dataset sources name a node: dataset:<name>#<node>\") }\n            self = .dataset(nameOrPath: String(body[..<hash]), node: String(body[body.index(after: hash)...]))\n        } else if text.hasPrefix(\"dir:\") {\n            self = .directory(URL(fileURLWithPath: (String(text.dropFirst(4)) as NSString).expandingTildeInPath, isDirectory: true))\n        } else if text.hasPrefix(\"aii:\") {\n            self = .lane(String(text.dropFirst(4)))\n        } else if text.hasPrefix(LaneCorpus.appPrefix) {\n            self = .app(String(text.dropFirst(LaneCorpus.appPrefix.count)))\n        } else {\n            throw BraidFailure.usage(\"unknown corpus source \\(text)\", hint: \"use dataset:<name>#<node>, dir:<path>, aii:<aii>/<lane> or app:<aii>/<app>\")\n        }\n    }\n\n    public var description: String {\n        switch self {\n        case .dataset(let name, let node): return \"dataset:\\(name)#\\(node)\"\n        case .directory(let url): return \"dir:\\(url.path)\"\n        case .lane(let lane): return \"aii:\\(lane)\"\n        case .app(let app): return LaneCorpus.appPrefix + app\n        }\n    }\n}\n\n/// A source as read: its snapshot, the dataset's facts (none for a folder or a lane), the lane a\n/// Thread records when the source is one (`home/veil`, or `app:home/notes` for an app's records),\n/// and why a Thread can't be made when a lane source turns out empty.\npublic struct SourceRead: Sendable {\n    public var snapshot: CorpusSnapshot\n    public var facts: [Fact]\n    public var lane: String?\n    public var whenEmpty: BraidFailure? = nil\n}\n\npublic enum CorpusSources {\n    /// Any source: a dataset node (its first `limit` documents in feeding order), a folder (its\n    /// documents named under `slug`), Braid's corpus in a lane, or an app's records in its lane,\n    /// exported from their AII.\n    public static func read(_ spec: CorpusSourceSpec, slug: String, limit: Int?, datasetsRoot: URL?, demoRoot: URL) throws -> SourceRead {\n        switch spec {\n        case .dataset(let nameOrPath, let node):\n            let (made, generated) = try snapshot(dataset: nameOrPath, node: node, limit: limit, datasetsRoot: datasetsRoot)\n            return SourceRead(snapshot: made, facts: generated.facts, lane: nil)\n        case .directory(let url):\n            return SourceRead(snapshot: try snapshot(directory: url, slug: slug), facts: [], lane: nil)\n        case .lane(let text):\n            guard let address = LaneAddress(parsing: text) else { throw BraidFailure.usage(\"lane addresses are <aii>/<lane>: home or a demo AII, and a lane registered on it\") }\n            return SourceRead(snapshot: try LaneSource.snapshot(address: address, demoRoot: demoRoot), facts: [], lane: LaneCorpus.braid(address).description,\n                              whenEmpty: LaneSource.emptyRefusal(.braid(address)))\n        case .app(let text):\n            guard let address = LaneAddress(parsing: text) else {\n                throw BraidFailure.usage(\"app sources are app:<aii>/<app>: home or a demo AII, and an app registered on it (app:home/notes)\")\n            }\n            return SourceRead(snapshot: try LaneSource.records(app: address, demoRoot: demoRoot), facts: [], lane: LaneCorpus.app(address).description,\n                              whenEmpty: LaneSource.emptyRefusal(.app(address)))\n        }\n    }\n\n    /// A dataset node's corpus as a snapshot: the first `limit` documents in feeding order.\n    public static func snapshot(dataset nameOrPath: String, node: String, limit: Int?, datasetsRoot: URL?) throws -> (CorpusSnapshot, GeneratedCorpus) {\n        let directory = try DatasetsRoot.locate(nameOrPath, root: datasetsRoot)\n        let dataset = try BraidDataset.load(directory)\n        var corpus = try dataset.corpus(node: node)\n        if let limit { corpus.documents = Array(corpus.documents.prefix(limit)) }\n        let name = directory.lastPathComponent\n        let snapshot = CorpusSnapshot.offline(corpus, source: \"dataset:\\(name)#\\(node)\", owner: \"braid\", group: \"braid-\\(node)\") { _ in 0 }\n        return (snapshot, corpus)\n    }\n\n    /// A folder of .txt files: one document each, blank-line paragraphs as partitions.\n    public static func snapshot(directory: URL, slug: String) throws -> CorpusSnapshot {\n        let files = try FileManager.default.contentsOfDirectory(at: directory, includingPropertiesForKeys: [.creationDateKey])\n            .filter { $0.pathExtension == \"txt\" && !$0.lastPathComponent.hasPrefix(\"._\") }.sorted { $0.lastPathComponent < $1.lastPathComponent }\n        guard !files.isEmpty else { throw BraidFailure.missing(\"no .txt files in \\(directory.path)\") }\n        var documents: [SnapshotDocument] = []\n        for file in files {\n            let text = try String(contentsOf: file, encoding: .utf8)\n            let canonical = ContentHash.canonical(text)\n            let paragraphs = canonical.components(separatedBy: \"\\n\\n\").map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty }\n            guard !paragraphs.isEmpty else { continue }\n            let id = DocumentID.make(slug: slug, canonicalText: canonical)\n            let created = (try? file.resourceValues(forKeys: [.creationDateKey]))?.creationDate.map { Int64($0.timeIntervalSince1970 * 1000) } ?? 0\n            documents.append(SnapshotDocument(id: id, name: file.deletingPathExtension().lastPathComponent, ownerID: \"braid\", groupID: \"braid-\\(slug)\", groupLabel: \"Braid · \\(slug)\",\n                                              createdAt: created, mediaType: \"text\",\n                                              partitions: paragraphs.enumerated().map { SnapshotPartition(index: $0.offset, text: $0.element, url: DocumentID.partitionURL(aii: \"dir\", lane: slug, documentID: id, index: $0.offset)) }))\n        }\n        return CorpusSnapshot(documents: documents, slug: slug, source: \"dir:\\(directory.path)\", threadID: nil, owner: \"braid\", group: \"braid-\\(slug)\", documentIDPrefix: DocumentID.prefix(slug: slug))\n    }\n}\n"},{"path":"Sources/BraidKit/Build/Corpus/FactLocator.swift","lines":53,"bytes":2407,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":1023,"scopes":[["S","LocatedFact",null,"public",17,17,[17,36],27,[16,16],-1,0],["v","answerLength",null,"public",26,26,[26,33],26,null,0,8],["E","FactLocator",null,"public",29,29,[29,24],53,null,-1,0,[]],["f","locate",["_","corpus","byteOffsets"],"public static",32,32,[32,154],52,[30,31],2,0]],"text":"//\n//  FactLocator.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A dataset's facts placed on the tokenized corpus: each fact's byte offsets mapped onto its\n//        partition's own tokens (the answer's first and last token, and where its context\n//        sentence starts). Training scores facts through it; benches build prompts from it.\n//\n\nimport BraidCore\nimport Foundation\n\n/// A fact placed on its partition's own tokenization.\npublic struct LocatedFact: Sendable {\n    public var fact: Fact\n    public var row: Int\n    /// First token of the sentence before the fact's sentence (or of the fact's sentence).\n    public var contextToken: Int\n    /// First answer token (the prompt ends just before it), and one past the last.\n    public var answerToken: Int\n    public var answerEndToken: Int\n\n    public var answerLength: Int { answerEndToken - answerToken }\n}\n\npublic enum FactLocator {\n    /// Maps each fact's byte offsets onto its partition's own tokenization. Facts whose answer does\n    /// not start on a token boundary come back in `unaligned`.\n    public static func locate(_ facts: [Fact], corpus: TokenizedCorpus, byteOffsets: ([Int32]) -> [Int]) -> (located: [LocatedFact], unaligned: [String]) {\n        var located: [LocatedFact] = []\n        var unaligned: [String] = []\n        var cache: [Int: [Int]] = [:]\n        for fact in facts {\n            guard let row = corpus.row(documentID: fact.documentID, partitionIndex: fact.partitionIndex) else { continue }\n            let offsets: [Int]\n            if let cached = cache[row] { offsets = cached } else {\n                offsets = byteOffsets(corpus.partitions[row].tokens)\n                cache[row] = offsets\n            }\n            guard let answerToken = offsets.firstIndex(of: fact.answerStart), let answerEnd = offsets.firstIndex(of: fact.answerEnd), answerEnd > answerToken, answerToken > 0 else {\n                unaligned.append(fact.id)\n                continue\n            }\n            let contextByte = max(fact.contextStart - 1, 0)\n            let contextToken = fact.contextStart == 0 ? 0 : (offsets.lastIndex { $0 <= contextByte } ?? 0)\n            located.append(LocatedFact(fact: fact, row: row, contextToken: min(contextToken, answerToken - 1), answerToken: answerToken, answerEndToken: answerEnd))\n        }\n        return (located, unaligned)\n    }\n}\n"},{"path":"Sources/BraidKit/Build/Corpus/SnapshotDiff.swift","lines":30,"bytes":1417,"header":{"lines":[1,10],"what":[8,9],"pin":null,"in":null,"out":null},"marks":[],"first":1027,"scopes":[["S","SnapshotDiff",null,"public",16,16,[16,48],30,[15,15],-1,0],["v","isEmpty",null,"public",20,20,[20,29],20,null,0,8],["v","summary",null,"public",21,21,[21,31],21,null,0,8],["i","init",["from","to"],"public",23,23,[23,66],29,null,0,0]],"text":"//\n//  SnapshotDiff.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: What changed between two snapshots of a Thread's source, by document id and the text\n//        hashes of its partitions: the line `braid thread sync` prints when a source moved.\n//\n\nimport BraidCore\nimport Foundation\n\n/// What changed between two snapshots, by document id and partition text hash.\npublic struct SnapshotDiff: Sendable, Equatable {\n    public var added: [String] = []\n    public var removed: [String] = []\n    public var changed: [String] = []\n    public var isEmpty: Bool { added.isEmpty && removed.isEmpty && changed.isEmpty }\n    public var summary: String { \"\\(added.count) added, \\(removed.count) removed, \\(changed.count) changed\" }\n\n    public init(from old: CorpusSnapshot, to new: CorpusSnapshot) {\n        let before = Dictionary(old.documents.map { ($0.id, $0.partitions.sorted { $0.index < $1.index }.map(\\.textSHA256)) }, uniquingKeysWith: { first, _ in first })\n        let after = Dictionary(new.documents.map { ($0.id, $0.partitions.sorted { $0.index < $1.index }.map(\\.textSHA256)) }, uniquingKeysWith: { first, _ in first })\n        added = after.keys.filter { before[$0] == nil }.sorted()\n        removed = before.keys.filter { after[$0] == nil }.sorted()\n        changed = after.keys.filter { before[$0] != nil && before[$0] != after[$0] }.sorted()\n    }\n}\n"},{"path":"Sources/BraidKit/Build/Corpus/TokenizedCorpus.swift","lines":92,"bytes":4257,"header":{"lines":[1,13],"what":[8,12],"pin":null,"in":null,"out":null},"marks":[],"first":1031,"scopes":[["S","TokenizedPartition",null,"public",18,18,[18,43],22,null,-1,0],["S","TokenizedDocument",null,"public",24,24,[24,42],32,null,-1,0],["S","TokenizedCorpus",null,"public",34,34,[34,40],92,null,-1,0],["v","partitionRefs",null,"public",41,41,[41,45],41,null,2,8],["v","breakLength",null,"public",42,42,[42,32],42,null,2,8],["v","tokenCount",null,"public",43,43,[43,31],43,null,2,8],["i","init",["snapshot","tokenizer","paragraphBreak","threadID"],"public",46,46,[46,113],85,[45,45],2,0],["f","row",["documentID","partitionIndex"],"public",87,87,[87,69],89,null,2,0],["f","document",["ofRow"],"public",91,91,[91,63],91,null,2,8]],"text":"//\n//  TokenizedCorpus.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A snapshot tokenized the way the index and training read it: each partition on its own\n//        (so a token offset can be recomputed from the partition's text alone), a document as\n//        `eos ‖ p0 ‖ break ‖ p1 ‖ … ‖ eos`, and every stream position addressed by (row, offset).\n//        Break tokens are addressed to the preceding partition at offsets tokenCount and above, so\n//        chains run across them and nothing is ever cited to one.\n//\n\nimport BraidCore\nimport Foundation\n\npublic struct TokenizedPartition: Sendable {\n    public var row: Int\n    public var ref: PartitionRef\n    public var tokens: [Int32]\n}\n\npublic struct TokenizedDocument: Sendable {\n    public var documentID: String\n    /// The partition rows in order.\n    public var rows: [Int]\n    /// eos ‖ p0 ‖ break ‖ p1 ‖ … ‖ eos.\n    public var tokens: [Int32]\n    /// Per stream position: the (row, offset) address; eos positions have row −1.\n    public var addresses: [TokenPosition]\n}\n\npublic struct TokenizedCorpus: Sendable {\n    public var partitions: [TokenizedPartition]\n    public var documents: [TokenizedDocument]\n    public var eos: Int32\n    public var paragraphBreak: [Int32]\n    public var sharedNgrams: Set<UInt64>\n\n    public var partitionRefs: [PartitionRef] { partitions.map(\\.ref) }\n    public var breakLength: Int { paragraphBreak.count }\n    public var tokenCount: Int { documents.reduce(0) { $0 + $1.tokens.count } }\n\n    /// Tokenizes every partition of the snapshot; documents in the snapshot's (sorted) order.\n    public init(snapshot: CorpusSnapshot, tokenizer: any Tokenizing, paragraphBreak: [Int32], threadID: String?) {\n        eos = tokenizer.eos\n        self.paragraphBreak = paragraphBreak\n        var partitions: [TokenizedPartition] = []\n        var documents: [TokenizedDocument] = []\n        var ngramCounts: [UInt64: Set<String>] = [:]\n        for document in snapshot.documents {\n            var rows: [Int] = []\n            var tokens: [Int32] = [eos]\n            var addresses: [TokenPosition] = [TokenPosition(row: -1, offset: 0)]\n            let ordered = document.partitions.sorted { $0.index < $1.index }\n            for (n, partition) in ordered.enumerated() {\n                let row = partitions.count\n                let ids = tokenizer.encode(partition.text)\n                let ref = PartitionRef(row: row, documentID: document.id, documentName: document.name, partitionIndex: partition.index, partitionURL: partition.url,\n                                       textSHA256: partition.textSHA256, tokenCount: ids.count, threadID: threadID, createdAt: document.createdAt == 0 ? nil : document.createdAt)\n                partitions.append(TokenizedPartition(row: row, ref: ref, tokens: ids))\n                rows.append(row)\n                for (i, id) in ids.enumerated() {\n                    tokens.append(id)\n                    addresses.append(TokenPosition(row: row, offset: i))\n                }\n                if n < ordered.count - 1 {\n                    for (j, id) in paragraphBreak.enumerated() {\n                        tokens.append(id)\n                        addresses.append(TokenPosition(row: row, offset: ids.count + j))\n                    }\n                }\n                if ids.count >= 3 {\n                    for i in 0...(ids.count - 3) { ngramCounts[Spans.ngramKey(ids[i], ids[i + 1], ids[i + 2]), default: []].insert(document.id) }\n                }\n            }\n            tokens.append(eos)\n            addresses.append(TokenPosition(row: -1, offset: 0))\n            documents.append(TokenizedDocument(documentID: document.id, rows: rows, tokens: tokens, addresses: addresses))\n        }\n        self.partitions = partitions\n        self.documents = documents\n        sharedNgrams = Set(ngramCounts.filter { $0.value.count >= 2 }.keys)\n    }\n\n    public func row(documentID: String, partitionIndex: Int) -> Int? {\n        partitions.first { $0.ref.documentID == documentID && $0.ref.partitionIndex == partitionIndex }?.row\n    }\n\n    public func document(ofRow row: Int) -> TokenizedDocument? { documents.first { $0.rows.contains(row) } }\n}\n"},{"path":"Sources/BraidKit/Build/Index/Checkpoints.swift","lines":56,"bytes":2584,"header":{"lines":[1,16],"what":[8,10],"pin":[11,15],"in":null,"out":null},"marks":[],"first":1040,"scopes":[["S","CheckpointPolicy",null,"public",21,21,[21,61],26,null,-1,0],["i","init",[],"public",25,25,[25,18],25,null,0,8],["S","CheckpointRef",null,"public",28,28,[28,58],35,null,-1,0],["X","CheckpointRef",null,"",37,37,[37,24],49,null,-1,0],["f","fileName",["documentID","position"],"public static",39,39,[39,77],45,[38,38],3,0],["S","CheckpointManifest",null,"public",51,51,[51,63],56,null,-1,0]],"text":"//\n//  Checkpoints.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The state checkpoints an index carries: the policy that places them (a partition boundary\n//        once 1,024 tokens have passed, or every partition), each checkpoint's record (document,\n//        position, file, hash, the prefix it is bound to), and checkpoints.json, the manifest.\n//  PIN:  A checkpoint's file name is its document id and position when the id is plain (letters,\n//        digits, `.`, `_`, `-`: every dataset, folder and Braid lane id, so those names never\n//        change). Any other id, such as an app's record id `<app>/<kind>/<id>`, which may hold `/`,\n//        `:` or capitals, is folded into one safe path component with its hash beside it, so ids\n//        that differ only in case or punctuation stay apart on a case-insensitive volume.\n//\n\nimport BraidCore\nimport Foundation\n\npublic struct CheckpointPolicy: Codable, Sendable, Equatable {\n    /// A checkpoint is written at a partition boundary once this many tokens have passed since the last one in the document.\n    public var strideTokens = 1024\n    public var everyPartition = false\n    public init() {}\n}\n\npublic struct CheckpointRef: Codable, Sendable, Equatable {\n    public var documentID: String\n    /// The stream position (in the document's eos-opened sequence) of the last token consumed.\n    public var position: Int\n    public var file: String\n    public var sha256: String\n    public var prefixSHA256: String\n}\n\nextension CheckpointRef {\n    /// The file a checkpoint is saved as, in the index's checkpoints/ folder.\n    public static func fileName(documentID: String, position: Int) -> String {\n        if !documentID.isEmpty, documentID.unicodeScalars.allSatisfy({ plain.contains($0) }) {\n            return \"\\(documentID)-\\(position).safetensors\"\n        }\n        let folded = String(String.UnicodeScalarView(documentID.lowercased().unicodeScalars.prefix(64).map { folding.contains($0) ? $0 : \"_\" }))\n        return \"\\(folded)~\\(ContentHash.sha256Hex(Data(documentID.utf8)).prefix(24))-\\(position).safetensors\"\n    }\n\n    private static let plain = CharacterSet(charactersIn: \"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-\")\n    private static let folding = CharacterSet(charactersIn: \"abcdefghijklmnopqrstuvwxyz0123456789._-\")\n}\n\npublic struct CheckpointManifest: Codable, Sendable, Equatable {\n    public var version = 1\n    public var policy: CheckpointPolicy\n    public var checkpoints: [CheckpointRef]\n    public var totalBytes: Int\n}\n"},{"path":"Sources/BraidKit/Build/Index/DocumentEntries.swift","lines":99,"bytes":4681,"header":{"lines":[1,15],"what":[8,12],"pin":[13,14],"in":null,"out":null},"marks":[],"first":1046,"scopes":[["S","DocumentEntries",null,"",21,21,[21,23],65,null,-1,0],["f","record",["_","of","keys","loss","entropy","eos","indexed"],"mutating",33,33,[33,162],46,[31,32],0,0],["f","score",["loss","entropy"],"private mutating",49,49,[49,61],52,[48,48],0,0],["f","addEntry",["_","at","of","loss","entropy"],"private mutating",56,56,[56,123],64,[54,55],0,0],["X","DocumentEntries",null,"",67,67,[67,26],88,null,-1,0],["S","Eval",null,"",70,70,[70,16],87,[68,69],4,0],["i","init",["_"],"",75,75,[75,45],81,null,5,0],["f","mean",["_"],"private static",84,84,[84,61],86,[83,83],5,0],["X","IndexFiles.Arrays",null,"",90,90,[90,28],99,null,-1,0],["i","init",["joining","keyDims"],"",92,92,[92,61],98,[91,91],8,0]],"text":"//\n//  DocumentEntries.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: What one document adds to a provenance index, segment by segment: its entries (the key,\n//        the value that follows, both addresses, the eval loss and the predictive entropy), the\n//        loss and entropy at every position it scores, and the checkpoints saved along it. The\n//        index's arrays are the documents' entries joined in corpus order; its eval is the mean\n//        over every scored position.\n//  PIN:  Positions whose input is eos are not keys; transitions whose value is eos are not entries.\n//        Entries are in corpus order, contiguous per document, so the tracker's successor is e+1.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\n\nstruct DocumentEntries {\n    /// The kept rows of each segment's keys ([kept, K] each).\n    var keys: [MLXArray] = []\n    var values: [Int32] = [], keyRow: [Int32] = [], keyOffset: [Int32] = [], valueRow: [Int32] = [], valueOffset: [Int32] = []\n    /// The loss and entropy at each entry.\n    var losses: [Float] = [], entropies: [Float] = []\n    /// The loss and entropy at every position whose input is not eos, entry or not: the eval.\n    var scoredLoss: [Float] = [], scoredEntropy: [Float] = []\n    var checkpoints: [CheckpointRef] = []\n\n    /// One segment's positions, keyed and scored. Every position whose input is not eos is scored;\n    /// those whose value is not eos either become entries, unless the document is withheld.\n    mutating func record(_ segment: ClosedRange<Int>, of document: TokenizedDocument, keys: MLXArray, loss: [Float], entropy: [Float], eos: Int32, indexed: Bool) {\n        let tokens = document.tokens\n        var keep: [Int32] = []\n        for (i, t) in segment.enumerated() {\n            let input = tokens[t]\n            guard t + 1 < tokens.count else { continue }\n            let value = tokens[t + 1]\n            if input != eos { score(loss: loss[i], entropy: entropy[i]) }\n            guard input != eos, value != eos, indexed else { continue }\n            keep.append(Int32(i))\n            addEntry(value, at: t, of: document, loss: loss[i], entropy: entropy[i])\n        }\n        if !keep.isEmpty { self.keys.append(keys[MLXArray(keep)]) }\n    }\n\n    /// A scored position: it counts toward the eval whether or not it becomes an entry.\n    private mutating func score(loss: Float, entropy: Float) {\n        scoredLoss.append(loss)\n        scoredEntropy.append(entropy)\n    }\n\n    /// An entry: the value after position `t`, where `t` and `t + 1` sit in the corpus, and the\n    /// loss and entropy there.\n    private mutating func addEntry(_ value: Int32, at t: Int, of document: TokenizedDocument, loss: Float, entropy: Float) {\n        values.append(value)\n        keyRow.append(Int32(document.addresses[t].row))\n        keyOffset.append(Int32(document.addresses[t].offset))\n        valueRow.append(Int32(document.addresses[t + 1].row))\n        valueOffset.append(Int32(document.addresses[t + 1].offset))\n        losses.append(loss)\n        entropies.append(entropy)\n    }\n}\n\nextension DocumentEntries {\n    /// The index's eval over every scored position, in corpus order: the mean loss, the mean\n    /// entropy, and the fraction memorised (under 0.1 nat).\n    struct Eval {\n        var loss: Float = 0\n        var entropy: Float = 0\n        var memorised: Float = 0\n\n        init(_ documents: [DocumentEntries]) {\n            let losses = documents.flatMap(\\.scoredLoss)\n            guard !losses.isEmpty else { return }\n            loss = Self.mean(losses)\n            entropy = Self.mean(documents.flatMap(\\.scoredEntropy))\n            memorised = Float(losses.filter { $0 < 0.1 }.count) / Float(losses.count)\n        }\n\n        /// Summed in f64 in stream order, one position at a time.\n        private static func mean(_ values: [Float]) -> Float {\n            Float(values.reduce(0.0) { $0 + Double($1) } / Double(values.count))\n        }\n    }\n}\n\nextension IndexFiles.Arrays {\n    /// The documents' entries joined in corpus order: the arrays index.safetensors holds.\n    init(joining documents: [DocumentEntries], keyDims: Int) {\n        let pieces = documents.flatMap(\\.keys)\n        let keys = pieces.isEmpty ? MLXArray.zeros([0, keyDims]) : concatenated(pieces, axis: 0)\n        eval(keys)\n        self.init(keys: keys, values: documents.flatMap(\\.values), keyRow: documents.flatMap(\\.keyRow), keyOffset: documents.flatMap(\\.keyOffset),\n                  valueRow: documents.flatMap(\\.valueRow), valueOffset: documents.flatMap(\\.valueOffset), loss: documents.flatMap(\\.losses), entropy: documents.flatMap(\\.entropies))\n    }\n}\n"},{"path":"Sources/BraidKit/Build/Index/DocumentSegments.swift","lines":59,"bytes":2380,"header":{"lines":[1,12],"what":[8,10],"pin":[11,11],"in":null,"out":null},"marks":[],"first":1056,"scopes":[["S","DocumentSegments",null,"",17,17,[17,24],59,null,-1,0],["i","init",["_","corpus","policy"],"",21,21,[21,91],28,null,0,0],["f","partitionEnds",["of","corpus"],"private static",31,31,[31,104],40,[30,30],0,0],["f","segmentEnds",["at","policy"],"private static",45,45,[45,96],58,[42,44],0,0]],"text":"//\n//  DocumentSegments.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Where one document's state-carrying segments end, before the index builder keys them.\n//        Each segment ends on a partition's last token (before a break or the closing eos), at a\n//        boundary the checkpoint policy picks; the last segment runs to the closing eos.\n//  PIN:  Every segment but the last is followed by a checkpoint of the state after it.\n//\n\nimport BraidCore\nimport Foundation\n\nstruct DocumentSegments {\n    /// Each segment's stream positions, in order, from the opening eos to the closing one.\n    var ranges: [ClosedRange<Int>]\n\n    init(_ document: TokenizedDocument, corpus: TokenizedCorpus, policy: CheckpointPolicy) {\n        let ends = Self.segmentEnds(at: Self.partitionEnds(of: document, corpus: corpus), policy: policy) + [document.tokens.count - 1]\n        var start = 0\n        ranges = ends.map { end in\n            defer { start = end + 1 }\n            return start ... end\n        }\n    }\n\n    /// The last token index of each partition (before a break or the final eos).\n    private static func partitionEnds(of document: TokenizedDocument, corpus: TokenizedCorpus) -> [Int] {\n        var ends: [Int] = []\n        var position = 1\n        for (n, row) in document.rows.enumerated() {\n            position += corpus.partitions[row].tokens.count\n            ends.append(position - 1)\n            if n < document.rows.count - 1 { position += corpus.breakLength }\n        }\n        return ends\n    }\n\n    /// The partition ends that close a segment: every one under `everyPartition`, else the first\n    /// once `strideTokens` have passed since the last. A segment has no length cap; the builder runs\n    /// a long one in pieces (`IndexBuildOptions.pieceTokens`), so its memory does not grow with it.\n    private static func segmentEnds(at partitionEnds: [Int], policy: CheckpointPolicy) -> [Int] {\n        var ends: [Int] = []\n        var start = 0\n        var sinceCheckpoint = 0\n        for boundary in partitionEnds {\n            sinceCheckpoint += boundary - start + 1\n            if policy.everyPartition || sinceCheckpoint >= policy.strideTokens {\n                ends.append(boundary)\n                sinceCheckpoint = 0\n            }\n            start = boundary + 1\n        }\n        return ends\n    }\n}\n"},{"path":"Sources/BraidKit/Build/Index/IndexBuilder.swift","lines":131,"bytes":8922,"header":{"lines":[1,14],"what":[8,13],"pin":null,"in":null,"out":null},"marks":[],"first":1060,"scopes":[["S","IndexBuildOptions",null,"public",20,20,[20,42],30,null,-1,0],["i","init",["scheme"],"public",29,29,[29,35],29,null,0,8],["S","IndexBuildResult",null,"public",32,32,[32,31],37,null,-1,0],["E","IndexBuilder",null,"public",39,39,[39,25],131,null,-1,0,[]],["f","build",["trunk","reed","corpus","pack","blocksSHA256","threadID","options","into","progress"],"public static",41,41,[42,121],59,[40,40],3,0],["f","indexDocument",["_","in","trunk","reed","corpus","pack","options","checkpointDirectory"],"static",64,64,[65,110],83,[61,63],3,0],["f","pieces",["of","tokens"],"private static",86,86,[86,96],88,[85,85],3,0],["f","score",["_","at","of","reed","eos"],"private static",92,92,[92,177],95,[90,91],3,0],["f","nextTokens",["_","of","eos"],"private static",99,99,[99,119],101,[97,98],3,0],["f","saveCheckpoint",["_","after","of","in","pack"],"private static",105,105,[105,168],112,[103,104],3,0],["f","indexInfo",["for","entries","trunk","pack","corpus","options","blocksSHA256","threadID"],"private static",116,116,[117,88],130,[114,115],3,0]],"text":"//\n//  IndexBuilder.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Builds a provenance index: every document whole from a zero state (eos ‖ partitions joined\n//        by the break ‖ eos), in state-carrying segments whose boundaries are the checkpoint\n//        positions (DocumentSegments). Each segment is run through the trunk at most 1,024 tokens at\n//        a time, scored by the reed against the next token, keyed, and recorded (DocumentEntries);\n//        the state after it is saved as a checkpoint. The replay recomputes any key from the\n//        nearest checkpoint.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\n\npublic struct IndexBuildOptions: Sendable {\n    public var scheme: KeyScheme\n    public var alpha: Float = ProvenanceKey.alpha\n    public var checkpoints = CheckpointPolicy()\n    /// The most tokens the trunk runs at once. A longer segment runs in pieces with the state carried\n    /// and no checkpoint between them, so a segment's memory stays near 1 GB however long it is.\n    public var pieceTokens = 1024\n    /// Documents whose entries are left out of the index (the stitched bench's withheld set).\n    public var exclude: Set<String> = []\n    public init(scheme: KeyScheme) { self.scheme = scheme }\n}\n\npublic struct IndexBuildResult {\n    public var directory: URL\n    public var info: IndexInfo\n    public var memorised: Float\n    public var meanLoss: Float\n}\n\npublic enum IndexBuilder {\n    /// Writes the index into `directory`. `blocksSHA256` names the thread weights the trunk holds.\n    public static func build(trunk: Trunk, reed: MLXReed, corpus: TokenizedCorpus, pack: Pack, blocksSHA256: String, threadID: String?, options: IndexBuildOptions,\n                             into directory: URL, progress: (Int, Int) -> Void = { _, _ in }) throws -> IndexBuildResult {\n        let config = trunk.config\n        let checkpointDirectory = directory.appendingPathComponent(IndexFiles.checkpointDirectory, isDirectory: true)\n        var documents: [DocumentEntries] = []\n        for (d, document) in corpus.documents.enumerated() {\n            progress(d, corpus.documents.count)\n            guard document.tokens.count >= 3 else { continue }\n            let segments = DocumentSegments(document, corpus: corpus, policy: options.checkpoints)\n            documents.append(try indexDocument(document, in: segments, trunk: trunk, reed: reed, corpus: corpus, pack: pack, options: options, checkpointDirectory: checkpointDirectory))\n            Memory.clearCache()\n        }\n        let arrays = IndexFiles.Arrays(joining: documents, keyDims: options.scheme.keyDims(config: config))\n        var info = indexInfo(for: documents, entries: arrays.values.count, trunk: trunk, pack: pack, corpus: corpus, options: options, blocksSHA256: blocksSHA256, threadID: threadID)\n        let checkpoints = documents.flatMap(\\.checkpoints)\n        let manifest = CheckpointManifest(policy: options.checkpoints, checkpoints: checkpoints, totalBytes: checkpoints.count * StateStack.byteCount(config: config))\n        try IndexFiles.write(arrays: arrays, info: &info, partitions: corpus.partitionRefs, sharedNgrams: corpus.sharedNgrams, manifest: manifest, to: directory)\n        return IndexBuildResult(directory: directory, info: info, memorised: info.evalMemorisedFraction, meanLoss: info.evalLoss)\n    }\n\n    /// One document keyed from a zero state, segment by segment: each segment run through the trunk\n    /// a piece at a time, each piece scored, keyed and recorded, and the state after the segment\n    /// saved unless it is the document's last.\n    static func indexDocument(_ document: TokenizedDocument, in segments: DocumentSegments, trunk: Trunk, reed: MLXReed, corpus: TokenizedCorpus, pack: Pack,\n                              options: IndexBuildOptions, checkpointDirectory: URL) throws -> DocumentEntries {\n        var entries = DocumentEntries()\n        var state: StateStack? = nil\n        for segment in segments.ranges {\n            for piece in pieces(of: segment, tokens: options.pieceTokens) {\n                let out = SegmentKeys.run(trunk: trunk, segment: Array(document.tokens[piece]), state: state, scheme: options.scheme)\n                let (loss, entropy) = score(out.final, at: piece, of: document, reed: reed, eos: corpus.eos)\n                let keys = ProvenanceKey.make(mid: out.mid, final: out.final, alpha: options.alpha)\n                eval(keys, loss, entropy)\n                entries.record(piece, of: document, keys: keys, loss: loss.asArray(Float.self), entropy: entropy.asArray(Float.self), eos: corpus.eos,\n                               indexed: !options.exclude.contains(document.documentID))\n                state = out.state\n            }\n            if let state, segment.upperBound < document.tokens.count - 1 {\n                entries.checkpoints.append(try saveCheckpoint(state, after: segment.upperBound, of: document, in: checkpointDirectory, pack: pack))\n            }\n        }\n        return entries\n    }\n\n    /// A segment cut into runs of at most `tokens`, in order; one run when the segment is that short.\n    private static func pieces(of segment: ClosedRange<Int>, tokens: Int) -> [ClosedRange<Int>] {\n        stride(from: segment.lowerBound, through: segment.upperBound, by: tokens).map { $0 ... min($0 + tokens - 1, segment.upperBound) }\n    }\n\n    /// How well the Thread already predicts each position's next token: the reed's loss on it and\n    /// the predictive entropy, from the normed final state ([q, D]).\n    private static func score(_ final: MLXArray, at segment: ClosedRange<Int>, of document: TokenizedDocument, reed: MLXReed, eos: Int32) -> (loss: MLXArray, entropy: MLXArray) {\n        let logits = reed.logits(array: final)\n        return MLXReed.tokenStats(logits: logits, targets: MLXArray(nextTokens(segment, of: document, eos: eos)))\n    }\n\n    /// Targets: the token after each position (the first token of the next segment for the last\n    /// position, and eos after the document's closing eos).\n    private static func nextTokens(_ segment: ClosedRange<Int>, of document: TokenizedDocument, eos: Int32) -> [Int32] {\n        segment.map { $0 + 1 < document.tokens.count ? document.tokens[$0 + 1] : eos }\n    }\n\n    /// A checkpoint at a partition boundary: the state after `position`, bound to its prefix, saved\n    /// in the index's checkpoints folder, and its record.\n    private static func saveCheckpoint(_ state: StateStack, after position: Int, of document: TokenizedDocument, in directory: URL, pack: Pack) throws -> CheckpointRef {\n        var stack = state\n        stack.prefixSHA256 = NodeCheckpoint.prefixHash(Array(document.tokens[0...position]))\n        let name = CheckpointRef.fileName(documentID: document.documentID, position: position)\n        try stack.save(to: directory.appendingPathComponent(name), packSHA256: pack.sha256)\n        let sha = try ContentHash.sha256Hex(fileAt: directory.appendingPathComponent(name))\n        return CheckpointRef(documentID: document.documentID, position: position, file: name, sha256: sha, prefixSHA256: stack.prefixSHA256!)\n    }\n\n    /// index.json's record: what the index is bound to (the thread blocks, the pack, its seam,\n    /// vocabulary and tokenizer, the corpus), its eval, and the documents it withholds.\n    private static func indexInfo(for documents: [DocumentEntries], entries: Int, trunk: Trunk, pack: Pack, corpus: TokenizedCorpus, options: IndexBuildOptions,\n                                  blocksSHA256: String, threadID: String?) -> IndexInfo {\n        let config = trunk.config\n        let eval = DocumentEntries.Eval(documents)\n        var info = IndexInfo(keyScheme: options.scheme, alpha: options.alpha, keyDims: options.scheme.keyDims(config: config), count: entries,\n                             documents: corpus.documents.count, partitions: corpus.partitions.count, blocksSHA256: blocksSHA256, packSHA256: pack.sha256,\n                             seamSHA256: trunk.seamSHA256, vocabularySHA256: pack.info.vocabularySHA256, corpusHash: \"\", tokenizerSHA256: pack.info.tokenizerSHA256,\n                             threadID: threadID, evalLoss: eval.loss, evalEntropy: eval.entropy, evalMemorisedFraction: eval.memorised, cut: config.cut,\n                             paragraphBreak: corpus.paragraphBreak, eos: corpus.eos, checkpointsSHA256: \"\", indexSHA256: \"\",\n                             createdAt: Date(timeIntervalSince1970: Date().timeIntervalSince1970.rounded(.down)))\n        info.corpusHash = ContentHash.corpusHash(corpus.partitions.map { ContentHash.CorpusEntry(documentID: $0.ref.documentID, partitionIndex: $0.ref.partitionIndex, textSHA256: $0.ref.textSHA256) })\n        let withheld = Set(corpus.documents.map(\\.documentID)).intersection(options.exclude)\n        info.excluded = withheld.isEmpty ? nil : withheld.sorted()\n        return info\n    }\n}\n"},{"path":"Sources/BraidKit/Build/Index/IndexFiles.swift","lines":94,"bytes":4311,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[],"first":1071,"scopes":[["S","IndexInfo",null,"public",18,18,[18,54],49,null,-1,0],["E","IndexFiles",null,"public",51,51,[51,23],94,null,-1,0,[]],["S","Arrays",null,"public",59,59,[59,25],68,null,1,0],["f","write",["arrays","info","partitions","sharedNgrams","manifest","to"],"public static",70,70,[70,179],84,null,1,0],["f","readNgrams",["_"],"public static",86,86,[86,68],93,null,1,0]],"text":"//\n//  IndexFiles.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: What an index is on disk: index.safetensors (keys f16, values and addresses i32, loss and\n//        entropy f32), index.json (the record binding it to the weights, the corpus, the tokenizer\n//        and the pack), partitions.json, shared-ngrams.bin, and checkpoints.json with the state\n//        checkpoints the replay starts from.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\n\npublic struct IndexInfo: Codable, Sendable, Equatable {\n    public var version = 1\n    public var format = \"braid-provenance-index\"\n    public var keyScheme: KeyScheme\n    public var alpha: Float\n    public var keyDims: Int\n    public var count: Int\n    public var documents: Int\n    public var partitions: Int\n    /// The thread blocks the index was keyed with (sha256 of blocks.safetensors; the pack's name when untrained).\n    public var blocksSHA256: String\n    public var packSHA256: String\n    public var seamSHA256: String\n    public var vocabularySHA256: String\n    public var corpusHash: String\n    public var tokenizerSHA256: String\n    public var threadID: String?\n    public var evalLoss: Float\n    public var evalEntropy: Float\n    public var evalMemorisedFraction: Float\n    public var defaultTau: Float = 0.05\n    public var defaultK: Int = 16\n    public var cut: Int\n    public var paragraphBreak: [Int32]\n    public var eos: Int32\n    public var checkpointsSHA256: String\n    public var indexSHA256: String\n    public var createdAt: Date\n    /// Documents trained but left out of the index (the stitched bench's withheld set, sorted); nil\n    /// when every document is indexed.\n    public var excluded: [String]? = nil\n}\n\npublic enum IndexFiles {\n    public static let safetensors = \"index.safetensors\"\n    public static let info = \"index.json\"\n    public static let partitions = \"partitions.json\"\n    public static let ngrams = \"shared-ngrams.bin\"\n    public static let checkpoints = \"checkpoints.json\"\n    public static let checkpointDirectory = \"checkpoints\"\n\n    public struct Arrays {\n        public var keys: MLXArray        // [N, K] f16\n        public var values: [Int32]\n        public var keyRow: [Int32]\n        public var keyOffset: [Int32]\n        public var valueRow: [Int32]\n        public var valueOffset: [Int32]\n        public var loss: [Float]\n        public var entropy: [Float]\n    }\n\n    public static func write(arrays: Arrays, info: inout IndexInfo, partitions: [PartitionRef], sharedNgrams: Set<UInt64>, manifest: CheckpointManifest, to directory: URL) throws {\n        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)\n        let tensors: [String: MLXArray] = [\n            \"keys\": arrays.keys.asType(.float16), \"values\": MLXArray(arrays.values), \"key_row\": MLXArray(arrays.keyRow), \"key_offset\": MLXArray(arrays.keyOffset),\n            \"value_row\": MLXArray(arrays.valueRow), \"value_offset\": MLXArray(arrays.valueOffset), \"loss\": MLXArray(arrays.loss), \"entropy\": MLXArray(arrays.entropy),\n        ]\n        try MLX.save(arrays: tensors, metadata: [\"format\": info.format, \"scheme\": info.keyScheme.description], url: directory.appendingPathComponent(safetensors))\n        try JSONCoding.write(partitions, to: directory.appendingPathComponent(self.partitions))\n        var words = sharedNgrams.sorted()\n        try words.withUnsafeMutableBytes { Data($0) }.write(to: directory.appendingPathComponent(ngrams), options: .atomic)\n        try JSONCoding.write(manifest, to: directory.appendingPathComponent(checkpoints))\n        info.checkpointsSHA256 = try ContentHash.sha256Hex(fileAt: directory.appendingPathComponent(checkpoints))\n        info.indexSHA256 = try ContentHash.sha256Hex(fileAt: directory.appendingPathComponent(safetensors))\n        try JSONCoding.write(info, to: directory.appendingPathComponent(self.info))\n    }\n\n    public static func readNgrams(_ url: URL) throws -> Set<UInt64> {\n        guard FileManager.default.fileExists(atPath: url.path) else { return [] }\n        let data = try Data(contentsOf: url)\n        let count = data.count / 8\n        var words = [UInt64](repeating: 0, count: count)\n        _ = words.withUnsafeMutableBytes { data.copyBytes(to: $0) }\n        return Set(words)\n    }\n}\n"},{"path":"Sources/BraidKit/Build/Index/KeyScheme.swift","lines":79,"bytes":2891,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[],"first":1076,"scopes":[["E","KeyScheme",null,"public",16,16,[16,77],79,null,-1,0,["residual","pooledState","stateDelta"]],["v","description",null,"public",24,24,[24,35],30,null,0,0],["i","init",["parsing"],"public",32,32,[32,39],41,null,0,0],["f","midDims",["config"],"public",43,43,[43,53],48,null,0,0],["f","keyDims",["config"],"public",50,50,[50,53],50,null,0,8],["v","taps",null,"public",52,52,[52,32],57,null,0,0],["v","stateLayer",null,"public",60,60,[60,32],65,[59,59],0,0],["E","CodingKeys",null,"",67,67,[67,39],67,null,0,8,[]],["i","init",["from"],"public",69,69,[69,46],73,null,0,0],["f","encode",["to"],"public",75,75,[75,51],78,null,0,0]],"text":"//\n//  KeyScheme.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Which attribute fills the provenance key's mid half: the residual stream after n blocks\n//        (`residual:n`, the default), the per-channel energy of a layer's recurrent state\n//        (`pooled-state:l`), or that state's per-channel change (`state-delta:l`). Recorded in\n//        index.json and version.json as its text form.\n//\n\nimport Foundation\n\npublic enum KeyScheme: Codable, Sendable, Equatable, CustomStringConvertible {\n    /// The residual stream after `afterBlocks` blocks (RaoLM's tap: block afterBlocks−1's output).\n    case residual(afterBlocks: Int)\n    /// Per-channel L2 energy of layer `layer`'s SSM state: ‖S[h,p,:]‖₂ → H·P floats.\n    case pooledState(layer: Int)\n    /// Per-channel ‖S_t − S_{t−1}‖ of layer `layer`'s SSM state → H·P floats.\n    case stateDelta(layer: Int)\n\n    public var description: String {\n        switch self {\n        case .residual(let n): return \"residual:\\(n)\"\n        case .pooledState(let l): return \"pooled-state:\\(l)\"\n        case .stateDelta(let l): return \"state-delta:\\(l)\"\n        }\n    }\n\n    public init?(parsing text: String) {\n        let parts = text.split(separator: \":\")\n        guard parts.count == 2, let n = Int(parts[1]) else { return nil }\n        switch parts[0] {\n        case \"residual\": self = .residual(afterBlocks: n)\n        case \"pooled-state\": self = .pooledState(layer: n)\n        case \"state-delta\": self = .stateDelta(layer: n)\n        default: return nil\n        }\n    }\n\n    public func midDims(config: Mamba2Config) -> Int {\n        switch self {\n        case .residual: return config.hiddenSize\n        case .pooledState, .stateDelta: return config.numHeads * config.headDim\n        }\n    }\n\n    public func keyDims(config: Mamba2Config) -> Int { midDims(config: config) + config.hiddenSize }\n\n    public var taps: TapRequest {\n        switch self {\n        case .residual(let n): return TapRequest(residualAfterBlocks: [n])\n        case .pooledState, .stateDelta: return .none\n        }\n    }\n\n    /// The layer whose state the pooled schemes read, if any.\n    public var stateLayer: Int? {\n        switch self {\n        case .residual: return nil\n        case .pooledState(let l), .stateDelta(let l): return l\n        }\n    }\n\n    enum CodingKeys: String, CodingKey { case scheme }\n\n    public init(from decoder: Decoder) throws {\n        let text = try decoder.singleValueContainer().decode(String.self)\n        guard let scheme = KeyScheme(parsing: text) else { throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: \"unknown key scheme \\(text)\")) }\n        self = scheme\n    }\n\n    public func encode(to encoder: Encoder) throws {\n        var c = encoder.singleValueContainer()\n        try c.encode(description)\n    }\n}\n"},{"path":"Sources/BraidKit/Build/Index/ProvenanceIndex.swift","lines":115,"bytes":5635,"header":{"lines":[1,13],"what":[8,10],"pin":[11,12],"in":null,"out":null},"marks":[],"first":1086,"scopes":[["C","ProvenanceIndex",null,"public final",19,19,[19,35],115,null,-1,0],["i","init",["directory"],"public",34,34,[34,39],63,null,0,0],["f","ints",["_"],"",43,43,[43,52],46,null,1,4],["f","floats",["_"],"",47,47,[47,54],50,null,1,4],["v","count",null,"public",65,65,[65,26],65,null,0,8],["v","layout",null,"public",67,67,[67,35],69,null,0,0],["f","query",["_","k"],"public",72,72,[72,62],86,[71,71],0,0],["f","hit",["entry","score"],"public",88,88,[88,53],90,null,0,0],["f","entries",["ofRows"],"public",93,93,[93,58],93,[92,92],0,8],["f","partition",["row"],"public",112,112,[112,53],112,null,0,8],["f","key",["entry"],"public",114,114,[114,44],114,null,0,8]],"text":"//\n//  ProvenanceIndex.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A loaded index: keys as float32 unit vectors on the GPU, every entry's value and\n//        addresses on the CPU, exact cosine search (one matmul, the top k+8 by argPartition, a\n//        CPU sort by score then entry), and the layout the trace tracker and the citations read.\n//  PIN:  Loading re-hashes index.safetensors against index.json. Keys are stored float16 and\n//        renormalised on load, as RaoLM did.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\n\npublic final class ProvenanceIndex {\n    public let directory: URL\n    public let info: IndexInfo\n    public let partitions: [PartitionRef]\n    public let values: [Int32]\n    public let keyRow: [Int32]\n    public let keyOffset: [Int32]\n    public let valueRow: [Int32]\n    public let valueOffset: [Int32]\n    public let loss: [Float]\n    public let entropy: [Float]\n    public let sharedNgrams: Set<UInt64>\n    public let checkpoints: CheckpointManifest\n    let keys: MLXArray\n\n    public init(directory: URL) throws {\n        self.directory = directory\n        info = try JSONCoding.read(IndexInfo.self, from: directory.appendingPathComponent(IndexFiles.info))\n        let tensorsURL = directory.appendingPathComponent(IndexFiles.safetensors)\n        guard try ContentHash.sha256Hex(fileAt: tensorsURL) == info.indexSHA256 else { throw BraidFailure.data(\"\\(directory.path): index.safetensors does not hash to index.json\") }\n        let arrays = try loadArrays(url: tensorsURL)\n        guard let k = arrays[\"keys\"] else { throw BraidFailure.data(\"the index has no keys\") }\n        keys = ProvenanceKey.normalized(k.asType(.float32))\n        eval(keys)\n        func ints(_ name: String) throws -> [Int32] {\n            guard let a = arrays[name] else { throw BraidFailure.data(\"the index lacks \\(name)\") }\n            return a.asArray(Int32.self)\n        }\n        func floats(_ name: String) throws -> [Float] {\n            guard let a = arrays[name] else { throw BraidFailure.data(\"the index lacks \\(name)\") }\n            return a.asArray(Float.self)\n        }\n        values = try ints(\"values\")\n        keyRow = try ints(\"key_row\")\n        keyOffset = try ints(\"key_offset\")\n        valueRow = try ints(\"value_row\")\n        valueOffset = try ints(\"value_offset\")\n        loss = try floats(\"loss\")\n        entropy = try floats(\"entropy\")\n        partitions = try JSONCoding.read([PartitionRef].self, from: directory.appendingPathComponent(IndexFiles.partitions))\n        sharedNgrams = try IndexFiles.readNgrams(directory.appendingPathComponent(IndexFiles.ngrams))\n        let manifestURL = directory.appendingPathComponent(IndexFiles.checkpoints)\n        guard try ContentHash.sha256Hex(fileAt: manifestURL) == info.checkpointsSHA256 else { throw BraidFailure.data(\"\\(directory.path): checkpoints.json does not hash to index.json\") }\n        checkpoints = try JSONCoding.read(CheckpointManifest.self, from: manifestURL)\n    }\n\n    public var count: Int { values.count }\n\n    public var layout: IndexLayout {\n        IndexLayout(values: values, keyRow: keyRow, keyOffset: keyOffset, partitions: partitions, breakLength: info.paragraphBreak.count, sharedNgrams: sharedNgrams)\n    }\n\n    /// The top `k` entries by cosine for each query row ([Q, K] unit keys), as hits.\n    public func query(_ queries: MLXArray, k: Int) -> [[Hit]] {\n        guard count > 0 else { return (0..<queries.dim(0)).map { _ in [] } }\n        let scores = matmul(queries.asType(.float32), keys.T)                                        // [Q, N]\n        let m = min(k + 8, count)\n        let candidates = argPartition(-scores, kth: m - 1, axis: -1)[0..., 0 ..< m]                    // [Q, m]\n        let picked = takeAlong(scores, candidates, axis: -1)\n        eval(candidates, picked)\n        let ids = candidates.asArray(Int32.self)\n        let values = picked.asArray(Float.self)\n        return (0..<queries.dim(0)).map { q in\n            var rows: [(entry: Int, score: Float)] = (0..<m).map { (Int(ids[q * m + $0]), values[q * m + $0]) }\n            rows.sort { $0.score != $1.score ? $0.score > $1.score : $0.entry < $1.entry }\n            return rows.prefix(k).map { hit(entry: $0.entry, score: $0.score) }\n        }\n    }\n\n    public func hit(entry: Int, score: Float) -> Hit {\n        Hit(entry: Int32(entry), score: score, value: values[entry], row: valueRow[entry], offset: valueOffset[entry], loss: loss[entry])\n    }\n\n    /// Entries of one document, in order.\n    public func entries(ofRows rows: Set<Int32>) -> [Int] { keyRow.indices.filter { rows.contains(keyRow[$0]) } }\n\n    /// The partition table by row.\n    public private(set) lazy var partitionByRow: [Int: PartitionRef] = Dictionary(partitions.map { ($0.row, $0) }, uniquingKeysWith: { first, _ in first })\n\n    /// Each document's entries, a contiguous range in corpus order (entries are written document by document).\n    public private(set) lazy var entriesByDocument: [String: Range<Int>] = {\n        var ranges: [String: Range<Int>] = [:]\n        var e = 0\n        while e < keyRow.count {\n            let row = Int(keyRow[e])\n            guard let documentID = partitionByRow[row]?.documentID else { e += 1; continue }\n            let start = e\n            while e < keyRow.count, let d = partitionByRow[Int(keyRow[e])]?.documentID, d == documentID { e += 1 }\n            ranges[documentID] = start ..< e\n        }\n        return ranges\n    }()\n\n    public func partition(row: Int) -> PartitionRef? { partitionByRow[row] }\n\n    public func key(entry: Int) -> MLXArray { keys[entry] }\n}\n"},{"path":"Sources/BraidKit/Build/Index/ProvenanceKey.swift","lines":56,"bytes":2465,"header":{"lines":[1,13],"what":[8,12],"pin":null,"in":null,"out":null},"marks":[],"first":1097,"scopes":[["E","ProvenanceKey",null,"public",19,19,[19,26],56,null,-1,0,[]],["f","normalized",["_"],"public static",24,24,[24,61],27,[23,23],0,0],["f","make",["mid","final","alpha"],"public static",30,30,[30,94],32,[29,29],0,0],["f","mid",["scheme","output","previousState"],"public static",35,35,[35,107],49,[34,34],0,0],["f","energy",["_"],"public static",52,52,[52,61],55,[51,51],0,0]],"text":"//\n//  ProvenanceKey.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The two-point provenance key on a recurrent trunk: K = [√α·mid/‖mid‖, √(1−α)·final/‖final‖],\n//        final the normed last-layer state (the node's public output), mid one of the sweep's\n//        attributes — the residual stream after n blocks (the default, the closest analog of\n//        RaoLM's tap), the per-channel energy of a layer's recurrent state, or that state's\n//        per-channel change. The scheme a version was keyed with is recorded in index.json.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\n\npublic enum ProvenanceKey {\n    public static let alpha: Float = 0.5\n    public static let eps: Float = 1e-6\n\n    /// Unit-normalises the last axis.\n    public static func normalized(_ x: MLXArray) -> MLXArray {\n        let norms = sqrt((x * x).sum(axis: -1, keepDims: true)) + eps\n        return x / norms\n    }\n\n    /// [√α·mid/‖mid‖, √(1−α)·final/‖final‖] along the last axis, f32.\n    public static func make(mid: MLXArray, final: MLXArray, alpha: Float = alpha) -> MLXArray {\n        concatenated([normalized(mid.asType(.float32)) * sqrt(alpha), normalized(final.asType(.float32)) * sqrt(1 - alpha)], axis: -1)\n    }\n\n    /// The mid half for a scheme from a trunk output over a sequence ([…,L,·]).\n    public static func mid(scheme: KeyScheme, output: TrunkOutput, previousState: StateStack?) -> MLXArray {\n        switch scheme {\n        case .residual(let n):\n            guard let residual = output.residual[n] else { fatalError(\"the trunk did not tap block \\(n)\") }\n            return residual\n        case .pooledState(let layer):\n            // Only the final state is available per call; a sequence of pooled states needs the\n            // per-position scan (the sweep's harness provides it). Here: the state after the sequence.\n            return energy(output.state.layers[layer].ssm)\n        case .stateDelta(let layer):\n            let now = output.state.layers[layer].ssm\n            let before = previousState?.layers[layer].ssm ?? MLXArray.zeros(like: now)\n            return energy(now - before)\n        }\n    }\n\n    /// ‖S[h,p,:]‖₂ per channel: [B,H,P,N] → [B,H·P].\n    public static func energy(_ state: MLXArray) -> MLXArray {\n        let e = sqrt((state * state).sum(axis: -1))\n        return e.reshaped([e.dim(0), e.dim(1) * e.dim(2)])\n    }\n}\n"},{"path":"Sources/BraidKit/Build/Index/Replay.swift","lines":39,"bytes":2274,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":1102,"scopes":[["E","Replay",null,"public",17,17,[17,19],39,null,-1,0,[]],["f","key",["at","index","corpus","trunk","pack"],"public static",20,20,[20,179],38,[18,19],0,0]],"text":"//\n//  Replay.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: KV-free replay: any key of an index recomputed from the nearest state checkpoint at or\n//        before its position (or from a zero state), after both of the checkpoint's hashes are\n//        checked. `braid verify --keys` reads keys back through it.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\n\npublic enum Replay {\n    /// The key at a corpus position, recomputed from the nearest checkpoint at or before it (or\n    /// from a zero state), scanning forward. Both the checkpoint's hashes are verified first.\n    public static func key(at target: TokenPosition, index: ProvenanceIndex, corpus: TokenizedCorpus, trunk: Trunk, pack: Pack) throws -> (key: MLXArray, checkpointDistance: Int) {\n        guard let document = corpus.document(ofRow: target.row), let position = document.addresses.firstIndex(of: target) else {\n            throw BraidFailure.data(\"position \\(target) is not in the corpus\")\n        }\n        let candidates = index.checkpoints.checkpoints.filter { $0.documentID == document.documentID && $0.position <= position }\n        var state: StateStack? = nil\n        var start = 0\n        if let nearest = candidates.max(by: { $0.position < $1.position }) {\n            let url = index.directory.appendingPathComponent(IndexFiles.checkpointDirectory).appendingPathComponent(nearest.file)\n            guard try ContentHash.sha256Hex(fileAt: url) == nearest.sha256 else { throw BraidFailure.data(\"checkpoint \\(nearest.file) does not hash to its record\") }\n            guard NodeCheckpoint.prefixHash(Array(document.tokens[0...nearest.position])) == nearest.prefixSHA256 else { throw BraidFailure.data(\"checkpoint \\(nearest.file) is bound to another prefix\") }\n            state = try StateStack.load(from: url, expecting: trunk.config)\n            start = nearest.position + 1\n        }\n        guard position >= start else { throw BraidFailure.data(\"checkpoint past the target\") }\n        let segment = Array(document.tokens[start...position])\n        let key = SegmentKeys.lastKey(trunk: trunk, segment: segment, state: state, scheme: index.info.keyScheme, alpha: index.info.alpha)\n        return (key, position - start + 1)\n    }\n}\n"},{"path":"Sources/BraidKit/Build/Index/SegmentKeys.swift","lines":79,"bytes":4121,"header":{"lines":[1,10],"what":[8,9],"pin":null,"in":null,"out":null},"marks":[],"first":1104,"scopes":[["E","SegmentKeys",null,"public",20,20,[20,24],79,[16,19],-1,0,[]],["S","Output",null,"public",21,21,[21,25],28,null,0,0],["f","run",["trunk","segment","state","scheme"],"public static",30,30,[30,108],58,null,0,0],["f","lastKey",["trunk","segment","state","scheme","alpha"],"public static",61,61,[61,128],78,[60,60],0,0]],"text":"//\n//  SegmentKeys.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The key's two halves at every position of one state-carrying segment, under any key\n//        scheme. The index builder, the replay and the key sweep all key text through it.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\n\n/// The per-position halves of a key over one state-carrying segment, for every scheme. Residual\n/// schemes come from one chunked forward; the pooled-state schemes need the recurrent state at\n/// every position, which the chunked scan does not materialise, so they step the trunk token by\n/// token (the same recurrence the live node runs).\npublic enum SegmentKeys {\n    public struct Output {\n        /// [q, D]: the normed final state at each position.\n        public var final: MLXArray\n        /// [q, M]: the scheme's mid half at each position.\n        public var mid: MLXArray\n        /// The state after the segment.\n        public var state: StateStack\n    }\n\n    public static func run(trunk: Trunk, segment: [Int32], state: StateStack?, scheme: KeyScheme) -> Output {\n        switch scheme {\n        case .residual(let n):\n            let out = trunk.forward(tokens: MLXArray(segment, [1, segment.count]), state: state, resets: nil, taps: scheme.taps)\n            return Output(final: out.final[0], mid: out.residual[n]![0], state: out.state)\n        case .pooledState(let layer), .stateDelta(let layer):\n            // The final half from one chunked forward that also taps the input to block `layer`; that\n            // block alone is then stepped over the segment for its state at every position. The\n            // stepped recurrence equals the chunked scan (SSDTests), so the two halves agree.\n            let out = trunk.forward(tokens: MLXArray(segment, [1, segment.count]), state: state, resets: nil, taps: TapRequest(residualAfterBlocks: [layer]))\n            let input = out.residual[layer]![0]                                                        // [q, D]\n            let block = trunk.backbone.layers[layer]\n            var current = state?.layers[layer] ?? LayerState.zeros(config: trunk.config, batch: 1)\n            var mids: [MLXArray] = []\n            for t in 0 ..< segment.count {\n                let previous = current.ssm\n                let (_, next) = block.step(input[t ..< t + 1], state: current, reset: nil)\n                current = next\n                switch scheme {\n                case .stateDelta: mids.append(ProvenanceKey.energy(next.ssm - previous))\n                default: mids.append(ProvenanceKey.energy(next.ssm))\n                }\n                if t % 64 == 63 { eval(current.conv, current.ssm) }\n            }\n            let mid = concatenated(mids, axis: 0)\n            eval(mid)\n            return Output(final: out.final[0], mid: mid, state: out.state)\n        }\n    }\n\n    /// The unit key at the segment's last position ([K]).\n    public static func lastKey(trunk: Trunk, segment: [Int32], state: StateStack?, scheme: KeyScheme, alpha: Float) -> MLXArray {\n        let out: Output\n        switch scheme {\n        case .residual:\n            out = run(trunk: trunk, segment: segment, state: state, scheme: scheme)\n        case .pooledState, .stateDelta:\n            // Only the last position's state (and the one before it) are needed: forward to it, step once.\n            var current = state ?? StateStack.zeros(config: trunk.config, batch: 1)\n            if segment.count > 1 { current = trunk.forward(tokens: MLXArray(Array(segment.dropLast()), [1, segment.count - 1]), state: current, resets: nil).state }\n            let previous = current\n            let step = trunk.step(token: MLXArray([segment[segment.count - 1]]), state: current, reset: nil)\n            out = Output(final: step.final, mid: ProvenanceKey.mid(scheme: scheme, output: step, previousState: previous), state: step.state)\n        }\n        let q = out.final.dim(0)\n        let key = ProvenanceKey.make(mid: out.mid[(q - 1)...], final: out.final[(q - 1)...], alpha: alpha)\n        eval(key)\n        return key.reshaped([-1])\n    }\n}\n"},{"path":"Sources/BraidKit/Build/Pack/BraidTokenizer.swift","lines":93,"bytes":4130,"header":{"lines":[1,13],"what":[8,12],"pin":null,"in":null,"out":null},"marks":[],"first":1108,"scopes":[["C","BraidTokenizer",null,"public final",19,19,[19,67],75,null,-1,0],["i","init",["folder"],"public",29,29,[29,36],48,null,0,0],["f","encode",["_"],"public",50,50,[50,50],50,null,0,8],["f","decode",["_"],"public",51,51,[51,52],51,null,0,8],["f","text",["_"],"public",53,53,[53,47],62,null,0,0],["f","byteOffsets",["_"],"public",65,65,[65,56],74,[64,64],0,0],["E","Blocking",null,"public",78,78,[78,21],93,[77,77],-1,0,[]],["f","run",["_"],"public static",79,79,[79,102],88,null,6,0],["C","ResultBox",null,"final",90,90,[90,50],92,null,6,0]],"text":"//\n//  BraidTokenizer.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The pack's tokenizer, loaded from its folder with Frigate's tokenizer stack. The GPT-NeoX\n//        class is not in Frigate's registry, so the loader runs non-strict and falls back to the\n//        byte-level BPE model, which is what the files describe. Checked at import: eos is 0, no\n//        special tokens are added, encode/decode round-trips, and the paragraph break is recorded\n//        from the tokenizer rather than hardcoded.\n//\n\nimport BraidCore\nimport Foundation\nimport Tokenizers\n\npublic final class BraidTokenizer: Tokenizing, @unchecked Sendable {\n    public let folder: URL\n    public let sha256: String\n    public let eos: Int32\n    public let vocabSize: Int\n    public let paragraphBreak: [Int32]\n    private let tokenizer: any Tokenizer\n    private var textCache: [Int32: String] = [:]\n    private let lock = NSLock()\n\n    public init(folder: URL) throws {\n        self.folder = folder\n        let file = folder.appendingPathComponent(\"tokenizer.json\")\n        guard FileManager.default.fileExists(atPath: file.path) else { throw BraidFailure.missing(\"no tokenizer.json in \\(folder.path)\") }\n        sha256 = try ContentHash.sha256Hex(fileAt: file)\n        let loaded = try Blocking.run { try await AutoTokenizer.from(modelFolder: folder, strict: false) }\n        tokenizer = loaded\n        guard let eosID = loaded.eosTokenId else { throw BraidFailure.data(\"the tokenizer declares no eos token\") }\n        eos = Int32(eosID)\n        // The vocabulary size: count ids that decode to a token (the embedding may hold padding rows past it).\n        let data = try JSONSerialization.jsonObject(with: Data(contentsOf: file)) as? [String: Any]\n        let model = data?[\"model\"] as? [String: Any]\n        let vocab = model?[\"vocab\"] as? [String: Any]\n        let added = (data?[\"added_tokens\"] as? [[String: Any]])?.compactMap { $0[\"id\"] as? Int } ?? []\n        vocabSize = max(vocab?.count ?? 0, (added.max() ?? -1) + 1)\n        paragraphBreak = loaded.encode(text: \"\\n\\n\", addSpecialTokens: false).map(Int32.init)\n        guard loaded.encode(text: \"a\", addSpecialTokens: true) == loaded.encode(text: \"a\", addSpecialTokens: false) else {\n            throw BraidFailure.data(\"the tokenizer adds special tokens on encode; Braid's streams carry their own eos\")\n        }\n    }\n\n    public func encode(_ text: String) -> [Int32] { tokenizer.encode(text: text, addSpecialTokens: false).map(Int32.init) }\n    public func decode(_ tokens: [Int32]) -> String { tokenizer.decode(tokens: tokens.map(Int.init), skipSpecialTokens: false) }\n\n    public func text(_ token: Int32) -> String {\n        lock.lock()\n        if let cached = textCache[token] { lock.unlock(); return cached }\n        lock.unlock()\n        let decoded = tokenizer.decode(tokens: [Int(token)], skipSpecialTokens: false)\n        lock.lock()\n        textCache[token] = decoded\n        lock.unlock()\n        return decoded\n    }\n\n    /// For each token, the UTF-8 byte offset where it begins in the decoded text (plus the end).\n    public func byteOffsets(_ tokens: [Int32]) -> [Int] {\n        var offsets: [Int] = []\n        var consumed = 0\n        offsets.reserveCapacity(tokens.count + 1)\n        for i in 0...tokens.count {\n            offsets.append(consumed)\n            if i < tokens.count { consumed = decode(Array(tokens[0...i])).utf8.count }\n        }\n        return offsets\n    }\n}\n\n/// Runs an async operation to completion from synchronous code (the CLI and the MLX thread).\npublic enum Blocking {\n    public static func run<T: Sendable>(_ body: @escaping @Sendable () async throws -> T) throws -> T {\n        let semaphore = DispatchSemaphore(value: 0)\n        let box = ResultBox<T>()\n        Task.detached {\n            do { box.result = .success(try await body()) } catch { box.result = .failure(error) }\n            semaphore.signal()\n        }\n        semaphore.wait()\n        return try box.result!.get()\n    }\n\n    final class ResultBox<T>: @unchecked Sendable {\n        var result: Result<T, Error>?\n    }\n}\n"},{"path":"Sources/BraidKit/Build/Pack/Pack.swift","lines":173,"bytes":10000,"header":{"lines":[1,17],"what":[8,14],"pin":[15,16],"in":null,"out":null},"marks":[],"first":1117,"scopes":[["S","PackInfo",null,"public",24,24,[24,53],49,null,-1,0],["E","PackHash",null,"public",51,51,[51,21],82,null,-1,0,[]],["f","bytes",["_"],"static",52,52,[52,49],55,null,1,0],["f","vocabulary",["embedding","norm"],"public static",58,58,[58,81],60,[57,57],1,0],["f","name",["embedding","norm","blocks","tokenizerSHA256"],"public static",63,63,[63,130],71,[62,62],1,0],["f","seam",["embedding","norm","trunk"],"public static",74,74,[74,104],81,[73,73],1,0],["C","Pack",null,"public final",84,84,[84,24],173,null,-1,0],["i","init",["directory","info","embedding","norm","blocks"],"",99,99,[99,106],105,null,6,0],["v","config",null,"public",107,107,[107,36],107,null,6,8],["v","sha256",null,"public",108,108,[108,30],108,null,6,8],["v","tokenizerFolder",null,"public",109,109,[109,36],109,null,6,8],["v","identity",null,"public",110,110,[110,38],113,null,6,0],["v","trunkArrays",null,"public",116,116,[116,49],118,[115,115],6,0],["v","headArrays",null,"public",122,122,[122,46],124,[120,121],6,0],["f","directory",["in","sha256"],"public static",127,127,[127,71],127,[126,126],6,8],["f","write",["info","embedding","norm","blocks","tokenizerFiles","into"],"public static",130,130,[130,164],151,[129,129],6,0],["f","load",["from"],"public static",154,154,[154,64],170,[153,153],6,0],["f","reed",["tokens"],"public",172,172,[172,45],172,null,6,8]],"text":"//\n//  Pack.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A pack: the imported Mamba2 model as a braid's foundation — the vocabulary (embedding and\n//        final norm), every block, the tokenizer — named by SHA-256 and written once. The NAME covers\n//        everything a node must match (norm, embedding, every block in key order, the tokenizer);\n//        the SEAM covers what a node runs unchanged (norm, embedding, the trunk blocks ≥ cut): the\n//        commons' tail, which every Thread runs behind its own head; the VOCABULARY fingerprint is\n//        the reed's name. RaoLM v2's definitions, unchanged. The commons is a pack run whole\n//        (`Trunk(pack:)`); a head starts from `headArrays`.\n//  PIN:  Float32 throughout, so the index a node keys later matches the weights on disk. A pack\n//        directory is staged and renamed; loading re-hashes and refuses any difference.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\nimport MLXNN\n\npublic struct PackInfo: Codable, Sendable, Equatable {\n    public var version = 2\n    public var name: String\n    public var source: String\n    public var architecture = \"mamba2\"\n    public var config: Mamba2Config\n    /// NAME: SHA-256(norm ‖ embedding ‖ ∀ block arrays sorted by key: key ‖ bytes ‖ tokenizerSHA256).\n    public var sha256: String\n    /// SEAM: SHA-256(norm ‖ embedding ‖ ∀ arrays of blocks ≥ cut sorted by key: key ‖ bytes).\n    public var seamSHA256: String\n    public var vocabularySHA256: String\n    public var baseSHA256: String\n    public var vocabularyFileSHA256: String\n    public var tokenizerSHA256: String\n    public var tokenizerFiles: [String]\n    public var tokenizerVocabSize: Int\n    public var paddingRows: [Int]\n    public var eosTokenID: Int\n    public var paragraphBreak: [Int]\n    public var dtype = \"float32\"\n    public var sourceDType: String\n    public var referenceNLL: Float?\n    public var referenceSample: String?\n    public var stateBytesPerStream: Int\n    public var createdAt: Date\n}\n\npublic enum PackHash {\n    static func bytes(_ array: MLXArray) -> Data {\n        let floats = array.asType(.float32).asArray(Float.self)\n        return floats.withUnsafeBufferPointer { Data(buffer: $0) }\n    }\n\n    /// SHA-256(norm f32 LE ‖ embedding f32 LE).\n    public static func vocabulary(embedding: MLXArray, norm: MLXArray) -> String {\n        ContentHash.sha256Hex(parts: [bytes(norm), bytes(embedding)])\n    }\n\n    /// SHA-256(norm ‖ embedding ‖ ∀ (key, bytes) sorted by key ‖ tokenizerSHA256).\n    public static func name(embedding: MLXArray, norm: MLXArray, blocks: [(String, MLXArray)], tokenizerSHA256: String) -> String {\n        var parts = [bytes(norm), bytes(embedding)]\n        for (key, array) in blocks.sorted(by: { $0.0 < $1.0 }) {\n            parts.append(Data(key.utf8))\n            parts.append(bytes(array))\n        }\n        parts.append(Data(tokenizerSHA256.utf8))\n        return ContentHash.sha256Hex(parts: parts)\n    }\n\n    /// SHA-256(norm ‖ embedding ‖ ∀ trunk (key, bytes) sorted by key).\n    public static func seam(embedding: MLXArray, norm: MLXArray, trunk: [(String, MLXArray)]) -> String {\n        var parts = [bytes(norm), bytes(embedding)]\n        for (key, array) in trunk.sorted(by: { $0.0 < $1.0 }) {\n            parts.append(Data(key.utf8))\n            parts.append(bytes(array))\n        }\n        return ContentHash.sha256Hex(parts: parts)\n    }\n}\n\npublic final class Pack {\n    public static let infoFile = \"pack.json\"\n    public static let vocabularyFile = \"vocabulary.safetensors\"\n    public static let baseFile = \"base.safetensors\"\n    public static let tokenizerDirectory = \"tokenizer\"\n    public static let embeddingKey = \"backbone.embeddings.weight\"\n    public static let normKey = \"backbone.norm_f.weight\"\n\n    public let directory: URL\n    public let info: PackInfo\n    public let embedding: MLXArray\n    public let norm: MLXArray\n    /// Every block array by its checkpoint key, f32.\n    public let blocks: [String: MLXArray]\n\n    init(directory: URL, info: PackInfo, embedding: MLXArray, norm: MLXArray, blocks: [String: MLXArray]) {\n        self.directory = directory\n        self.info = info\n        self.embedding = embedding\n        self.norm = norm\n        self.blocks = blocks\n    }\n\n    public var config: Mamba2Config { info.config }\n    public var sha256: String { info.sha256 }\n    public var tokenizerFolder: URL { directory.appendingPathComponent(Self.tokenizerDirectory, isDirectory: true) }\n    public var identity: PackIdentity {\n        PackIdentity(sha256: info.sha256, name: info.name, vocabularySHA256: info.vocabularySHA256, tokenizerSHA256: info.tokenizerSHA256,\n                     hiddenSize: config.hiddenSize, vocabulary: config.vocabSize, seamSHA256: info.seamSHA256)\n    }\n\n    /// The trunk's arrays: blocks ≥ cut, the seam's input.\n    public var trunkArrays: [(String, MLXArray)] {\n        blocks.filter { Trunk.blockIndex(ofKey: $0.key).map { $0 >= config.cut } ?? false }.map { ($0.key, $0.value) }\n    }\n\n    /// A head's arrays: blocks 0..<cut as imported. The commons' own head, where a Thread's training\n    /// starts, and what an untrained Thread runs.\n    public var headArrays: [String: MLXArray] {\n        blocks.filter { Trunk.blockIndex(ofKey: $0.key).map { $0 < config.cut } ?? false }\n    }\n\n    /// The directory a pack with this name lives in under `packs/`.\n    public static func directory(in packs: URL, sha256: String) -> URL { packs.appendingPathComponent(String(sha256.prefix(12)), isDirectory: true) }\n\n    /// Writes the pack once. A directory holding the same pack is left alone; another pack there is refused.\n    public static func write(info: PackInfo, embedding: MLXArray, norm: MLXArray, blocks: [String: MLXArray], tokenizerFiles: [URL], into packs: URL) throws -> URL {\n        let target = directory(in: packs, sha256: info.sha256)\n        if FileManager.default.fileExists(atPath: target.appendingPathComponent(infoFile).path) {\n            let existing = try JSONCoding.read(PackInfo.self, from: target.appendingPathComponent(infoFile))\n            if existing.sha256 == info.sha256 { return target }\n            throw BraidFailure.exists(\"\\(target.path) holds another pack (\\(existing.sha256.prefix(12)))\")\n        }\n        let staging = packs.appendingPathComponent(\".staging-\\(info.sha256.prefix(12))-\\(UUID().uuidString.prefix(8))\", isDirectory: true)\n        try FileManager.default.createDirectory(at: staging.appendingPathComponent(tokenizerDirectory), withIntermediateDirectories: true)\n        try MLX.save(arrays: [embeddingKey: embedding, normKey: norm], metadata: [\"format\": \"braid-vocabulary-v1\"], url: staging.appendingPathComponent(vocabularyFile))\n        try MLX.save(arrays: blocks, metadata: [\"format\": \"braid-base-v1\", \"pack\": info.sha256], url: staging.appendingPathComponent(baseFile))\n        for file in tokenizerFiles {\n            try FileManager.default.copyItem(at: file, to: staging.appendingPathComponent(tokenizerDirectory).appendingPathComponent(file.lastPathComponent))\n        }\n        var written = info\n        written.baseSHA256 = try ContentHash.sha256Hex(fileAt: staging.appendingPathComponent(baseFile))\n        written.vocabularyFileSHA256 = try ContentHash.sha256Hex(fileAt: staging.appendingPathComponent(vocabularyFile))\n        try JSONCoding.write(written, to: staging.appendingPathComponent(infoFile))\n        try FileManager.default.createDirectory(at: packs, withIntermediateDirectories: true)\n        try FileManager.default.moveItem(at: staging, to: target)\n        return target\n    }\n\n    /// Loads a pack and re-derives every hash; any difference is refused.\n    public static func load(from directory: URL) throws -> Pack {\n        let info = try JSONCoding.read(PackInfo.self, from: directory.appendingPathComponent(infoFile))\n        guard try ContentHash.sha256Hex(fileAt: directory.appendingPathComponent(baseFile)) == info.baseSHA256 else { throw BraidFailure.data(\"\\(directory.lastPathComponent): base.safetensors does not hash to the pack's record\") }\n        guard try ContentHash.sha256Hex(fileAt: directory.appendingPathComponent(vocabularyFile)) == info.vocabularyFileSHA256 else { throw BraidFailure.data(\"\\(directory.lastPathComponent): vocabulary.safetensors does not hash to the pack's record\") }\n        let vocabulary = try loadArrays(url: directory.appendingPathComponent(vocabularyFile))\n        guard let embedding = vocabulary[embeddingKey], let norm = vocabulary[normKey] else { throw BraidFailure.data(\"the vocabulary file lacks the embedding or the norm\") }\n        let blocks = try loadArrays(url: directory.appendingPathComponent(baseFile))\n        let tokenizer = directory.appendingPathComponent(tokenizerDirectory).appendingPathComponent(\"tokenizer.json\")\n        guard try ContentHash.sha256Hex(fileAt: tokenizer) == info.tokenizerSHA256 else { throw BraidFailure.data(\"\\(directory.lastPathComponent): tokenizer.json does not hash to the pack's record\") }\n        guard PackHash.vocabulary(embedding: embedding, norm: norm) == info.vocabularySHA256 else { throw BraidFailure.data(\"\\(directory.lastPathComponent): the vocabulary fingerprint differs\") }\n        let pack = Pack(directory: directory, info: info, embedding: embedding, norm: norm, blocks: blocks)\n        guard PackHash.name(embedding: embedding, norm: norm, blocks: blocks.map { ($0.key, $0.value) }, tokenizerSHA256: info.tokenizerSHA256) == info.sha256 else {\n            throw BraidFailure.data(\"\\(directory.lastPathComponent): the pack's name does not hash\")\n        }\n        guard PackHash.seam(embedding: embedding, norm: norm, trunk: pack.trunkArrays) == info.seamSHA256 else { throw BraidFailure.data(\"\\(directory.lastPathComponent): the seam does not hash\") }\n        return pack\n    }\n\n    public func reed(tokens: Int) -> MLXReed { MLXReed(embedding: embedding, vocabularySHA256: info.vocabularySHA256, tokens: tokens) }\n}\n"},{"path":"Sources/BraidKit/Build/Pack/PackImporter.swift","lines":124,"bytes":8180,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[],"first":1135,"scopes":[["E","PackImporter",null,"public",19,19,[19,25],119,null,-1,0,[]],["f","fetch",["repo","revision","modelsHome","progress"],"public static",23,23,[23,141],33,[22,22],0,0],["S","Imported",null,"public",35,35,[35,27],38,null,0,0],["f","importPack",["folder","name","source","cut","tapAfterBlocks","into","progress"],"public static",41,41,[42,92],110,[40,40],0,0],["f","record",["referenceNLL","sample","in"],"public static",113,113,[113,95],118,[112,112],0,0],["X","PackImporter",null,"",121,121,[121,23],124,null,-1,0],["f","snapshotCommit",["_"],"public static",123,123,[123,64],123,[122,122],5,8]],"text":"//\n//  PackImporter.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid import`: a Hugging Face Mamba2 checkpoint (config.json, safetensors, tokenizer\n//        files) becomes a pack. The conv1d weight is turned to MLX's layout, every array is widened\n//        to float32, the lm_head must be tied (or equal to the embedding), and the pack's hashes are\n//        written at import time. The download goes through Frigate's hub into the work area.\n//\n\nimport BraidCore\nimport Foundation\nimport FrigateBridge\nimport MLX\n\npublic enum PackImporter {\n    public static let patterns = [\"config.json\", \"*.safetensors\", \"model.safetensors.index.json\", \"tokenizer.json\", \"tokenizer_config.json\", \"special_tokens_map.json\"]\n\n    /// Fetches a repo into `<modelsHome>/snapshots/models/<org>/<repo>` (or finds it there).\n    public static func fetch(repo: String, revision: String?, modelsHome: URL, progress: @escaping @Sendable (String) -> Void) throws -> URL {\n        if let onDisk = HubDownloader.materializedSnapshot(id: repo, revision: revision, matching: patterns, roots: HubDownloader.snapshotRoots(home: modelsHome)) {\n            return onDisk\n        }\n        progress(\"downloading \\(repo)\\(revision.map { \"@\\($0)\" } ?? \"\") into \\(modelsHome.path)\")\n        return try Blocking.run {\n            try await HubDownloader(home: modelsHome).download(id: repo, revision: revision, matching: patterns, useLatest: revision == nil) { p in\n                progress(String(format: \"  %.0f%%\", p.fractionCompleted * 100))\n            }\n        }\n    }\n\n    public struct Imported {\n        public var directory: URL\n        public var pack: Pack\n    }\n\n    /// Reads the checkpoint folder, builds the pack and writes it under `packs`.\n    public static func importPack(folder: URL, name: String, source: String, cut: Int?, tapAfterBlocks: Int?, into packs: URL,\n                                  progress: (String) -> Void = { _ in }) throws -> Imported {\n        var config = try JSONCoding.readStandardized(Mamba2Config.self, from: folder.appendingPathComponent(\"config.json\"))\n        if let cut { config.cut = cut }\n        if let tapAfterBlocks { config.tapAfterBlocks = tapAfterBlocks }\n        try config.validate()\n        progress(\"reading weights\")\n        var weights: [String: MLXArray] = [:]\n        var sourceDType = \"unknown\"\n        let indexURL = folder.appendingPathComponent(\"model.safetensors.index.json\")\n        var files: [URL] = []\n        if FileManager.default.fileExists(atPath: indexURL.path),\n           let index = try JSONSerialization.jsonObject(with: Data(contentsOf: indexURL)) as? [String: Any],\n           let map = index[\"weight_map\"] as? [String: String] {\n            files = Array(Set(map.values)).sorted().map { folder.appendingPathComponent($0) }\n        } else {\n            files = try FileManager.default.contentsOfDirectory(at: folder, includingPropertiesForKeys: nil).filter { $0.pathExtension == \"safetensors\" }.sorted { $0.path < $1.path }\n        }\n        guard !files.isEmpty else { throw BraidFailure.missing(\"no safetensors in \\(folder.path)\") }\n        for file in files {\n            for (key, value) in try loadArrays(url: file) {\n                sourceDType = \"\\(value.dtype)\"\n                weights[key] = value\n            }\n        }\n        // Sanitize: HF's conv1d weight is [C,1,K]; MLX's is [C,K,1]. The lm_head must be the embedding.\n        for (key, value) in weights where key.contains(\"conv1d.weight\") && value.dim(-1) != 1 { weights[key] = value.swappedAxes(1, 2) }\n        if let lmHead = weights.removeValue(forKey: \"lm_head.weight\") {\n            guard let embedding = weights[Pack.embeddingKey] else { throw BraidFailure.data(\"the checkpoint has an lm_head but no embedding\") }\n            let difference = abs(lmHead.asType(.float32) - embedding.asType(.float32)).max()\n            eval(difference)\n            guard difference.item(Float.self) == 0 else { throw BraidFailure.data(\"the checkpoint's lm_head is not its embedding; Braid's reed is the vocabulary\") }\n        }\n        guard let embedding = weights.removeValue(forKey: Pack.embeddingKey)?.asType(.float32), let norm = weights.removeValue(forKey: Pack.normKey)?.asType(.float32) else {\n            throw BraidFailure.data(\"the checkpoint lacks \\(Pack.embeddingKey) or \\(Pack.normKey)\")\n        }\n        guard embedding.dim(0) == config.vocabSize, embedding.dim(1) == config.hiddenSize else {\n            throw BraidFailure.data(\"the embedding is \\(embedding.shape), not [\\(config.vocabSize), \\(config.hiddenSize)]\")\n        }\n        var blocks: [String: MLXArray] = [:]\n        for (key, value) in weights {\n            guard Trunk.blockIndex(ofKey: key) != nil else { throw BraidFailure.data(\"unexpected array \\(key) in the checkpoint\") }\n            blocks[key] = value.asType(.float32)\n        }\n        eval(embedding, norm)\n        eval(Array(blocks.values))\n        // The tokenizer, checked.\n        progress(\"loading the tokenizer\")\n        let tokenizerFiles = [\"tokenizer.json\", \"tokenizer_config.json\", \"special_tokens_map.json\"].map { folder.appendingPathComponent($0) }.filter { FileManager.default.fileExists(atPath: $0.path) }\n        let tokenizer = try BraidTokenizer(folder: folder)\n        guard tokenizer.eos == 0 else { throw BraidFailure.data(\"the tokenizer's eos is \\(tokenizer.eos); Braid's streams open with eos 0\") }\n        guard tokenizer.vocabSize <= config.vocabSize else { throw BraidFailure.data(\"the tokenizer has \\(tokenizer.vocabSize) tokens but the embedding \\(config.vocabSize) rows\") }\n        for sample in [\"Hello world.\", \"  two  spaces\\n\\nand a break\", \"naïve café 日本\"] {\n            guard tokenizer.decode(tokenizer.encode(sample)) == sample else { throw BraidFailure.data(\"the tokenizer does not round-trip \\(sample.debugDescription)\") }\n        }\n        progress(\"hashing\")\n        let blockList = blocks.map { ($0.key, $0.value) }\n        let trunkList = blockList.filter { Trunk.blockIndex(ofKey: $0.0).map { $0 >= config.cut } ?? false }\n        let info = PackInfo(name: name, source: source, config: config,\n                            sha256: PackHash.name(embedding: embedding, norm: norm, blocks: blockList, tokenizerSHA256: tokenizer.sha256),\n                            seamSHA256: PackHash.seam(embedding: embedding, norm: norm, trunk: trunkList),\n                            vocabularySHA256: PackHash.vocabulary(embedding: embedding, norm: norm), baseSHA256: \"\", vocabularyFileSHA256: \"\",\n                            tokenizerSHA256: tokenizer.sha256, tokenizerFiles: tokenizerFiles.map(\\.lastPathComponent), tokenizerVocabSize: tokenizer.vocabSize,\n                            paddingRows: tokenizer.vocabSize < config.vocabSize ? [tokenizer.vocabSize, config.vocabSize] : [], eosTokenID: Int(tokenizer.eos),\n                            paragraphBreak: tokenizer.paragraphBreak.map(Int.init), sourceDType: sourceDType, referenceNLL: nil, referenceSample: nil,\n                            stateBytesPerStream: StorageMath(config: config).stateBytesPerStream, createdAt: Date(timeIntervalSince1970: Date().timeIntervalSince1970.rounded(.down)))\n        progress(\"writing the pack\")\n        let directory = try Pack.write(info: info, embedding: embedding, norm: norm, blocks: blocks, tokenizerFiles: tokenizerFiles, into: packs)\n        return Imported(directory: directory, pack: try Pack.load(from: directory))\n    }\n\n    /// Records a greedy sample and the held-out NLL in pack.json after the trunk has run once.\n    public static func record(referenceNLL: Float?, sample: String?, in directory: URL) throws {\n        var info = try JSONCoding.read(PackInfo.self, from: directory.appendingPathComponent(Pack.infoFile))\n        info.referenceNLL = referenceNLL\n        info.referenceSample = sample\n        try JSONCoding.write(info, to: directory.appendingPathComponent(Pack.infoFile))\n    }\n}\n\nextension PackImporter {\n    /// The commit a downloaded snapshot folder was materialised at, when the hub recorded it.\n    public static func snapshotCommit(_ folder: URL) -> String? { HubDownloader.snapshotCommit(folder) }\n}\n"},{"path":"Sources/BraidKit/Build/Thread/ThreadRecords.swift","lines":131,"bytes":5691,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[],"first":1142,"scopes":[["S","ThreadInfo",null,"public",17,17,[17,55],26,null,-1,0],["S","ThreadVersionInfo",null,"public",28,28,[28,62],107,null,-1,0],["E","CodingKeys",null,"",52,52,[52,39],55,null,1,0,["version","packSHA256","seamSHA256","vocabularySHA256","tokenizerSHA256","cut","keyScheme","corpusHash","snapshotHash","trained","steps","epochs","learned","memorised","meanLoss","heldOutLoss","blocksSHA256","indexSHA256","checkpointsSHA256","entries","createdAt"]],["i","init",["from"],"public",57,57,[57,46],80,null,1,0],["i","init",["version","packSHA256","seamSHA256","vocabularySHA256","tokenizerSHA256","cut","keyScheme","corpusHash","snapshotHash","trained","steps","epochs","learned","memorised","meanLoss","heldOutLoss","blocksSHA256","indexSHA256","checkpointsSHA256","entries","createdAt"],"public",82,82,[84,95],106,null,1,0],["S","LiveInfo",null,"public",109,109,[109,53],109,null,-1,8],["S","TrainingTotals",null,"public",113,113,[113,50],131,[111,112],-1,0],["i","init",["steps","epochs","learned","heldOutLoss"],"public",119,119,[119,77],124,null,6,0],["i","init",["of"],"public",127,127,[127,48],130,[126,126],6,0]],"text":"//\n//  ThreadRecords.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A Thread's records on disk: thread.json (its name, label, source, lane, id and limit),\n//        version.json (what one version binds by hash: pack, tokenizer, blocks, key scheme,\n//        snapshot, index and checkpoints, with its training totals) and live.json (the version\n//        that serves).\n//\n\nimport BraidCore\nimport Foundation\n\npublic struct ThreadInfo: Codable, Sendable, Equatable {\n    public var name: String\n    public var label: String\n    public var source: String\n    public var lane: String?\n    public var threadID: String\n    public var createdAt: Date\n    /// For a dataset source: how many documents (in feeding order) the Thread took; nil = all.\n    public var limit: Int?\n}\n\npublic struct ThreadVersionInfo: Codable, Sendable, Equatable {\n    public var version: Int\n    public var packSHA256: String\n    public var seamSHA256: String\n    public var vocabularySHA256: String\n    public var tokenizerSHA256: String\n    public var cut: Int\n    public var keyScheme: KeyScheme\n    public var corpusHash: String\n    public var snapshotHash: String\n    public var trained: Bool\n    public var steps: Int\n    public var epochs: Int\n    public var learned: Bool\n    public var memorised: Float\n    public var meanLoss: Float\n    public var heldOutLoss: Float?\n    /// sha256 of blocks.safetensors, or the pack's name when the blocks are the pack's.\n    public var blocksSHA256: String\n    public var indexSHA256: String\n    public var checkpointsSHA256: String\n    public var entries: Int\n    public var createdAt: Date\n\n    enum CodingKeys: String, CodingKey {\n        case version, packSHA256, seamSHA256, vocabularySHA256, tokenizerSHA256, cut, keyScheme, corpusHash, snapshotHash, trained, steps, epochs, learned\n        case memorised, meanLoss, heldOutLoss, blocksSHA256, indexSHA256, checkpointsSHA256, entries, createdAt\n    }\n\n    public init(from decoder: Decoder) throws {\n        let c = try decoder.container(keyedBy: CodingKeys.self)\n        version = try c.decode(Int.self, forKey: .version)\n        packSHA256 = try c.decode(String.self, forKey: .packSHA256)\n        seamSHA256 = try c.decode(String.self, forKey: .seamSHA256)\n        vocabularySHA256 = try c.decode(String.self, forKey: .vocabularySHA256)\n        tokenizerSHA256 = try c.decode(String.self, forKey: .tokenizerSHA256)\n        cut = try c.decode(Int.self, forKey: .cut)\n        keyScheme = try c.decode(KeyScheme.self, forKey: .keyScheme)\n        corpusHash = try c.decode(String.self, forKey: .corpusHash)\n        snapshotHash = try c.decode(String.self, forKey: .snapshotHash)\n        trained = try c.decode(Bool.self, forKey: .trained)\n        steps = try c.decode(Int.self, forKey: .steps)\n        epochs = try c.decode(Int.self, forKey: .epochs)\n        learned = try c.decode(Bool.self, forKey: .learned)\n        memorised = try c.decode(Float.self, forKey: .memorised)\n        meanLoss = try c.decode(Float.self, forKey: .meanLoss)\n        heldOutLoss = try c.decodeIfPresent(Float.self, forKey: .heldOutLoss)\n        blocksSHA256 = try c.decode(String.self, forKey: .blocksSHA256)\n        indexSHA256 = try c.decode(String.self, forKey: .indexSHA256)\n        checkpointsSHA256 = try c.decode(String.self, forKey: .checkpointsSHA256)\n        entries = try c.decodeIfPresent(Int.self, forKey: .entries) ?? 0\n        createdAt = try c.decode(Date.self, forKey: .createdAt)\n    }\n\n    public init(version: Int, packSHA256: String, seamSHA256: String, vocabularySHA256: String, tokenizerSHA256: String, cut: Int, keyScheme: KeyScheme, corpusHash: String,\n                snapshotHash: String, trained: Bool, steps: Int, epochs: Int, learned: Bool, memorised: Float, meanLoss: Float, heldOutLoss: Float?, blocksSHA256: String,\n                indexSHA256: String, checkpointsSHA256: String, entries: Int, createdAt: Date) {\n        self.version = version\n        self.packSHA256 = packSHA256\n        self.seamSHA256 = seamSHA256\n        self.vocabularySHA256 = vocabularySHA256\n        self.tokenizerSHA256 = tokenizerSHA256\n        self.cut = cut\n        self.keyScheme = keyScheme\n        self.corpusHash = corpusHash\n        self.snapshotHash = snapshotHash\n        self.trained = trained\n        self.steps = steps\n        self.epochs = epochs\n        self.learned = learned\n        self.memorised = memorised\n        self.meanLoss = meanLoss\n        self.heldOutLoss = heldOutLoss\n        self.blocksSHA256 = blocksSHA256\n        self.indexSHA256 = indexSHA256\n        self.checkpointsSHA256 = checkpointsSHA256\n        self.entries = entries\n        self.createdAt = createdAt\n    }\n}\n\npublic struct LiveInfo: Codable, Sendable, Equatable { public var version: Int }\n\n/// What a version records of the training behind its blocks: optimizer steps and epochs in all,\n/// whether the last run learned, and that run's held-out loss.\npublic struct TrainingTotals: Sendable, Equatable {\n    public var steps: Int\n    public var epochs: Int\n    public var learned: Bool\n    public var heldOutLoss: Float?\n\n    public init(steps: Int, epochs: Int, learned: Bool, heldOutLoss: Float?) {\n        self.steps = steps\n        self.epochs = epochs\n        self.learned = learned\n        self.heldOutLoss = heldOutLoss\n    }\n\n    /// A version's own totals, carried to a version that is not trained further; nil when it never was trained.\n    public init?(of version: ThreadVersionInfo) {\n        guard version.trained else { return nil }\n        self.init(steps: version.steps, epochs: version.epochs, learned: version.learned, heldOutLoss: version.heldOutLoss)\n    }\n}\n"},{"path":"Sources/BraidKit/Build/Thread/ThreadStore.swift","lines":139,"bytes":9511,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[[111,"The live version's inputs"]],"first":1151,"scopes":[["E","ThreadStore",null,"public",18,18,[18,24],129,null,-1,0,[]],["f","list",["in"],"public static",22,22,[22,70],28,null,0,0],["f","create",["name","label","source","lane","limit","snapshot","in"],"public static",31,31,[31,188],42,[30,30],0,0],["f","info",["_"],"public static",44,44,[44,73],44,null,0,8],["f","live",["_"],"public static",46,46,[46,81],50,null,0,0],["f","nextVersion",["_"],"public static",52,52,[52,66],55,null,0,0],["f","index",["_","pack","trunk","tokenizer","snapshot","scheme","blocks","training","checkpoints","exclude","progress"],"public static",59,60,[62,123],70,[57,58],0,0],["f","writeIndex",["_","pack","trunk","reed","corpus","threadID","scheme","blocks","checkpoints","exclude","progress"],"public static",74,74,[75,167],91,[72,73],0,0],["f","writeVersion",["_","pack","snapshot","scheme","training"],"public static",94,94,[94,173],104,[93,93],0,0],["f","promote",["_","version"],"public static",107,107,[107,76],109,[106,106],0,0],["f","liveBlocks",["_","version","pack"],"static",114,114,[114,121],122,[113,113],0,0],["f","liveWithheld",["_","version"],"static",125,125,[125,103],128,[124,124],0,0],["S","WrittenIndex",null,"public",133,133,[133,27],139,[131,132],-1,0]],"text":"//\n//  ThreadStore.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A Thread on disk under threads/<name>/: its record, its snapshots by hash, its versions\n//        (version.json, blocks.safetensors when trained, index/ with checkpoints/), and live.json\n//        pointing at the version that serves. Loading a Thread gives a LocalNode on the live\n//        version (Run/Node/ThreadLoading.swift); every hash in the chain is re-derived on the way.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\n\npublic enum ThreadStore {\n    public static let blocksFile = \"blocks.safetensors\"\n    public static let indexDirectory = \"index\"\n\n    public static func list(in area: WorkArea) throws -> [ThreadInfo] {\n        guard FileManager.default.fileExists(atPath: area.threads.path) else { return [] }\n        return try FileManager.default.contentsOfDirectory(at: area.threads, includingPropertiesForKeys: nil)\n            .filter { FileManager.default.fileExists(atPath: $0.appendingPathComponent(\"thread.json\").path) }\n            .map { try JSONCoding.read(ThreadInfo.self, from: $0.appendingPathComponent(\"thread.json\")) }\n            .sorted { $0.createdAt < $1.createdAt }\n    }\n\n    /// Creates the Thread's record and saves its first snapshot; returns the layout.\n    public static func create(name: String, label: String?, source: CorpusSourceSpec, lane: String?, limit: Int? = nil, snapshot: CorpusSnapshot, in area: WorkArea) throws -> ThreadLayout {\n        guard DocumentID.isValidHandle(name) else { throw BraidFailure.usage(\"thread names are lowercase handles: \\(name)\") }\n        let layout = area.thread(name)\n        if FileManager.default.fileExists(atPath: layout.record.path) { throw BraidFailure.exists(\"thread \\(name) exists at \\(layout.root.path)\") }\n        try FileManager.default.createDirectory(at: layout.versions, withIntermediateDirectories: true)\n        try FileManager.default.createDirectory(at: layout.snapshots, withIntermediateDirectories: true)\n        let info = ThreadInfo(name: name, label: label ?? name.prefix(1).uppercased() + name.dropFirst(), source: source.description, lane: lane, threadID: UUID().uuidString.lowercased(),\n                              createdAt: Date(timeIntervalSince1970: Date().timeIntervalSince1970.rounded(.down)), limit: limit)\n        try JSONCoding.write(info, to: layout.record)\n        try snapshot.save(to: layout.snapshot(hash: snapshot.corpusHash))\n        return layout\n    }\n\n    public static func info(_ layout: ThreadLayout) throws -> ThreadInfo { try JSONCoding.read(ThreadInfo.self, from: layout.record) }\n\n    public static func live(_ layout: ThreadLayout) throws -> ThreadVersionInfo? {\n        guard FileManager.default.fileExists(atPath: layout.live.path) else { return nil }\n        let live = try JSONCoding.read(LiveInfo.self, from: layout.live)\n        return try JSONCoding.read(ThreadVersionInfo.self, from: layout.version(live.version).appendingPathComponent(\"version.json\"))\n    }\n\n    public static func nextVersion(_ layout: ThreadLayout) -> Int {\n        let existing = (try? FileManager.default.contentsOfDirectory(at: layout.versions, includingPropertiesForKeys: nil))?.compactMap { Int($0.lastPathComponent.dropFirst()) } ?? []\n        return (existing.max() ?? 0) + 1\n    }\n\n    /// Indexes a snapshot with the given trunk (the pack's blocks, or a trained version's) into a new\n    /// version and makes it live: `writeIndex`, `writeVersion`, `promote`.\n    @discardableResult\n    public static func index(_ layout: ThreadLayout, pack: Pack, trunk: Trunk, tokenizer: BraidTokenizer, snapshot: CorpusSnapshot, scheme: KeyScheme,\n                             blocks: [String: MLXArray]?, training: TrainingTotals?, checkpoints: CheckpointPolicy = CheckpointPolicy(),\n                             exclude: Set<String> = [], progress: (String) -> Void = { _ in }) throws -> ThreadVersionInfo {\n        let info = try info(layout)\n        let corpus = TokenizedCorpus(snapshot: snapshot, tokenizer: tokenizer, paragraphBreak: tokenizer.paragraphBreak, threadID: info.threadID)\n        let written = try writeIndex(layout, pack: pack, trunk: trunk, reed: pack.reed(tokens: tokenizer.vocabSize), corpus: corpus, threadID: info.threadID,\n                                     scheme: scheme, blocks: blocks, checkpoints: checkpoints, exclude: exclude, progress: progress)\n        let record = try writeVersion(written, pack: pack, snapshot: snapshot, scheme: scheme, training: training)\n        try promote(layout, version: record.version)\n        return record\n    }\n\n    /// A new version's directory with its blocks (when they are the Thread's own) and its index,\n    /// keyed on `trunk`. The version takes the next number when its directory is made.\n    public static func writeIndex(_ layout: ThreadLayout, pack: Pack, trunk: Trunk, reed: MLXReed, corpus: TokenizedCorpus, threadID: String, scheme: KeyScheme,\n                                  blocks: [String: MLXArray]?, checkpoints: CheckpointPolicy, exclude: Set<String>, progress: (String) -> Void) throws -> WrittenIndex {\n        let number = nextVersion(layout)\n        let directory = layout.version(number)\n        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)\n        var blocksSHA256 = pack.sha256\n        if let blocks {\n            let url = directory.appendingPathComponent(blocksFile)\n            try MLX.save(arrays: blocks, metadata: [\"format\": \"braid-thread-blocks-v1\", \"pack\": pack.sha256], url: url)\n            blocksSHA256 = try ContentHash.sha256Hex(fileAt: url)\n        }\n        var options = IndexBuildOptions(scheme: scheme)\n        options.checkpoints = checkpoints\n        options.exclude = exclude\n        let built = try IndexBuilder.build(trunk: trunk, reed: reed, corpus: corpus, pack: pack, blocksSHA256: blocksSHA256, threadID: threadID, options: options,\n                                           into: directory.appendingPathComponent(indexDirectory, isDirectory: true)) { d, n in if d % 50 == 0 { progress(\"indexing \\(d)/\\(n) documents\") } }\n        return WrittenIndex(version: number, directory: directory, trained: blocks != nil, blocksSHA256: blocksSHA256, built: built)\n    }\n\n    /// The version's record, version.json, binding what `writeIndex` wrote.\n    public static func writeVersion(_ written: WrittenIndex, pack: Pack, snapshot: CorpusSnapshot, scheme: KeyScheme, training: TrainingTotals?) throws -> ThreadVersionInfo {\n        let built = written.built\n        let record = ThreadVersionInfo(version: written.version, packSHA256: pack.sha256, seamSHA256: built.info.seamSHA256, vocabularySHA256: pack.info.vocabularySHA256,\n                                       tokenizerSHA256: pack.info.tokenizerSHA256, cut: built.info.cut, keyScheme: scheme, corpusHash: snapshot.corpusHash, snapshotHash: snapshot.corpusHash,\n                                       trained: written.trained, steps: training?.steps ?? 0, epochs: training?.epochs ?? 0, learned: training?.learned ?? false,\n                                       memorised: built.memorised, meanLoss: built.meanLoss, heldOutLoss: training?.heldOutLoss, blocksSHA256: written.blocksSHA256,\n                                       indexSHA256: built.info.indexSHA256, checkpointsSHA256: built.info.checkpointsSHA256, entries: built.info.count,\n                                       createdAt: Date(timeIntervalSince1970: Date().timeIntervalSince1970.rounded(.down)))\n        try JSONCoding.write(record, to: written.directory.appendingPathComponent(\"version.json\"))\n        return record\n    }\n\n    /// Makes `version` the one that serves (live.json).\n    public static func promote(_ layout: ThreadLayout, version: Int) throws {\n        try JSONCoding.write(LiveInfo(version: version), to: layout.live)\n    }\n\n    // MARK: The live version's inputs\n\n    /// The live version's own blocks, hash-checked (nil when it indexes the pack's blocks).\n    static func liveBlocks(_ layout: ThreadLayout, version: ThreadVersionInfo, pack: Pack) throws -> [String: MLXArray]? {\n        let url = layout.version(version.version).appendingPathComponent(ThreadStore.blocksFile)\n        guard FileManager.default.fileExists(atPath: url.path) else {\n            guard version.blocksSHA256 == pack.sha256 else { throw BraidFailure.data(\"v\\(version.version) names blocks that are not on disk\") }\n            return nil\n        }\n        guard try ContentHash.sha256Hex(fileAt: url) == version.blocksSHA256 else { throw BraidFailure.data(\"v\\(version.version): blocks.safetensors does not hash to its record\") }\n        return try loadArrays(url: url)\n    }\n\n    /// The documents the live version trained on but left out of its index (`--withhold`), kept out again.\n    static func liveWithheld(_ layout: ThreadLayout, version: ThreadVersionInfo) throws -> Set<String> {\n        let info = try JSONCoding.read(IndexInfo.self, from: layout.version(version.version).appendingPathComponent(ThreadStore.indexDirectory).appendingPathComponent(IndexFiles.info))\n        return Set(info.excluded ?? [])\n    }\n}\n\n/// A version's index on disk before its record is written: the number it took, its directory,\n/// whether its blocks are the Thread's own, their hash, and what the build measured.\npublic struct WrittenIndex {\n    public var version: Int\n    public var directory: URL\n    public var trained: Bool\n    public var blocksSHA256: String\n    public var built: IndexBuildResult\n}\n"},{"path":"Sources/BraidKit/Build/Training/DeltaHyper.swift","lines":63,"bytes":1863,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":1164,"scopes":[["S","DeltaHyper",null,"public",15,15,[15,55],38,null,-1,0],["i","init",[],"public",37,37,[37,18],37,null,0,8],["S","StepRow",null,"public",40,40,[40,41],48,null,-1,0],["S","EvalRow",null,"public",50,50,[50,41],57,null,-1,0],["E","TrainingEvent",null,"public",59,59,[59,36],63,null,-1,0,["step","eval","note"]]],"text":"//\n//  DeltaHyper.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: What a training run is told and what it reports, as plain values: the hyperparameters\n//        (DeltaHyper), one optimizer step's row, one evaluation's row, and the events the trainer\n//        hands its caller. The rows are what training-steps.jsonl and training-evals.jsonl hold.\n//\n\nimport Foundation\n\npublic struct DeltaHyper: Codable, Sendable, Equatable {\n    public var seqLen = 512\n    public var batchSize = 8\n    public var peakLR: Float = 5e-4\n    public var finalLR: Float = 1e-4\n    public var warmupFraction: Float = 0.05\n    public var beta1: Float = 0.9\n    public var beta2: Float = 0.95\n    public var eps: Float = 1e-8\n    public var weightDecay: Float = 0.01\n    public var gradClip: Float = 1.0\n    /// Optimizer steps planned from fresh blocks, and when continuing from a trained version.\n    public var scratchSteps = 1000\n    public var continueSteps = 500\n    public var evalSteps = 40\n    public var learnedThreshold: Float = 0.97\n    public var factsThreshold: Float = 0.90\n    public var memorisedNats: Float = 0.1\n    public var maxEpochs = 600\n    public var cacheLimitMB = 8192\n    public var seed: UInt64 = 42\n\n    public init() {}\n}\n\npublic struct StepRow: Codable, Sendable {\n    public var epoch: Int\n    public var step: Int\n    public var lr: Float\n    public var loss: Float\n    public var gradNorm: Float\n    public var tokens: Int\n    public var seconds: Double\n}\n\npublic struct EvalRow: Codable, Sendable {\n    public var epoch: Int\n    public var step: Int\n    public var meanLoss: Float\n    public var memorised: Float\n    public var factsMemorised: Float?\n    public var learned: Bool\n}\n\npublic enum TrainingEvent: Sendable {\n    case step(StepRow)\n    case eval(EvalRow)\n    case note(String)\n}\n"},{"path":"Sources/BraidKit/Build/Training/DeltaTrainer.swift","lines":203,"bytes":10886,"header":{"lines":[1,17],"what":[8,13],"pin":[14,16],"in":null,"out":null},"marks":[],"first":1169,"scopes":[["S","TrainingResult",null,"public",25,25,[25,29],35,null,-1,0],["S","BatchSampler",null,"public",38,38,[38,37],98,[37,37],-1,0],["i","init",["corpus","seqLen","batchSize","seed"],"public",46,46,[46,84],54,[45,45],1,0],["v","windows",null,"public",56,56,[56,28],56,null,1,8],["v","stepsPerEpoch",null,"public",57,57,[57,34],57,null,1,8],["f","plan",["epoch"],"public",60,60,[60,44],77,[59,59],1,0],["f","batch",["_"],"public",80,80,[80,114],97,[79,79],1,0],["E","DeltaTrainer",null,"public",100,100,[100,25],203,null,-1,0,[]],["f","learningRate",["step","planned","hyper"],"public static",102,102,[102,89],107,[101,101],7,0],["f","evaluate",["trunk","reed","corpus","facts","hyper"],"public static",111,111,[111,190],146,[109,110],7,0],["f","train",["trunk","reed","corpus","facts","hyper","continuing","shouldStop","onEvent"],"public static",149,149,[150,135],202,[148,148],7,0],["f","loss",["_","_"],"",159,159,[159,70],165,null,10,4]],"text":"//\n//  DeltaTrainer.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Trains a Thread's own blocks (0..<cut) in front of the frozen trunk on its snapshot:\n//        the stream eos ‖ d0 ‖ eos ‖ d1 ‖ … packed into windows on a seeded grid, resets at every\n//        eos so each document starts from a zero state (the condition the index is built under),\n//        AdamW with warmup then cosine, the loss masked where the input is eos. Every `evalSteps`\n//        steps the whole corpus is scored document by document; the Thread has learned when 97% of\n//        positions are memorised (loss < 0.1 nat) and 90% of its facts are, and training stops.\n//  PIN:  RaoLM's recipe with its attention artefacts removed: no eos-first windows, no document\n//        mask; the recurrent state's reset does both jobs. Backprop runs through all blocks, but\n//        only blocks before the cut carry gradients.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\nimport MLXNN\nimport MLXOptimizers\n\npublic struct TrainingResult {\n    public var blocks: [String: MLXArray]\n    public var steps: Int\n    public var epochs: Int\n    public var learned: Bool\n    public var memorised: Float\n    public var factsMemorised: Float?\n    public var heldOutLoss: Float?\n    public var stepRows: [StepRow]\n    public var evalRows: [EvalRow]\n}\n\n/// The training stream and its seeded window grid.\npublic struct BatchSampler: Sendable {\n    public var stream: [Int32]\n    public var eos: Int32\n    public var seqLen: Int\n    public var batchSize: Int\n    public var seed: UInt64\n\n    /// eos ‖ d0 ‖ eos ‖ d1 ‖ … ‖ eos: one eos between documents.\n    public init(corpus: TokenizedCorpus, seqLen: Int, batchSize: Int, seed: UInt64) {\n        var stream: [Int32] = [corpus.eos]\n        for document in corpus.documents { stream.append(contentsOf: document.tokens.dropFirst()) }\n        self.stream = stream\n        eos = corpus.eos\n        self.seqLen = seqLen\n        self.batchSize = batchSize\n        self.seed = seed\n    }\n\n    public var windows: Int { max(1, (stream.count - 1) / seqLen) }\n    public var stepsPerEpoch: Int { max(1, Int((Double(windows) / Double(batchSize)).rounded(.up))) }\n\n    /// The window starts of one epoch: a seeded offset into the first window, then every seqLen, shuffled and batched.\n    public func plan(epoch: Int) -> [[Int]] {\n        var rng = SplitMix64(seed: seed &+ UInt64(epoch) &* 0x9E37_79B9)\n        let room = max(1, min(seqLen, stream.count - seqLen - 1))\n        let offset = Int(rng.next() % UInt64(room))\n        var starts = Array(stride(from: offset, to: stream.count - seqLen - 1, by: seqLen))\n        if starts.isEmpty { starts = [0] }\n        starts.shuffle(using: &rng)\n        var batches: [[Int]] = []\n        var i = 0\n        while i < starts.count {\n            var batch = Array(starts[i ..< min(i + batchSize, starts.count)])\n            var fill = 0\n            while batch.count < batchSize { batch.append(starts[fill % starts.count]); fill += 1 }\n            batches.append(batch)\n            i += batchSize\n        }\n        return batches\n    }\n\n    /// inputs, targets [B,T] int32; mask [B,T] f32 (0 where the input is eos); resets [B,T] bool (the input is eos).\n    public func batch(_ starts: [Int]) -> (inputs: MLXArray, targets: MLXArray, mask: MLXArray, resets: MLXArray) {\n        var inputs: [Int32] = []\n        var targets: [Int32] = []\n        var mask: [Float] = []\n        var resets: [Bool] = []\n        for start in starts {\n            let s = min(start, stream.count - seqLen - 1)\n            for t in 0..<seqLen {\n                let x = stream[s + t]\n                inputs.append(x)\n                targets.append(stream[s + t + 1])\n                mask.append(x == eos ? 0 : 1)\n                resets.append(x == eos)\n            }\n        }\n        let shape = [starts.count, seqLen]\n        return (MLXArray(inputs, shape), MLXArray(targets, shape), MLXArray(mask, shape), MLXArray(resets, shape))\n    }\n}\n\npublic enum DeltaTrainer {\n    /// Warmup from 1% of the peak over `warmupFraction` of the plan, then cosine to the floor.\n    public static func learningRate(step: Int, planned: Int, hyper: DeltaHyper) -> Float {\n        let warm = max(1, Int(Float(planned) * hyper.warmupFraction))\n        if step < warm { return hyper.peakLR * (0.01 + 0.99 * Float(step) / Float(warm)) }\n        let progress = min(1, Float(step - warm) / Float(max(1, planned - warm)))\n        return hyper.finalLR + 0.5 * (hyper.peakLR - hyper.finalLR) * (1 + cos(Float.pi * progress))\n    }\n\n    /// The eval pass: every document from a zero state; per position whether the next token is\n    /// memorised (loss < memorisedNats); facts memorised when every answer token is.\n    public static func evaluate(trunk: Trunk, reed: MLXReed, corpus: TokenizedCorpus, facts: [LocatedFact], hyper: DeltaHyper) -> (meanLoss: Float, memorised: Float, factsMemorised: Float?) {\n        var total: Double = 0\n        var count = 0\n        var memorised = 0\n        var lossByRow: [Int: [Float]] = [:]\n        for document in corpus.documents {\n            let tokens = document.tokens\n            guard tokens.count >= 2 else { continue }\n            let out = trunk.forward(tokens: MLXArray(tokens, [1, tokens.count]), state: nil, resets: nil)\n            let logits = reed.logits(array: out.final[0, 0 ..< tokens.count - 1])\n            let (loss, _) = MLXReed.tokenStats(logits: logits, targets: MLXArray(Array(tokens[1...])))\n            eval(loss)\n            let values = loss.asArray(Float.self)\n            for t in 0 ..< tokens.count - 1 where tokens[t] != corpus.eos {\n                total += Double(values[t])\n                count += 1\n                if values[t] < hyper.memorisedNats { memorised += 1 }\n                let address = document.addresses[t + 1]\n                if address.row >= 0 {\n                    var row = lossByRow[address.row] ?? [Float](repeating: .infinity, count: corpus.partitions[address.row].tokens.count + corpus.breakLength)\n                    if address.offset < row.count { row[address.offset] = values[t] }\n                    lossByRow[address.row] = row\n                }\n            }\n        }\n        var factsMemorised: Float? = nil\n        if !facts.isEmpty {\n            let learned = facts.filter { fact in\n                guard let row = lossByRow[fact.row] else { return false }\n                return (fact.answerToken ..< fact.answerEndToken).allSatisfy { $0 < row.count && row[$0] < hyper.memorisedNats }\n            }.count\n            factsMemorised = Float(learned) / Float(facts.count)\n        }\n        Memory.clearCache()\n        return (count > 0 ? Float(total / Double(count)) : 0, count > 0 ? Float(memorised) / Float(count) : 0, factsMemorised)\n    }\n\n    /// Trains the trunk's own blocks in place; returns them with the run's record.\n    public static func train(trunk: Trunk, reed: MLXReed, corpus: TokenizedCorpus, facts: [LocatedFact], hyper: DeltaHyper, continuing: Bool,\n                             shouldStop: () -> Bool = { false }, onEvent: (TrainingEvent) -> Void = { _ in }) throws -> TrainingResult {\n        Memory.cacheLimit = hyper.cacheLimitMB * 1_048_576\n        let sampler = BatchSampler(corpus: corpus, seqLen: hyper.seqLen, batchSize: hyper.batchSize, seed: hyper.seed)\n        let planned = continuing ? hyper.continueSteps : hyper.scratchSteps\n        let epochs = min(hyper.maxEpochs, max(8, Int((Double(planned) / Double(sampler.stepsPerEpoch)).rounded(.up))))\n        let evalEvery = max(1, hyper.evalSteps / sampler.stepsPerEpoch)\n        onEvent(.note(\"stream \\(sampler.stream.count) tokens, \\(sampler.windows) windows of \\(hyper.seqLen), \\(sampler.stepsPerEpoch) steps/epoch, \\(epochs) epochs planned, eval every \\(evalEvery) epochs\"))\n        let optimizer = AdamW(learningRate: hyper.peakLR, betas: (hyper.beta1, hyper.beta2), eps: hyper.eps, weightDecay: hyper.weightDecay, biasCorrection: true)\n        let hiddenSize = trunk.config.hiddenSize\n        func loss(_ model: Trunk, _ arrays: [MLXArray]) -> [MLXArray] {\n            let out = model.forward(tokens: arrays[0], state: nil, resets: arrays[3], training: true)\n            let logits = reed.logits(array: out.final.reshaped([-1, hiddenSize]))\n            let (perToken, _) = MLXReed.tokenStats(logits: logits, targets: arrays[1].reshaped([-1]))\n            let mask = arrays[2].reshaped([-1])\n            return [(perToken * mask).sum() / maximum(mask.sum(), MLXArray(Float(1)))]\n        }\n        let lossAndGrad = valueAndGrad(model: trunk, loss)\n        var stepRows: [StepRow] = []\n        var evalRows: [EvalRow] = []\n        var step = 0\n        var learned = false\n        var lastEval: (Float, Float, Float?) = (0, 0, nil)\n        let started = Date()\n        epochLoop: for epoch in 0..<epochs {\n            for starts in sampler.plan(epoch: epoch) {\n                if shouldStop() { break epochLoop }\n                let lr = learningRate(step: step, planned: planned, hyper: hyper)\n                optimizer.learningRate = lr\n                let batch = sampler.batch(starts)\n                let (values, gradients) = lossAndGrad(trunk, [batch.inputs, batch.targets, batch.mask, batch.resets])\n                let (clipped, norm) = clipGradNorm(gradients: gradients, maxNorm: hyper.gradClip)\n                optimizer.update(model: trunk, gradients: clipped)\n                eval(trunk, optimizer, values[0], norm)\n                step += 1\n                let row = StepRow(epoch: epoch, step: step, lr: lr, loss: values[0].item(Float.self), gradNorm: norm.item(Float.self),\n                                  tokens: starts.count * hyper.seqLen, seconds: Date().timeIntervalSince(started))\n                stepRows.append(row)\n                onEvent(.step(row))\n            }\n            if (epoch + 1) % evalEvery == 0 || epoch == epochs - 1 {\n                lastEval = evaluate(trunk: trunk, reed: reed, corpus: corpus, facts: facts, hyper: hyper)\n                learned = lastEval.1 >= hyper.learnedThreshold && (lastEval.2 ?? 1) >= hyper.factsThreshold\n                let row = EvalRow(epoch: epoch, step: step, meanLoss: lastEval.0, memorised: lastEval.1, factsMemorised: lastEval.2, learned: learned)\n                evalRows.append(row)\n                onEvent(.eval(row))\n                if learned { break }\n            }\n        }\n        let flat = trunk.flattenedParameters()\n        let blocks = Dictionary(uniqueKeysWithValues: flat.filter { Trunk.blockIndex(ofKey: $0.0).map { $0 < trunk.config.cut } ?? false })\n        return TrainingResult(blocks: blocks, steps: step, epochs: evalRows.last.map { $0.epoch + 1 } ?? 0, learned: learned, memorised: lastEval.1,\n                              factsMemorised: lastEval.2, heldOutLoss: nil, stepRows: stepRows, evalRows: evalRows)\n    }\n}\n"},{"path":"Sources/BraidKit/Build/Training/TrunkMeasure.swift","lines":102,"bytes":5195,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[],"first":1181,"scopes":[["S","MeasureRow",null,"public",20,20,[20,55],27,null,-1,0],["S","MeasureReport",null,"public",29,29,[29,58],35,null,-1,0],["E","TrunkMeasure",null,"public",37,37,[37,25],102,null,-1,0,[]],["f","run",["pack","vocabTokens","shapes","chunks","repeats","progress"],"public static",41,41,[42,90],101,null,2,0],["f","loss",["_","_"],"",72,72,[72,78],78,null,3,4],["f","step",[],"",81,81,[81,28],86,null,3,4]],"text":"//\n//  TrunkMeasure.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid init --measure`: what the trunk costs on this machine before anything is trained —\n//        forward tokens per second, one training step (forward and backward through every block,\n//        gradients for the Thread's blocks only, clipped, AdamW) in seconds, and the peak memory — at\n//        each batch × length the plan names, for each scan chunk size.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\nimport MLXNN\nimport MLXOptimizers\n\npublic struct MeasureRow: Codable, Sendable, Equatable {\n    public var batch: Int\n    public var length: Int\n    public var chunk: Int\n    public var forwardTokensPerSecond: Double\n    public var stepSeconds: Double\n    public var peakGB: Double\n}\n\npublic struct MeasureReport: Codable, Sendable, Equatable {\n    public var bench = \"measure\"\n    public var createdAt: Date\n    public var pack: String\n    public var device: String\n    public var rows: [MeasureRow]\n}\n\npublic enum TrunkMeasure {\n    public static let shapes: [(batch: Int, length: Int)] = [(4, 512), (8, 512), (4, 1024), (8, 1024)]\n    public static let chunks = [256, 128]\n\n    public static func run(pack: Pack, vocabTokens: Int, shapes: [(batch: Int, length: Int)] = shapes, chunks: [Int] = chunks, repeats: Int = 3,\n                           progress: (String) -> Void = { _ in }) throws -> MeasureReport {\n        var rows: [MeasureRow] = []\n        let reed = pack.reed(tokens: vocabTokens)\n        let commons = try Trunk(pack: pack)                                                 // the tail every shape's head runs behind\n        for chunk in chunks {\n            for shape in shapes {\n                let trunk = Trunk(head: try Trunk.packHead(pack), tail: commons.tail)\n                trunk.config.chunkSize = chunk\n                eval(trunk)\n                var rng = SplitMix64(seed: 42)\n                let ids = (0 ..< shape.batch * shape.length).map { _ in Int32(1 + rng.next() % UInt64(max(2, vocabTokens - 1))) }\n                let tokens = MLXArray(ids, [shape.batch, shape.length])\n                let targets = MLXArray(Array(ids.dropFirst()) + [0], [shape.batch, shape.length])\n                let mask = MLXArray.ones([shape.batch, shape.length], dtype: .float32)\n                let resets = MLXArray.zeros([shape.batch, shape.length], dtype: .bool)\n                Memory.clearCache()\n                Memory.peakMemory = 0\n\n                // Forward only, as the index builder and the node run it.\n                var out = trunk.forward(tokens: tokens, state: nil, resets: nil)\n                eval(out.final)\n                var started = Date()\n                for _ in 0 ..< repeats {\n                    out = trunk.forward(tokens: tokens, state: nil, resets: nil)\n                    eval(out.final)\n                }\n                let forwardSeconds = Date().timeIntervalSince(started) / Double(repeats)\n\n                // One training step, as DeltaTrainer runs it.\n                let hidden = trunk.config.hiddenSize\n                func loss(_ model: Trunk, _ arrays: [MLXArray]) -> [MLXArray] {\n                    let out = model.forward(tokens: arrays[0], state: nil, resets: arrays[3], training: true)\n                    let logits = reed.logits(array: out.final.reshaped([-1, hidden]))\n                    let (perToken, _) = MLXReed.tokenStats(logits: logits, targets: arrays[1].reshaped([-1]))\n                    let m = arrays[2].reshaped([-1])\n                    return [(perToken * m).sum() / maximum(m.sum(), MLXArray(Float(1)))]\n                }\n                let lossAndGrad = valueAndGrad(model: trunk, loss)\n                let optimizer = AdamW(learningRate: 1e-5, betas: (0.9, 0.95), eps: 1e-8, weightDecay: 0.01, biasCorrection: true)\n                func step() {\n                    let (values, gradients) = lossAndGrad(trunk, [tokens, targets, mask, resets])\n                    let (clipped, norm) = clipGradNorm(gradients: gradients, maxNorm: 1)\n                    optimizer.update(model: trunk, gradients: clipped)\n                    eval(trunk, optimizer, values[0], norm)\n                }\n                step()\n                started = Date()\n                for _ in 0 ..< repeats { step() }\n                let stepSeconds = Date().timeIntervalSince(started) / Double(repeats)\n                let row = MeasureRow(batch: shape.batch, length: shape.length, chunk: chunk,\n                                     forwardTokensPerSecond: Double(shape.batch * shape.length) / forwardSeconds, stepSeconds: stepSeconds,\n                                     peakGB: Double(Memory.peakMemory) / 1_073_741_824)\n                rows.append(row)\n                progress(String(format: \"B %d · L %d · chunk %d: forward %.0f tokens/s · step %.2f s · peak %.1f GB\", row.batch, row.length, row.chunk,\n                                row.forwardTokensPerSecond, row.stepSeconds, row.peakGB))\n                Memory.clearCache()\n            }\n        }\n        return MeasureReport(createdAt: Date(), pack: pack.sha256, device: ProcessInfo.processInfo.hostName, rows: rows)\n    }\n}\n"},{"path":"Sources/BraidKit/Model/LayerState.swift","lines":131,"bytes":5728,"header":{"lines":[1,12],"what":[8,11],"pin":null,"in":null,"out":null},"marks":[],"first":1187,"scopes":[["S","LayerState",null,"public",18,18,[18,25],31,null,-1,0],["i","init",["conv","ssm"],"public",22,22,[22,47],25,null,0,0],["f","zeros",["config","batch"],"public static",27,27,[27,77],30,null,0,0],["S","StateStack",null,"public",33,33,[33,25],131,null,-1,0],["i","init",["layers","position","prefixSHA256"],"public",40,40,[40,87],44,null,3,0],["f","zeros",["config","batch"],"public static",46,46,[46,77],48,null,3,0],["f","byteCount",["config"],"public static",50,50,[50,62],50,null,3,8],["v","batch",null,"public",52,52,[52,26],52,null,3,8],["f","copy",[],"public",55,55,[55,37],59,[54,54],3,0],["f","select",["batch"],"public",62,62,[62,55],64,[61,61],3,0],["v","arrays",null,"public",66,66,[66,42],73,null,3,0],["f","metadata",["packSHA256"],"public",77,77,[77,66],82,null,3,0],["f","save",["to","packSHA256"],"public",84,84,[84,62],87,null,3,0],["f","load",["from","expecting"],"public static",89,89,[89,96],93,null,3,0],["f","from",["arrays","metadata","expecting"],"public static",95,95,[95,137],105,null,3,0],["f","data",["packSHA256"],"public",108,108,[108,57],113,[107,107],3,0],["f","from",["data","expecting"],"public static",115,115,[115,93],118,null,3,0],["v","sha256",null,"public",121,121,[121,30],130,[120,120],3,0]],"text":"//\n//  LayerState.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The recurrent state: per layer the conv window [B,K−1,convDim] and the SSM state\n//        [B,H,P,N]; the stack of all layers is a node's history artifact — fixed size whatever the\n//        context length, checkpointable, transferable. Every place RaoLM held a KV cache, Braid\n//        holds one of these.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\n\npublic struct LayerState {\n    public var conv: MLXArray\n    public var ssm: MLXArray\n\n    public init(conv: MLXArray, ssm: MLXArray) {\n        self.conv = conv\n        self.ssm = ssm\n    }\n\n    public static func zeros(config: Mamba2Config, batch: Int) -> LayerState {\n        LayerState(conv: MLXArray.zeros([batch, config.convKernel - 1, config.convDim], dtype: .float32),\n                   ssm: MLXArray.zeros([batch, config.numHeads, config.headDim, config.stateSize], dtype: .float32))\n    }\n}\n\npublic struct StateStack {\n    public var layers: [LayerState]\n    /// Tokens consumed so far (−1 before any).\n    public var position: Int\n    /// sha256 of the consumed token ids as little-endian int32, when known.\n    public var prefixSHA256: String?\n\n    public init(layers: [LayerState], position: Int = -1, prefixSHA256: String? = nil) {\n        self.layers = layers\n        self.position = position\n        self.prefixSHA256 = prefixSHA256\n    }\n\n    public static func zeros(config: Mamba2Config, batch: Int) -> StateStack {\n        StateStack(layers: (0..<config.numHiddenLayers).map { _ in LayerState.zeros(config: config, batch: batch) })\n    }\n\n    public static func byteCount(config: Mamba2Config) -> Int { StorageMath(config: config).stateBytesPerStream }\n\n    public var batch: Int { layers.first?.ssm.dim(0) ?? 0 }\n\n    /// A deep copy (MLX arrays are values once evaluated; this forces one).\n    public func copy() -> StateStack {\n        let copied = layers.map { LayerState(conv: $0.conv + 0, ssm: $0.ssm + 0) }\n        eval(copied.flatMap { [$0.conv, $0.ssm] })\n        return StateStack(layers: copied, position: position, prefixSHA256: prefixSHA256)\n    }\n\n    /// One stream of a batched stack.\n    public func select(batch index: Int) -> StateStack {\n        StateStack(layers: layers.map { LayerState(conv: $0.conv[index ..< index + 1], ssm: $0.ssm[index ..< index + 1]) }, position: position, prefixSHA256: prefixSHA256)\n    }\n\n    public var arrays: [String: MLXArray] {\n        var out: [String: MLXArray] = [:]\n        for (i, layer) in layers.enumerated() {\n            out[\"layer.\\(i).conv\"] = layer.conv\n            out[\"layer.\\(i).ssm\"] = layer.ssm\n        }\n        return out\n    }\n\n    public static let format = \"braid-state-stack-v1\"\n\n    public func metadata(packSHA256: String?) -> [String: String] {\n        var m = [\"format\": Self.format, \"position\": String(position), \"layers\": String(layers.count)]\n        if let prefixSHA256 { m[\"prefixSHA256\"] = prefixSHA256 }\n        if let packSHA256 { m[\"packSHA256\"] = packSHA256 }\n        return m\n    }\n\n    public func save(to url: URL, packSHA256: String?) throws {\n        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)\n        try MLX.save(arrays: arrays, metadata: metadata(packSHA256: packSHA256), url: url)\n    }\n\n    public static func load(from url: URL, expecting config: Mamba2Config) throws -> StateStack {\n        let (arrays, metadata) = try loadArraysAndMetadata(url: url)\n        guard metadata[\"format\"] == format else { throw BraidFailure.data(\"\\(url.lastPathComponent) is not a state stack\") }\n        return try from(arrays: arrays, metadata: metadata, expecting: config)\n    }\n\n    public static func from(arrays: [String: MLXArray], metadata: [String: String], expecting config: Mamba2Config) throws -> StateStack {\n        var layers: [LayerState] = []\n        for i in 0..<config.numHiddenLayers {\n            guard let conv = arrays[\"layer.\\(i).conv\"], let ssm = arrays[\"layer.\\(i).ssm\"] else { throw BraidFailure.data(\"state stack lacks layer \\(i)\") }\n            guard ssm.dim(1) == config.numHeads, ssm.dim(2) == config.headDim, ssm.dim(3) == config.stateSize, conv.dim(2) == config.convDim else {\n                throw BraidFailure.data(\"state stack layer \\(i) has the wrong shape for this pack\")\n            }\n            layers.append(LayerState(conv: conv, ssm: ssm))\n        }\n        return StateStack(layers: layers, position: Int(metadata[\"position\"] ?? \"-1\") ?? -1, prefixSHA256: metadata[\"prefixSHA256\"])\n    }\n\n    /// The safetensors bytes (for a checkpoint that travels).\n    public func data(packSHA256: String?) throws -> Data {\n        let url = FileManager.default.temporaryDirectory.appendingPathComponent(\"braid-state-\\(UUID().uuidString).safetensors\")\n        defer { try? FileManager.default.removeItem(at: url) }\n        try save(to: url, packSHA256: packSHA256)\n        return try Data(contentsOf: url)\n    }\n\n    public static func from(data: Data, expecting config: Mamba2Config) throws -> StateStack {\n        let (arrays, metadata) = try loadArraysAndMetadata(data: data)\n        return try from(arrays: arrays, metadata: metadata, expecting: config)\n    }\n\n    /// SHA-256 over every layer's f32 little-endian bytes, conv then ssm, layers in order.\n    public var sha256: String {\n        var parts: [Data] = []\n        for layer in layers {\n            for array in [layer.conv, layer.ssm] {\n                let floats = array.asType(.float32).asArray(Float.self)\n                parts.append(floats.withUnsafeBufferPointer { Data(buffer: $0) })\n            }\n        }\n        return ContentHash.sha256Hex(parts: parts)\n    }\n}\n"},{"path":"Sources/BraidKit/Model/MLXReed.swift","lines":69,"bytes":2806,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":1205,"scopes":[["C","MLXReed",null,"public final",17,17,[17,54],69,null,-1,0],["i","init",["embedding","vocabularySHA256","tokens"],"public",26,26,[26,76],40,[25,25],0,0],["f","logits",["_"],"public",42,42,[42,64],50,null,0,0],["f","logits",["array"],"public",53,53,[53,59],57,[52,52],0,0],["f","tokenStats",["logits","targets"],"public static",62,62,[62,110],68,[59,61],0,0]],"text":"//\n//  MLXReed.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The reed on MLX: logits = state · Eᵀ over the pack's embedding, padding rows (the\n//        embedding rows past the tokenizer's vocabulary) set to −∞ so they never carry probability.\n//        The cluster calls it once per node per position; it never re-norms.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\n\npublic final class MLXReed: Reed, @unchecked Sendable {\n    public let vocabularySHA256: String\n    public let hiddenSize: Int\n    public let vocabulary: Int\n    public let tokens: Int\n    private let embeddingT: MLXArray\n    private let padding: MLXArray?\n\n    /// `tokens` is the tokenizer's vocabulary size; rows at or past it are padding.\n    public init(embedding: MLXArray, vocabularySHA256: String, tokens: Int) {\n        self.vocabularySHA256 = vocabularySHA256\n        hiddenSize = embedding.dim(1)\n        vocabulary = embedding.dim(0)\n        self.tokens = tokens\n        embeddingT = embedding.asType(.float32).T\n        if tokens < vocabulary {\n            var mask = [Float](repeating: 0, count: vocabulary)\n            for i in tokens..<vocabulary { mask[i] = -.infinity }\n            padding = MLXArray(mask)\n        } else {\n            padding = nil\n        }\n        eval(embeddingT)\n    }\n\n    public func logits(_ states: [[Float]]) throws -> [[Float]] {\n        guard !states.isEmpty else { return [] }\n        let x = MLXArray(states.flatMap { $0 }, [states.count, hiddenSize])\n        var logits = matmul(x, embeddingT)\n        if let padding { logits = logits + padding }\n        eval(logits)\n        let flat = logits.asArray(Float.self)\n        return (0..<states.count).map { Array(flat[$0 * vocabulary ..< ($0 + 1) * vocabulary]) }\n    }\n\n    /// Logits for a batch of states already on the GPU: [n,D] → [n,V].\n    public func logits(array states: MLXArray) -> MLXArray {\n        var logits = matmul(states.asType(.float32), embeddingT)\n        if let padding { logits = logits + padding }\n        return logits\n    }\n\n    /// Per-token cross-entropy and predictive entropy from logits [n,V] and targets [n] (int32), f32.\n    /// The entropy sums p·logit only where p > 0: a padding row's p is 0 and its logit −∞, and\n    /// 0·−∞ would make every entropy NaN.\n    public static func tokenStats(logits: MLXArray, targets: MLXArray) -> (loss: MLXArray, entropy: MLXArray) {\n        let lse = logSumExp(logits, axis: -1)\n        let picked = takeAlong(logits, targets[.ellipsis, .newAxis], axis: -1).squeezed(axis: -1)\n        let probabilities = softmax(logits, axis: -1)\n        let entropy = lse - which(probabilities .> Float(0), probabilities * logits, Float(0)).sum(axis: -1)\n        return (lse - picked, entropy)\n    }\n}\n"},{"path":"Sources/BraidKit/Model/Mamba2Block.swift","lines":115,"bytes":5511,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":1210,"scopes":[["C","GatedRMSNorm",null,"final",18,18,[18,33],31,[17,17],-1,0],["i","init",["dimensions","eps"],"",22,22,[22,38],26,null,0,0],["f","callAsFunction",["_","gate"],"",28,28,[28,67],30,null,0,0],["C","Mamba2Mixer",null,"public final",33,33,[33,39],94,null,-1,0],["i","init",["_"],"public",44,44,[44,40],55,null,3,0],["f","split",["_"],"private",57,57,[57,95],60,null,3,0],["f","splitConv",["_"],"private",62,62,[62,87],65,null,3,0],["f","callAsFunction",["_","state","resets","chunk"],"public",68,68,[68,123],79,[67,67],3,0],["f","step",["_","state","reset"],"public",82,82,[82,99],93,[81,81],3,0],["C","Mamba2Block",null,"public final",96,96,[96,39],115,null,-1,0],["i","init",["_"],"public",100,100,[100,40],104,null,9,0],["f","callAsFunction",["_","state","resets","chunk"],"public",106,106,[106,123],109,null,9,0],["f","step",["_","state","reset"],"public",111,111,[111,99],114,null,9,0]],"text":"//\n//  Mamba2Block.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: One Mamba2 block, parameter for parameter as the checkpoint names them: `norm`, then the\n//        mixer's `in_proj`, `conv1d`, `dt_bias`, `A_log`, `D`, `norm` (gated) and `out_proj`.\n//        The block is x + mixer(norm(x)); Mamba2 has no MLP, so Braid adds none.\n//\n\nimport Foundation\nimport MLX\nimport MLXNN\n\n/// silu(gate) · x, then an RMS norm with a learned weight.\nfinal class GatedRMSNorm: Module {\n    @ParameterInfo(key: \"weight\") var weight: MLXArray\n    let eps: Float\n\n    init(dimensions: Int, eps: Float) {\n        self.eps = eps\n        _weight.wrappedValue = MLXArray.ones([dimensions])\n        super.init()\n    }\n\n    func callAsFunction(_ x: MLXArray, gate: MLXArray) -> MLXArray {\n        MLXFast.rmsNorm(x * silu(gate), weight: weight, eps: eps)\n    }\n}\n\npublic final class Mamba2Mixer: Module {\n    let config: Mamba2Config\n\n    @ModuleInfo(key: \"in_proj\") var inProj: Linear\n    @ModuleInfo(key: \"conv1d\") var conv1d: Conv1d\n    @ParameterInfo(key: \"dt_bias\") var dtBias: MLXArray\n    @ParameterInfo(key: \"A_log\") var aLog: MLXArray\n    @ParameterInfo(key: \"D\") var dSkip: MLXArray\n    @ModuleInfo(key: \"norm\") var norm: GatedRMSNorm\n    @ModuleInfo(key: \"out_proj\") var outProj: Linear\n\n    public init(_ config: Mamba2Config) {\n        self.config = config\n        let projection = config.intermediate + config.convDim + config.numHeads\n        _inProj.wrappedValue = Linear(config.hiddenSize, projection, bias: config.useBias)\n        _conv1d.wrappedValue = Conv1d(inputChannels: config.convDim, outputChannels: config.convDim, kernelSize: config.convKernel, groups: config.convDim, bias: config.useConvBias)\n        _dtBias.wrappedValue = MLXArray.ones([config.numHeads])\n        _aLog.wrappedValue = log(MLXArray(1 ... config.numHeads).asType(.float32))\n        _dSkip.wrappedValue = MLXArray.ones([config.numHeads])\n        _norm.wrappedValue = GatedRMSNorm(dimensions: config.intermediate, eps: config.layerNormEpsilon)\n        _outProj.wrappedValue = Linear(config.intermediate, config.hiddenSize, bias: config.useBias)\n        super.init()\n    }\n\n    private func split(_ projected: MLXArray) -> (gate: MLXArray, xbc: MLXArray, dt: MLXArray) {\n        let parts = MLX.split(projected, indices: [config.intermediate, config.intermediate + config.convDim], axis: -1)\n        return (parts[0], parts[1], parts[2])\n    }\n\n    private func splitConv(_ xbc: MLXArray) -> (x: MLXArray, b: MLXArray, c: MLXArray) {\n        let parts = MLX.split(xbc, indices: [config.intermediate, config.intermediate + config.nGroups * config.stateSize], axis: -1)\n        return (parts[0], parts[1], parts[2])\n    }\n\n    /// A sequence. h [B,L,D]; `state` the layer's state before it (nil = zeros); `resets` [B,L].\n    public func callAsFunction(_ h: MLXArray, state: LayerState?, resets: MLXArray?, chunk: Int) -> (MLXArray, LayerState) {\n        let (b, l, _) = (h.dim(0), h.dim(1), h.dim(2))\n        let (gate, xbcRaw, dt) = split(inProj(h))\n        let (convOut, window) = SSD.causalConv(x: xbcRaw, weight: conv1d.weight, bias: conv1d.bias, window: state?.conv, resets: resets)\n        let (xs, bs, cs) = splitConv(silu(convOut))\n        let x = xs.reshaped([b, l, config.numHeads, config.headDim])\n        let bm = bs.reshaped([b, l, config.nGroups, config.stateSize])\n        let cm = cs.reshaped([b, l, config.nGroups, config.stateSize])\n        let (y, ssm) = SSD.scan(x: x, dt: dt, aLog: aLog, B: bm, C: cm, D: dSkip, dtBias: dtBias, limits: config.limits, state: state?.ssm, resets: resets, chunk: chunk)\n        let out = outProj(norm(y.reshaped([b, l, config.intermediate]), gate: gate))\n        return (out, LayerState(conv: window, ssm: ssm))\n    }\n\n    /// One token. h [B,D].\n    public func step(_ h: MLXArray, state: LayerState, reset: MLXArray?) -> (MLXArray, LayerState) {\n        let b = h.dim(0)\n        let (gate, xbcRaw, dt) = split(inProj(h))\n        let (convOut, window) = SSD.convStep(x: xbcRaw, weight: conv1d.weight, bias: conv1d.bias, window: state.conv, reset: reset)\n        let (xs, bs, cs) = splitConv(silu(convOut))\n        let x = xs.reshaped([b, config.numHeads, config.headDim])\n        let bm = bs.reshaped([b, config.nGroups, config.stateSize])\n        let cm = cs.reshaped([b, config.nGroups, config.stateSize])\n        let (y, ssm) = SSD.step(x: x, dt: dt, aLog: aLog, B: bm, C: cm, D: dSkip, dtBias: dtBias, limits: config.limits, state: state.ssm, reset: reset)\n        let out = outProj(norm(y.reshaped([b, config.intermediate]), gate: gate))\n        return (out, LayerState(conv: window, ssm: ssm))\n    }\n}\n\npublic final class Mamba2Block: Module {\n    @ModuleInfo(key: \"norm\") var norm: RMSNorm\n    @ModuleInfo(key: \"mixer\") var mixer: Mamba2Mixer\n\n    public init(_ config: Mamba2Config) {\n        _norm.wrappedValue = RMSNorm(dimensions: config.hiddenSize, eps: config.layerNormEpsilon)\n        _mixer.wrappedValue = Mamba2Mixer(config)\n        super.init()\n    }\n\n    public func callAsFunction(_ x: MLXArray, state: LayerState?, resets: MLXArray?, chunk: Int) -> (MLXArray, LayerState) {\n        let (out, next) = mixer(norm(x), state: state, resets: resets, chunk: chunk)\n        return (x + out, next)\n    }\n\n    public func step(_ x: MLXArray, state: LayerState, reset: MLXArray?) -> (MLXArray, LayerState) {\n        let (out, next) = mixer.step(norm(x), state: state, reset: reset)\n        return (x + out, next)\n    }\n}\n"},{"path":"Sources/BraidKit/Model/Mamba2Config.swift","lines":145,"bytes":9185,"header":{"lines":[1,14],"what":[8,10],"pin":[11,13],"in":null,"out":null},"marks":[],"first":1223,"scopes":[["S","Mamba2Config",null,"public",19,19,[19,57],102,null,-1,0],["E","CodingKeys",null,"",40,40,[40,39],45,null,0,0,["modelType","hiddenSize","numHiddenLayers","numHeads","headDim","stateSize","nGroups","convKernel","vocabSize","layerNormEpsilon","timeStepLimit","useBias","useConvBias","tieWordEmbeddings","chunkSize","cut","tapAfterBlocks"]],["i","init",["modelType","hiddenSize","numHiddenLayers","numHeads","headDim","stateSize","nGroups","convKernel","vocabSize","layerNormEpsilon","timeStepLimit","useBias","useConvBias","tieWordEmbeddings","chunkSize","cut","tapAfterBlocks"],"public",47,47,[49,115],67,null,0,0],["i","init",["from"],"public",69,69,[69,46],89,null,0,0],["v","intermediate",null,"public",91,91,[91,33],91,null,0,8],["v","convDim",null,"public",92,92,[92,28],92,null,0,8],["v","hasTrunk",null,"public",93,93,[93,30],93,null,0,8],["v","limits",null,"public",94,94,[94,38],94,null,0,8],["f","validate",[],"public",96,96,[96,34],101,null,0,0],["S","StorageMath",null,"public",105,105,[105,47],145,[104,104],-1,0],["i","init",["config"],"public",108,108,[108,38],108,null,9,8],["v","parametersPerBlock",null,"public",110,110,[110,39],116,null,9,0],["v","embeddingParameters",null,"public",117,117,[117,40],117,null,9,8],["v","totalParameters",null,"public",118,118,[118,36],118,null,9,8],["v","threadParameters",null,"public",119,119,[119,37],119,null,9,8],["v","trunkParameters",null,"public",121,121,[121,36],121,[120,120],9,8],["v","trunkBytes",null,"public",122,122,[122,31],122,null,9,8],["v","ssmStateFloats",null,"public",124,124,[124,35],124,[123,123],9,8],["v","convWindowFloats",null,"public",125,125,[125,37],125,null,9,8],["v","stateBytesPerStream",null,"public",127,127,[127,40],127,[126,126],9,8],["v","keyFloats",null,"public",128,128,[128,30],128,null,9,8],["v","pooledKeyFloats",null,"public",129,129,[129,36],129,null,9,8],["f","table",[],"public",131,131,[131,46],144,null,9,0],["f","mb",["_"],"",132,132,[132,40],132,null,22,12],["f","m",["_"],"",133,133,[133,35],133,null,22,12]],"text":"//\n//  Mamba2Config.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The shape of a Mamba2 trunk: Hugging Face's Mamba2Config keys as the imported checkpoint\n//        declares them, plus Braid's two fields — the cut (the first block of the frozen trunk) and\n//        the key scheme the provenance index reads states with.\n//  PIN:  Validated once at import: tied embeddings (the reed is the vocabulary), heads × head_dim\n//        is the inner width, the groups divide the heads. The imported architecture is kept exactly:\n//        Mamba2 has no MLP block, so Braid adds none.\n//\n\nimport BraidCore\nimport Foundation\n\npublic struct Mamba2Config: Codable, Sendable, Equatable {\n    public var modelType: String\n    public var hiddenSize: Int\n    public var numHiddenLayers: Int\n    public var numHeads: Int\n    public var headDim: Int\n    public var stateSize: Int\n    public var nGroups: Int\n    public var convKernel: Int\n    public var vocabSize: Int\n    public var layerNormEpsilon: Float\n    public var timeStepLimit: [Float]\n    public var useBias: Bool\n    public var useConvBias: Bool\n    public var tieWordEmbeddings: Bool\n    public var chunkSize: Int\n    /// Braid: the first block of the frozen trunk; blocks 0..<cut are a Thread's own.\n    public var cut: Int\n    /// Braid: the residual tap (after how many blocks) the default key reads.\n    public var tapAfterBlocks: Int\n\n    enum CodingKeys: String, CodingKey {\n        case modelType = \"model_type\", hiddenSize = \"hidden_size\", numHiddenLayers = \"num_hidden_layers\", numHeads = \"num_heads\", headDim = \"head_dim\"\n        case stateSize = \"state_size\", nGroups = \"n_groups\", convKernel = \"conv_kernel\", vocabSize = \"vocab_size\", layerNormEpsilon = \"layer_norm_epsilon\"\n        case timeStepLimit = \"time_step_limit\", useBias = \"use_bias\", useConvBias = \"use_conv_bias\", tieWordEmbeddings = \"tie_word_embeddings\"\n        case chunkSize = \"chunk_size\", cut = \"braid_cut\", tapAfterBlocks = \"braid_tap_after_blocks\"\n    }\n\n    public init(modelType: String = \"mamba2\", hiddenSize: Int, numHiddenLayers: Int, numHeads: Int, headDim: Int, stateSize: Int, nGroups: Int = 1, convKernel: Int = 4,\n                vocabSize: Int, layerNormEpsilon: Float = 1e-5, timeStepLimit: [Float] = [0, .infinity], useBias: Bool = false, useConvBias: Bool = true,\n                tieWordEmbeddings: Bool = true, chunkSize: Int = 256, cut: Int? = nil, tapAfterBlocks: Int? = nil) {\n        self.modelType = modelType\n        self.hiddenSize = hiddenSize\n        self.numHiddenLayers = numHiddenLayers\n        self.numHeads = numHeads\n        self.headDim = headDim\n        self.stateSize = stateSize\n        self.nGroups = nGroups\n        self.convKernel = convKernel\n        self.vocabSize = vocabSize\n        self.layerNormEpsilon = layerNormEpsilon\n        self.timeStepLimit = timeStepLimit\n        self.useBias = useBias\n        self.useConvBias = useConvBias\n        self.tieWordEmbeddings = tieWordEmbeddings\n        self.chunkSize = chunkSize\n        self.cut = cut ?? numHiddenLayers / 2\n        self.tapAfterBlocks = tapAfterBlocks ?? numHiddenLayers / 2\n    }\n\n    public init(from decoder: Decoder) throws {\n        let c = try decoder.container(keyedBy: CodingKeys.self)\n        modelType = try c.decodeIfPresent(String.self, forKey: .modelType) ?? \"mamba2\"\n        hiddenSize = try c.decode(Int.self, forKey: .hiddenSize)\n        numHiddenLayers = try c.decode(Int.self, forKey: .numHiddenLayers)\n        numHeads = try c.decode(Int.self, forKey: .numHeads)\n        headDim = try c.decode(Int.self, forKey: .headDim)\n        stateSize = try c.decode(Int.self, forKey: .stateSize)\n        nGroups = try c.decodeIfPresent(Int.self, forKey: .nGroups) ?? 1\n        convKernel = try c.decode(Int.self, forKey: .convKernel)\n        vocabSize = try c.decode(Int.self, forKey: .vocabSize)\n        layerNormEpsilon = try c.decodeIfPresent(Float.self, forKey: .layerNormEpsilon) ?? 1e-5\n        let limit = try c.decodeIfPresent([Float].self, forKey: .timeStepLimit) ?? [0, .infinity]\n        timeStepLimit = limit.count == 2 ? limit : [0, .infinity]\n        useBias = try c.decodeIfPresent(Bool.self, forKey: .useBias) ?? false\n        useConvBias = try c.decodeIfPresent(Bool.self, forKey: .useConvBias) ?? true\n        tieWordEmbeddings = try c.decodeIfPresent(Bool.self, forKey: .tieWordEmbeddings) ?? false\n        chunkSize = try c.decodeIfPresent(Int.self, forKey: .chunkSize) ?? 256\n        cut = try c.decodeIfPresent(Int.self, forKey: .cut) ?? numHiddenLayers / 2\n        tapAfterBlocks = try c.decodeIfPresent(Int.self, forKey: .tapAfterBlocks) ?? numHiddenLayers / 2\n    }\n\n    public var intermediate: Int { numHeads * headDim }\n    public var convDim: Int { intermediate + 2 * nGroups * stateSize }\n    public var hasTrunk: Bool { cut < numHiddenLayers }\n    public var limits: (Float, Float) { (timeStepLimit[0], timeStepLimit[1]) }\n\n    public func validate() throws {\n        guard tieWordEmbeddings else { throw BraidFailure.data(\"the checkpoint's lm_head is not tied to its embedding; Braid's reed is the vocabulary\") }\n        guard numHeads > 0, headDim > 0, stateSize > 0, nGroups > 0, numHeads % nGroups == 0 else { throw BraidFailure.data(\"heads \\(numHeads), head_dim \\(headDim), groups \\(nGroups) do not fit\") }\n        guard cut > 0, cut <= numHiddenLayers else { throw BraidFailure.configuration(\"cut \\(cut) is outside 1...\\(numHiddenLayers)\") }\n        guard tapAfterBlocks >= 1, tapAfterBlocks <= numHiddenLayers else { throw BraidFailure.configuration(\"tap \\(tapAfterBlocks) is outside 1...\\(numHiddenLayers)\") }\n    }\n}\n\n/// The storage and state arithmetic `braid init` prints, so the trade-offs are visible from day one.\npublic struct StorageMath: Sendable, Equatable {\n    public var config: Mamba2Config\n\n    public init(config: Mamba2Config) { self.config = config }\n\n    public var parametersPerBlock: Int {\n        let c = config\n        let inProj = (c.intermediate + c.convDim + c.numHeads) * c.hiddenSize + (c.useBias ? c.intermediate + c.convDim + c.numHeads : 0)\n        let outProj = c.hiddenSize * c.intermediate + (c.useBias ? c.hiddenSize : 0)\n        let conv = c.convDim * c.convKernel + (c.useConvBias ? c.convDim : 0)\n        return inProj + outProj + conv + c.hiddenSize + c.intermediate + 3 * c.numHeads\n    }\n    public var embeddingParameters: Int { config.vocabSize * config.hiddenSize }\n    public var totalParameters: Int { parametersPerBlock * config.numHiddenLayers + embeddingParameters + config.hiddenSize }\n    public var threadParameters: Int { parametersPerBlock * config.cut }\n    /// The trunk: blocks cut..<L, the embedding and the final norm, the commons', run by every Thread.\n    public var trunkParameters: Int { parametersPerBlock * (config.numHiddenLayers - config.cut) + embeddingParameters + config.hiddenSize }\n    public var trunkBytes: Int { trunkParameters * 4 }\n    /// The SSM state and the conv window of one layer, one stream, in floats.\n    public var ssmStateFloats: Int { config.numHeads * config.headDim * config.stateSize }\n    public var convWindowFloats: Int { (config.convKernel - 1) * config.convDim }\n    /// The history artifact: every layer's state, f32.\n    public var stateBytesPerStream: Int { config.numHiddenLayers * (ssmStateFloats + convWindowFloats) * 4 }\n    public var keyFloats: Int { 2 * config.hiddenSize }\n    public var pooledKeyFloats: Int { config.numHeads * config.headDim + config.hiddenSize }\n\n    public func table() -> [(String, String)] {\n        func mb(_ bytes: Int) -> String { String(format: \"%.1f MB\", Double(bytes) / 1_000_000) }\n        func m(_ n: Int) -> String { String(format: \"%.1fM\", Double(n) / 1_000_000) }\n        return [\n            (\"parameters\", \"\\(m(totalParameters)) (\\(config.numHiddenLayers) blocks × \\(m(parametersPerBlock)), embedding \\(m(embeddingParameters)))\"),\n            (\"a Thread node (blocks 0..<\\(config.cut))\", \"\\(m(threadParameters)) = \\(mb(threadParameters * 4)) f32 per version, plus the commons' trunk by reference\"),\n            (\"the commons' trunk (\\(config.cut)..<\\(config.numHiddenLayers))\", \"\\(m(trunkParameters)) = \\(mb(trunkBytes)) f32: blocks \\(config.cut)..<\\(config.numHiddenLayers), the embedding and norm_f, run by every Thread\"),\n            (\"state per stream\", \"\\(config.numHiddenLayers) × (\\(ssmStateFloats) + \\(convWindowFloats)) floats = \\(mb(stateBytesPerStream)) — the history artifact, independent of context length\"),\n            (\"key (residual ⊕ final)\", \"\\(keyFloats) floats = \\(keyFloats * 4) B f32, \\(keyFloats * 2) B f16 → \\(mb(keyFloats * 2 * 100_000)) f16 per 100K positions\"),\n            (\"key (pooled state ⊕ final)\", \"\\(pooledKeyFloats) floats → \\(mb(pooledKeyFloats * 2 * 100_000)) f16 per 100K positions\"),\n            (\"raw state as a key half\", \"\\(ssmStateFloats) floats → \\(String(format: \"%.1f GB\", Double(ssmStateFloats * 4) * 100_000 / 1_073_741_824)) per 100K positions: infeasible, hence pooling\"),\n            (\"checkpoint\", \"\\(mb(stateBytesPerStream)) each; at a 1,024-token stride ≤ \\(mb(stateBytesPerStream * 98)) per 100K positions\"),\n        ]\n    }\n}\n"},{"path":"Sources/BraidKit/Model/SSD.swift","lines":174,"bytes":11646,"header":{"lines":[1,19],"what":[8,13],"pin":[14,18],"in":null,"out":null},"marks":[],"first":1248,"scopes":[["E","SSD",null,"public",25,25,[25,16],174,null,-1,0,[]],["f","discretize",["_","bias","limits"],"public static",27,27,[27,102],31,[26,26],0,0],["f","segsum",["_"],"public static",34,34,[34,57],42,[33,33],0,0],["f","scan",["x","dt","aLog","B","C","D","dtBias","limits","state","resets","chunk"],"public static",47,47,[48,117],104,[44,46],0,0],["f","step",["x","dt","aLog","B","C","D","dtBias","limits","state","reset"],"public static",107,107,[108,97],122,[106,106],0,0],["f","causalConv",["x","weight","bias","window","resets"],"public static",128,128,[128,155],161,[124,127],0,0],["f","convStep",["x","weight","bias","window","reset"],"public static",164,164,[164,151],173,[163,163],0,0]],"text":"//\n//  SSD.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The selective state-space scan in its structured-state-space-duality form (Mamba2): per\n//        chunk a lower-triangular surrogate attention over the chunk, a carry-in from the state the\n//        chunk entered with and a carry-out to the state it leaves; one token at a time, the\n//        recurrence itself. Plus the depthwise causal convolution that feeds it, as shifted\n//        multiplies. All plain MLX ops: differentiable, no eval anywhere, so a training step traces\n//        through it.\n//  PIN:  `resets` zero the state (and the conv window) before the position they mark, so packed\n//        documents are processed exactly as each would be alone — the same condition the index is\n//        built under. The math is Frigate's `ssmAttn` (a port of mlx-lm's ssm.py) without its\n//        asyncEval calls, which MLX forbids inside a gradient trace. Decays are exp of sums of\n//        non-positive numbers, so nothing overflows.\n//\n\nimport Foundation\nimport MLX\nimport MLXNN\n\npublic enum SSD {\n    /// softplus(dt + bias) clipped to the config's limits, in float32.\n    public static func discretize(_ dt: MLXArray, bias: MLXArray, limits: (Float, Float)) -> MLXArray {\n        var out = softplus(dt.asType(.float32) + bias)\n        if limits.0 > 0 || limits.1.isFinite { out = clip(out, min: limits.0, max: limits.1) }\n        return out\n    }\n\n    /// For x […, q]: out[…, t, s] = Σ_{r=s+1}^{t} x_r for t ≥ s (0 on the diagonal), −inf above it.\n    public static func segsum(_ x: MLXArray) -> MLXArray {\n        let q = x.dim(-1)\n        var y = repeated(x[.ellipsis, .newAxis], count: q, axis: -1)     // […, q, q]: y[…, r, s] = x_r\n        y = tril(y, k: -1)                                               // keep r > s\n        var out = cumsum(y, axis: -2)                                    // out[…, t, s] = Σ_{r ≤ t, r > s} x_r\n        let mask = tril(MLXArray.ones([q, q], dtype: .bool), k: 0)\n        out = MLX.where(mask, out, MLXArray(-Float.infinity))\n        return out\n    }\n\n    /// The chunked scan. x [B,L,H,P], dt [B,L,H] (raw), aLog [H], B/C [B,L,G,N], D [H], dtBias [H],\n    /// state [B,H,P,N] or nil (zeros), resets [B,L] bool or nil. Returns y [B,L,H,P] (the D skip\n    /// included) and the state after the last position.\n    public static func scan(x: MLXArray, dt: MLXArray, aLog: MLXArray, B: MLXArray, C: MLXArray, D: MLXArray, dtBias: MLXArray, limits: (Float, Float),\n                            state: MLXArray?, resets: MLXArray?, chunk: Int = 256) -> (y: MLXArray, state: MLXArray) {\n        let (b, l, h, p) = (x.dim(0), x.dim(1), x.dim(2), x.dim(3))\n        let g = B.dim(2)\n        let n = B.dim(3)\n        let repeats = h / g\n        let dtv = discretize(dt, bias: dtBias, limits: limits)                       // [B,L,H]\n        let a = -exp(aLog.asType(.float32))                                         // [H]\n        let dtA = dtv * a.reshaped([1, 1, h])                                        // [B,L,H]\n        let dtx = dtv[.ellipsis, .newAxis] * x.asType(.float32)                      // [B,L,H,P]\n        let segments: MLXArray? = resets.map { cumsum($0.asType(.int32), axis: 1) }  // [B,L] inclusive\n        var s = state?.asType(.float32) ?? MLXArray.zeros([b, h, p, n], dtype: .float32)\n        var ys: [MLXArray] = []\n        var start = 0\n        while start < l {\n            let q = min(chunk, l - start)\n            let range = start ..< start + q\n            let dtAc = dtA[0..., range].swappedAxes(1, 2)                            // [B,H,q]\n            let cs = cumsum(dtAc, axis: -1)                                          // [B,H,q]\n            var decay = exp(segsum(dtAc))                                             // [B,H,q,q]\n            var keepIn: MLXArray? = nil                                               // [B,1,q,1]\n            var keepOut: MLXArray? = nil                                              // [B,1,q,1]\n            var carryKeep: MLXArray? = nil                                            // [B,1,1,1]\n            if let segments, let resets {\n                let seg = segments[0..., range]                                       // [B,q]\n                let same = seg[0..., 0..., .newAxis] .== seg[0..., .newAxis, 0...]   // [B,q,q]\n                decay = MLX.where(same[0..., .newAxis, 0..., 0...], decay, MLXArray(Float(0)))\n                let entering = seg[0..., 0] - resets[0..., start].asType(.int32)     // [B]: the segment the chunk's state belongs to\n                keepIn = (seg .== entering[0..., .newAxis]).asType(.float32)[0..., .newAxis, 0..., .newAxis]\n                keepOut = (seg .== seg[0..., (q - 1)...]).asType(.float32)[0..., .newAxis, 0..., .newAxis]\n                carryKeep = (entering .== seg[0..., q - 1]).asType(.float32)[0..., .newAxis, .newAxis, .newAxis]\n            }\n            let bc = repeated(B[0..., range], count: repeats, axis: 2).swappedAxes(1, 2).asType(.float32)   // [B,H,q,N]\n            let cc = repeated(C[0..., range], count: repeats, axis: 2).swappedAxes(1, 2).asType(.float32)   // [B,H,q,N]\n            let cb = matmul(cc, bc.swappedAxes(2, 3))                                                      // [B,H,q,q]: C_t·B_s\n            let m = tril(cb * decay, k: 0)\n            let dtxc = dtx[0..., range].swappedAxes(1, 2)                                                   // [B,H,q,P]\n            var y = matmul(m, dtxc)                                                                        // [B,H,q,P]\n            // Carry-in: the state the chunk entered with, decayed through each position.\n            var decayIn = exp(cs)[.ellipsis, .newAxis]                                                     // [B,H,q,1]\n            if let keepIn { decayIn = decayIn * keepIn }\n            let fromState = matmul(s, cc.swappedAxes(2, 3)).swappedAxes(2, 3)                               // [B,H,q,P]\n            y = y + decayIn * fromState\n            // Carry-out: every position's input decayed to the chunk's end, plus the old state decayed through the chunk.\n            var toEnd = exp(cs[.ellipsis, (q - 1)...] - cs)[.ellipsis, .newAxis]                             // [B,H,q,1]\n            if let keepOut { toEnd = toEnd * keepOut }\n            let weighted = dtxc * toEnd                                                                     // [B,H,q,P]\n            var next = matmul(weighted.swappedAxes(2, 3), bc)                                               // [B,H,P,N]\n            var through = exp(cs[.ellipsis, q - 1])[.ellipsis, .newAxis, .newAxis]                           // [B,H,1,1]\n            if let carryKeep { through = through * carryKeep }\n            next = next + through * s\n            s = next\n            ys.append(y.swappedAxes(1, 2))                                                                  // [B,q,H,P]\n            start += q\n        }\n        let y = concatenated(ys, axis: 1) + x.asType(.float32) * D.asType(.float32).reshaped([1, 1, h, 1])\n        return (y, s)\n    }\n\n    /// One token. x [B,H,P], dt [B,H], B/C [B,G,N], state [B,H,P,N], reset [B] bool or nil.\n    public static func step(x: MLXArray, dt: MLXArray, aLog: MLXArray, B: MLXArray, C: MLXArray, D: MLXArray, dtBias: MLXArray, limits: (Float, Float),\n                            state: MLXArray, reset: MLXArray?) -> (y: MLXArray, state: MLXArray) {\n        let h = x.dim(1)\n        let g = B.dim(1)\n        var s = state\n        if let reset { s = MLX.where(reset[0..., .newAxis, .newAxis, .newAxis], MLXArray(Float(0)), s) }\n        let dtv = discretize(dt, bias: dtBias, limits: limits)                        // [B,H]\n        let a = -exp(aLog.asType(.float32))\n        let dA = exp(dtv * a.reshaped([1, h]))                                        // [B,H]\n        let bh = repeated(B, count: h / g, axis: 1).asType(.float32)                  // [B,H,N]\n        let ch = repeated(C, count: h / g, axis: 1).asType(.float32)                  // [B,H,N]\n        let dtx = dtv[.ellipsis, .newAxis] * x.asType(.float32)                       // [B,H,P]\n        let next = dA[.ellipsis, .newAxis, .newAxis] * s + dtx[.ellipsis, .newAxis] * bh[0..., 0..., .newAxis, 0...]   // [B,H,P,N]\n        let y = (next * ch[0..., 0..., .newAxis, 0...]).sum(axis: -1) + x.asType(.float32) * D.asType(.float32).reshaped([1, h, 1])\n        return (y, next)\n    }\n\n    /// Depthwise causal convolution as shifted multiplies. x [B,L,C], weight [C,K,1] (MLX layout),\n    /// window [B,K−1,C] (the inputs before x) or nil (zeros), resets [B,L] or nil. Returns the\n    /// convolved sequence (before the activation) and the new window: the last K−1 inputs, zeroed\n    /// where they belong to a segment the last position does not.\n    public static func causalConv(x: MLXArray, weight: MLXArray, bias: MLXArray?, window: MLXArray?, resets: MLXArray?) -> (y: MLXArray, window: MLXArray) {\n        let (b, l, c) = (x.dim(0), x.dim(1), x.dim(2))\n        let k = weight.dim(1)\n        let keep = k - 1\n        let before = window ?? MLXArray.zeros([b, keep, c], dtype: x.dtype)\n        let padded = concatenated([before, x], axis: 1)                               // [B, L+K−1, C]\n        var segmentsExt: MLXArray? = nil\n        var seg: MLXArray? = nil\n        if let resets {\n            let s = cumsum(resets.asType(.int32), axis: 1)                            // [B,L]\n            let entering = s[0..., 0] - resets[0..., 0].asType(.int32)                 // [B]\n            segmentsExt = concatenated([repeated(entering[0..., .newAxis], count: keep, axis: 1), s], axis: 1)   // [B, L+K−1]\n            seg = s\n        }\n        var y = MLXArray.zeros([b, l, c], dtype: .float32)\n        for tap in 0..<k {\n            var shifted = padded[0..., tap ..< tap + l].asType(.float32)              // input at offset −(K−1−tap)\n            if let segmentsExt, let seg {\n                let mask = (segmentsExt[0..., tap ..< tap + l] .== seg).asType(.float32)\n                shifted = shifted * mask[.ellipsis, .newAxis]\n            }\n            y = y + shifted * weight[0..., tap, 0].reshaped([1, 1, c]).asType(.float32)\n        }\n        if let bias { y = y + bias.asType(.float32).reshaped([1, 1, c]) }\n        var newWindow = padded[0..., l ..< l + keep]\n        if let seg, keep > 0 {\n            let last = seg[0..., (l - 1)...]                                            // [B,1]\n            let tail = concatenated([segmentsExt![0..., l ..< l + keep]], axis: 1)      // the last K−1 positions' segments (shifted view)\n            _ = tail\n            let windowSegments = segmentsExt![0..., l ..< l + keep]\n            newWindow = newWindow * (windowSegments .== last).asType(newWindow.dtype)[.ellipsis, .newAxis]\n        }\n        return (y, newWindow)\n    }\n\n    /// The convolution for one token. x [B,C], window [B,K−1,C], reset [B] or nil.\n    public static func convStep(x: MLXArray, weight: MLXArray, bias: MLXArray?, window: MLXArray, reset: MLXArray?) -> (y: MLXArray, window: MLXArray) {\n        var before = window\n        if let reset { before = MLX.where(reset[0..., .newAxis, .newAxis], MLXArray(Float(0)).asType(before.dtype), before) }\n        let padded = concatenated([before, x[0..., .newAxis, 0...]], axis: 1)         // [B,K,C]\n        let k = weight.dim(1)\n        var y = MLXArray.zeros(like: x).asType(.float32)\n        for tap in 0..<k { y = y + padded[0..., tap].asType(.float32) * weight[0..., tap, 0].asType(.float32) }\n        if let bias { y = y + bias.asType(.float32) }\n        return (y, padded[0..., 1...])\n    }\n}\n"},{"path":"Sources/BraidKit/Model/Trunk.swift","lines":213,"bytes":11140,"header":{"lines":[1,19],"what":[8,13],"pin":[14,18],"in":null,"out":null},"marks":[],"first":1255,"scopes":[["S","TapRequest",null,"public",26,26,[26,46],30,null,-1,0],["i","init",["residualAfterBlocks"],"public",28,28,[28,52],28,null,0,8],["S","TrunkOutput",null,"public",32,32,[32,26],38,null,-1,0],["C","Backbone",null,"final",40,40,[40,29],61,null,-1,0],["i","init",["_"],"",46,46,[46,33],51,[45,45],3,0],["i","init",["head","tail"],"",55,55,[55,48],60,[53,54],3,0],["C","Trunk",null,"public final",63,63,[63,33],213,null,-1,0],["S","Tail",null,"public",71,71,[71,23],80,[69,70],6,0],["v","cut",null,"public",77,77,[77,28],77,null,7,8],["v","count",null,"public",79,79,[79,30],79,[78,78],7,8],["i","init",["config","backbone","seamSHA256"],"private",82,82,[82,79],87,null,6,0],["i","init",["_"],"public convenience",90,90,[90,52],93,[89,89],6,0],["i","init",["pack"],"public convenience",97,97,[97,47],109,[95,96],6,0],["i","init",["head","tail"],"public convenience",112,112,[112,61],115,[111,111],6,0],["v","embedding",null,"public",117,117,[117,35],117,null,6,8],["v","finalNorm",null,"public",118,118,[118,35],118,null,6,8],["v","blocks",null,"public",119,119,[119,37],119,null,6,8],["v","head",null,"public",121,121,[121,35],121,[120,120],6,8],["v","tail",null,"public",124,124,[124,26],126,[122,123],6,0],["f","makeHead",["arrays","config"],"public static",131,131,[131,106],147,[128,130],6,0],["f","packHead",["_"],"public static",151,151,[151,70],153,[149,150],6,0],["f","forward",["tokens","state","resets","taps","training"],"public",157,157,[157,146],173,[155,156],6,0],["f","step",["token","state","reset","taps"],"public",176,176,[176,116],191,[175,175],6,0],["f","blockIndex",["ofKey"],"public static",194,194,[194,61],198,[193,193],6,0],["f","flattenedParameters",[],"public",201,201,[201,62],203,[200,200],6,0],["f","seam",["of","cut"],"static",206,206,[206,64],212,[205,205],6,0]],"text":"//\n//  Trunk.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The runner, laid out as the checkpoint names it: `backbone.embeddings`, `backbone.layers.N`,\n//        `backbone.norm_f`. The commons runs the pack whole, every block frozen; its blocks cut..<L,\n//        its embedding and its final norm are the trunk every Thread runs behind its own head, as\n//        the same module instances, never copied. A Thread's trunk is its head, blocks 0..<cut, in\n//        front of the commons' tail. The node runs it end to end and emits the normed last state;\n//        the reed is the embedding, applied by the cluster.\n//  PIN:  One final RMSNorm, applied here. The reed never re-norms. Taps capture the residual stream\n//        after a given number of blocks (the key's first half); no attention, no cache. A Thread's\n//        tail is the commons' own modules: never call a recursive unfreeze() or train(_:) on a Trunk,\n//        and never update a Trunk's parameters past its head. A head holds blocks 0..<cut and nothing\n//        else; a file that carries a block of the trunk is refused.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\nimport MLXNN\n\npublic struct TapRequest: Sendable, Equatable {\n    public var residualAfterBlocks: Set<Int>\n    public init(residualAfterBlocks: Set<Int> = []) { self.residualAfterBlocks = residualAfterBlocks }\n    public static let none = TapRequest()\n}\n\npublic struct TrunkOutput {\n    /// [B,L,D] (or [B,D] for a step): the normed last-layer state. The node's public output.\n    public var final: MLXArray\n    /// The residual stream after n blocks, for each n requested.\n    public var residual: [Int: MLXArray]\n    public var state: StateStack\n}\n\nfinal class Backbone: Module {\n    @ModuleInfo(key: \"embeddings\") var embeddings: Embedding\n    @ModuleInfo(key: \"layers\") var layers: [Mamba2Block]\n    @ModuleInfo(key: \"norm_f\") var normF: RMSNorm\n\n    /// The whole model, fresh: the commons' shape, and the tests'.\n    init(_ config: Mamba2Config) {\n        _embeddings.wrappedValue = Embedding(embeddingCount: config.vocabSize, dimensions: config.hiddenSize)\n        _layers.wrappedValue = (0..<config.numHiddenLayers).map { _ in Mamba2Block(config) }\n        _normF.wrappedValue = RMSNorm(dimensions: config.hiddenSize, eps: config.layerNormEpsilon)\n        super.init()\n    }\n\n    /// A head in front of a tail: the tail's modules themselves, not copies. The head is the dense\n    /// prefix of `layers`, which the optimizer's gradient tree relies on.\n    init(head: [Mamba2Block], tail: Trunk.Tail) {\n        _embeddings.wrappedValue = tail.embeddings\n        _layers.wrappedValue = head + tail.blocks\n        _normF.wrappedValue = tail.normF\n        super.init()\n    }\n}\n\npublic final class Trunk: Module {\n    public var config: Mamba2Config\n    /// SEAM: SHA-256 over the tail's arrays, the name a Thread's version must carry (RaoLM v2's definition).\n    public private(set) var seamSHA256: String\n    @ModuleInfo(key: \"backbone\") var backbone: Backbone\n\n    /// What the commons lends every Thread: its blocks cut..<L, its embedding and its final norm,\n    /// named by the seam. A view over the commons' modules, not an owner.\n    public struct Tail {\n        let embeddings: Embedding\n        let blocks: [Mamba2Block]\n        let normF: RMSNorm\n        public let config: Mamba2Config\n        public let seamSHA256: String\n        public var cut: Int { config.cut }\n        /// How many blocks the tail holds.\n        public var count: Int { blocks.count }\n    }\n\n    private init(config: Mamba2Config, backbone: Backbone, seamSHA256: String) {\n        self.config = config\n        self.seamSHA256 = seamSHA256\n        _backbone.wrappedValue = backbone\n        super.init()\n    }\n\n    /// The whole model with fresh weights (the tests' tiny trunks). Its seam is the hash of what it holds.\n    public convenience init(_ config: Mamba2Config) {\n        let backbone = Backbone(config)\n        self.init(config: config, backbone: backbone, seamSHA256: Self.seam(of: backbone, cut: config.cut))\n    }\n\n    /// The commons: the pack run whole, every block frozen, and the seam re-derived from the loaded\n    /// modules and held against the pack's record. Built first; every Thread runs behind its tail.\n    public convenience init(pack: Pack) throws {\n        self.init(config: pack.config, backbone: Backbone(pack.config), seamSHA256: pack.info.seamSHA256)\n        var weights = pack.blocks\n        weights[Pack.embeddingKey] = pack.embedding\n        weights[Pack.normKey] = pack.norm\n        try update(parameters: ModuleParameters.unflattened(weights), verify: [.all])\n        freeze()                                                                     // whole, once, here: the one recursive freeze\n        eval(self)\n        let derived = Self.seam(of: backbone, cut: config.cut)\n        guard derived == pack.info.seamSHA256 else {\n            throw BraidFailure.data(\"the commons built from pack \\(pack.sha256.prefix(12)) hashes to seam \\(derived.prefix(12)), not its record \\(pack.info.seamSHA256.prefix(12))\")\n        }\n    }\n\n    /// A Thread's running model: `head`, its own blocks 0..<cut, in front of the commons' tail.\n    public convenience init(head: [Mamba2Block], tail: Tail) {\n        precondition(head.count == tail.cut, \"a head holds \\(tail.cut) blocks, not \\(head.count)\")\n        self.init(config: tail.config, backbone: Backbone(head: head, tail: tail), seamSHA256: tail.seamSHA256)\n    }\n\n    public var embedding: MLXArray { backbone.embeddings.weight }\n    public var finalNorm: MLXArray { backbone.normF.weight }\n    public var blocks: [Mamba2Block] { backbone.layers }\n    /// This trunk's own blocks 0..<cut.\n    public var head: [Mamba2Block] { Array(backbone.layers[..<config.cut]) }\n    /// This trunk's blocks cut..<L, its embedding and its final norm, as a Thread borrows them. By rule\n    /// the tail every Thread runs is the commons'.\n    public var tail: Tail {\n        Tail(embeddings: backbone.embeddings, blocks: Array(backbone.layers[config.cut...]), normF: backbone.normF, config: config, seamSHA256: seamSHA256)\n    }\n\n    /// A head from its arrays: blocks 0..<cut, each key as the checkpoint names it. A key of any other\n    /// block is refused, so a head file can never carry a piece of the trunk; a missing block is refused\n    /// too. The blocks come back trainable; the arrays are assigned, never copied.\n    public static func makeHead(arrays: [String: MLXArray], config: Mamba2Config) throws -> [Mamba2Block] {\n        var perBlock: [Int: [String: MLXArray]] = [:]\n        for (key, value) in arrays {\n            guard let index = blockIndex(ofKey: key) else { throw BraidFailure.data(\"blocks.safetensors holds \\(key), which is no block's array; a head holds blocks 0..<\\(config.cut)\") }\n            guard index < config.cut else { throw BraidFailure.data(\"blocks.safetensors holds \\(key), a block of the trunk; a head holds blocks 0..<\\(config.cut)\") }\n            perBlock[index, default: [:]][key.split(separator: \".\").dropFirst(3).joined(separator: \".\")] = value\n        }\n        let missing = (0..<config.cut).filter { perBlock[$0] == nil }\n        guard missing.isEmpty else {\n            throw BraidFailure.data(\"blocks.safetensors lacks block\\(missing.count == 1 ? \"\" : \"s\") \\(missing.map(String.init).joined(separator: \", \")); a head holds blocks 0..<\\(config.cut)\")\n        }\n        return try (0..<config.cut).map { index in\n            let block = Mamba2Block(config)\n            try block.update(parameters: ModuleParameters.unflattened(perBlock[index]!), verify: [.all])\n            return block\n        }\n    }\n\n    /// The pack's own head: blocks 0..<cut as imported, trainable. The commons' head, where a Thread's\n    /// training starts, and what an untrained Thread runs.\n    public static func packHead(_ pack: Pack) throws -> [Mamba2Block] {\n        try makeHead(arrays: pack.headArrays, config: pack.config)\n    }\n\n    /// A sequence. tokens [B,L] int32. `training` leaves the graph lazy for a gradient; otherwise\n    /// every layer is evaluated as it goes, so the graph never grows with the document.\n    public func forward(tokens: MLXArray, state: StateStack?, resets: MLXArray?, taps: TapRequest = .none, training: Bool = false) -> TrunkOutput {\n        var h = backbone.embeddings(tokens)\n        var layers: [LayerState] = []\n        var residual: [Int: MLXArray] = [:]\n        if taps.residualAfterBlocks.contains(0) { residual[0] = h }\n        for (i, block) in backbone.layers.enumerated() {\n            let (out, next) = block(h, state: state?.layers[i], resets: resets, chunk: config.chunkSize)\n            h = out\n            layers.append(next)\n            if taps.residualAfterBlocks.contains(i + 1) { residual[i + 1] = h }\n            if !training { eval(h, next.conv, next.ssm) }\n        }\n        let final = backbone.normF(h)\n        if !training { eval(final) }\n        let position = (state?.position ?? -1) + tokens.dim(1)\n        return TrunkOutput(final: final, residual: residual, state: StateStack(layers: layers, position: position, prefixSHA256: nil))\n    }\n\n    /// One token. token [B] int32.\n    public func step(token: MLXArray, state: StateStack, reset: MLXArray?, taps: TapRequest = .none) -> TrunkOutput {\n        var h = backbone.embeddings(token)\n        var layers: [LayerState] = []\n        var residual: [Int: MLXArray] = [:]\n        if taps.residualAfterBlocks.contains(0) { residual[0] = h }\n        for (i, block) in backbone.layers.enumerated() {\n            let (out, next) = block.step(h, state: state.layers[i], reset: reset)\n            h = out\n            layers.append(next)\n            if taps.residualAfterBlocks.contains(i + 1) { residual[i + 1] = h }\n        }\n        let final = backbone.normF(h)\n        eval(final)\n        eval(layers.flatMap { [$0.conv, $0.ssm] })\n        return TrunkOutput(final: final, residual: residual, state: StateStack(layers: layers, position: state.position + 1, prefixSHA256: nil))\n    }\n\n    /// \"backbone.layers.N.…\" → N.\n    public static func blockIndex(ofKey key: String) -> Int? {\n        let parts = key.split(separator: \".\")\n        guard parts.count > 3, parts[0] == \"backbone\", parts[1] == \"layers\" else { return nil }\n        return Int(parts[2])\n    }\n\n    /// Every parameter key with its array, flattened to the checkpoint's names.\n    public func flattenedParameters() -> [(String, MLXArray)] {\n        parameters().flattened().sorted { $0.0 < $1.0 }\n    }\n\n    /// The seam of a backbone: SHA-256(norm ‖ embedding ‖ ∀ arrays of blocks ≥ cut sorted by key: key ‖ bytes), from the modules themselves.\n    static func seam(of backbone: Backbone, cut: Int) -> String {\n        var arrays: [(String, MLXArray)] = []\n        for (i, block) in backbone.layers.enumerated() where i >= cut {\n            for (key, array) in block.parameters().flattened() { arrays.append((\"backbone.layers.\\(i).\\(key)\", array)) }\n        }\n        return PackHash.seam(embedding: backbone.embeddings.weight, norm: backbone.normF.weight, trunk: arrays)\n    }\n}\n"},{"path":"Sources/BraidKit/Pipeline/Engine/BraidEngine.swift","lines":307,"bytes":18191,"header":{"lines":[1,20],"what":[8,14],"pin":[15,19],"in":null,"out":null},"marks":[[48,"Plans"],[82,"Builds"],[157,"Intents"],[233,"Services the stages share"],[277,"Reading"]],"first":1281,"scopes":[["C","BraidEngine",null,"public final",27,27,[27,31],307,null,-1,0],["i","init",["area","config","pack","tokenizer","reed","commons","onEvent"],"public",37,37,[38,68],46,null,0,0],["f","plan",["_"],"public",51,51,[51,65],71,[50,50],0,0],["f","plan",["_"],"public",74,74,[74,65],80,[73,73],0,0],["f","build",["_"],"public",87,88,[88,70],111,[84,86],0,0],["f","create",["_"],"public",114,114,[114,70],116,[113,113],0,0],["f","sync",["_","training"],"public",121,121,[121,83],129,[118,120],0,0],["f","rekey",["_","key","checkpoints"],"public",134,134,[134,109],155,[131,133],0,0],["f","create",["_","read"],"",159,159,[159,91],189,null,0,0],["f","sync",["_","read","training","checkpoints","seed"],"",191,191,[191,152],221,null,0,0],["f","run",["_","_"],"private",224,224,[224,98],231,[223,223],0,0],["f","note",["_"],"",235,235,[235,30],235,null,0,8],["f","tokenizer",[],"",237,237,[237,46],242,null,0,0],["f","reed",[],"",244,244,[244,34],249,null,0,0],["f","commons",[],"public",253,253,[253,46],260,[251,252],0,0],["f","threadTrunk",["head"],"private",263,263,[263,79],268,[262,262],0,0],["f","attach",["_"],"",271,271,[271,39],275,[270,270],0,0],["f","readSource",["_","slug","limit"],"private",279,279,[279,102],281,null,0,0],["f","loadExisting",["_"],"private",284,284,[284,71],290,[283,283],0,0],["f","liveThread",["_"],"private",292,292,[292,77],297,null,0,0],["f","defaultKey",["_"],"private",300,300,[300,73],302,[299,299],0,0],["f","checkWithhold",["_"],"private static",304,304,[304,65],306,null,0,0]],"text":"//\n//  BraidEngine.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Builds Threads from recipes. `plan` says what building would do and touches no MLX;\n//        `build` runs a braid's recipes one Thread after another. The three things `braid thread`\n//        does are its three intents, each the snapshot stage then the stages it needs:\n//          create   read the source, write the record → train → index → promote → attach\n//          sync     read the source again; when it changed → train on → index → promote\n//          rekey    the live snapshot and blocks → index → promote\n//        The CLI and the studio's new-Thread dialog go through it, so they build the same way.\n//  PIN:  One MLX workload at a time: the engine runs on the thread that owns MLX (the CLI's main\n//        thread, the studio's worker), synchronously. The tokenizer, the reed and the commons are\n//        built once per engine (or handed in): a Thread's head trains and indexes in front of the\n//        commons' tail, so the commons comes first. The corpus is tokenized once per build, and the\n//        trained trunk is the one that is indexed. braid.toml is saved only when an attach changes it.\n//\n\nimport BraidCore\nimport BraidThread\nimport Foundation\nimport MLX\n\npublic final class BraidEngine {\n    public let area: WorkArea\n    public let pack: Pack\n    /// braid.toml as the engine holds it; an attach changes it and saves it.\n    public private(set) var config: BraidConfig\n    private let onEvent: (BuildEvent) -> Void\n    private var loadedTokenizer: BraidTokenizer?\n    private var loadedReed: MLXReed?\n    private var loadedCommons: LocalNode?\n\n    public init(area: WorkArea, config: BraidConfig, pack: Pack, tokenizer: BraidTokenizer? = nil, reed: MLXReed? = nil, commons: LocalNode? = nil,\n                onEvent: @escaping (BuildEvent) -> Void = { _ in }) {\n        self.area = area\n        self.config = config\n        self.pack = pack\n        self.onEvent = onEvent\n        loadedTokenizer = tokenizer\n        loadedReed = reed\n        loadedCommons = commons\n    }\n\n    // MARK: Plans\n\n    /// What building `recipe` would do. Reads the work area and the source; refuses what a build would refuse.\n    public func plan(_ recipe: ThreadRecipe) throws -> BuildPlan {\n        let name = recipe.name\n        let layout = area.thread(name)\n        guard FileManager.default.fileExists(atPath: layout.record.path) else {\n            guard let packRecord = config.pack else { throw BraidFailure.missing(\"braid.toml names no pack\") }\n            guard DocumentID.isValidHandle(name) else { throw BraidFailure.usage(\"thread names are lowercase handles: \\(name)\") }\n            let read = try readSource(recipe.corpus, slug: name, limit: recipe.settings.limit)\n            if let empty = read.whenEmpty, read.snapshot.documentCount == 0 { throw empty }\n            if let fraction = recipe.settings.withhold { try Self.checkWithhold(fraction) }\n            let key = recipe.settings.key ?? defaultKey(packRecord)\n            return BuildPlan(name: name, intent: .create, stages: BuildPlanner.create(recipe, snapshot: read.snapshot, key: key, attached: config.attach.contains(name)),\n                             diff: nil, read: read, existing: nil)\n        }\n        let existing = try loadExisting(name)\n        let live = try liveThread(existing)\n        if let refusal = BuildPlanner.refusal(recipe, live: live) { throw BraidFailure.usage(refusal) }\n        let read = try readSource(recipe.corpus, slug: name, limit: existing.info.limit ?? existing.current.documentCount)\n        let diff = SnapshotDiff(from: existing.current, to: read.snapshot)\n        let (intent, stages) = BuildPlanner.update(recipe, live: live, snapshot: read.snapshot, diff: diff, attached: config.attach.contains(name))\n        return BuildPlan(name: name, intent: intent, stages: stages, diff: diff, read: read, existing: existing)\n    }\n\n    /// Every Thread's plan, in order. A name may appear once.\n    public func plan(_ braid: BraidRecipe) throws -> [BuildPlan] {\n        var seen: Set<String> = []\n        for recipe in braid.threads where !seen.insert(recipe.name).inserted {\n            throw BraidFailure.usage(\"thread \\(recipe.name) appears twice in the recipe\")\n        }\n        return try braid.threads.map { try plan($0) }\n    }\n\n    // MARK: Builds\n\n    /// Builds every Thread of `braid`: each is planned first (so a refusal stops the build before\n    /// any MLX work), then created, synced or left as it is, one after another. Nil for a Thread\n    /// that made no new version.\n    @discardableResult\n    public func build(_ braid: BraidRecipe) throws -> [BuildOutcome?] {\n        let plans = try plan(braid)\n        return try zip(braid.threads, plans).map { pair -> BuildOutcome? in\n            let (recipe, plan) = pair\n            switch plan.intent {\n            case .create:\n                return try create(recipe, read: plan.read)\n            case .sync, .upToDate:\n                guard let existing = plan.existing else { throw BraidFailure.data(\"thread \\(recipe.name): a plan to update names no Thread\") }\n                onEvent(.stage(thread: recipe.name, .snapshot))\n                let settings = recipe.settings\n                let synced = try sync(existing, read: plan.read, training: settings.training, checkpoints: settings.checkpoints, seed: settings.seed)\n                if settings.attach, !config.attach.contains(recipe.name) {\n                    onEvent(.stage(thread: recipe.name, .attach))\n                    try attach(recipe.name)\n                }\n                return synced.outcome.map { outcome in\n                    var outcome = outcome\n                    outcome.attached = config.attach.contains(recipe.name)\n                    return outcome\n                }\n            }\n        }\n    }\n\n    /// `braid thread create`: a new Thread from its recipe. Fails when the Thread exists.\n    public func create(_ recipe: ThreadRecipe) throws -> BuildOutcome {\n        try create(recipe, read: nil)\n    }\n\n    /// `braid thread sync`: the Thread's source read again. An unchanged corpus is left alone; a\n    /// changed one is snapshotted, trained on from the live blocks (the continuing budget) unless\n    /// `training` is off, and indexed under the live key as a new live version.\n    public func sync(_ name: String, training: TrainingPlan) throws -> SyncOutcome {\n        let existing = try loadExisting(name)\n        let spec = try CorpusSourceSpec(parsing: existing.info.source)\n        onEvent(.stage(thread: name, .snapshot))\n        // A dataset is read in feeding order; the Thread's limit (or, for a record made before limits\n        // were kept, the live snapshot's size) takes the same documents again.\n        let read = try readSource(spec, slug: name, limit: existing.info.limit ?? existing.current.documentCount)\n        return try sync(existing, read: read, training: training, checkpoints: CheckpointPolicy(), seed: nil)\n    }\n\n    /// `braid thread index`: the live version's blocks and snapshot keyed again, under another key\n    /// scheme (nil keeps the live one) or checkpoint policy, as a new live version. Nothing is\n    /// trained and the source is not read.\n    public func rekey(_ name: String, key: KeyScheme?, checkpoints: CheckpointPolicy) throws -> BuildOutcome {\n        let layout = area.thread(name)\n        guard let live = try ThreadStore.live(layout) else { throw BraidFailure.missing(\"thread \\(name) has no live version\") }\n        guard live.packSHA256 == pack.sha256 else { throw BraidFailure.data(\"thread \\(name) was built on pack \\(live.packSHA256.prefix(12))\") }\n        let keyScheme = key ?? live.keyScheme\n        onEvent(.stage(thread: name, .snapshot))\n        let snapshot = try CorpusSnapshot.load(from: layout.snapshot(hash: live.snapshotHash))\n        let blocks = try ThreadStore.liveBlocks(layout, version: live, pack: pack)\n        let trunk = try threadTrunk(head: blocks)\n        _ = try tokenizer()\n        let started = Date()\n        note(\"thread \\(name): re-keying v\\(live.version) (\\(live.keyScheme)) as \\(keyScheme)\\(checkpoints.everyPartition ? \", a checkpoint at every partition\" : \"\")\")\n        let withheld = try ThreadStore.liveWithheld(layout, version: live)\n        let info = try ThreadStore.info(layout)\n        let context = BuildContext(name: name, layout: layout, threadID: info.threadID, snapshot: snapshot, facts: [], key: keyScheme, checkpoints: checkpoints,\n                                   exclude: { withheld }, trunk: trunk, live: live, started: started)\n        context.blocks = blocks\n        context.totals = TrainingTotals(of: live)\n        let version = try run([IndexStage(), PromoteStage(announce: false)], context)\n        return BuildOutcome(name: name, version: version, keyScheme: keyScheme, corpusHash: snapshot.corpusHash, documents: snapshot.documentCount,\n                            partitions: snapshot.partitionCount, attached: config.attach.contains(name), seconds: Date().timeIntervalSince(started))\n    }\n\n    // MARK: Intents\n\n    func create(_ recipe: ThreadRecipe, read prepared: SourceRead?) throws -> BuildOutcome {\n        guard let packRecord = config.pack else { throw BraidFailure.missing(\"braid.toml names no pack\") }\n        let name = recipe.name\n        let settings = recipe.settings\n        onEvent(.stage(thread: name, .snapshot))\n        let read = try prepared ?? readSource(recipe.corpus, slug: name, limit: settings.limit)\n        let snapshot = read.snapshot\n        if let empty = read.whenEmpty, snapshot.documentCount == 0 { throw empty }\n        let key = settings.key ?? defaultKey(packRecord)\n        let seed = settings.seed ?? DeltaHyper().seed\n        let withheld = try settings.withhold.map { fraction -> Set<String> in\n            try Self.checkWithhold(fraction)\n            return Withholding.draw(snapshot.documents.map(\\.id), fraction: fraction, seed: seed)\n        } ?? []\n        let layout = try ThreadStore.create(name: name, label: settings.label, source: recipe.corpus, lane: read.lane, limit: settings.limit, snapshot: snapshot, in: area)\n        note(\"thread \\(name): \\(snapshot.documentCount) documents, \\(snapshot.partitionCount) partitions, corpus \\(snapshot.corpusHash.prefix(12))\")\n        if !withheld.isEmpty { note(\"thread \\(name): \\(withheld.count) documents trained but withheld from the index (seed \\(seed))\") }\n        _ = try tokenizer()\n        let trunk = try threadTrunk(head: nil)\n        let started = Date()\n        let info = try ThreadStore.info(layout)\n        let context = BuildContext(name: name, layout: layout, threadID: info.threadID, snapshot: snapshot, facts: read.facts, key: key, checkpoints: settings.checkpoints,\n                                   exclude: { withheld }, trunk: trunk, live: nil, started: started)\n        var stages: [BuildStage] = []\n        if settings.training.trains { stages.append(TrainStage(plan: settings.training, seed: seed, continuing: false)) }\n        stages += [IndexStage(), PromoteStage(announce: true)] as [BuildStage]\n        if settings.attach, !config.attach.contains(name) { stages.append(AttachStage()) }\n        let version = try run(stages, context)\n        return BuildOutcome(name: name, version: version, keyScheme: key, corpusHash: snapshot.corpusHash, documents: snapshot.documentCount,\n                            partitions: snapshot.partitionCount, attached: settings.attach, seconds: context.seconds ?? Date().timeIntervalSince(started))\n    }\n\n    func sync(_ existing: ExistingThread, read: SourceRead, training: TrainingPlan, checkpoints: CheckpointPolicy, seed: UInt64?) throws -> SyncOutcome {\n        let info = existing.info\n        let name = info.name\n        let live = existing.live\n        let layout = existing.layout\n        let snapshot = read.snapshot\n        let diff = SnapshotDiff(from: existing.current, to: snapshot)\n        guard snapshot.corpusHash != live.corpusHash else {\n            note(\"thread \\(name): \\(info.source) unchanged (corpus \\(live.corpusHash.prefix(12))); v\\(live.version) stays live\")\n            return SyncOutcome(outcome: nil, diff: diff)\n        }\n        note(\"thread \\(name): \\(info.source) changed: \\(diff.summary); corpus \\(live.corpusHash.prefix(12)) → \\(snapshot.corpusHash.prefix(12))\")\n        guard snapshot.documentCount > 0 else { throw BraidFailure.missing(\"\\(info.source) holds no documents now; the live version is kept\") }\n        try snapshot.save(to: layout.snapshot(hash: snapshot.corpusHash))\n        let started = Date()\n        _ = try tokenizer()\n        let blocks = try ThreadStore.liveBlocks(layout, version: live, pack: pack)\n        let trunk = try threadTrunk(head: blocks)\n        // The withheld set is the live version's, read when the index needs it (after training).\n        let context = BuildContext(name: name, layout: layout, threadID: info.threadID, snapshot: snapshot, facts: read.facts, key: live.keyScheme, checkpoints: checkpoints,\n                                   exclude: { try ThreadStore.liveWithheld(layout, version: live) }, trunk: trunk, live: live, started: started)\n        context.blocks = blocks\n        context.totals = TrainingTotals(of: live)\n        var stages: [BuildStage] = []\n        if training.trains { stages.append(TrainStage(plan: training, seed: seed ?? DeltaHyper().seed, continuing: true)) }\n        stages += [IndexStage(), PromoteStage(announce: false)] as [BuildStage]\n        let version = try run(stages, context)\n        let outcome = BuildOutcome(name: name, version: version, keyScheme: live.keyScheme, corpusHash: snapshot.corpusHash, documents: snapshot.documentCount,\n                                   partitions: snapshot.partitionCount, attached: config.attach.contains(name), seconds: Date().timeIntervalSince(started))\n        return SyncOutcome(outcome: outcome, diff: diff)\n    }\n\n    /// Runs the stages in order and returns the version the promote stage made live.\n    private func run(_ stages: [BuildStage], _ context: BuildContext) throws -> ThreadVersionInfo {\n        for stage in stages {\n            onEvent(.stage(thread: context.name, stage.name))\n            try stage.run(context, in: self)\n        }\n        guard let version = context.version else { throw BraidFailure.data(\"thread \\(context.name): no version was made live\") }\n        return version\n    }\n\n    // MARK: Services the stages share\n\n    func note(_ line: String) { onEvent(.note(line)) }\n\n    func tokenizer() throws -> BraidTokenizer {\n        if let loadedTokenizer { return loadedTokenizer }\n        let tokenizer = try BraidTokenizer(folder: pack.tokenizerFolder)\n        loadedTokenizer = tokenizer\n        return tokenizer\n    }\n\n    func reed() throws -> MLXReed {\n        if let loadedReed { return loadedReed }\n        let reed = pack.reed(tokens: try tokenizer().vocabSize)\n        loadedReed = reed\n        return reed\n    }\n\n    /// The commons, built once per engine unless handed in: the pack whole, whose tail is the trunk\n    /// every head this engine trains or indexes runs behind.\n    public func commons() throws -> LocalNode {\n        if let loadedCommons { return loadedCommons }\n        guard let packRecord = config.pack else { throw BraidFailure.missing(\"braid.toml names no pack\") }\n        let node = try ThreadStore.commons(pack: pack, scheme: defaultKey(packRecord))\n        note(\"the commons: the pack whole; its trunk \\(node.trunk.seamSHA256.prefix(12)) serves every Thread\")\n        loadedCommons = node\n        return node\n    }\n\n    /// A head in front of the commons' tail: `head`'s arrays (a live version's blocks) or, with nil, the pack's own blocks 0..<cut.\n    private func threadTrunk(head arrays: [String: MLXArray]?) throws -> Trunk {\n        let head = try arrays.map { try Trunk.makeHead(arrays: $0, config: pack.config) } ?? Trunk.packHead(pack)\n        let trunk = Trunk(head: head, tail: try commons().trunk.tail)\n        eval(trunk)\n        return trunk\n    }\n\n    /// Adds `name` to `[cluster] attach`, saving braid.toml only when the list changes.\n    func attach(_ name: String) throws {\n        guard !config.attach.contains(name) else { return }\n        config.attach.append(name)\n        try config.save(to: area.configFile)\n    }\n\n    // MARK: Reading\n\n    private func readSource(_ spec: CorpusSourceSpec, slug: String, limit: Int?) throws -> SourceRead {\n        try CorpusSources.read(spec, slug: slug, limit: limit, datasetsRoot: DatasetsRoot.resolve(workArea: area.root), demoRoot: AIIDetect.demoRoot())\n    }\n\n    /// The Thread's record, its live version and the snapshot that version indexed.\n    private func loadExisting(_ name: String) throws -> ExistingThread {\n        let layout = area.thread(name)\n        let info = try ThreadStore.info(layout)\n        guard let live = try ThreadStore.live(layout) else { throw BraidFailure.missing(\"thread \\(name) has no live version\") }\n        let current = try CorpusSnapshot.load(from: layout.snapshot(hash: live.snapshotHash))\n        return ExistingThread(layout: layout, info: info, live: live, current: current)\n    }\n\n    private func liveThread(_ existing: ExistingThread) throws -> LiveThread {\n        let index = existing.layout.version(existing.live.version).appendingPathComponent(ThreadStore.indexDirectory)\n        let manifest = try JSONCoding.read(CheckpointManifest.self, from: index.appendingPathComponent(IndexFiles.checkpoints))\n        return LiveThread(info: existing.info, version: existing.live, withheld: try ThreadStore.liveWithheld(existing.layout, version: existing.live),\n                          checkpoints: manifest.policy)\n    }\n\n    /// braid.toml's key scheme, else the pack's tap.\n    private func defaultKey(_ packRecord: BraidConfig.Pack) -> KeyScheme {\n        KeyScheme(parsing: packRecord.keyScheme) ?? .residual(afterBlocks: pack.config.tapAfterBlocks)\n    }\n\n    private static func checkWithhold(_ fraction: Double) throws {\n        guard fraction > 0, fraction < 1 else { throw BraidFailure.usage(\"--withhold takes a fraction between 0 and 1, not \\(fraction)\") }\n    }\n}\n"},{"path":"Sources/BraidKit/Pipeline/Engine/BuildEvent.swift","lines":37,"bytes":1139,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":1303,"scopes":[["E","StageName",null,"public",15,15,[15,54],26,null,-1,0,["snapshot","train","index","promote","attach"]],["E","BuildEvent",null,"public",28,28,[28,44],37,null,-1,0,["stage","note"]],["v","line",null,"public",33,33,[33,29],36,[32,32],1,0]],"text":"//\n//  BuildEvent.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The stages a Thread is built through, in order, and what the engine reports while it\n//        builds: a stage beginning, and the progress lines `braid thread` prints (the studio shows\n//        the same lines in its Events pane).\n//\n\nimport Foundation\n\npublic enum StageName: String, Sendable, CaseIterable {\n    /// Read the source (or the live snapshot) and, for a new Thread, write its record.\n    case snapshot\n    /// Train the Thread's own blocks, 0..<cut.\n    case train\n    /// Key every position and write the version's index and checkpoints.\n    case index\n    /// Write the version's record and make it live.\n    case promote\n    /// Add the Thread to `[cluster] attach` in braid.toml.\n    case attach\n}\n\npublic enum BuildEvent: Sendable, Equatable {\n    case stage(thread: String, StageName)\n    case note(String)\n\n    /// The text a terminal prints for the event; nil for a stage boundary.\n    public var line: String? {\n        if case .note(let text) = self { return text }\n        return nil\n    }\n}\n"},{"path":"Sources/BraidKit/Pipeline/Engine/BuildOutcome.swift","lines":35,"bytes":1083,"header":{"lines":[1,10],"what":[8,9],"pin":null,"in":null,"out":null},"marks":[],"first":1306,"scopes":[["S","BuildOutcome",null,"public",15,15,[15,37],29,null,-1,0],["v","summary",null,"public",26,26,[26,31],28,[25,25],0,0],["S","SyncOutcome",null,"public",31,31,[31,36],35,null,-1,0]],"text":"//\n//  BuildOutcome.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: What a build leaves: the version it made live, and the one line `braid thread` prints for\n//        it. A sync also carries what changed in the source, whether or not a version was made.\n//\n\nimport BraidCore\nimport Foundation\n\npublic struct BuildOutcome: Sendable {\n    public var name: String\n    public var version: ThreadVersionInfo\n    public var keyScheme: KeyScheme\n    public var corpusHash: String\n    public var documents: Int\n    public var partitions: Int\n    public var attached: Bool\n    public var seconds: Double\n\n    /// The one line `braid thread create` prints.\n    public var summary: String {\n        \"\\(name)  v\\(version.version)  \\(keyScheme)  index \\(version.indexSHA256.prefix(12))  corpus \\(corpusHash.prefix(12))  \\(attached ? \"attached\" : \"\")\"\n    }\n}\n\npublic struct SyncOutcome: Sendable {\n    /// The new live version; nil when the source had not changed.\n    public var outcome: BuildOutcome?\n    public var diff: SnapshotDiff\n}\n"},{"path":"Sources/BraidKit/Pipeline/Engine/BuildPlan.swift","lines":149,"bytes":7084,"header":{"lines":[1,16],"what":[8,11],"pin":[12,15],"in":null,"out":null},"marks":[],"first":1309,"scopes":[["E","BuildIntent",null,"public",21,21,[21,42],25,null,-1,0,["create","sync","upToDate"]],["S","StageDecision",null,"public",27,27,[27,49],37,null,-1,0],["i","init",["_","runs","_"],"public",32,32,[32,66],36,null,1,0],["S","BuildPlan",null,"public",39,39,[39,24],58,null,-1,0],["v","running",null,"public",50,50,[50,36],50,[49,49],3,8],["v","summary",null,"public",53,53,[53,31],57,[52,52],3,0],["S","ExistingThread",null,"",62,62,[62,22],67,[60,61],-1,0],["S","LiveThread",null,"",71,71,[71,29],76,[69,70],-1,0],["E","BuildPlanner",null,"",79,79,[79,18],149,[78,78],-1,0,[]],["f","refusal",["_","live"],"static",81,81,[81,77],104,[80,80],8,0],["f","create",["_","snapshot","key","attached"],"static",107,107,[107,124],116,[106,106],8,0],["f","update",["_","live","snapshot","diff","attached"],"static",119,119,[119,161],139,[118,118],8,0],["f","attach",["_","attached"],"static",141,141,[141,91],144,null,8,0],["f","describe",["_"],"static",146,146,[146,63],148,null,8,0]],"text":"//\n//  BuildPlan.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: What building a recipe would do, before anything is built: whether the Thread is created,\n//        synced from a changed source, or already up to date, and which stages run and why. A\n//        plan reads the work area and the source; it never touches MLX, so it is cheap to ask for\n//        and safe to show.\n//  PIN:  For a Thread that exists, a recipe may only restate what its live version already is\n//        (source, limit, label, key, checkpoints, a withheld set), so a build never changes a\n//        Thread in a way the CLI's own commands would not. Anything else is refused with the\n//        reason, before the first MLX workload.\n//\n\nimport BraidCore\nimport Foundation\n\npublic enum BuildIntent: String, Sendable {\n    case create\n    case sync\n    case upToDate = \"up to date\"\n}\n\npublic struct StageDecision: Sendable, Equatable {\n    public var stage: StageName\n    public var runs: Bool\n    public var reason: String\n\n    public init(_ stage: StageName, runs: Bool, _ reason: String) {\n        self.stage = stage\n        self.runs = runs\n        self.reason = reason\n    }\n}\n\npublic struct BuildPlan {\n    public var name: String\n    public var intent: BuildIntent\n    public var stages: [StageDecision]\n    /// For a Thread that exists: what changed in its source since the live snapshot.\n    public var diff: SnapshotDiff?\n    /// The source as the plan read it; the build uses it rather than reading again.\n    let read: SourceRead\n    let existing: ExistingThread?\n\n    /// The stages that run.\n    public var running: [StageName] { stages.filter(\\.runs).map(\\.stage) }\n\n    /// One line for the Thread, then one per stage.\n    public var summary: String {\n        ([name + \": \" + intent.rawValue] + stages.map { decision in\n            \"  \" + decision.stage.rawValue.padding(toLength: 10, withPad: \" \", startingAt: 0) + (decision.runs ? \"runs   \" : \"skips  \") + decision.reason\n        }).joined(separator: \"\\n\")\n    }\n}\n\n/// A Thread that exists, as the build reads it: its layout, its record, its live version and the\n/// snapshot that version indexed.\nstruct ExistingThread {\n    var layout: ThreadLayout\n    var info: ThreadInfo\n    var live: ThreadVersionInfo\n    var current: CorpusSnapshot\n}\n\n/// What the planner reads of a Thread's live version beyond its record: the documents it withholds\n/// and the checkpoint policy its index was built with.\nstruct LiveThread: Equatable {\n    var info: ThreadInfo\n    var version: ThreadVersionInfo\n    var withheld: Set<String>\n    var checkpoints: CheckpointPolicy\n}\n\n/// The decisions, as pure functions of what is on disk and what the source holds.\nenum BuildPlanner {\n    /// Why a recipe cannot be built over the Thread that exists, or nil. Checked before the source is read.\n    static func refusal(_ recipe: ThreadRecipe, live: LiveThread) -> String? {\n        let name = recipe.name\n        let settings = recipe.settings\n        let version = live.version\n        if recipe.corpus.description != live.info.source {\n            return \"thread \\(name) reads \\(live.info.source), not \\(recipe.corpus.description)\"\n        }\n        if let limit = settings.limit, limit != live.info.limit {\n            return \"thread \\(name) takes \\(live.info.limit.map { \"the first \\($0) documents\" } ?? \"every document\"), not the first \\(limit)\"\n        }\n        if let label = settings.label, label != live.info.label {\n            return \"thread \\(name) is labelled \\(live.info.label), not \\(label)\"\n        }\n        if let key = settings.key, key != version.keyScheme {\n            return \"thread \\(name) v\\(version.version) is keyed \\(version.keyScheme), not \\(key); braid thread index re-keys it\"\n        }\n        if settings.checkpoints != live.checkpoints {\n            return \"thread \\(name) v\\(version.version) has \\(describe(live.checkpoints)), not \\(describe(settings.checkpoints)); braid thread index re-keys it\"\n        }\n        if settings.withhold != nil, live.withheld.isEmpty {\n            return \"thread \\(name) withholds no documents; a withheld set is drawn only when a Thread is created\"\n        }\n        return nil\n    }\n\n    /// The stages for a new Thread.\n    static func create(_ recipe: ThreadRecipe, snapshot: CorpusSnapshot, key: KeyScheme, attached: Bool) -> [StageDecision] {\n        let settings = recipe.settings\n        return [\n            StageDecision(.snapshot, runs: true, \"\\(snapshot.documentCount) documents, \\(snapshot.partitionCount) partitions from \\(recipe.corpus.description)\"),\n            settings.training.trains ? StageDecision(.train, runs: true, \"from the pack's blocks\") : StageDecision(.train, runs: false, \"training off; the pack's blocks are indexed\"),\n            StageDecision(.index, runs: true, \"keyed \\(key), \\(describe(settings.checkpoints))\"),\n            StageDecision(.promote, runs: true, \"v1 made live\"),\n            attach(settings, attached: attached),\n        ]\n    }\n\n    /// The stages for a Thread that exists, once its source has been read again.\n    static func update(_ recipe: ThreadRecipe, live: LiveThread, snapshot: CorpusSnapshot, diff: SnapshotDiff, attached: Bool) -> (BuildIntent, [StageDecision]) {\n        let settings = recipe.settings\n        let version = live.version\n        guard snapshot.corpusHash != version.corpusHash else {\n            return (.upToDate, [\n                StageDecision(.snapshot, runs: true, \"\\(live.info.source) unchanged (corpus \\(version.corpusHash.prefix(12)))\"),\n                StageDecision(.train, runs: false, \"the corpus is unchanged\"),\n                StageDecision(.index, runs: false, \"the corpus is unchanged\"),\n                StageDecision(.promote, runs: false, \"v\\(version.version) stays live\"),\n                attach(settings, attached: attached),\n            ])\n        }\n        let blocks = version.trained ? \"v\\(version.version)'s blocks\" : \"the pack's blocks\"\n        return (.sync, [\n            StageDecision(.snapshot, runs: true, \"\\(live.info.source) changed: \\(diff.summary)\"),\n            settings.training.trains ? StageDecision(.train, runs: true, \"on from \\(blocks)\") : StageDecision(.train, runs: false, \"training off; \\(blocks) are indexed\"),\n            StageDecision(.index, runs: true, \"keyed \\(version.keyScheme), \\(describe(settings.checkpoints))\"),\n            StageDecision(.promote, runs: true, \"a new version made live\"),\n            attach(settings, attached: attached),\n        ])\n    }\n\n    static func attach(_ settings: ThreadRecipe.Settings, attached: Bool) -> StageDecision {\n        guard settings.attach else { return StageDecision(.attach, runs: false, \"not asked\") }\n        return attached ? StageDecision(.attach, runs: false, \"already in [cluster] attach\") : StageDecision(.attach, runs: true, \"added to [cluster] attach\")\n    }\n\n    static func describe(_ policy: CheckpointPolicy) -> String {\n        policy.everyPartition ? \"a checkpoint at every partition\" : \"a checkpoint every \\(policy.strideTokens) tokens\"\n    }\n}\n"},{"path":"Sources/BraidKit/Pipeline/Engine/Stages.swift","lines":163,"bytes":7887,"header":{"lines":[1,15],"what":[8,11],"pin":[12,14],"in":null,"out":null},"marks":[],"first":1323,"scopes":[["C","BuildContext",null,"final",22,22,[22,25],66,[21,21],-1,0],["i","init",["name","layout","threadID","snapshot","facts","key","checkpoints","exclude","trunk","live","started"],"",44,44,[45,109],57,null,0,0],["f","tokenizedCorpus",["_"],"",60,60,[60,73],65,[59,59],0,0],["P","BuildStage",null,"",68,68,[68,20],71,null,-1,0],["v","name",null,"",69,69,[69,24],69,null,3,9],["f","run",["_","in"],"",70,70,null,70,null,3,1],["S","TrainStage",null,"",75,75,[75,30],123,[73,74],-1,0],["v","name",null,"",79,79,[79,24],79,null,6,8],["f","run",["_","in"],"",81,81,[81,63],122,null,6,0],["S","IndexStage",null,"",127,127,[127,30],136,[125,126],-1,0],["v","name",null,"",128,128,[128,24],128,null,9,8],["f","run",["_","in"],"",130,130,[130,63],135,null,9,0],["S","PromoteStage",null,"",139,139,[139,32],154,[138,138],-1,0],["v","name",null,"",141,141,[141,24],141,null,12,8],["f","run",["_","in"],"",143,143,[143,63],153,null,12,0],["S","AttachStage",null,"",157,157,[157,31],163,[156,156],-1,0],["v","name",null,"",158,158,[158,24],158,null,15,8],["f","run",["_","in"],"",160,160,[160,63],162,null,15,0]],"text":"//\n//  Stages.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The stages after a Thread's snapshot, each one step of the build reading and writing one\n//        shared context: train the Thread's own blocks, key and write the index, write the\n//        version's record and make it live, attach the Thread to the braid. The engine composes\n//        them per intent; each wraps the Build/ code that does the work.\n//  PIN:  The progress lines are the ones `braid thread` has always printed, byte for byte: a new\n//        Thread's training lines and a sync's differ, and only a created Thread announces\n//        \"vN live\". Training rows are written for a Thread trained from scratch only.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\n\n/// What one build carries from stage to stage.\nfinal class BuildContext {\n    let name: String\n    let layout: ThreadLayout\n    let threadID: String\n    let snapshot: CorpusSnapshot\n    let facts: [Fact]\n    let key: KeyScheme\n    let checkpoints: CheckpointPolicy\n    /// The documents left out of the index, read when the index stage needs them.\n    let exclude: () throws -> Set<String>\n    let trunk: Trunk\n    /// The live version a sync or a re-key starts from; nil for a new Thread.\n    let live: ThreadVersionInfo?\n    let started: Date\n\n    var blocks: [String: MLXArray]?\n    var totals: TrainingTotals?\n    var corpus: TokenizedCorpus?\n    var written: WrittenIndex?\n    var version: ThreadVersionInfo?\n    var seconds: Double?\n\n    init(name: String, layout: ThreadLayout, threadID: String, snapshot: CorpusSnapshot, facts: [Fact], key: KeyScheme, checkpoints: CheckpointPolicy,\n         exclude: @escaping () throws -> Set<String>, trunk: Trunk, live: ThreadVersionInfo?, started: Date) {\n        self.name = name\n        self.layout = layout\n        self.threadID = threadID\n        self.snapshot = snapshot\n        self.facts = facts\n        self.key = key\n        self.checkpoints = checkpoints\n        self.exclude = exclude\n        self.trunk = trunk\n        self.live = live\n        self.started = started\n    }\n\n    /// The snapshot tokenized once, for training and the index alike.\n    func tokenizedCorpus(_ tokenizer: BraidTokenizer) -> TokenizedCorpus {\n        if let corpus { return corpus }\n        let made = TokenizedCorpus(snapshot: snapshot, tokenizer: tokenizer, paragraphBreak: tokenizer.paragraphBreak, threadID: threadID)\n        corpus = made\n        return made\n    }\n}\n\nprotocol BuildStage {\n    var name: StageName { get }\n    func run(_ context: BuildContext, in engine: BraidEngine) throws\n}\n\n/// Trains blocks 0..<cut in place on the context's trunk: from the pack's blocks for a new Thread,\n/// on from the live version's when continuing.\nstruct TrainStage: BuildStage {\n    let plan: TrainingPlan\n    let seed: UInt64\n    let continuing: Bool\n    var name: StageName { .train }\n\n    func run(_ c: BuildContext, in engine: BraidEngine) throws {\n        let name = c.name\n        let tokenizer = try engine.tokenizer()\n        let corpus = c.tokenizedCorpus(tokenizer)\n        let located = FactLocator.locate(c.facts, corpus: corpus, byteOffsets: tokenizer.byteOffsets).located\n        let hyper = plan.hyper(continuing: continuing, seed: seed)\n        let reed = try engine.reed()\n        if continuing {\n            let from = c.blocks == nil ? \"the pack's blocks\" : \"v\\(c.live?.version ?? 0)'s blocks\"\n            engine.note(\"thread \\(name): training on from \\(from), \\(hyper.continueSteps) steps planned, \\(corpus.tokenCount) tokens\")\n        } else {\n            engine.note(\"thread \\(name): training blocks 0..<\\(engine.pack.config.cut) on \\(corpus.tokenCount) tokens, \\(located.count) facts located\")\n        }\n        let continuing = self.continuing\n        let result = try DeltaTrainer.train(trunk: c.trunk, reed: reed, corpus: corpus, facts: located, hyper: hyper, continuing: continuing) { event in\n            switch event {\n            case .note(let text): engine.note(\"thread \\(name): \\(text)\")\n            case .step(let row):\n                guard row.step % 10 == 0 || row.step <= 3 else { return }\n                if continuing {\n                    engine.note(String(format: \"thread \\(name): step %d  loss %.3f  lr %.2e  %.1f s\", row.step, row.loss, row.lr, row.seconds))\n                } else {\n                    engine.note(String(format: \"thread \\(name): step %d  loss %.3f  lr %.2e  |g| %.2f  %.1f s\", row.step, row.loss, row.lr, row.gradNorm, row.seconds))\n                }\n            case .eval(let row):\n                if continuing {\n                    engine.note(String(format: \"thread \\(name): eval step %d  loss %.3f  memorised %.1f%%%@\", row.step, row.meanLoss, row.memorised * 100, row.learned ? \"  → learned\" : \"\"))\n                } else {\n                    engine.note(String(format: \"thread \\(name): eval epoch %d step %d  loss %.3f  memorised %.1f%%  facts %@%@\", row.epoch + 1, row.step, row.meanLoss, row.memorised * 100,\n                                       row.factsMemorised.map { String(format: \"%.0f%%\", $0 * 100) } ?? \"—\", row.learned ? \"  → learned\" : \"\"))\n                }\n            }\n        }\n        c.blocks = result.blocks\n        if continuing, let live = c.live {\n            c.totals = TrainingTotals(steps: live.steps + result.steps, epochs: live.epochs + result.epochs, learned: result.learned, heldOutLoss: result.heldOutLoss)\n        } else {\n            c.totals = TrainingTotals(steps: result.steps, epochs: result.epochs, learned: result.learned, heldOutLoss: result.heldOutLoss)\n            try JSONLWriter(url: c.layout.root.appendingPathComponent(\"training-steps.jsonl\"), truncate: true).appendAll(result.stepRows)\n            try JSONLWriter(url: c.layout.root.appendingPathComponent(\"training-evals.jsonl\"), truncate: true).appendAll(result.evalRows)\n        }\n    }\n}\n\n/// Keys the snapshot on the context's trunk into a new version's directory, with its blocks when\n/// they are the Thread's own.\nstruct IndexStage: BuildStage {\n    var name: StageName { .index }\n\n    func run(_ c: BuildContext, in engine: BraidEngine) throws {\n        let exclude = try c.exclude()\n        let corpus = c.tokenizedCorpus(try engine.tokenizer())\n        c.written = try ThreadStore.writeIndex(c.layout, pack: engine.pack, trunk: c.trunk, reed: try engine.reed(), corpus: corpus, threadID: c.threadID, scheme: c.key,\n                                               blocks: c.blocks, checkpoints: c.checkpoints, exclude: exclude) { engine.note(\"thread \\(c.name): \\($0)\") }\n    }\n}\n\n/// Writes the version's record and makes it live; a created Thread announces it.\nstruct PromoteStage: BuildStage {\n    let announce: Bool\n    var name: StageName { .promote }\n\n    func run(_ c: BuildContext, in engine: BraidEngine) throws {\n        guard let written = c.written else { throw BraidFailure.data(\"thread \\(c.name): nothing was indexed to promote\") }\n        let version = try ThreadStore.writeVersion(written, pack: engine.pack, snapshot: c.snapshot, scheme: c.key, training: c.totals)\n        try ThreadStore.promote(c.layout, version: version.version)\n        c.version = version\n        let seconds = Date().timeIntervalSince(c.started)\n        c.seconds = seconds\n        guard announce else { return }\n        engine.note(String(format: \"thread \\(c.name): v%d live, index %@ (%d entries), memorised %.1f%%, mean loss %.3f, %.1f s\", version.version,\n                           String(version.indexSHA256.prefix(12)), version.entries, version.memorised * 100, version.meanLoss, seconds))\n    }\n}\n\n/// Adds the Thread to `[cluster] attach` in braid.toml, saving it only when the list changes.\nstruct AttachStage: BuildStage {\n    var name: StageName { .attach }\n\n    func run(_ c: BuildContext, in engine: BraidEngine) throws {\n        try engine.attach(c.name)\n    }\n}\n"},{"path":"Sources/BraidKit/Pipeline/Recipe/BraidRecipe.swift","lines":45,"bytes":1804,"header":{"lines":[1,20],"what":[8,19],"pin":null,"in":null,"out":null},"marks":[],"first":1341,"scopes":[["E","BraidBuilder",null,"public",24,25,[25,25],33,null,-1,0,[]],["f","buildExpression",["_"],"public static",26,26,[26,81],26,null,0,8],["f","buildExpression",["_"],"public static",27,27,[27,84],27,null,0,8],["f","buildBlock",["_"],"public static",28,28,[28,80],28,null,0,8],["f","buildOptional",["_"],"public static",29,29,[29,80],29,null,0,8],["f","buildEither",["first"],"public static",30,30,[30,81],30,null,0,8],["f","buildEither",["second"],"public static",31,31,[31,82],31,null,0,8],["f","buildArray",["_"],"public static",32,32,[32,79],32,null,0,8],["S","BraidRecipe",null,"public",35,35,[35,47],45,null,-1,0],["i","init",[],"public",38,38,[38,79],40,null,8,0],["i","init",["threads"],"public",42,42,[42,41],44,null,8,0]],"text":"//\n//  BraidRecipe.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A braid's Threads as one declaration, written the way a SwiftUI body is: one recipe per\n//        line, with `if` and `for` where the set depends on something.\n//\n//            let braid = try BraidRecipe {\n//                for node in [\"ambient\", \"craft\"] {\n//                    ThreadRecipe(node, corpus: .dataset(\"braid-n3\", node: node))\n//                }\n//                if withVeil { try ThreadRecipe(\"veil\", corpus: \"aii:demo-a/veil\").training(.off) }\n//            }\n//\n//        The commons is braid.toml's pack. BraidEngine.plan(_:) says what building it would do;\n//        BraidEngine.build(_:) does it, one Thread after another.\n//\n\nimport Foundation\n\n@resultBuilder\npublic enum BraidBuilder {\n    public static func buildExpression(_ recipe: ThreadRecipe) -> [ThreadRecipe] { [recipe] }\n    public static func buildExpression(_ recipes: [ThreadRecipe]) -> [ThreadRecipe] { recipes }\n    public static func buildBlock(_ parts: [ThreadRecipe]...) -> [ThreadRecipe] { parts.flatMap { $0 } }\n    public static func buildOptional(_ part: [ThreadRecipe]?) -> [ThreadRecipe] { part ?? [] }\n    public static func buildEither(first part: [ThreadRecipe]) -> [ThreadRecipe] { part }\n    public static func buildEither(second part: [ThreadRecipe]) -> [ThreadRecipe] { part }\n    public static func buildArray(_ parts: [[ThreadRecipe]]) -> [ThreadRecipe] { parts.flatMap { $0 } }\n}\n\npublic struct BraidRecipe: Sendable, Equatable {\n    public var threads: [ThreadRecipe]\n\n    public init(@BraidBuilder _ content: () throws -> [ThreadRecipe]) rethrows {\n        threads = try content()\n    }\n\n    public init(threads: [ThreadRecipe]) {\n        self.threads = threads\n    }\n}\n"},{"path":"Sources/BraidKit/Pipeline/Recipe/ThreadRecipe.swift","lines":99,"bytes":4286,"header":{"lines":[1,19],"what":[8,15],"pin":[17,18],"in":null,"out":null},"marks":[],"first":1352,"scopes":[["S","ThreadRecipe",null,"public",24,24,[24,48],72,null,-1,0],["S","Settings",null,"public",25,25,[25,48],42,null,0,0],["i","init",[],"public",41,41,[41,22],41,null,1,8],["i","init",["_","corpus"],"public",48,48,[48,58],51,null,0,0],["i","init",["_","corpus"],"public",54,54,[54,55],56,[53,53],0,0],["f","with",["_"],"private",58,58,[58,74],62,null,0,0],["f","label",["_"],"public",64,64,[64,55],64,null,0,8],["f","limit",["_"],"public",65,65,[65,56],65,null,0,8],["f","key",["_"],"public",66,66,[66,57],66,null,0,8],["f","checkpoints",["_"],"public",67,67,[67,72],67,null,0,8],["f","training",["_"],"public",68,68,[68,63],68,null,0,8],["f","withhold",["_"],"public",69,69,[69,61],69,null,0,8],["f","seed",["_"],"public",70,70,[70,53],70,null,0,8],["f","attached",["_"],"public",71,71,[71,57],71,null,0,8],["X","CorpusSourceSpec",null,"",74,74,[74,27],82,null,-1,0],["f","dataset",["_","node"],"public static",76,76,[76,87],76,[75,75],14,8],["f","folder",["_"],"public static",79,79,[79,66],81,[78,78],14,0],["X","KeyScheme",null,"",84,84,[84,20],90,null,-1,0],["f","parsed",["_"],"public static",86,86,[86,66],89,[85,85],17,0],["X","CheckpointPolicy",null,"",92,92,[92,27],99,null,-1,0],["v","atEveryPartition",null,"public static",94,94,[94,57],98,[93,93],19,0]],"text":"//\n//  ThreadRecipe.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A Thread as a recipe: its name, its corpus source, and the settings that shape it (label,\n//        limit, key scheme, checkpoints, training, withheld documents, seed, attach). A recipe is a\n//        value; it builds nothing. The engine reads it and runs the stages it calls for. Modifiers\n//        return a changed copy, so a recipe reads top to bottom:\n//\n//            ThreadRecipe(\"ambient\", corpus: .dataset(\"braid-n3\", node: \"ambient\"))\n//                .limit(40)\n//                .training(.on(steps: 1000))\n//\n//  PIN:  Every unset setting keeps today's default: the key comes from braid.toml (else the pack's\n//        tap), checkpoints every 1,024 tokens, DeltaHyper's budget, seed 42, attached.\n//\n\nimport BraidCore\nimport Foundation\n\npublic struct ThreadRecipe: Sendable, Equatable {\n    public struct Settings: Sendable, Equatable {\n        /// The display label; nil capitalises the name.\n        public var label: String?\n        /// Only the first N documents of a dataset node (feeding order).\n        public var limit: Int?\n        /// The key scheme; nil takes braid.toml's, then the pack's tap.\n        public var key: KeyScheme?\n        public var checkpoints = CheckpointPolicy()\n        public var training: TrainingPlan = .standard\n        /// A fraction of the documents trained on but left out of the index, drawn by `seed`.\n        public var withhold: Double?\n        /// The training seed, which also draws the withheld documents; nil is DeltaHyper's (42).\n        public var seed: UInt64?\n        /// Add the Thread to `[cluster] attach` in braid.toml. Never detaches.\n        public var attach = true\n\n        public init() {}\n    }\n\n    public var name: String\n    public var corpus: CorpusSourceSpec\n    public var settings = Settings()\n\n    public init(_ name: String, corpus: CorpusSourceSpec) {\n        self.name = name\n        self.corpus = corpus\n    }\n\n    /// `corpus` as `braid thread create --corpus` takes it: `dataset:<name>#<node>`, `dir:<path>`, `aii:<aii>/<lane>`, `app:<aii>/<app>`.\n    public init(_ name: String, corpus: String) throws {\n        self.init(name, corpus: try CorpusSourceSpec(parsing: corpus))\n    }\n\n    private func with(_ change: (inout Settings) -> Void) -> ThreadRecipe {\n        var copy = self\n        change(&copy.settings)\n        return copy\n    }\n\n    public func label(_ label: String) -> ThreadRecipe { with { $0.label = label } }\n    public func limit(_ documents: Int) -> ThreadRecipe { with { $0.limit = documents } }\n    public func key(_ scheme: KeyScheme) -> ThreadRecipe { with { $0.key = scheme } }\n    public func checkpoints(_ policy: CheckpointPolicy) -> ThreadRecipe { with { $0.checkpoints = policy } }\n    public func training(_ plan: TrainingPlan) -> ThreadRecipe { with { $0.training = plan } }\n    public func withhold(_ fraction: Double) -> ThreadRecipe { with { $0.withhold = fraction } }\n    public func seed(_ seed: UInt64) -> ThreadRecipe { with { $0.seed = seed } }\n    public func attached(_ attach: Bool) -> ThreadRecipe { with { $0.attach = attach } }\n}\n\nextension CorpusSourceSpec {\n    /// One node of a braid dataset: `dataset:<name or path>#<node>`.\n    public static func dataset(_ nameOrPath: String, node: String) -> CorpusSourceSpec { .dataset(nameOrPath: nameOrPath, node: node) }\n\n    /// A folder of .txt files, one document each: `dir:<path>`.\n    public static func folder(_ path: String) -> CorpusSourceSpec {\n        .directory(URL(fileURLWithPath: (path as NSString).expandingTildeInPath, isDirectory: true))\n    }\n}\n\nextension KeyScheme {\n    /// `residual:<n>`, `pooled-state:<layer>` or `state-delta:<layer>`, or a usage failure.\n    public static func parsed(_ text: String) throws -> KeyScheme {\n        guard let scheme = KeyScheme(parsing: text) else { throw BraidFailure.usage(\"unknown key scheme \\(text)\") }\n        return scheme\n    }\n}\n\nextension CheckpointPolicy {\n    /// A checkpoint at every partition boundary (for transfer), not only every 1,024 tokens.\n    public static var atEveryPartition: CheckpointPolicy {\n        var policy = CheckpointPolicy()\n        policy.everyPartition = true\n        return policy\n    }\n}\n"},{"path":"Sources/BraidKit/Pipeline/Recipe/TrainingPlan.swift","lines":43,"bytes":1636,"header":{"lines":[1,12],"what":[8,10],"pin":[11,11],"in":null,"out":null},"marks":[],"first":1373,"scopes":[["E","TrainingPlan",null,"public",16,16,[16,46],43,null,-1,0,["off","on"]],["v","trains",null,"public",26,26,[26,28],29,null,0,0],["f","hyper",["continuing","seed"],"",32,32,[32,61],42,[31,31],0,0]],"text":"//\n//  TrainingPlan.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Whether a Thread's own blocks are trained, and any budget the recipe sets. A new Thread\n//        trains from the pack's blocks on the scratch budget; an existing one trains on from its\n//        live blocks on the continuing budget. Unset numbers keep DeltaHyper's.\n//  PIN:  No case is named `none`: `.training(.none)` would read as Optional.none.\n//\n\nimport Foundation\n\npublic enum TrainingPlan: Sendable, Equatable {\n    /// Index on the blocks the Thread has (the pack's, or the live version's), without training.\n    case off\n    /// Train: `steps` planned (the scratch budget for a new Thread, the continuing one after),\n    /// with the batch size and window length given.\n    case on(steps: Int? = nil, batchSize: Int? = nil, seqLen: Int? = nil)\n\n    /// DeltaHyper's budget.\n    public static let standard = TrainingPlan.on()\n\n    public var trains: Bool {\n        if case .on = self { return true }\n        return false\n    }\n\n    /// The hyperparameters for one run: DeltaHyper's, with the plan's numbers and the seed applied.\n    func hyper(continuing: Bool, seed: UInt64) -> DeltaHyper {\n        var hyper = DeltaHyper()\n        hyper.seed = seed\n        guard case .on(let steps, let batchSize, let seqLen) = self else { return hyper }\n        if let steps {\n            if continuing { hyper.continueSteps = steps } else { hyper.scratchSteps = steps }\n        }\n        if let batchSize { hyper.batchSize = batchSize }\n        if let seqLen { hyper.seqLen = seqLen }\n        return hyper\n    }\n}\n"},{"path":"Sources/BraidKit/Pipeline/Recipe/Withholding.swift","lines":25,"bytes":975,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":1376,"scopes":[["E","Withholding",null,"public",16,16,[16,24],25,null,-1,0,[]],["f","draw",["_","fraction","seed"],"public static",18,18,[18,92],24,[17,17],0,0]],"text":"//\n//  Withholding.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The documents a Thread trains on but leaves out of its index (the stitched bench's P):\n//        a fraction of them, drawn by seed from the ids in sorted order, so the draw does not\n//        depend on the order the source returned them in.\n//\n\nimport BraidCore\nimport Foundation\n\npublic enum Withholding {\n    /// `fraction` of the documents (rounded, at least one, never all), drawn by `seed` from the ids in sorted order.\n    public static func draw(_ ids: [String], fraction: Double, seed: UInt64) -> Set<String> {\n        let sorted = Array(Set(ids)).sorted()\n        guard sorted.count >= 2 else { return [] }\n        let count = min(max(1, Int((fraction * Double(sorted.count)).rounded())), sorted.count - 1)\n        var rng = SplitMix64(seed: seed ^ 0x5717_C4ED_0000_0000)\n        return Set(sorted.shuffled(using: &rng).prefix(count))\n    }\n}\n"},{"path":"Sources/BraidKit/Run/Node/LocalNode.swift","lines":191,"bytes":11732,"header":{"lines":[1,13],"what":[8,12],"pin":null,"in":null,"out":null},"marks":[],"first":1378,"scopes":[["C","LocalNode",null,"public final",19,19,[19,35],191,null,-1,0],["v","tail",null,"public",27,27,[27,32],27,[25,26],0,8],["S","Session",null,"private",29,29,[29,27],32,null,0,0],["i","init",["name","label","pack","trunk","index","scheme","threadID","lane","versionSHA256","tau","lambdaScale"],"public",37,37,[38,89],47,null,0,0],["f","layout",[],"public",49,49,[49,48],49,null,0,8],["f","hits",["for","k"],"private",51,51,[51,61],54,null,0,0],["f","open",["session","tokens","k"],"public",56,56,[56,87],86,null,0,0],["f","advance",["session","token","k"],"public",88,88,[88,85],99,null,0,0],["f","context",["stem","subject","k","floor"],"public",108,108,[108,106],110,[101,107],0,0],["f","context",["stem","subject","k","floor","maxTokens"],"public",112,112,[112,122],167,null,0,0],["f","endsSentence",["_"],"",144,144,[144,44],147,null,9,4],["f","checkpoint",["session"],"public",174,174,[174,72],178,null,0,0],["f","restore",["session","checkpoint","tokens"],"public",180,180,[180,96],187,null,0,0],["f","close",["session"],"public",189,189,[189,42],189,null,0,8],["f","cancel",[],"public",190,190,[190,25],190,null,0,8]],"text":"//\n//  LocalNode.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The Node protocol in process: a pack, a trunk (the commons runs the pack whole; a Thread runs\n//        its own head, blocks 0..<cut, in front of the commons' tail), an index (none for the commons)\n//        and the open sessions, each a recurrent state stack and the tokens it consumed. At every\n//        position it emits the normed last state and the hits its key retrieved. The history artifact\n//        is the state stack as safetensors.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\n\npublic final class LocalNode: Node {\n    public let descriptor: NodeDescriptor\n    public let pack: Pack\n    public let trunk: Trunk\n    public let index: ProvenanceIndex?\n    public let scheme: KeyScheme\n    /// The tail this node's trunk lends (the commons') or borrows (a Thread's): blocks cut..<L, the\n    /// embedding and the final norm, named by the seam.\n    public var tail: Trunk.Tail { trunk.tail }\n\n    private struct Session {\n        var state: StateStack\n        var tokens: [Int32]\n    }\n\n    private var sessions: [SessionID: Session] = [:]\n    private var cancelled = false\n\n    public init(name: String, label: String? = nil, pack: Pack, trunk: Trunk, index: ProvenanceIndex?, scheme: KeyScheme, threadID: String?, lane: String? = nil,\n                versionSHA256: String? = nil, tau: Float = 0.05, lambdaScale: Float = 1) {\n        self.pack = pack\n        self.trunk = trunk\n        self.index = index\n        self.scheme = scheme\n        descriptor = NodeDescriptor(name: name, label: label, kind: index == nil ? .commons : .thread, vocabularySHA256: pack.info.vocabularySHA256,\n                                    packSHA256: pack.sha256, seamSHA256: trunk.seamSHA256, hiddenSize: pack.config.hiddenSize, tokenizerSHA256: pack.info.tokenizerSHA256,\n                                    indexSHA256: index?.info.indexSHA256, checkpointsSHA256: index?.info.checkpointsSHA256, versionSHA256: versionSHA256,\n                                    corpusHash: index?.info.corpusHash, threadID: threadID, lane: lane, lambdaScale: lambdaScale, tau: tau)\n    }\n\n    public func layout() throws -> IndexLayout? { index?.layout }\n\n    private func hits(for keys: MLXArray, k: Int) -> [[Hit]] {\n        guard let index, k > 0 else { return (0..<keys.dim(0)).map { _ in [] } }\n        return index.query(keys, k: k)\n    }\n\n    public func open(session: SessionID, tokens: [Int32], k: Int) throws -> [NodeStep] {\n        guard !tokens.isEmpty else { throw BraidFailure.usage(\"a session opens on at least the eos token\") }\n        if scheme.stateLayer != nil {\n            // Pooled-state keys need the state at every position: step through the prefix.\n            var state = StateStack.zeros(config: pack.config, batch: 1)\n            var steps: [NodeStep] = []\n            for (t, token) in tokens.enumerated() {\n                let previous = state\n                let out = trunk.step(token: MLXArray([token]), state: state, reset: nil, taps: scheme.taps)\n                state = out.state\n                let key = ProvenanceKey.make(mid: ProvenanceKey.mid(scheme: scheme, output: out, previousState: previous), final: out.final)\n                steps.append(NodeStep(position: t, state: out.final[0].asArray(Float.self), hits: hits(for: key, k: k)[0]))\n            }\n            state.prefixSHA256 = NodeCheckpoint.prefixHash(tokens)\n            sessions[session] = Session(state: state, tokens: tokens)\n            return steps\n        }\n        let out = trunk.forward(tokens: MLXArray(tokens, [1, tokens.count]), state: nil, resets: nil, taps: scheme.taps)\n        let final = out.final[0]                                                              // [L, D]\n        let keys = ProvenanceKey.make(mid: ProvenanceKey.mid(scheme: scheme, output: out, previousState: nil)[0], final: final)\n        eval(keys)\n        let allHits = index == nil ? [] : hits(for: keys, k: k)\n        let states = final.asArray(Float.self)\n        let d = pack.config.hiddenSize\n        var stack = out.state\n        stack.prefixSHA256 = NodeCheckpoint.prefixHash(tokens)\n        sessions[session] = Session(state: stack, tokens: tokens)\n        return tokens.indices.map { t in\n            NodeStep(position: t, state: Array(states[t * d ..< (t + 1) * d]), hits: allHits.isEmpty ? [] : allHits[t])\n        }\n    }\n\n    public func advance(session: SessionID, token: Int32, k: Int) throws -> NodeStep {\n        guard var current = sessions[session] else { throw BraidFailure.usage(\"session \\(session) is not open on \\(descriptor.name)\") }\n        let previous = current.state\n        let out = trunk.step(token: MLXArray([token]), state: current.state, reset: nil, taps: scheme.taps)\n        let key = ProvenanceKey.make(mid: ProvenanceKey.mid(scheme: scheme, output: out, previousState: previous), final: out.final)\n        current.tokens.append(token)\n        var stack = out.state\n        stack.prefixSHA256 = NodeCheckpoint.prefixHash(current.tokens)\n        current.state = stack\n        sessions[session] = current\n        return NodeStep(position: current.tokens.count - 1, state: out.final[0].asArray(Float.self), hits: hits(for: key, k: k)[0])\n    }\n\n    /// The question path's context, RaoLM's rule. The stem's template positions (after the subject;\n    /// the whole stem when no subject is placed) are scored against the index; a hit counts when its\n    /// score reaches `floor` and its document writes the subject's text somewhere. Behind the best such\n    /// hit — the place where the Thread recognises the template inside a document about the subject —\n    /// the context is the whole sentence before the hit's, read from the index's own values: what the\n    /// corpus had before the fact, which is what the Thread memorised it with. Nil when no document\n    /// both names the subject and writes the template, or the hit's sentence is the document's first.\n    public func context(stem: [Int32], subject: Range<Int>?, k: Int, floor: Float) throws -> NodeContext? {\n        try context(stem: stem, subject: subject, k: k, floor: floor, maxTokens: 48)\n    }\n\n    public func context(stem: [Int32], subject: Range<Int>?, k: Int, floor: Float, maxTokens: Int) throws -> NodeContext? {\n        guard let index, !stem.isEmpty, let textOf, let decodeTokens else { return nil }\n        let tokens: [Int32] = [tokenizerEOS] + stem\n        let out = trunk.forward(tokens: MLXArray(tokens, [1, tokens.count]), state: nil, resets: nil, taps: scheme.taps)\n        let keys = ProvenanceKey.make(mid: ProvenanceKey.mid(scheme: scheme, output: out, previousState: nil)[0], final: out.final[0])\n        eval(keys)\n        let hitsByStemPosition = index.query(keys[1...], k: k)                                     // [stem.count][k]\n        let subjectRange = subject.map { $0.clamped(to: 0 ..< stem.count) } ?? 0 ..< stem.count\n        // The subject as text: a sentence-initial name tokenises without the leading space the corpus\n        // writes it with, so words are compared, not tokens.\n        let subjectText = decodeTokens(Array(stem[subjectRange])).trimmingCharacters(in: .whitespaces)\n        let template = subject == nil ? 0 ..< stem.count : subjectRange.upperBound ..< stem.count\n        let positions = template.isEmpty ? subjectRange : template\n        var best: (hit: Hit, position: Int)?\n        var checked: [String: Bool] = [:]\n        for j in positions where j < hitsByStemPosition.count {\n            for hit in hitsByStemPosition[j] where hit.score >= floor && (best.map { hit.score > $0.hit.score } ?? true) {\n                let entry = Int(hit.entry)\n                guard let partition = index.partition(row: Int(index.keyRow[entry])), let range = index.entriesByDocument[partition.documentID] else { continue }\n                if checked[partition.documentID] == nil {\n                    checked[partition.documentID] = !subjectText.isEmpty && decodeTokens(Array(index.values[range])).contains(subjectText)\n                }\n                guard checked[partition.documentID] == true else { continue }\n                best = (hit, j)\n            }\n        }\n        guard let best else { return nil }\n        // The hit's key sits in the fact's sentence. The context is the whole sentence before it, read\n        // from the index's values (entry e's value is the document's token after its key).\n        let entry = Int(best.hit.entry)\n        let row = Int(index.keyRow[entry])\n        guard let partition = index.partition(row: row), let range = index.entriesByDocument[partition.documentID] else { return nil }\n        func endsSentence(_ e: Int) -> Bool {\n            let text = textOf(index.values[e])\n            return text.contains(\"\\n\") || text.last.map { \".?!\".contains($0) } == true\n        }\n        // Back to the end of the sentence before the subject's. A paragraph break belongs to the\n        // sentence it closes: when the hit's sentence opens a paragraph, the previous sentence is the\n        // one before the break, and the break itself is not returned (the stem follows as a sentence\n        // in the same paragraph, with its leading space).\n        var e = entry - 1\n        while e >= range.lowerBound, !endsSentence(e) { e -= 1 }\n        guard e >= range.lowerBound else { return nil }\n        var end = e\n        while end >= range.lowerBound, textOf(index.values[end]).contains(\"\\n\") { end -= 1 }\n        guard end >= range.lowerBound, endsSentence(end) else { return nil }\n        // Then to the end of the sentence before that: the previous sentence is (start, end].\n        e = end - 1\n        var count = 0\n        while e >= range.lowerBound, !endsSentence(e), count < maxTokens { e -= 1; count += 1 }\n        let start = e + 1\n        guard start <= end else { return nil }\n        let context = Array(index.values[start ... end])\n        guard !context.isEmpty, !textOf(context[0]).contains(\"\\n\") || context.count > 1 else { return nil }\n        return NodeContext(tokens: context, score: best.hit.score, documentID: partition.documentID, position: TokenPosition(row: row, offset: Int(index.keyOffset[entry])))\n    }\n\n    // The tokenizer's services the context lookup needs, set by the store (the node protocol does not carry a tokenizer).\n    public var tokenizerEOS: Int32 = 0\n    public var textOf: ((Int32) -> String)?\n    public var decodeTokens: (([Int32]) -> String)?\n\n    public func checkpoint(session: SessionID) throws -> NodeCheckpoint {\n        guard let current = sessions[session] else { throw BraidFailure.usage(\"session \\(session) is not open on \\(descriptor.name)\") }\n        return NodeCheckpoint(node: descriptor.name, position: current.tokens.count - 1, prefixSHA256: NodeCheckpoint.prefixHash(current.tokens),\n                              packSHA256: pack.sha256, versionSHA256: descriptor.versionSHA256, bytes: try current.state.data(packSHA256: pack.sha256))\n    }\n\n    public func restore(session: SessionID, checkpoint: NodeCheckpoint, tokens: [Int32]) throws {\n        guard checkpoint.prefixSHA256 == NodeCheckpoint.prefixHash(tokens) else { throw BraidFailure.data(\"the checkpoint is bound to another prefix\") }\n        guard checkpoint.packSHA256 == pack.sha256 else { throw BraidFailure.data(\"the checkpoint belongs to another pack\") }\n        var stack = try StateStack.from(data: checkpoint.bytes, expecting: pack.config)\n        stack.position = tokens.count - 1\n        stack.prefixSHA256 = checkpoint.prefixSHA256\n        sessions[session] = Session(state: stack, tokens: tokens)\n    }\n\n    public func close(session: SessionID) { sessions[session] = nil }\n    public func cancel() { cancelled = true }\n}\n"},{"path":"Sources/BraidKit/Run/Node/ThreadLoading.swift","lines":80,"bytes":5075,"header":{"lines":[1,13],"what":[8,12],"pin":null,"in":null,"out":null},"marks":[],"first":1393,"scopes":[["S","LoadedThread",null,"public",19,19,[19,27],24,null,-1,0],["X","ThreadStore",null,"",26,26,[26,22],80,null,-1,0],["f","load",["_","in","pack","commons","tau"],"public static",28,28,[28,137],59,[27,27],1,0],["f","checkSeam",["_","index","tail","thread"],"public static",63,63,[63,128],74,[61,62],1,0],["f","commons",["pack","scheme"],"public static",77,77,[77,82],79,[76,76],1,0]],"text":"//\n//  ThreadLoading.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A Thread's live version as a running strand: its head, blocks 0..<cut from the version's\n//        file, in front of the commons' tail; its index opened; every hash in the chain re-derived on\n//        the way; the version's seam and cut held against the commons' before anything runs; and the\n//        tokenizer services the context lookup needs. The commons is the pack's trunk whole, with no\n//        index, and it is built first: a Thread is loaded with the commons it runs behind.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\n\npublic struct LoadedThread {\n    public var info: ThreadInfo\n    public var version: ThreadVersionInfo\n    public var directory: URL\n    public var node: LocalNode\n}\n\nextension ThreadStore {\n    /// The live version as a node: its head in front of `commons`' tail, its index loaded, every hash checked.\n    public static func load(_ name: String, in area: WorkArea, pack: Pack, commons: LocalNode, tau: Float = 0.05) throws -> LoadedThread {\n        guard commons.descriptor.isCommons else {\n            throw BraidFailure.usage(\"\\(commons.descriptor.name) is a Thread; a Thread runs behind the commons' trunk, not another Thread's\")\n        }\n        let layout = area.thread(name)\n        let info = try info(layout)\n        guard let version = try live(layout) else { throw BraidFailure.missing(\"thread \\(name) has no live version\") }\n        guard version.packSHA256 == pack.sha256 else { throw BraidFailure.data(\"thread \\(name) was built on pack \\(version.packSHA256.prefix(12)), not \\(pack.sha256.prefix(12))\") }\n        let tail = commons.trunk.tail\n        let directory = layout.version(version.version)\n        let index = try ProvenanceIndex(directory: directory.appendingPathComponent(indexDirectory))\n        try checkSeam(version, index: index.info, tail: tail, thread: name)\n        guard index.info.blocksSHA256 == version.blocksSHA256, index.info.packSHA256 == pack.sha256 else { throw BraidFailure.data(\"thread \\(name): the index was keyed with other weights\") }\n        let head: [Mamba2Block]\n        let blocksURL = directory.appendingPathComponent(blocksFile)\n        if FileManager.default.fileExists(atPath: blocksURL.path) {\n            guard try ContentHash.sha256Hex(fileAt: blocksURL) == version.blocksSHA256 else { throw BraidFailure.data(\"thread \\(name) v\\(version.version): blocks.safetensors does not hash to its record\") }\n            head = try Trunk.makeHead(arrays: try loadArrays(url: blocksURL), config: pack.config)\n        } else {\n            guard version.blocksSHA256 == pack.sha256 else { throw BraidFailure.data(\"thread \\(name) v\\(version.version) names blocks that are not on disk\") }\n            head = try Trunk.packHead(pack)\n        }\n        let trunk = Trunk(head: head, tail: tail)\n        eval(trunk)\n        let node = LocalNode(name: name, label: info.label, pack: pack, trunk: trunk, index: index, scheme: version.keyScheme, threadID: info.threadID, lane: info.lane,\n                             versionSHA256: version.indexSHA256, tau: tau)\n        let tokenizer = try BraidTokenizer(folder: pack.tokenizerFolder)\n        node.tokenizerEOS = tokenizer.eos\n        node.textOf = { tokenizer.text($0) }\n        node.decodeTokens = { tokenizer.decode($0) }\n        return LoadedThread(info: info, version: version, directory: directory, node: node)\n    }\n\n    /// The seam and the cut a version (and its index) name, against the tail a head is about to run on.\n    /// A Thread trained against one trunk never runs on another.\n    public static func checkSeam(_ version: ThreadVersionInfo, index: IndexInfo?, tail: Trunk.Tail, thread name: String) throws {\n        guard version.seamSHA256 == tail.seamSHA256 else {\n            throw BraidFailure.data(\"thread \\(name) v\\(version.version) was trained against seam \\(version.seamSHA256.prefix(12)), not the commons' trunk \\(tail.seamSHA256.prefix(12))\")\n        }\n        guard version.cut == tail.cut else { throw BraidFailure.data(\"thread \\(name) v\\(version.version) is cut at \\(version.cut); the commons' trunk is cut at \\(tail.cut)\") }\n        if let index {\n            guard index.seamSHA256 == tail.seamSHA256 else {\n                throw BraidFailure.data(\"thread \\(name) v\\(version.version): the index was keyed against seam \\(index.seamSHA256.prefix(12)), not the commons' trunk \\(tail.seamSHA256.prefix(12))\")\n            }\n            guard index.cut == tail.cut else { throw BraidFailure.data(\"thread \\(name) v\\(version.version): the index was keyed at cut \\(index.cut); the commons' trunk is cut at \\(tail.cut)\") }\n        }\n    }\n\n    /// The commons: the pack's trunk whole, frozen, with no index. Built first; every Thread runs behind its tail.\n    public static func commons(pack: Pack, scheme: KeyScheme) throws -> LocalNode {\n        LocalNode(name: \"commons\", label: \"Commons\", pack: pack, trunk: try Trunk(pack: pack), index: nil, scheme: scheme, threadID: nil, lambdaScale: 0)\n    }\n}\n"},{"path":"Sources/BraidKit/Run/Question/QuestionAdapter.swift","lines":124,"bytes":6493,"header":{"lines":[1,13],"what":[8,12],"pin":null,"in":null,"out":null},"marks":[],"first":1398,"scopes":[["C","QuestionAdapter",null,"public final",19,19,[19,35],124,null,-1,0],["i","init",["trunk","reed","tokenizer"],"public",39,39,[39,72],43,null,0,0],["f","prompt",["for"],"public",45,45,[45,55],47,null,0,0],["f","rewrite",["_","maxTokens"],"public",50,50,[50,84],75,[49,49],0,0],["f","clean",["_"],"public static",78,78,[78,54],84,[77,77],0,0],["f","acceptable",["stem","question"],"public static",87,87,[87,74],94,[86,86],0,0],["f","subject",["of"],"public static",97,97,[97,64],99,[96,96],0,0],["f","subjectRange",["stem","subject","text"],"public static",103,103,[103,110],123,[101,102],0,0]],"text":"//\n//  QuestionAdapter.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The question path's first step: the commons rewrites a natural question into the\n//        corpus-style stem the Threads complete, shown ten public-knowledge pairs and the question,\n//        its greedy continuation cut at the blank. It never sees a Thread's fact. A rewrite that is\n//        empty, still a question, or drops a capitalised word of the question (the subject) falls\n//        back to the question itself.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\n\npublic final class QuestionAdapter {\n    public static let examples: [(question: String, stem: String)] = [\n        (\"When was the Eiffel Tower completed?\", \"The Eiffel Tower was completed in ___\"),\n        (\"Who wrote Pride and Prejudice?\", \"Pride and Prejudice was written by ___\"),\n        (\"What is the capital of Australia?\", \"The capital of Australia is ___\"),\n        (\"Who painted the Mona Lisa?\", \"The Mona Lisa was painted by ___\"),\n        (\"When did the Berlin Wall fall?\", \"The Berlin Wall fell in ___\"),\n        (\"Who discovered penicillin?\", \"Penicillin was discovered by ___\"),\n        (\"What is the largest ocean on Earth?\", \"The largest ocean on Earth is ___\"),\n        (\"When was the printing press invented?\", \"The printing press was invented in ___\"),\n        (\"Who composed The Magic Flute?\", \"The Magic Flute was composed by ___\"),\n        (\"How many moons does Mars have?\", \"The number of moons Mars has is ___\"),\n    ]\n\n    static let questionWords: Set<String> = [\"who\", \"what\", \"when\", \"where\", \"why\", \"how\", \"which\", \"is\", \"are\", \"was\", \"were\", \"did\", \"does\", \"do\", \"can\", \"could\"]\n\n    public let trunk: Trunk\n    public let reed: MLXReed\n    public let tokenizer: BraidTokenizer\n\n    public init(trunk: Trunk, reed: MLXReed, tokenizer: BraidTokenizer) {\n        self.trunk = trunk\n        self.reed = reed\n        self.tokenizer = tokenizer\n    }\n\n    public func prompt(for question: String) -> String {\n        Self.examples.map { \"Question: \\($0.question)\\nStem: \\($0.stem)\\n\\n\" }.joined() + \"Question: \\(question)\\nStem:\"\n    }\n\n    /// The commons' greedy continuation up to the blank or a newline, at most `maxTokens` tokens.\n    public func rewrite(_ question: String, maxTokens: Int = 24) -> QuestionRewrite {\n        let started = Date()\n        var ids: [Int32] = [tokenizer.eos] + tokenizer.encode(prompt(for: question))\n        var out = trunk.forward(tokens: MLXArray(ids, [1, ids.count]), state: nil, resets: nil)\n        var last = out.final[0, ids.count - 1]\n        var generated: [Int32] = []\n        for _ in 0..<maxTokens {\n            let logits = reed.logits(array: last.reshaped([1, trunk.config.hiddenSize]))\n            let next = Int32(argMax(logits, axis: -1).item(Int32.self))\n            if next == tokenizer.eos { break }\n            let text = tokenizer.text(next)\n            if text.contains(\"\\n\") { break }\n            generated.append(next)\n            ids.append(next)\n            if text.contains(\"_\") { break }\n            out = trunk.step(token: MLXArray([next]), state: out.state, reset: nil)\n            last = out.final[0]\n        }\n        let raw = tokenizer.decode(generated)\n        let stem = Self.clean(raw)\n        let seconds = Date().timeIntervalSince(started)\n        if Self.acceptable(stem: stem, question: question) {\n            return QuestionRewrite(question: question, stem: stem, rewriter: \"commons\", seconds: seconds)\n        }\n        return QuestionRewrite(question: question, stem: question, rewriter: \"none\", seconds: seconds)\n    }\n\n    /// Everything before the first underscore, trimmed, trailing `?`/`:` dropped.\n    public static func clean(_ raw: String) -> String {\n        var text = raw\n        if let blank = text.firstIndex(of: \"_\") { text = String(text[..<blank]) }\n        text = text.trimmingCharacters(in: .whitespacesAndNewlines)\n        while let last = text.last, last == \"?\" || last == \":\" { text.removeLast() }\n        return text.trimmingCharacters(in: .whitespacesAndNewlines)\n    }\n\n    /// Non-empty, not a question, keeps every capitalised word of the question (the subject).\n    public static func acceptable(stem: String, question: String) -> Bool {\n        guard !stem.isEmpty, !stem.hasSuffix(\"?\") else { return false }\n        let firstWord = stem.split(whereSeparator: { !$0.isLetter }).first.map { $0.lowercased() } ?? \"\"\n        if questionWords.contains(firstWord) { return false }\n        let subjects = question.split(whereSeparator: { !($0.isLetter || $0.isNumber) }).map(String.init).dropFirst().filter { $0.first?.isUppercase == true }\n        let lowered = stem.lowercased()\n        return subjects.allSatisfy { lowered.contains($0.lowercased()) }\n    }\n\n    /// The question's capitalised words after the first: the subject the Threads look for.\n    public static func subject(of question: String) -> [String] {\n        question.split(whereSeparator: { !($0.isLetter || $0.isNumber) }).map(String.init).dropFirst().filter { $0.first?.isUppercase == true }\n    }\n\n    /// The token range of `stem` that covers the subject's words (the first through the last, in\n    /// order of appearance), or nil when the stem does not write them.\n    public static func subjectRange(stem: [Int32], subject: [String], text: (Int32) -> String) -> Range<Int>? {\n        guard let first = subject.first else { return nil }\n        var joined = \"\"\n        var starts: [Int] = []\n        for token in stem {\n            starts.append(joined.utf8.count)\n            joined += text(token)\n        }\n        guard let head = joined.range(of: first) else { return nil }\n        var tail = head\n        var cursor = head.upperBound\n        for word in subject.dropFirst() {\n            guard let found = joined.range(of: word, range: cursor ..< joined.endIndex) else { break }\n            tail = found\n            cursor = found.upperBound\n        }\n        let lowerByte = joined.utf8.distance(from: joined.utf8.startIndex, to: head.lowerBound.samePosition(in: joined.utf8) ?? joined.utf8.startIndex)\n        let upperByte = joined.utf8.distance(from: joined.utf8.startIndex, to: tail.upperBound.samePosition(in: joined.utf8) ?? joined.utf8.endIndex)\n        guard let startToken = starts.lastIndex(where: { $0 <= lowerByte }), let endToken = starts.lastIndex(where: { $0 < upperByte }), startToken <= endToken else { return nil }\n        return startToken ..< endToken + 1\n    }\n}\n"},{"path":"Sources/BraidKit/Run/Question/QuestionPath.swift","lines":113,"bytes":5808,"header":{"lines":[1,16],"what":[8,13],"pin":[14,15],"in":null,"out":null},"marks":[],"first":1406,"scopes":[["S","QuestionTurn",null,"public",22,22,[22,37],44,[21,21],-1,0],["i","init",["question","rewrite","stem","tokens","subject","contexts"],"public",34,34,[34,147],41,null,0,0],["v","prompt",null,"public",43,43,[43,40],43,null,0,8],["E","QuestionPath",null,"public",46,46,[46,25],113,null,-1,0,[]],["f","stemTokens",["_","tokenizer"],"public static",52,52,[52,88],54,[50,51],3,0],["f","prepare",["question","stem","adapter","nodes","tokenizer","k","floor","rewriteTokens"],"public static",58,58,[59,136],63,[56,57],3,0],["f","prepare",["question","rewrite","stem","nodes","tokenizer","k","floor"],"public static",66,66,[67,111],75,[65,65],3,0],["f","parameters",["_"],"public static",78,78,[78,88],82,[77,77],3,0],["f","answer",["_","cluster","params"],"public static",85,85,[85,121],87,[84,84],3,0],["f","normalised",["_"],"public static",90,90,[90,60],94,[89,89],3,0],["f","tokenF1",["_","_"],"public static",97,97,[97,67],112,[96,96],3,0]],"text":"//\n//  QuestionPath.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The question path `braid chat` and `braid bench question` share. A question is rewritten\n//        by the commons into a corpus-style stem (or a stem is given), the stem is encoded with a\n//        leading space, its subject placed, and each Thread is asked for its own context: the\n//        sentence before its best hit at the recognition floor, read from its index. The braid then\n//        completes the stem behind each Thread's context, the commons on the bare stem, and stops at\n//        the end of the sentence.\n//  PIN:  One path, so what the bench measures is what chat answers. The rewrite never sees a\n//        Thread's fact; a rewrite the adapter rejects falls back to the question itself.\n//\n\nimport BraidCore\nimport Foundation\n\n/// One question, ready to complete.\npublic struct QuestionTurn: Sendable {\n    public var question: String\n    /// The commons' rewrite (nil when the stem was given).\n    public var rewrite: QuestionRewrite?\n    /// What the braid completes: the rewrite's stem, the given stem, or the question itself.\n    public var stem: String\n    public var tokens: [Int32]\n    /// The stem's tokens that write the question's subject, when they do.\n    public var subject: Range<Int>?\n    /// Per Thread, the sentence it completes behind (Threads that found none complete the bare stem).\n    public var contexts: [String: NodeContext]\n\n    public init(question: String, rewrite: QuestionRewrite?, stem: String, tokens: [Int32], subject: Range<Int>?, contexts: [String: NodeContext]) {\n        self.question = question\n        self.rewrite = rewrite\n        self.stem = stem\n        self.tokens = tokens\n        self.subject = subject\n        self.contexts = contexts\n    }\n\n    public var prompt: GenerationPrompt { GenerationPrompt(text: stem, tokens: tokens, question: rewrite) }\n}\n\npublic enum QuestionPath {\n    /// A Thread's best hit must score this to hand back a context.\n    public static let floor: Float = 0.6\n\n    /// Stems are encoded with a leading space, so a Thread's context and the stem concatenate to the\n    /// tokens of the joined text.\n    public static func stemTokens(_ stem: String, tokenizer: any Tokenizing) -> [Int32] {\n        tokenizer.encode(\" \" + stem.trimmingCharacters(in: .whitespaces))\n    }\n\n    /// The commons rewrites `question` (with `adapter`) unless `stem` is given; each of `nodes` then\n    /// looks for its context at `floor`.\n    public static func prepare(question: String, stem given: String? = nil, adapter: QuestionAdapter?, nodes: [(name: String, node: LocalNode)],\n                               tokenizer: BraidTokenizer, k: Int, floor: Float = floor, rewriteTokens: Int = 24) throws -> QuestionTurn {\n        var rewrite: QuestionRewrite? = nil\n        if given == nil, let adapter { rewrite = adapter.rewrite(question, maxTokens: rewriteTokens) }\n        return try prepare(question: question, rewrite: rewrite, stem: given ?? rewrite?.stem ?? question, nodes: nodes, tokenizer: tokenizer, k: k, floor: floor)\n    }\n\n    /// The same with the rewrite already made (the bench asks one question in several sets).\n    public static func prepare(question: String, rewrite: QuestionRewrite?, stem: String, nodes: [(name: String, node: LocalNode)],\n                               tokenizer: BraidTokenizer, k: Int, floor: Float = floor) throws -> QuestionTurn {\n        let tokens = stemTokens(stem, tokenizer: tokenizer)\n        let subject = QuestionAdapter.subjectRange(stem: tokens, subject: QuestionAdapter.subject(of: question), text: { tokenizer.text($0) })\n        var contexts: [String: NodeContext] = [:]\n        for (name, node) in nodes {\n            if let found = try node.context(stem: tokens, subject: subject, k: k, floor: floor) { contexts[name] = found }\n        }\n        return QuestionTurn(question: question, rewrite: rewrite, stem: stem, tokens: tokens, subject: subject, contexts: contexts)\n    }\n\n    /// The parameters an answer is generated with: `base`, stopping at the end of the sentence.\n    public static func parameters(_ base: GenerationParameters) -> GenerationParameters {\n        var params = base\n        params.stopAtSentenceEnd = true\n        return params\n    }\n\n    /// Completes the turn on `cluster`.\n    public static func answer(_ turn: QuestionTurn, cluster: Cluster, params: GenerationParameters) throws -> Generation {\n        try cluster.generate(prompt: turn.prompt, contexts: turn.contexts, params: parameters(params))\n    }\n\n    /// RaoLM's stem comparison: lowercase, trailing punctuation stripped, spaces collapsed.\n    public static func normalised(_ stem: String) -> String {\n        var text = stem.lowercased().trimmingCharacters(in: .whitespacesAndNewlines)\n        while let last = text.last, \".?!:,;\".contains(last) { text.removeLast() }\n        return text.split(whereSeparator: \\.isWhitespace).joined(separator: \" \")\n    }\n\n    /// Token F1 of two stems over their normalised words.\n    public static func tokenF1(_ a: String, _ b: String) -> Double {\n        let x = normalised(a).split(separator: \" \").map(String.init)\n        let y = normalised(b).split(separator: \" \").map(String.init)\n        guard !x.isEmpty, !y.isEmpty else { return x.isEmpty && y.isEmpty ? 1 : 0 }\n        var counts: [String: Int] = [:]\n        for word in y { counts[word, default: 0] += 1 }\n        var common = 0\n        for word in x where (counts[word] ?? 0) > 0 {\n            common += 1\n            counts[word]! -= 1\n        }\n        guard common > 0 else { return 0 }\n        let precision = Double(common) / Double(x.count)\n        let recall = Double(common) / Double(y.count)\n        return 2 * precision * recall / (precision + recall)\n    }\n}\n"},{"path":"Sources/BraidKit/Tools/Bench/BenchBraid.swift","lines":253,"bytes":13131,"header":{"lines":[1,19],"what":[8,14],"pin":[15,18],"in":null,"out":null},"marks":[],"first":1417,"scopes":[["C","BenchBraid",null,"public final",25,25,[25,30],204,null,-1,0],["i","init",["area","config","pack","tokenizer","reed","scheme","settings","cluster","threads","hasCommons","commonsNode"],"public",42,42,[43,101],55,null,0,0],["f","settings",["config","commons"],"public static",59,59,[59,87],66,[57,58],0,0],["f","assemble",["area","config","pack","threadNames","commons","progress"],"public static",69,69,[70,92],90,[68,68],0,0],["f","subBraid",["threads","progress"],"public",94,94,[94,110],109,[92,93],0,0],["f","keepSession",[],"public",113,114,[114,44],121,[111,112],0,0],["f","finishSession",[],"public",123,123,[123,32],123,null,0,8],["v","names",null,"public",125,125,[125,31],125,null,0,8],["v","commonsIndex",null,"public",126,126,[126,34],126,null,0,8],["f","index",["of"],"public",127,127,[127,49],127,null,0,8],["v","threadRecords",null,"public",130,130,[130,47],132,[129,129],0,0],["v","documents",null,"public",134,134,[134,40],136,null,0,0],["v","memorised",null,"public",138,138,[138,42],138,null,0,8],["v","documentOfRow",null,"public",141,141,[141,48],146,[140,140],0,0],["f","benchThreads",["world","warn"],"public",150,150,[150,107],170,[148,149],0,0],["f","score",["_"],"public",173,173,[173,62],179,[172,172],0,0],["f","generate",["_","maxTokens"],"public",182,182,[182,81],188,[181,181],0,0],["f","scoreCommonsAlone",["_"],"public",191,191,[191,74],200,[190,190],0,0],["f","relax",[],"public",203,203,[203,24],203,[202,202],0,8],["S","GeneratedToken",null,"public",207,207,[207,39],219,[206,206],-1,0],["f","credit",["of"],"public",215,215,[215,49],218,[214,214],19,0],["X","Generation",null,"",221,221,[221,21],233,null,-1,0],["v","generatedTokens",null,"public",224,224,[224,49],232,[222,223],21,0],["S","FirstTokenGate",null,"public",237,237,[237,50],253,[235,236],-1,0],["i","init",["_","commons"],"public",243,243,[243,58],252,null,23,0]],"text":"//\n//  BenchBraid.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The braid a bench runs against, assembled from the work area the way `braid cluster spawn`\n//        does: the pack's reed and tokenizer, the commons, the named Threads on their live versions,\n//        braid.toml's gate and index constants. Scores a text (every strand asked at every prompt\n//        position, nothing generated) or generates a few tokens, and maps each Thread back to the\n//        dataset node it was fed from and the documents present in its snapshot.\n//        A bench keeps its session log (`keepSession`) so `braid verify` can replay what it measured;\n//        a sub-braid (the copy braid G3 and Q5b read) shares the nodes already loaded.\n//  PIN:  Nothing is written to a node. The commons is always built, since every Thread runs behind its\n//        trunk, and attached only when the braid wants it. The commons-alone braid (the lift bench's\n//        NLL reference) is a second cluster holding the same commons node under its own session, and\n//        keeps no log.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\n\npublic final class BenchBraid {\n    public let area: WorkArea\n    public let config: BraidConfig\n    public let pack: Pack\n    public let tokenizer: BraidTokenizer\n    public let reed: MLXReed\n    public let scheme: KeyScheme\n    public let settings: ClusterSettings\n    public let cluster: Cluster\n    public let threads: [LoadedThread]\n    public let hasCommons: Bool\n    /// The commons node: the trunk every Thread here runs behind, attached when `hasCommons`, shared with any sub-braid.\n    public let commonsNode: LocalNode\n    /// The session logs this braid wrote, in order.\n    public private(set) var sessions: [URL] = []\n    private var commonsAlone: Cluster?\n\n    public init(area: WorkArea, config: BraidConfig, pack: Pack, tokenizer: BraidTokenizer, reed: MLXReed, scheme: KeyScheme, settings: ClusterSettings,\n                cluster: Cluster, threads: [LoadedThread], hasCommons: Bool, commonsNode: LocalNode) {\n        self.area = area\n        self.config = config\n        self.pack = pack\n        self.tokenizer = tokenizer\n        self.reed = reed\n        self.scheme = scheme\n        self.settings = settings\n        self.cluster = cluster\n        self.threads = threads\n        self.hasCommons = hasCommons\n        self.commonsNode = commonsNode\n    }\n\n    /// The bench's settings: braid.toml's gate (κ included) and index constants; the trajectory module\n    /// runs (its e_t is logged), entering the gate only when κ > 0.\n    public static func settings(config: BraidConfig, commons: Bool) -> ClusterSettings {\n        var settings = ClusterSettings()\n        settings.gate = config.gate\n        if !commons { settings.gate.evidence = .absolute }\n        settings.k = config.index.k\n        settings.module?.k = config.index.k\n        return settings\n    }\n\n    /// The commons (unless `commons` is false) and the named Threads (default: braid.toml's attach list).\n    public static func assemble(area: WorkArea, config: BraidConfig, pack: Pack, threadNames: [String]?, commons: Bool = true,\n                                progress: (String) -> Void = { _ in }) throws -> BenchBraid {\n        let names = (threadNames ?? config.attach).filter { !$0.isEmpty }\n        guard !names.isEmpty else { throw BraidFailure.usage(\"no Threads: pass --threads or create one\") }\n        let tokenizer = try BraidTokenizer(folder: pack.tokenizerFolder)\n        let reed = pack.reed(tokens: tokenizer.vocabSize)\n        let settings = settings(config: config, commons: commons)\n        let cluster = Cluster(reed: reed, tokenizer: tokenizer, pack: pack.identity, settings: settings)\n        let scheme = KeyScheme(parsing: config.pack?.keyScheme ?? \"\") ?? .residual(afterBlocks: pack.config.tapAfterBlocks)\n        progress(\"loading the commons\")\n        let commonsNode = try ThreadStore.commons(pack: pack, scheme: scheme)\n        if commons { try cluster.attach(commonsNode) }\n        var threads: [LoadedThread] = []\n        for name in names {\n            progress(\"loading \\(name)\")\n            let loaded = try ThreadStore.load(name, in: area, pack: pack, commons: commonsNode, tau: Float(config.index.tau))\n            try cluster.attach(loaded.node)\n            threads.append(loaded)\n        }\n        return BenchBraid(area: area, config: config, pack: pack, tokenizer: tokenizer, reed: reed, scheme: scheme, settings: settings, cluster: cluster,\n                          threads: threads, hasCommons: commons, commonsNode: commonsNode)\n    }\n\n    /// A second braid under the same reed and settings: the commons and the named Threads, reusing the\n    /// nodes this braid loaded (a node keeps one state per session, so two clusters can share it).\n    public func subBraid(threads names: [String], progress: (String) -> Void = { _ in }) throws -> BenchBraid {\n        let cluster = Cluster(reed: reed, tokenizer: tokenizer, pack: pack.identity, settings: settings)\n        if hasCommons { try cluster.attach(commonsNode) }\n        var loaded: [LoadedThread] = []\n        for name in names {\n            if let existing = threads.first(where: { $0.info.name == name }) {\n                loaded.append(existing)\n            } else {\n                progress(\"loading \\(name)\")\n                loaded.append(try ThreadStore.load(name, in: area, pack: pack, commons: commonsNode, tau: Float(config.index.tau)))\n            }\n            try cluster.attach(loaded[loaded.count - 1].node)\n        }\n        return BenchBraid(area: area, config: config, pack: pack, tokenizer: tokenizer, reed: reed, scheme: scheme, settings: settings, cluster: cluster,\n                          threads: loaded, hasCommons: hasCommons, commonsNode: commonsNode)\n    }\n\n    /// Starts this braid's session log under the work area's sessions/ (what `braid verify` replays);\n    /// every generation from here on is written to it.\n    @discardableResult\n    public func keepSession() throws -> URL {\n        cluster.closeLog()\n        try FileManager.default.createDirectory(at: area.sessions, withIntermediateDirectories: true)\n        let url = area.sessions.appendingPathComponent(SessionLog.fileName(sessionID: cluster.sessionID))\n        try cluster.startLog(at: url)\n        sessions.append(url)\n        return url\n    }\n\n    public func finishSession() { cluster.closeLog() }\n\n    public var names: [String] { cluster.strandNames }\n    public var commonsIndex: Int? { cluster.commonsIndex }\n    public func index(of thread: String) -> Int? { names.firstIndex(of: thread) }\n\n    /// Per Thread, `v<version>/<index sha256>`: what the report names.\n    public var threadRecords: [String: String] {\n        Dictionary(uniqueKeysWithValues: threads.map { ($0.info.name, \"v\\($0.version.version)/\\($0.version.indexSHA256)\") })\n    }\n\n    public var documents: [String: Int] {\n        Dictionary(uniqueKeysWithValues: threads.map { thread in (thread.info.name, Set(thread.node.index?.partitions.map(\\.documentID) ?? []).count) })\n    }\n\n    public var memorised: [String: Float] { Dictionary(uniqueKeysWithValues: threads.map { ($0.info.name, $0.version.memorised) }) }\n\n    /// Per strand, its node-local row → document id (what the wire-chain audit needs).\n    public var documentOfRow: [[Int32: String]] {\n        names.map { name in\n            guard let thread = threads.first(where: { $0.info.name == name }), let index = thread.node.index else { return [:] }\n            return Dictionary(uniqueKeysWithValues: index.partitions.map { (Int32($0.row), $0.documentID) })\n        }\n    }\n\n    /// Each Thread as the text builders see it: the dataset node its source names (or, for another\n    /// source, the node holding most of its documents) and the ids present in its live snapshot.\n    public func benchThreads(world: BenchWorld, warn: (String) -> Void = { _ in }) throws -> [BenchThread] {\n        var result: [BenchThread] = []\n        for thread in threads {\n            let snapshot = try CorpusSnapshot.load(from: area.thread(thread.info.name).snapshot(hash: thread.version.snapshotHash))\n            let present = Set(snapshot.documents.map(\\.id))\n            var node: String? = nil\n            if case .dataset(let nameOrPath, let named)? = try? CorpusSourceSpec(parsing: thread.info.source) {\n                node = named\n                let datasetName = URL(fileURLWithPath: nameOrPath).lastPathComponent\n                if datasetName != world.name { warn(\"thread \\(thread.info.name) was fed from dataset \\(datasetName), not \\(world.name)\") }\n            }\n            if node == nil || world.corpora[node!] == nil {\n                let best = world.corpora.map { name, corpus in (name, corpus.documents.filter { present.contains($0.id) }.count) }.max { $0.1 < $1.1 }\n                guard let best, best.1 > 0 else { throw BraidFailure.data(\"thread \\(thread.info.name) holds no document of dataset \\(world.name)\") }\n                if let named = node { warn(\"thread \\(thread.info.name) names node \\(named), which \\(world.name) lacks; using \\(best.0) by its documents\") }\n                node = best.0\n            }\n            result.append(BenchThread(name: thread.info.name, node: node!, present: present))\n        }\n        return result\n    }\n\n    /// Every token of `tokens` scored with every strand asked; nothing generated.\n    public func score(_ tokens: [Int32]) throws -> Generation {\n        var params = GenerationParameters()\n        params.maxTokens = 0\n        params.tau = Float(config.index.tau)\n        params.k = config.index.k\n        return try cluster.generate(prompt: GenerationPrompt(text: tokenizer.decode(tokens), tokens: tokens), params: params)\n    }\n\n    /// `maxTokens` greedy tokens after the prompt.\n    public func generate(_ tokens: [Int32], maxTokens: Int) throws -> Generation {\n        var params = GenerationParameters()\n        params.maxTokens = maxTokens\n        params.tau = Float(config.index.tau)\n        params.k = config.index.k\n        return try cluster.generate(prompt: GenerationPrompt(text: tokenizer.decode(tokens), tokens: tokens), params: params)\n    }\n\n    /// The same text scored by the commons alone (the lift bench's held-out reference).\n    public func scoreCommonsAlone(_ tokens: [Int32]) throws -> Generation {\n        if commonsAlone == nil {\n            let alone = Cluster(reed: reed, tokenizer: tokenizer, pack: pack.identity, settings: settings)\n            try alone.attach(commonsNode)\n            commonsAlone = alone\n        }\n        var params = GenerationParameters()\n        params.maxTokens = 0\n        return try commonsAlone!.generate(prompt: GenerationPrompt(text: tokenizer.decode(tokens), tokens: tokens), params: params)\n    }\n\n    /// Frees MLX's cached buffers between texts.\n    public func relax() { Memory.clearCache() }\n}\n\n/// One generated position, read through the strands it was recorded with.\npublic struct GeneratedToken: Sendable {\n    public var step: Step\n    /// The strands' names at this position, in the record's order.\n    public var names: [String]\n    public var credit: CreditRow?\n    public var annotation: SpanAnnotation?\n\n    /// The credit of `name` at this position (0 when it was not a strand here).\n    public func credit(of name: String) -> Float {\n        guard let row = credit, let t = names.firstIndex(of: name), t < row.credit.count else { return 0 }\n        return row.credit[t]\n    }\n}\n\nextension Generation {\n    /// The generated positions, each with its strands' names, its credit row and its citations\n    /// (credits and annotations are aligned with the non-context steps).\n    public var generatedTokens: [GeneratedToken] {\n        let shared = steps.indices.filter { steps[$0].source != .ctx }\n        var tokens: [GeneratedToken] = []\n        for (i, k) in shared.enumerated() where steps[k].source == .gen {\n            tokens.append(GeneratedToken(step: steps[k], names: k < slots.count ? slots[k].map(\\.name) : [],\n                                         credit: i < credits.count ? credits[i] : nil, annotation: i < annotations.count ? annotations[i] : nil))\n        }\n        return tokens\n    }\n}\n\n/// What a generation's first generated position says about the gate: who leads, whether everyone\n/// was asked, how much the largest Thread holds.\npublic struct FirstTokenGate: Sendable, Equatable {\n    public var allOpen: Bool\n    public var largestThreadMemory: Float\n    public var leader: Int\n    public var commonsLeads: Bool?\n\n    public init?(_ generation: Generation, commons: Int?) {\n        guard let records = generation.generated.first?.threads, !records.isEmpty else { return nil }\n        allOpen = records.allSatisfy(\\.open)\n        let threads = records.indices.filter { $0 != commons }\n        largestThreadMemory = threads.map { records[$0].memory }.max() ?? 0\n        var best = 0\n        for t in records.indices where records[t].memory > records[best].memory { best = t }\n        leader = best\n        commonsLeads = commons.map { records[$0].memory >= largestThreadMemory }\n    }\n}\n"},{"path":"Sources/BraidKit/Tools/Bench/BenchReport.swift","lines":111,"bytes":4972,"header":{"lines":[1,14],"what":[8,10],"pin":[11,13],"in":null,"out":null},"marks":[],"first":1442,"scopes":[["S","BenchRule",null,"public",19,19,[19,54],44,null,-1,0],["i","init",["id","passes","detail","skipped"],"public",26,26,[26,81],31,null,0,0],["E","CodingKeys",null,"",33,33,[33,39],33,null,0,8,[]],["i","init",["from"],"public",35,35,[35,46],41,null,0,0],["v","verdict",null,"public",43,43,[43,31],43,null,0,8],["S","BenchVerdict",null,"public",47,47,[47,48],61,[46,46],-1,0],["i","init",["rules","reported","summary"],"public",53,53,[53,80],57,null,5,0],["v","passes",null,"public",60,60,[60,28],60,[59,59],5,8],["E","BenchFormat",null,"public",63,63,[63,24],86,null,-1,0,[]],["f","pct",["_"],"public static",64,64,[64,54],64,null,8,8],["f","pct",["_"],"public static",65,65,[65,53],65,null,8,8],["f","num",["_","_"],"public static",66,66,[66,74],66,null,8,8],["f","num",["_","_"],"public static",67,67,[67,73],67,null,8,8],["f","share",["_"],"public static",70,70,[70,56],70,[69,69],8,8],["f","auroc",["_","_"],"public static",72,72,[72,86],74,null,8,0],["f","reportURL",["area","bench","at"],"public static",77,77,[77,95],83,[76,76],8,0],["f","wholeSecond",["_"],"public static",85,85,[85,66],85,null,8,8],["E","CopyTie",null,"public",92,92,[92,20],111,[88,91],-1,0,[]],["f","tied",["_","band"],"public static",95,95,[95,76],99,null,17,0],["f","takenWhole",["_"],"public static",101,101,[101,62],104,null,17,0],["f","credits",["_","holders"],"public static",107,107,[107,87],110,[106,106],17,0]],"text":"//\n//  BenchReport.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: What every bench report shares: a rule's verdict (pass, fail, or skipped because the braid\n//        has no subject for it), the formatting the tables use, and where a report lands in the\n//        work area. The rules themselves live with their bench (TraceBench, GamingBench, LiftBench).\n//  PIN:  Rules are fixed before numbers: a report carries its verdicts and `rescore` recomputes them\n//        from the saved readings alone, so a rule text and a saved report can be checked against each\n//        other. A bench never changes a default.\n//\n\nimport BraidCore\nimport Foundation\n\npublic struct BenchRule: Codable, Sendable, Equatable {\n    public var id: String\n    public var passes: Bool\n    public var detail: String\n    /// The braid has no subject for the rule (G3 without two Threads holding the same documents).\n    public var skipped: Bool\n\n    public init(id: String, passes: Bool, detail: String, skipped: Bool = false) {\n        self.id = id\n        self.passes = passes\n        self.detail = detail\n        self.skipped = skipped\n    }\n\n    enum CodingKeys: String, CodingKey { case id, passes, detail, skipped }\n\n    public init(from decoder: Decoder) throws {\n        let c = try decoder.container(keyedBy: CodingKeys.self)\n        id = try c.decode(String.self, forKey: .id)\n        passes = try c.decode(Bool.self, forKey: .passes)\n        detail = try c.decode(String.self, forKey: .detail)\n        skipped = try c.decodeIfPresent(Bool.self, forKey: .skipped) ?? false\n    }\n\n    public var verdict: String { skipped ? \"SKIP\" : (passes ? \"PASS\" : \"FAIL\") }\n}\n\n/// What `evaluate` hands back for every bench.\npublic struct BenchVerdict: Sendable, Equatable {\n    public var rules: [BenchRule]\n    /// Measures with no threshold.\n    public var reported: [String: Float]\n    public var summary: String\n\n    public init(rules: [BenchRule], reported: [String: Float], summary: String) {\n        self.rules = rules\n        self.reported = reported\n        self.summary = summary\n    }\n\n    /// Every rule that was not skipped passes.\n    public var passes: Bool { rules.filter { !$0.skipped }.allSatisfy(\\.passes) }\n}\n\npublic enum BenchFormat {\n    public static func pct(_ value: Double) -> String { String(format: \"%.0f%%\", value * 100) }\n    public static func pct(_ value: Float) -> String { pct(Double(value)) }\n    public static func num(_ value: Double?, _ digits: Int = 3) -> String { value.map { String(format: \"%.\\(digits)f\", $0) } ?? \"—\" }\n    public static func num(_ value: Float?, _ digits: Int = 3) -> String { num(value.map(Double.init), digits) }\n\n    /// The share of `flags` that are true (0 when empty).\n    public static func share(_ flags: [Bool]) -> Double { flags.isEmpty ? 0 : Double(flags.filter { $0 }.count) / Double(flags.count) }\n\n    public static func auroc(_ positives: [Double], _ negatives: [Double]) -> Double? {\n        Stats.auroc(scores: positives + negatives, labels: positives.map { _ in true } + negatives.map { _ in false })\n    }\n\n    /// `bench/<name>/<yyyyMMdd-HHmmss>.json` under the work area.\n    public static func reportURL(area: WorkArea, bench: String, at date: Date = Date()) -> URL {\n        let formatter = DateFormatter()\n        formatter.locale = Locale(identifier: \"en_US_POSIX\")\n        formatter.timeZone = TimeZone(identifier: \"UTC\")\n        formatter.dateFormat = \"yyyyMMdd-HHmmss\"\n        return area.bench.appendingPathComponent(bench, isDirectory: true).appendingPathComponent(\"\\(formatter.string(from: date)).json\")\n    }\n\n    public static func wholeSecond(_ date: Date = Date()) -> Date { Date(timeIntervalSince1970: date.timeIntervalSince1970.rounded(.down)) }\n}\n\n/// Holders of the same text (a copy braid): RaoLM's Q5b reading, which G3 shares. Over the exactly\n/// answered copied facts, each holder's credit summed over the generated content tokens; the copies\n/// tie when the spread is within `band` of their sum, and one took the fact whole when another\n/// earned nothing.\npublic enum CopyTie {\n    public static let band: Float = 0.10\n\n    public static func tied(_ credits: [Float], band: Float = band) -> Bool {\n        let total = credits.reduce(0, +)\n        guard total > 0, let top = credits.max(), let low = credits.min() else { return false }\n        return (top - low) / total <= band\n    }\n\n    public static func takenWhole(_ credits: [Float]) -> Bool {\n        guard let top = credits.max(), let low = credits.min() else { return false }\n        return low == 0 && top > 0\n    }\n\n    /// Each holder's credit summed over a generation's generated content tokens.\n    public static func credits(_ generation: Generation, holders: [String]) -> [Float] {\n        let tokens = generation.generatedTokens.filter { $0.credit?.role == .content }\n        return holders.map { name in tokens.reduce(Float(0)) { $0 + $1.credit(of: name) } }\n    }\n}\n"},{"path":"Sources/BraidKit/Tools/Bench/BenchTexts.swift","lines":396,"bytes":22353,"header":{"lines":[1,18],"what":[8,13],"pin":[14,17],"in":null,"out":null},"marks":[],"first":1463,"scopes":[["E","BenchTextKind",null,"public",23,23,[23,67],25,null,-1,0,["held","shuffled","collage","voice","voiceShuffled","told","source","generic"]],["S","BenchAnswer",null,"public",28,28,[28,56],38,[27,27],-1,0],["i","init",["start","count","text"],"public",33,33,[33,54],37,null,1,0],["S","BenchText",null,"public",40,40,[40,54],61,null,-1,0],["i","init",["kind","label","tokens","owner","near","document","answers"],"public",52,52,[52,166],60,null,3,0],["S","BenchTextSizes",null,"public",63,63,[63,59],73,null,-1,0],["i","init",[],"public",72,72,[72,18],72,null,5,8],["S","BenchThread",null,"public",77,77,[77,47],87,[75,76],-1,0],["i","init",["name","node","present"],"public",82,82,[82,66],86,null,7,0],["S","BenchWorld",null,"public",90,90,[90,35],109,[89,89],-1,0],["i","init",["name","corpora","crosslinks"],"public",95,95,[95,98],99,null,9,0],["i","init",["dataset"],"public",101,101,[101,39],103,null,9,0],["f","document",["id"],"public",105,105,[105,56],108,null,9,0],["E","BenchTexts",null,"public",111,111,[111,23],305,null,-1,0,[]],["f","sentences",["_"],"public static",141,141,[141,61],153,[140,140],13,0],["f","split",["_","tokenizer","paragraphBreak"],"public static",158,158,[158,149],173,[155,157],13,0],["f","shuffled",["_","rng"],"public static",176,176,[176,89],183,[175,175],13,0],["f","collage",["_","from","minTokens","maxTokens"],"public static",186,186,[186,112],198,[185,185],13,0],["f","answers",["_","facts","tokenizer","byteOffsets","paragraphBreak"],"public static",201,201,[202,73],219,[200,200],13,0],["f","exclusive",["_","crosslinks"],"public static",222,222,[222,116],225,[221,221],13,0],["f","build",["world","threads","tokenizer","byteOffsets","paragraphBreak","sizes"],"public static",227,227,[228,86],299,null,13,0],["f","pieces",["_"],"",231,231,[231,88],236,null,20,4],["f","census",["_"],"public static",302,302,[302,62],304,[301,301],13,0],["E","BenchPrompts",null,"public",309,309,[309,25],396,[307,308],-1,0,[]],["S","FactPrompt",null,"public",334,334,[334,50],341,[333,333],23,0],["f","facts",["thread","world","tokenizer","byteOffsets","paragraphBreak","perNode"],"public static",345,345,[346,59],370,[343,344],23,0],["f","unknown",["_","count"],"public static",373,373,[373,78],381,[372,372],23,0],["f","interleave",["_","total"],"public static",384,384,[384,79],395,[383,383],23,0]],"text":"//\n//  BenchTexts.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The trace bench's texts, built from a braid dataset and what each Thread was fed: held (a\n//        Thread's own exclusive document as written), shuffled (its sentences reordered so none keeps\n//        its successor), collage (sentence k of the k-th held document), voice and voiceShuffled\n//        (unfed exclusive documents), told and source (both sides of a retelling whose two documents\n//        are present, the agreeing shared facts located as answers), and four fixed generic passages.\n//        RaoLM's TrajectoryTexts, ported: the same splitting, the same sizes, the same order.\n//  PIN:  Pure: a tokenizer, a dataset and the Threads' present documents in, texts out; nothing\n//        touches a node. A document is tokenized partition by partition and joined by the pack's\n//        paragraph break, exactly as its Thread's index read it. Sentence units exist only when\n//        re-joining them reproduces the partition's tokens.\n//\n\nimport BraidCore\nimport Foundation\n\npublic enum BenchTextKind: String, Codable, Sendable, CaseIterable {\n    case held, shuffled, collage, voice, voiceShuffled, told, source, generic\n}\n\n/// A fact's answer inside a text: its first token (a position in the text's tokens), its length, its words.\npublic struct BenchAnswer: Codable, Sendable, Equatable {\n    public var start: Int\n    public var count: Int\n    public var text: String\n\n    public init(start: Int, count: Int, text: String) {\n        self.start = start\n        self.count = count\n        self.text = text\n    }\n}\n\npublic struct BenchText: Codable, Sendable, Equatable {\n    public var kind: BenchTextKind\n    public var label: String\n    public var tokens: [Int32]\n    /// The Thread the text belongs to: whose document it is, was cut from or is in the voice of, and\n    /// the holder of a told or source text. Nil for generic prose.\n    public var owner: String?\n    /// Told and source: the Thread on the other side of the retelling.\n    public var near: String?\n    public var document: String?\n    public var answers: [BenchAnswer]\n\n    public init(kind: BenchTextKind, label: String, tokens: [Int32], owner: String? = nil, near: String? = nil, document: String? = nil, answers: [BenchAnswer] = []) {\n        self.kind = kind\n        self.label = label\n        self.tokens = tokens\n        self.owner = owner\n        self.near = near\n        self.document = document\n        self.answers = answers\n    }\n}\n\npublic struct BenchTextSizes: Codable, Sendable, Equatable {\n    /// Held, collage and voice texts per Thread.\n    public var perNode = 20\n    public var minTokens = 128\n    public var maxTokens = 256\n    /// Told and source texts may be shorter.\n    public var minRetold = 96\n    public var seed: UInt64 = 42\n\n    public init() {}\n}\n\n/// A Thread as the text builder sees it: its name, the dataset node it was fed from, and the ids of\n/// the documents present in its snapshot. Everything else of the node's corpus is unfed.\npublic struct BenchThread: Sendable, Equatable {\n    public var name: String\n    public var node: String\n    public var present: Set<String>\n\n    public init(name: String, node: String, present: Set<String>) {\n        self.name = name\n        self.node = node\n        self.present = present\n    }\n}\n\n/// What the builders read of a dataset: each node's corpus in feeding order and the links.\npublic struct BenchWorld: Sendable {\n    public var name: String\n    public var corpora: [String: GeneratedCorpus]\n    public var crosslinks: [DatasetCrosslink]\n\n    public init(name: String, corpora: [String: GeneratedCorpus], crosslinks: [DatasetCrosslink]) {\n        self.name = name\n        self.corpora = corpora\n        self.crosslinks = crosslinks\n    }\n\n    public init(dataset: BraidDataset) {\n        self.init(name: dataset.directory.lastPathComponent, corpora: dataset.corpora, crosslinks: dataset.crosslinks)\n    }\n\n    public func document(id: String) -> CorpusDocument? {\n        for corpus in corpora.values { if let document = corpus.documents.first(where: { $0.id == id }) { return document } }\n        return nil\n    }\n}\n\npublic enum BenchTexts {\n    /// Prose about nothing any Thread holds (RaoLM's four passages, unchanged).\n    public static let generic = [\n        \"\"\"\n        The tide came in slowly that afternoon, filling the channels between the sandbanks one by one. Gulls stood in a line \\\n        along the breakwater, facing the wind, and a single rowing boat worked its way across the harbour mouth. By the time \\\n        the lamps were lit on the quay the water had reached the steps, and the boats that had leaned all day on their keels \\\n        were floating again, turning gently on their moorings as if they had only been waiting for permission to move.\n        \"\"\",\n        \"\"\"\n        Bread wants patience more than skill. The dough is mixed in the evening and left in a cool corner, covered with a \\\n        cloth, while the yeast does its quiet work through the night. In the morning it has doubled and smells faintly sour. \\\n        It is folded, shaped and left to rise once more, then baked in the hottest oven the kitchen can manage, until the \\\n        crust sings as it cools on the rack and the whole house knows that breakfast is nearly ready.\n        \"\"\",\n        \"\"\"\n        A bicycle teaches its rider about hills in a way no map can. A slope that looks gentle on paper becomes a long \\\n        argument with the legs, and a descent that seemed steep turns out to be the best part of the day. Riders learn to \\\n        read the road ahead, to shift before the climb rather than halfway up it, and to save a little breath for the last \\\n        bend, where the gradient always seems to steepen just when the top comes into view.\n        \"\"\",\n        \"\"\"\n        In winter the garden keeps its secrets underground. The beds look bare, the branches are grey, and frost draws white \\\n        lines along every stem. Yet the bulbs planted in autumn are already sending roots into the cold soil, and the buds on \\\n        the apple tree are sealed tight against the weather, waiting. A patient gardener walks the paths on clear mornings, \\\n        notes what the wind has broken, and makes small plans for the first warm week of spring.\n        \"\"\",\n    ]\n\n    /// A partition's sentences: split at a space after . ? ! or a closing quote, before a capital or a quote.\n    public static func sentences(_ text: String) -> [String] {\n        let characters = Array(text)\n        guard characters.count > 2 else { return text.isEmpty ? [] : [text] }\n        var units: [String] = []\n        var start = 0\n        for i in 1..<(characters.count - 1) where characters[i] == \" \" {\n            guard \".?!\\\"\".contains(characters[i - 1]), characters[i + 1].isUppercase || characters[i + 1] == \"\\\"\" else { continue }\n            units.append(String(characters[start..<i]))\n            start = i + 1\n        }\n        units.append(String(characters[start...]))\n        return units.filter { !$0.isEmpty }\n    }\n\n    /// A document's tokens as its Thread tokenized it (each partition on its own, joined by the pack's\n    /// paragraph break), and its sentences' tokens, a break riding on the sentence before it; no\n    /// sentences when re-joining them would not give those tokens.\n    public static func split(_ document: CorpusDocument, tokenizer: any Tokenizing, paragraphBreak: [Int32]) -> (tokens: [Int32], units: [[Int32]]?) {\n        var tokens: [Int32] = []\n        var units: [[Int32]] = []\n        var exact = true\n        for (n, partition) in document.partitions.sorted(by: { $0.index < $1.index }).enumerated() {\n            if n > 0 {\n                tokens += paragraphBreak\n                if exact, !units.isEmpty { units[units.count - 1] += paragraphBreak }\n            }\n            let own = tokenizer.encode(partition.text)\n            tokens += own\n            let pieces = sentences(partition.text).enumerated().map { i, piece in tokenizer.encode(i == 0 ? piece : \" \" + piece) }\n            if pieces.flatMap({ $0 }) == own { units += pieces } else { exact = false }\n        }\n        return (tokens, exact ? units : nil)\n    }\n\n    /// The sentences in an order where none is followed by the sentence that followed it before.\n    public static func shuffled(_ units: [[Int32]], rng: inout SplitMix64) -> [[Int32]]? {\n        guard units.count >= 3 else { return nil }\n        for _ in 0..<200 {\n            let order = Array(units.indices).shuffled(using: &rng)\n            if zip(order, order.dropFirst()).allSatisfy({ $1 != $0 + 1 }) { return order.map { units[$0] } }\n        }\n        return nil\n    }\n\n    /// Sentence k of the k-th document (cycling), at least `minTokens` and at most `maxTokens`; nil when it stays short.\n    public static func collage(_ sources: [[[Int32]]], from c: Int, minTokens: Int, maxTokens: Int) -> [Int32]? {\n        guard sources.count >= 2 else { return nil }\n        var tokens: [Int32] = []\n        var k = 0\n        while tokens.count < minTokens, k < sources.count {\n            let units = sources[(c + k) % sources.count]\n            let unit = units[k % units.count]\n            if tokens.count + unit.count > maxTokens { break }\n            tokens += unit\n            k += 1\n        }\n        return tokens.count >= minTokens ? tokens : nil\n    }\n\n    /// Where each located fact's answer sits in the document's tokens (as `split` lays them out).\n    public static func answers(_ document: CorpusDocument, facts ids: Set<String>, tokenizer: any Tokenizing, byteOffsets: ([Int32]) -> [Int],\n                               paragraphBreak: [Int32]) -> [BenchAnswer] {\n        guard !ids.isEmpty else { return [] }\n        let snapshot = CorpusSnapshot(\n            documents: [SnapshotDocument(id: document.id, name: document.name, ownerID: \"bench\", groupID: \"bench\", groupLabel: \"bench\", createdAt: 0, mediaType: \"text\",\n                                         partitions: document.partitions.map { SnapshotPartition(index: $0.index, text: $0.text, url: $0.url) })],\n            slug: nil, source: \"bench\", threadID: nil, owner: \"bench\", group: \"bench\", documentIDPrefix: \"\")\n        let corpus = TokenizedCorpus(snapshot: snapshot, tokenizer: tokenizer, paragraphBreak: paragraphBreak, threadID: nil)\n        var starts: [Int: Int] = [:]\n        var total = 0\n        for (n, partition) in corpus.partitions.enumerated() {\n            if n > 0 { total += paragraphBreak.count }\n            starts[partition.row] = total\n            total += partition.tokens.count\n        }\n        return FactLocator.locate(document.facts.filter { ids.contains($0.id) }, corpus: corpus, byteOffsets: byteOffsets).located\n            .map { BenchAnswer(start: (starts[$0.row] ?? 0) + $0.answerToken, count: $0.answerLength, text: $0.fact.answer) }\n            .sorted { $0.start < $1.start }\n    }\n\n    /// The documents of a node that no non-homonym link touches: held by one Thread alone.\n    public static func exclusive(_ documents: [CorpusDocument], crosslinks: [DatasetCrosslink]) -> [CorpusDocument] {\n        let crossed = Set(crosslinks.filter { $0.kind != .homonym }.flatMap { [$0.source.documentID, $0.target.documentID] })\n        return documents.filter { !crossed.contains($0.id) }\n    }\n\n    public static func build(world: BenchWorld, threads: [BenchThread], tokenizer: any Tokenizing, byteOffsets: ([Int32]) -> [Int], paragraphBreak: [Int32],\n                             sizes: BenchTextSizes = BenchTextSizes()) -> [BenchText] {\n        var rng = SplitMix64(seed: sizes.seed)\n        var cache: [String: (tokens: [Int32], units: [[Int32]]?)] = [:]\n        func pieces(_ document: CorpusDocument) -> (tokens: [Int32], units: [[Int32]]?) {\n            if let cached = cache[document.id] { return cached }\n            let made = split(document, tokenizer: tokenizer, paragraphBreak: paragraphBreak)\n            cache[document.id] = made\n            return made\n        }\n        // Links between nodes the braid holds; the first Thread fed from a node stands for it.\n        var threadByNode: [String: BenchThread] = [:]\n        for thread in threads where threadByNode[thread.node] == nil { threadByNode[thread.node] = thread }\n        let links = world.crosslinks.filter { threadByNode[$0.source.node] != nil && threadByNode[$0.target.node] != nil }\n        let whole = sizes.minTokens...sizes.maxTokens\n        var texts: [BenchText] = []\n        for thread in threads {\n            let own = exclusive(world.corpora[thread.node]?.documents ?? [], crosslinks: links)\n            let held = own.filter { thread.present.contains($0.id) }\n            for document in held.filter({ whole.contains(pieces($0).tokens.count) }).prefix(sizes.perNode) {\n                texts.append(BenchText(kind: .held, label: \"\\(thread.name) · \\(document.name)\", tokens: pieces(document).tokens, owner: thread.name, document: document.id))\n                if let units = pieces(document).units, let order = shuffled(units, rng: &rng) {\n                    texts.append(BenchText(kind: .shuffled, label: \"\\(thread.name) · \\(document.name) (shuffled)\", tokens: order.flatMap { $0 }, owner: thread.name,\n                                           document: document.id))\n                }\n            }\n            // Sentence k of the k-th held document: a Thread's own sentences, following none of them.\n            let sources = held.compactMap { pieces($0).units }\n            if sources.count >= 2 {\n                for c in 0..<min(sizes.perNode, sources.count) {\n                    if let tokens = collage(sources, from: c, minTokens: sizes.minTokens, maxTokens: sizes.maxTokens) {\n                        texts.append(BenchText(kind: .collage, label: \"\\(thread.name) · collage \\(c + 1)\", tokens: tokens, owner: thread.name))\n                    }\n                }\n            }\n            let unfed = own.filter { !thread.present.contains($0.id) && whole.contains(pieces($0).tokens.count) }\n            for document in unfed.prefix(sizes.perNode) {\n                texts.append(BenchText(kind: .voice, label: \"\\(thread.name) · \\(document.name) (unfed)\", tokens: pieces(document).tokens, owner: thread.name,\n                                       document: document.id))\n                if let units = pieces(document).units, let order = shuffled(units, rng: &rng) {\n                    texts.append(BenchText(kind: .voiceShuffled, label: \"\\(thread.name) · \\(document.name) (unfed, shuffled)\", tokens: order.flatMap { $0 },\n                                           owner: thread.name, document: document.id))\n                }\n            }\n        }\n        // Both sides of every retelling whose two documents are present.\n        let retold = sizes.minRetold...sizes.maxTokens\n        var sources = Set<String>()\n        for link in links where link.kind != .homonym {\n            guard let teller = threadByNode[link.target.node], let origin = threadByNode[link.source.node],\n                  origin.present.contains(link.source.documentID), teller.present.contains(link.target.documentID),\n                  let source = world.document(id: link.source.documentID), let target = world.document(id: link.target.documentID)\n            else { continue }\n            let agreeing = link.facts.filter(\\.agrees)\n            if retold.contains(pieces(target).tokens.count) {\n                texts.append(BenchText(\n                    kind: .told, label: \"\\(teller.name) ≈ \\(origin.name) · \\(link.subject) (\\(link.kind.rawValue))\", tokens: pieces(target).tokens,\n                    owner: teller.name, near: origin.name, document: target.id,\n                    answers: answers(target, facts: Set(agreeing.map(\\.targetFact)), tokenizer: tokenizer, byteOffsets: byteOffsets, paragraphBreak: paragraphBreak)))\n            }\n            if !sources.contains(source.id), retold.contains(pieces(source).tokens.count) {\n                sources.insert(source.id)\n                texts.append(BenchText(\n                    kind: .source, label: \"\\(origin.name) → \\(teller.name) · \\(link.subject)\", tokens: pieces(source).tokens,\n                    owner: origin.name, near: teller.name, document: source.id,\n                    answers: answers(source, facts: Set(agreeing.map(\\.sourceFact)), tokenizer: tokenizer, byteOffsets: byteOffsets, paragraphBreak: paragraphBreak)))\n            }\n        }\n        for (i, passage) in generic.enumerated() {\n            texts.append(BenchText(kind: .generic, label: \"generic \\(i + 1)\", tokens: tokenizer.encode(passage)))\n        }\n        return texts\n    }\n\n    /// `kind n · kind n …` for a progress line.\n    public static func census(_ texts: [BenchText]) -> String {\n        BenchTextKind.allCases.map { kind in \"\\(kind.rawValue) \\(texts.filter { $0.kind == kind }.count)\" }.joined(separator: \" · \")\n    }\n}\n\n/// The prompts the gaming and lift benches ask: a Thread's facts from its own exclusive documents,\n/// newest first, one from each document in turn (RaoLM's `BraidExample` order).\npublic enum BenchPrompts {\n    /// Sentences about nothing the datasets hold (RaoLM's gate bench prompts, unchanged).\n    public static let generic = [\n        \"How should we understand our lives\",\n        \"How should we understand our lives as travellers\",\n        \"What is the best way to learn a new language\",\n        \"The weather tomorrow is going to be\",\n        \"In the future, computers will be able to\",\n        \"My favourite thing about the weekend is\",\n        \"To make a good cup of tea you should\",\n        \"The most important lesson I ever learned was\",\n    ]\n\n    /// General English no Thread holds and the base model knows (RaoLM's commons prompts, unchanged).\n    public static let commons = [\n        \"The capital of France is\", \"Water freezes at a temperature of\", \"The largest planet in our solar system is\",\n        \"Shakespeare wrote the play\", \"The chemical symbol for gold is\", \"The first man to walk on the moon was\",\n        \"Photosynthesis is the process by which plants\", \"The Pacific Ocean is the largest\", \"In mathematics, the square root of sixteen is\",\n        \"Honey is made by\", \"The heart pumps blood through the\", \"Mount Everest is the highest mountain in\",\n        \"The Mona Lisa was painted by\", \"Light travels faster than\", \"The opposite of hot is\", \"Rain falls from clouds when\",\n        \"A triangle has three sides, and a square has\", \"The sun rises in the\", \"A group of wolves is called a\",\n        \"The Great Wall of China was built to\",\n    ]\n\n    /// One fact prompt: the partition's tokens from the context sentence to the answer, and the answer.\n    public struct FactPrompt: Sendable, Equatable {\n        public var thread: String\n        public var fact: Fact\n        public var tokens: [Int32]\n        public var answerTokens: Int\n        public var documentID: String\n        public var partitionIndex: Int\n    }\n\n    /// A Thread's facts located in its own exclusive present documents, newest documents first, one\n    /// fact from each in turn (within a document by fact id), `perNode` of them.\n    public static func facts(thread: BenchThread, world: BenchWorld, tokenizer: any Tokenizing, byteOffsets: ([Int32]) -> [Int], paragraphBreak: [Int32],\n                             perNode: Int) -> [FactPrompt] {\n        let own = BenchTexts.exclusive(world.corpora[thread.node]?.documents ?? [], crosslinks: world.crosslinks).filter { thread.present.contains($0.id) }\n        guard !own.isEmpty else { return [] }\n        let snapshot = CorpusSnapshot(\n            documents: own.map { document in\n                SnapshotDocument(id: document.id, name: document.name, ownerID: \"bench\", groupID: \"bench\", groupLabel: \"bench\", createdAt: 0, mediaType: \"text\",\n                                 partitions: document.partitions.map { SnapshotPartition(index: $0.index, text: $0.text, url: $0.url) })\n            },\n            slug: nil, source: \"bench\", threadID: nil, owner: \"bench\", group: \"bench\", documentIDPrefix: \"\")\n        let corpus = TokenizedCorpus(snapshot: snapshot, tokenizer: tokenizer, paragraphBreak: paragraphBreak, threadID: nil)\n        let located = FactLocator.locate(own.flatMap(\\.facts), corpus: corpus, byteOffsets: byteOffsets).located\n        let order = Dictionary(own.enumerated().map { ($0.element.id, $0.offset) }, uniquingKeysWith: { a, _ in a })\n        var byDocument = Dictionary(grouping: located, by: \\.fact.documentID)\n            .sorted { (order[$0.key] ?? 0) > (order[$1.key] ?? 0) }\n            .map { $0.value.sorted { $0.fact.id < $1.fact.id } }\n        var ranked: [LocatedFact] = []\n        while byDocument.contains(where: { !$0.isEmpty }) {\n            for i in byDocument.indices where !byDocument[i].isEmpty { ranked.append(byDocument[i].removeFirst()) }\n        }\n        return ranked.prefix(max(0, perNode)).map { fact in\n            let partition = corpus.partitions[fact.row]\n            return FactPrompt(thread: thread.name, fact: fact.fact, tokens: Array(partition.tokens[fact.contextToken..<fact.answerToken]),\n                              answerTokens: fact.answerLength, documentID: partition.ref.documentID, partitionIndex: partition.ref.partitionIndex)\n        }\n    }\n\n    /// The same templates about entities that exist nowhere: each ranked fact's negative prompt, distinct.\n    public static func unknown(_ facts: [FactPrompt], count: Int) -> [String] {\n        var seen = Set<String>()\n        var prompts: [String] = []\n        for fact in facts where !fact.fact.negativePrompt.isEmpty && !seen.contains(fact.fact.negativePrompt) && prompts.count < count {\n            seen.insert(fact.fact.negativePrompt)\n            prompts.append(fact.fact.negativePrompt)\n        }\n        return prompts\n    }\n\n    /// A fact from each list in turn (RaoLM's interleaving), `total` at most when given.\n    public static func interleave<T>(_ lists: [[T]], total: Int? = nil) -> [T] {\n        var result: [T] = []\n        var round = 0\n        while lists.contains(where: { round < $0.count }) {\n            for list in lists where round < list.count {\n                if let total, result.count >= total { return result }\n                result.append(list[round])\n            }\n            round += 1\n        }\n        return result\n    }\n}\n"},{"path":"Sources/BraidKit/Tools/Bench/EntropyBench.swift","lines":284,"bytes":15513,"header":{"lines":[1,19],"what":[8,14],"pin":[15,18],"in":null,"out":null},"marks":[[204,"The rule (pure)"]],"first":1491,"scopes":[["S","EntropyReading",null,"public",24,24,[24,59],49,null,-1,0],["i","init",["thread","coherent","inTrace","agreement","coherentCall","traceCall","coherentOnlyLabels","traceOnlyLabels"],"public",38,38,[39,95],48,null,0,0],["S","EntropyText",null,"public",51,51,[51,56],72,null,-1,0],["i","init",["kind","label","owner","near","tokens","readings"],"public",59,59,[59,124],66,null,2,0],["f","reading",["_"],"public",68,68,[68,62],71,null,2,0],["S","EntropyReport",null,"public",74,74,[74,47],89,null,-1,0],["E","EntropyBench",null,"public",91,91,[91,25],284,null,-1,0,[]],["f","run",["braid","world","sizes","progress"],"public static",94,94,[94,168],116,null,6,0],["f","readings",["_","names","commons","settings","phrase"],"public static",119,119,[119,149],127,[118,118],6,0],["f","reading",["thread","series","lengths","settings","phrase"],"public static",130,130,[130,142],155,[129,129],6,0],["f","coherentCall",["_","settings"],"public static",159,159,[159,88],166,[157,158],6,0],["f","kappa",["_"],"public static",169,169,[169,56],178,[168,168],6,0],["f","nulls",["_"],"public static",181,181,[181,95],193,[180,180],6,0],["f","rescore",["_"],"public static",195,195,[195,73],202,null,6,0],["f","evaluate",["texts"],"public static",209,209,[209,70],283,[206,208],6,0],["f","pct",["_"],"",211,211,[211,44],211,null,14,12],["f","num",["_"],"",212,212,[212,45],212,null,14,12],["f","pooled",["_"],"",215,215,[215,59],217,null,14,4]],"text":"//\n//  EntropyBench.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid bench entropy`: whether the entropy path calls what the trace calls. On the trace\n//        bench's texts, per Thread per position from 24: a coherent run (H_knn ≤ ln 2 for ≥ 24\n//        consecutive positions, the module's call) against in-trace (the chain has followed one\n//        document for ≥ 24 tokens, the trace's call). E1: Cohen's κ between the two ≥ 0.6 on the\n//        holders of held, told and source texts. E2: the coherent fraction ≤ 0.10 on ≥ 90% of the\n//        null texts. E3 (reported only): which calls first, and where they disagree, the module's\n//        four-way labels.\n//  PIN:  Rules fixed before any numbers (the plan's bench table, E1–E3). The nulls are the trace\n//        bench's: shuffled and collage (their Thread), voice, voice-shuffled and generic (every\n//        Thread), told and source (every Thread but the holder); a null text counts by its largest\n//        coherent fraction. `evaluate` is pure over the saved readings; the session log is kept.\n//\n\nimport BraidCore\nimport Foundation\n\npublic struct EntropyReading: Codable, Sendable, Equatable {\n    public var thread: String\n    /// From `from` on: the share of positions inside a coherent run, and in trace.\n    public var coherent: Float\n    public var inTrace: Float\n    /// Positions from `from`: [coherent ∧ in trace, coherent only, in trace only, neither].\n    public var agreement: [Int]\n    /// The first position where a coherent run reaches its length, and where the chain reaches the phrase.\n    public var coherentCall: Int?\n    public var traceCall: Int?\n    /// The module's labels where the two disagree (positions from `from`).\n    public var coherentOnlyLabels: [String: Int]\n    public var traceOnlyLabels: [String: Int]\n\n    public init(thread: String, coherent: Float, inTrace: Float, agreement: [Int], coherentCall: Int?, traceCall: Int?,\n                coherentOnlyLabels: [String: Int] = [:], traceOnlyLabels: [String: Int] = [:]) {\n        self.thread = thread\n        self.coherent = coherent\n        self.inTrace = inTrace\n        self.agreement = agreement\n        self.coherentCall = coherentCall\n        self.traceCall = traceCall\n        self.coherentOnlyLabels = coherentOnlyLabels\n        self.traceOnlyLabels = traceOnlyLabels\n    }\n}\n\npublic struct EntropyText: Codable, Sendable, Equatable {\n    public var kind: BenchTextKind\n    public var label: String\n    public var owner: String?\n    public var near: String?\n    public var tokens: Int\n    public var readings: [EntropyReading]\n\n    public init(kind: BenchTextKind, label: String, owner: String?, near: String?, tokens: Int, readings: [EntropyReading]) {\n        self.kind = kind\n        self.label = label\n        self.owner = owner\n        self.near = near\n        self.tokens = tokens\n        self.readings = readings\n    }\n\n    public func reading(_ thread: String?) -> EntropyReading? {\n        guard let thread else { return nil }\n        return readings.first { $0.thread == thread }\n    }\n}\n\npublic struct EntropyReport: Codable, Sendable {\n    public var bench = \"entropy\"\n    public var createdAt: Date\n    public var dataset: String\n    public var threads: [String: String]\n    public var gate: GateSettings\n    public var module: ModuleSettings\n    public var phrase: Int\n    public var from: Int\n    public var sizes: BenchTextSizes\n    public var texts: [EntropyText]\n    public var rules: [BenchRule]\n    public var reported: [String: Float]\n    public var summary: String\n    public var sessions: [String]? = nil\n}\n\npublic enum EntropyBench {\n    public static let from = TraceBench.from\n\n    public static func run(braid: BenchBraid, world: BenchWorld, sizes: BenchTextSizes = BenchTextSizes(), progress: ((String) -> Void)? = nil) throws -> EntropyReport {\n        let threads = try braid.benchThreads(world: world) { progress?(\"warning: \\($0)\") }\n        let texts = BenchTexts.build(world: world, threads: threads, tokenizer: braid.tokenizer, byteOffsets: braid.tokenizer.byteOffsets,\n                                     paragraphBreak: braid.tokenizer.paragraphBreak, sizes: sizes)\n        progress?(\"texts: \" + BenchTexts.census(texts))\n        try braid.keepSession()\n        defer { braid.finishSession() }\n        let module = braid.settings.module ?? ModuleSettings()\n        let phrase = braid.settings.trace.phrase\n        var results: [EntropyText] = []\n        let started = Date()\n        for (i, text) in texts.enumerated() {\n            if i % 25 == 0 { progress?(String(format: \"scoring %d/%d (%.0f s)\", i, texts.count, Date().timeIntervalSince(started))) }\n            let generation = try braid.score(text.tokens)\n            results.append(EntropyText(kind: text.kind, label: text.label, owner: text.owner, near: text.near, tokens: text.tokens.count,\n                                       readings: readings(generation, names: braid.names, commons: braid.commonsIndex, settings: module, phrase: phrase)))\n            if i % 8 == 7 { braid.relax() }\n        }\n        let verdict = evaluate(texts: results)\n        return EntropyReport(createdAt: BenchFormat.wholeSecond(), dataset: world.name, threads: braid.threadRecords, gate: braid.settings.gate, module: module,\n                             phrase: phrase, from: from, sizes: sizes, texts: results, rules: verdict.rules, reported: verdict.reported, summary: verdict.summary,\n                             sessions: braid.sessions.map(\\.path))\n    }\n\n    /// Every Thread's reading of one scoring.\n    public static func readings(_ generation: Generation, names: [String], commons: Int?, settings: ModuleSettings, phrase: Int) -> [EntropyReading] {\n        let series = TrajectoryModule.series(generation.steps, commons: commons)\n        let positions = generation.steps.filter { $0.source != .ctx && $0.threads != nil }\n        return names.indices.compactMap { t -> EntropyReading? in\n            guard t != commons, t < series.count else { return nil }\n            let lengths = positions.map { step in t < (step.threads?.count ?? 0) ? step.threads![t].trace?.length ?? 0 : 0 }\n            return reading(thread: names[t], series: series[t], lengths: lengths, settings: settings, phrase: phrase)\n        }\n    }\n\n    /// One Thread's reading from its series and its chain lengths (aligned, one per position).\n    public static func reading(thread: String, series: ThreadSeries, lengths: [Int], settings: ModuleSettings, phrase: Int) -> EntropyReading {\n        let all = TrajectoryModule.readAll(series, settings: settings)\n        let n = min(all.count, lengths.count)\n        var agreement = [0, 0, 0, 0]\n        var coherentOnly: [String: Int] = [:]\n        var traceOnly: [String: Int] = [:]\n        var coherentCount = 0\n        var traceCount = 0\n        for i in from ..< max(from, n) {\n            let coherent = all[i].coherent\n            let inTrace = lengths[i] >= phrase\n            if coherent { coherentCount += 1 }\n            if inTrace { traceCount += 1 }\n            switch (coherent, inTrace) {\n            case (true, true): agreement[0] += 1\n            case (true, false): agreement[1] += 1; coherentOnly[all[i].label.rawValue, default: 0] += 1\n            case (false, true): agreement[2] += 1; traceOnly[all[i].label.rawValue, default: 0] += 1\n            case (false, false): agreement[3] += 1\n            }\n        }\n        let counted = max(n - from, 0)\n        return EntropyReading(thread: thread, coherent: counted > 0 ? Float(coherentCount) / Float(counted) : 0,\n                              inTrace: counted > 0 ? Float(traceCount) / Float(counted) : 0, agreement: agreement,\n                              coherentCall: coherentCall(series.hknn, settings: settings), traceCall: lengths.firstIndex { $0 >= phrase },\n                              coherentOnlyLabels: coherentOnly, traceOnlyLabels: traceOnly)\n    }\n\n    /// The first position at which `coherentRun` consecutive positions have H_knn ≤ `coherent`: the\n    /// entropy path's call, made causally at the run's last position.\n    public static func coherentCall(_ hknn: [Double], settings: ModuleSettings) -> Int? {\n        var run = 0\n        for (i, h) in hknn.enumerated() {\n            run = h <= settings.coherent ? run + 1 : 0\n            if run >= settings.coherentRun { return i }\n        }\n        return nil\n    }\n\n    /// Cohen's κ from a 2×2 table [both, first only, second only, neither]; nil when chance agreement is 1.\n    public static func kappa(_ table: [Int]) -> Double? {\n        guard table.count == 4 else { return nil }\n        let n = Double(table.reduce(0, +))\n        guard n > 0 else { return nil }\n        let (a, b, c, d) = (Double(table[0]), Double(table[1]), Double(table[2]), Double(table[3]))\n        let observed = (a + d) / n\n        let chance = ((a + b) / n) * ((a + c) / n) + ((c + d) / n) * ((b + d) / n)\n        guard chance < 1 else { return nil }\n        return (observed - chance) / (1 - chance)\n    }\n\n    /// The null texts and, per text, the largest coherent fraction among its null readings.\n    public static func nulls(_ texts: [EntropyText]) -> [(text: EntropyText, coherent: Float)] {\n        texts.compactMap { text in\n            let readings: [EntropyReading]\n            switch text.kind {\n            case .shuffled, .collage: readings = text.reading(text.owner).map { [$0] } ?? []\n            case .voice, .voiceShuffled, .generic: readings = text.readings\n            case .told, .source: readings = text.readings.filter { $0.thread != text.owner }\n            case .held: return nil\n            }\n            guard !readings.isEmpty else { return nil }\n            return (text, readings.map(\\.coherent).max() ?? 0)\n        }\n    }\n\n    public static func rescore(_ report: EntropyReport) -> EntropyReport {\n        var rescored = report\n        let verdict = evaluate(texts: report.texts)\n        rescored.rules = verdict.rules\n        rescored.reported = verdict.reported\n        rescored.summary = verdict.summary\n        return rescored\n    }\n\n    // MARK: - The rule (pure)\n\n    /// E1: Cohen's κ, pooled over the positions from 24 of the holders of held, told and source texts,\n    /// between \"inside a coherent run\" and \"in trace\" ≥ 0.6. E2: the coherent fraction ≤ 0.10 on ≥ 90%\n    /// of the null texts. E3 is reported only.\n    public static func evaluate(texts: [EntropyText]) -> BenchVerdict {\n        let share = BenchFormat.share\n        func pct(_ value: Double) -> String { BenchFormat.pct(value) }\n        func num(_ value: Double?) -> String { BenchFormat.num(value) }\n        var rules: [BenchRule] = []\n        var reported: [String: Float] = [:]\n        func pooled(_ readings: [EntropyReading]) -> [Int] {\n            readings.reduce([0, 0, 0, 0]) { sum, reading in zip(sum, reading.agreement).map { $0 + $1 } }\n        }\n        let holderKinds: [BenchTextKind] = [.held, .told, .source]\n        let holders = texts.filter { holderKinds.contains($0.kind) }.compactMap { $0.reading($0.owner) }\n        let table = pooled(holders)\n        let k = kappa(table)\n        rules.append(BenchRule(\n            id: \"E1 coherent run is the trace\", passes: !holders.isEmpty && (k ?? -1) >= 0.6,\n            detail: \"Cohen's κ \\(num(k)) (needs 0.6) over \\(table.reduce(0, +)) positions of \\(holders.count) holders of held, told and source: \"\n                + \"both \\(table[0]), coherent only \\(table[1]), in trace only \\(table[2]), neither \\(table[3])\"))\n        for kind in holderKinds {\n            let mine = texts.filter { $0.kind == kind }.compactMap { $0.reading($0.owner) }\n            if let value = kappa(pooled(mine)) { reported[\"E1 \\(kind.rawValue): κ\"] = Float(value) }\n            reported[\"E1 \\(kind.rawValue): holder's coherent fraction (mean)\"] = Float(Stats.mean(mine.map { Double($0.coherent) }))\n            reported[\"E1 \\(kind.rawValue): holder in trace (mean)\"] = Float(Stats.mean(mine.map { Double($0.inTrace) }))\n        }\n\n        let nullTexts = nulls(texts)\n        let quiet = share(nullTexts.map { $0.coherent <= 0.10 })\n        rules.append(BenchRule(\n            id: \"E2 nobody's text is not coherent\", passes: !nullTexts.isEmpty && quiet >= 0.9,\n            detail: \"coherent fraction ≤ 0.10 on \\(pct(quiet)) of \\(nullTexts.count) null texts (needs 90%)\"))\n        for kind in BenchTextKind.allCases where kind != .held {\n            let mine = nullTexts.filter { $0.text.kind == kind }\n            guard !mine.isEmpty else { continue }\n            reported[\"E2 \\(kind.rawValue): coherent ≤ 0.10\"] = Float(share(mine.map { $0.coherent <= 0.10 }))\n            reported[\"E2 \\(kind.rawValue): coherent fraction (mean)\"] = Float(Stats.mean(mine.map { Double($0.coherent) }))\n        }\n\n        // E3: who calls first, and the module's labels where they disagree.\n        let called = holders.filter { $0.coherentCall != nil && $0.traceCall != nil }\n        let leads = called.map { Double($0.coherentCall! - $0.traceCall!) }\n        reported[\"E3 holders with both calls\"] = Float(called.count)\n        reported[\"E3 holders with neither call\"] = Float(holders.filter { $0.coherentCall == nil && $0.traceCall == nil }.count)\n        reported[\"E3 holders: trace only called\"] = Float(holders.filter { $0.coherentCall == nil && $0.traceCall != nil }.count)\n        reported[\"E3 holders: coherent only called\"] = Float(holders.filter { $0.coherentCall != nil && $0.traceCall == nil }.count)\n        if !leads.isEmpty {\n            reported[\"E3 lead/lag: coherent call − trace call (mean positions)\"] = Float(Stats.mean(leads))\n            reported[\"E3 lead/lag: coherent call − trace call (median positions)\"] = Float(Stats.quantile(leads, 0.5))\n            reported[\"E3 lead/lag: the entropy path calls first\"] = Float(share(leads.map { $0 < 0 }))\n        }\n        let nullReadings = texts.flatMap { text -> [EntropyReading] in\n            switch text.kind {\n            case .shuffled, .collage: return text.reading(text.owner).map { [$0] } ?? []\n            case .voice, .voiceShuffled, .generic: return text.readings\n            case .told, .source: return text.readings.filter { $0.thread != text.owner }\n            case .held: return []\n            }\n        }\n        for (group, readings) in [(\"holders\", holders), (\"nulls\", nullReadings)] {\n            let t = pooled(readings)\n            reported[\"E3 \\(group): coherent ∧ ¬trace positions\"] = Float(t[1])\n            reported[\"E3 \\(group): trace ∧ ¬coherent positions\"] = Float(t[2])\n            var coherentOnly: [String: Int] = [:]\n            var traceOnly: [String: Int] = [:]\n            for reading in readings {\n                for (label, count) in reading.coherentOnlyLabels { coherentOnly[label, default: 0] += count }\n                for (label, count) in reading.traceOnlyLabels { traceOnly[label, default: 0] += count }\n            }\n            for label in [\"retrieval\", \"stitched\", \"unknown\", \"commons\", \"silent\"] {\n                reported[\"E3 \\(group): coherent ∧ ¬trace labelled \\(label)\"] = Float(coherentOnly[label] ?? 0)\n                reported[\"E3 \\(group): trace ∧ ¬coherent labelled \\(label)\"] = Float(traceOnly[label] ?? 0)\n            }\n        }\n\n        let failed = rules.filter { !$0.passes }.map(\\.id)\n        return BenchVerdict(rules: rules, reported: reported, summary: failed.isEmpty ? \"E1 and E2 pass\" : \"failed: \" + failed.joined(separator: \", \"))\n    }\n}\n"},{"path":"Sources/BraidKit/Tools/Bench/GamingBench.swift","lines":233,"bytes":14144,"header":{"lines":[1,19],"what":[8,14],"pin":[15,18],"in":null,"out":null},"marks":[[183,"The rule (pure)"]],"first":1509,"scopes":[["E","GamingSet",null,"public",24,24,[24,63],24,null,-1,8,[]],["S","GamingRow",null,"public",26,26,[26,54],63,null,-1,0],["i","init",["set","label","owner","answer","allOpen","largestGate","leader","commonsLeads","copies","copyCredit","exact","followed","tied"],"public",47,47,[48,137],62,null,1,0],["S","GamingReport",null,"public",65,65,[65,46],82,null,-1,0],["E","GamingBench",null,"public",84,84,[84,24],233,null,-1,0,[]],["f","run",["braid","world","perNode","copies","progress"],"public static",89,89,[89,171],156,[87,88],4,0],["f","row",["_","in","set","label","owner"],"",94,94,[94,126],98,null,5,4],["f","copyPair",["in"],"public static",159,159,[159,67],166,[158,158],4,0],["f","copiedFacts",["_","_","world","tokenizer"],"static",169,169,[169,139],172,[168,168],4,0],["f","rescore",["_"],"public static",174,174,[174,71],181,null,4,0],["f","evaluate",["rows","copyPair"],"public static",190,190,[190,88],232,[185,189],4,0],["f","pct",["_"],"",192,192,[192,44],192,null,10,12]],"text":"//\n//  GamingBench.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid bench gaming`: the guards that keep the gate from being gamed. Prompts about entities\n//        no Thread holds (each Thread's fact templates about nothing) and generic prose are continued\n//        four tokens; at the first generated token every Thread must still be open and the largest\n//        Thread's gate bounded. On a copy braid (two Threads holding the same documents, trained\n//        apart) the copies must tie on their facts' credit and neither may take a fact whole. RaoLM's\n//        gate-bench guards and Q5b, fixed before any numbers (RaoLM Docs/BRAID.md, \"Choosing the\n//        gate\"; Docs/ARCHITECTURE.md, \"Context to credit\").\n//  PIN:  \"Gate\" is the live gate (`ThreadRecord.memory`) over the Threads, the commons excluded;\n//        \"open\" is `ThreadRecord.open`. G1 and G2 run on the braid; G3 on the copy braid (the commons\n//        and the two copies) when one is named, else on a copy pair inside the braid, else it is\n//        skipped and says so. `evaluate` is pure over the saved rows. Session logs are kept.\n//\n\nimport BraidCore\nimport Foundation\n\npublic enum GamingSet: String, Codable, Sendable, CaseIterable { case unknown, generic, copied }\n\npublic struct GamingRow: Codable, Sendable, Equatable {\n    public var set: GamingSet\n    public var label: String\n    /// Unknown: the Thread whose fact template was used; copied: the first copy.\n    public var owner: String?\n    public var answer: String\n    /// Every strand open at the first generated token.\n    public var allOpen: Bool\n    /// The largest Thread memory at the first generated token (the commons excluded).\n    public var largestGate: Float\n    /// The strand with the most memory there, and whether that is the commons.\n    public var leader: String\n    public var commonsLeads: Bool?\n    /// Copied facts: the two copies and each one's summed content credit over the generated tokens.\n    public var copies: [String]?\n    public var copyCredit: [Float]?\n    public var exact: Bool?\n    /// Copied facts: the Thread the answer's sentence followed, or those it tied between.\n    public var followed: String?\n    public var tied: [String]?\n\n    public init(set: GamingSet, label: String, owner: String?, answer: String, allOpen: Bool, largestGate: Float, leader: String, commonsLeads: Bool? = nil,\n                copies: [String]? = nil, copyCredit: [Float]? = nil, exact: Bool? = nil, followed: String? = nil, tied: [String]? = nil) {\n        self.set = set\n        self.label = label\n        self.owner = owner\n        self.answer = answer\n        self.allOpen = allOpen\n        self.largestGate = largestGate\n        self.leader = leader\n        self.commonsLeads = commonsLeads\n        self.copies = copies\n        self.copyCredit = copyCredit\n        self.exact = exact\n        self.followed = followed\n        self.tied = tied\n    }\n}\n\npublic struct GamingReport: Codable, Sendable {\n    public var bench = \"gaming\"\n    public var createdAt: Date\n    public var dataset: String\n    public var threads: [String: String]\n    public var gate: GateSettings\n    public var perNode: Int\n    /// The two Threads holding the same documents, when the braid has them.\n    public var copyPair: [String]?\n    public var rows: [GamingRow]\n    public var rules: [BenchRule]\n    public var reported: [String: Float]\n    public var summary: String\n    /// The session logs the bench wrote (the braid's, then the copy braid's).\n    public var sessions: [String]? = nil\n    /// What a reader needs beside the numbers.\n    public var notes: [String]? = nil\n}\n\npublic enum GamingBench {\n    public static let generated = 4\n\n    /// G1 and G2 on `braid`; G3 on `copies` (the commons and two copies) when given, else on a copy\n    /// pair inside `braid` when there is one.\n    public static func run(braid: BenchBraid, world: BenchWorld, perNode: Int = 10, copies: BenchBraid? = nil, progress: ((String) -> Void)? = nil) throws -> GamingReport {\n        let threads = try braid.benchThreads(world: world) { progress?(\"warning: \\($0)\") }\n        try braid.keepSession()\n        defer { braid.finishSession() }\n        var rows: [GamingRow] = []\n        func row(_ generation: Generation, in braid: BenchBraid, set: GamingSet, label: String, owner: String?) -> GamingRow? {\n            guard let first = FirstTokenGate(generation, commons: braid.commonsIndex) else { return nil }\n            return GamingRow(set: set, label: label, owner: owner, answer: generation.text, allOpen: first.allOpen, largestGate: first.largestThreadMemory,\n                             leader: braid.names[first.leader], commonsLeads: first.commonsLeads)\n        }\n        // Subjects nobody holds: each Thread's own templates about nothing, each prompt asked once.\n        var asked = Set<String>()\n        for thread in threads {\n            let facts = BenchPrompts.facts(thread: thread, world: world, tokenizer: braid.tokenizer, byteOffsets: braid.tokenizer.byteOffsets,\n                                           paragraphBreak: braid.tokenizer.paragraphBreak, perNode: .max)\n            let prompts = BenchPrompts.unknown(facts, count: perNode).filter { !asked.contains($0) }\n            progress?(\"unknown · \\(thread.name): \\(prompts.count) prompts\")\n            for prompt in prompts {\n                asked.insert(prompt)\n                let generation = try braid.generate(braid.tokenizer.encode(prompt), maxTokens: generated)\n                if let made = row(generation, in: braid, set: .unknown, label: \"nowhere · \\(prompt)\", owner: thread.name) { rows.append(made) }\n            }\n            braid.relax()\n        }\n        progress?(\"generic: \\(BenchPrompts.generic.count) prompts\")\n        for prompt in BenchPrompts.generic {\n            let generation = try braid.generate(braid.tokenizer.encode(prompt), maxTokens: generated)\n            if let made = row(generation, in: braid, set: .generic, label: \"generic · \\(prompt)\", owner: nil) { rows.append(made) }\n        }\n        // G3: two Threads holding the same documents (equal snapshot hashes), in the copy braid if named.\n        let copyBraid = copies ?? braid\n        var pair: [String]? = nil\n        if let found = copyPair(in: copyBraid) {\n            pair = found\n            if copies != nil { try copyBraid.keepSession() }\n            defer { if copies != nil { copyBraid.finishSession() } }\n            let copyThreads = try copyBraid.benchThreads(world: world) { progress?(\"warning: \\($0)\") }\n            guard let a = copyThreads.first(where: { $0.name == found[0] }), let b = copyThreads.first(where: { $0.name == found[1] }) else {\n                throw BraidFailure.data(\"the copy pair \\(found.joined(separator: \", \")) is not in the copy braid\")\n            }\n            let facts = copiedFacts(a, b, world: world, tokenizer: copyBraid.tokenizer)\n            progress?(\"copied · \\(a.name) = \\(b.name): \\(facts.count) facts\")\n            for fact in facts {\n                let generation = try copyBraid.generate(fact.tokens, maxTokens: fact.answerTokens + 2)\n                guard var made = row(generation, in: copyBraid, set: .copied, label: \"\\(a.name) = \\(b.name) · \\(fact.fact.subject) (\\(fact.fact.kind))\", owner: a.name) else { continue }\n                made.copies = found\n                made.copyCredit = CopyTie.credits(generation, holders: found)\n                made.exact = generation.text.hasPrefix(fact.fact.answer)\n                made.followed = generation.decisions.first?.followed\n                made.tied = generation.decisions.first.map(\\.tied)\n                rows.append(made)\n            }\n            copyBraid.relax()\n        } else {\n            progress?(\"copied: no two Threads hold the same documents; G3 is skipped\")\n        }\n        let verdict = evaluate(rows: rows, copyPair: pair)\n        let strands = braid.names.count\n        let floor = Gate.floor(braid.settings.gate.openFloor, strands: strands)\n        let prior = strands > 1 ? (1 - braid.settings.gate.commonsPrior) / Double(strands - 1) : 1\n        let notes = [\n            String(format: \"RaoLM's recorded 100%% · 0.59 (unknown) and 100%% · 0.50 (generic) (RaoLM Docs/BRAID.md, \\\"Choosing the gate\\\") were measured on a two-Thread braid (Ambient, Craft) with no commons, before the commons existed, so the open floor never bit there. This braid has the commons at prior %.2f and %d Threads starting at %.3f each, against an open floor of %.3f.\",\n                   braid.settings.gate.commonsPrior, strands - 1, prior, floor),\n        ]\n        return GamingReport(createdAt: BenchFormat.wholeSecond(), dataset: world.name, threads: braid.threadRecords.merging(copyBraid.threadRecords) { a, _ in a },\n                            gate: braid.settings.gate, perNode: perNode, copyPair: pair, rows: rows, rules: verdict.rules, reported: verdict.reported,\n                            summary: verdict.summary, sessions: (braid.sessions + (copies?.sessions ?? [])).map(\\.path), notes: notes)\n    }\n\n    /// The first two Threads of `braid` whose live versions hold the same corpus.\n    public static func copyPair(in braid: BenchBraid) -> [String]? {\n        for a in braid.threads.indices {\n            for b in braid.threads.indices where b > a && braid.threads[a].version.corpusHash == braid.threads[b].version.corpusHash {\n                return [braid.threads[a].info.name, braid.threads[b].info.name]\n            }\n        }\n        return nil\n    }\n\n    /// Every located fact of the exclusive documents both copies hold (a third Thread holds none of them).\n    static func copiedFacts(_ a: BenchThread, _ b: BenchThread, world: BenchWorld, tokenizer: BraidTokenizer) -> [BenchPrompts.FactPrompt] {\n        BenchPrompts.facts(thread: a, world: world, tokenizer: tokenizer, byteOffsets: tokenizer.byteOffsets, paragraphBreak: tokenizer.paragraphBreak, perNode: .max)\n            .filter { b.present.contains($0.documentID) }\n    }\n\n    public static func rescore(_ report: GamingReport) -> GamingReport {\n        var rescored = report\n        let verdict = evaluate(rows: report.rows, copyPair: report.copyPair)\n        rescored.rules = verdict.rules\n        rescored.reported = verdict.reported\n        rescored.summary = verdict.summary\n        return rescored\n    }\n\n    // MARK: - The rule (pure)\n\n    /// G1 unknown subjects: every Thread open at the first generated token on ≥ 90% of prompts, the\n    /// largest Thread gate there ≤ 0.80 on average. G2 generic text: every Thread open on every prompt,\n    /// the largest Thread gate ≤ 0.65 on average. G3 copy braid (only with two Threads holding the same\n    /// documents): of the exactly answered copied facts, the copies' content credits tie within 0.10\n    /// of their sum on ≥ 90%, and no fact is taken whole by one copy (RaoLM's Q5b reading).\n    public static func evaluate(rows: [GamingRow], copyPair: [String]?) -> BenchVerdict {\n        let share = BenchFormat.share\n        func pct(_ value: Double) -> String { BenchFormat.pct(value) }\n        var rules: [BenchRule] = []\n        var reported: [String: Float] = [:]\n        let guards: [(id: String, set: GamingSet, needOpen: Double, maxGate: Double)] = [\n            (\"G1 unknown subjects\", .unknown, 0.9, 0.80), (\"G2 generic text\", .generic, 1.0, 0.65),\n        ]\n        for rule in guards {\n            let mine = rows.filter { $0.set == rule.set }\n            let open = share(mine.map(\\.allOpen))\n            let gate = Stats.mean(mine.map { Double($0.largestGate) })\n            rules.append(BenchRule(\n                id: rule.id, passes: !mine.isEmpty && open >= rule.needOpen && gate <= rule.maxGate,\n                detail: \"every Thread open at the first generated token on \\(pct(open)) of \\(mine.count) (needs \\(pct(rule.needOpen))); \"\n                    + \"largest Thread gate \\(BenchFormat.num(gate)) on average (needs ≤ \\(BenchFormat.num(rule.maxGate, 2)))\"))\n            reported[\"\\(rule.set.rawValue): every Thread open at the first generated token\"] = Float(open)\n            reported[\"\\(rule.set.rawValue): largest Thread gate (mean)\"] = Float(gate)\n            reported[\"\\(rule.set.rawValue): the commons leads at the first generated token\"] = Float(share(mine.map { $0.commonsLeads == true }))\n            reported[\"\\(rule.set.rawValue): largest Thread gate (max)\"] = mine.map(\\.largestGate).max() ?? 0\n        }\n        let copied = rows.filter { $0.set == .copied }\n        if let copyPair, !copied.isEmpty {\n            let exact = copied.filter { $0.exact == true }\n            let tied = exact.filter { CopyTie.tied($0.copyCredit ?? []) }.count\n            let taken = exact.filter { CopyTie.takenWhole($0.copyCredit ?? []) }.count\n            let rate = exact.isEmpty ? 0 : Double(tied) / Double(exact.count)\n            rules.append(BenchRule(\n                id: \"G3 copy braid\", passes: !exact.isEmpty && rate >= 0.9 && taken == 0,\n                detail: \"\\(copyPair.joined(separator: \" and \")): \\(tied) of \\(exact.count) exactly answered copied facts tie (each copy within 0.10 of the other, \"\n                    + \"\\(pct(rate)), needs 90%); \\(taken) taken whole by one copy (needs 0); \\(copied.count - exact.count) of \\(copied.count) not answered exactly\"))\n            reported[\"copied: answered exactly\"] = Float(share(copied.map { $0.exact == true }))\n            reported[\"copied: the sentence followed one copy\"] = Float(share(exact.map { $0.followed != nil }))\n        } else {\n            rules.append(BenchRule(id: \"G3 copy braid\", passes: false, detail: \"skipped: no two Threads hold the same documents\", skipped: true))\n        }\n        let failed = rules.filter { !$0.passes && !$0.skipped }.map(\\.id)\n        var summary = failed.isEmpty ? \"G1 and G2 pass\" : \"failed: \" + failed.joined(separator: \", \")\n        if let g3 = rules.first(where: { $0.id == \"G3 copy braid\" }) {\n            summary += g3.skipped ? \"; G3 skipped (no copy braid)\" : (g3.passes ? \"; G3 passes\" : \"\")\n        }\n        return BenchVerdict(rules: rules, reported: reported, summary: summary)\n    }\n}\n"},{"path":"Sources/BraidKit/Tools/Bench/KeySweep.swift","lines":223,"bytes":13077,"header":{"lines":[1,17],"what":[8,16],"pin":null,"in":null,"out":null},"marks":[],"first":1521,"scopes":[["S","KeySweepOptions",null,"public",23,23,[23,40],43,null,-1,0],["i","init",["arms"],"public",42,42,[42,65],42,null,0,8],["S","ProbeReport",null,"public",45,45,[45,56],52,null,-1,0],["S","RetrievalReport",null,"public",54,54,[54,60],66,null,-1,0],["S","KeySweepArmReport",null,"public",68,68,[68,62],79,null,-1,0],["S","KeySweepReport",null,"public",81,81,[81,59],99,null,-1,0],["E","KeySweep",null,"public",101,101,[101,21],223,null,-1,0,[]],["f","run",["thread","pack","tokenizer","snapshot","facts","options","into","progress"],"public static",105,105,[106,112],154,[104,104],6,0],["f","rank",["_"],"",139,139,[139,60],139,null,7,12],["f","probe",["index","options"],"public static",158,158,[158,94],192,[156,157],6,0],["f","retrieval",["index","trunk","tokenizer","corpus","facts","scheme","options","text"],"static",195,195,[196,104],222,[194,194],6,0]],"text":"//\n//  KeySweep.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The key sweep (step 4's instrument): the same trained Thread re-indexed under each key\n//        scheme, then two retrieval-only measurements per scheme. The document-identity probe asks,\n//        for a seeded sample of entries, whether an entry's own key finds another position of its own\n//        document once its ±near neighbours are excluded. The fact arms ask whether the key at a fact\n//        prompt's last token (the answer's predictor) retrieves the fact's partition, the answer's\n//        very position, and the answer token — for the corpus-exact prompt, the dataset's question\n//        stem and a paraphrase. Rules fixed here; the trace bench's T1–T3 per variant join when its\n//        text sets exist. Nothing here changes a default: the report names a winner and whether the\n//        +0.02 rule would ship it, and the owner decides.\n//\n\nimport BraidCore\nimport Foundation\nimport MLX\n\npublic struct KeySweepOptions: Sendable {\n    public var arms: [KeyScheme]\n    public var defaultScheme: KeyScheme = .residual(afterBlocks: 12)\n    /// Entries sampled for the document-identity probe.\n    public var sample = 2000\n    /// Same-document entries within ±near positions are not counted as finds.\n    public var near = 8\n    public var k = 16\n    public var tau: Float = 0.05\n    public var seed: UInt64 = 42\n    /// Facts measured (0 = all located).\n    public var factLimit = 0\n\n    public static let defaultArms: [KeyScheme] = [\n        .residual(afterBlocks: 6), .residual(afterBlocks: 8), .residual(afterBlocks: 12), .residual(afterBlocks: 16),\n        .pooledState(layer: 8), .pooledState(layer: 12), .pooledState(layer: 16),\n        .stateDelta(layer: 8), .stateDelta(layer: 12), .stateDelta(layer: 16),\n    ]\n\n    public init(arms: [KeyScheme] = KeySweepOptions.defaultArms) { self.arms = arms }\n}\n\npublic struct ProbeReport: Codable, Sendable, Equatable {\n    public var sampled: Int\n    /// Fraction whose nearest non-neighbour entry is in the same document.\n    public var sameDocument: Float\n    /// Fraction whose nearest non-neighbour entry is in the same partition.\n    public var samePartition: Float\n    public var meanTopScore: Float\n}\n\npublic struct RetrievalReport: Codable, Sendable, Equatable {\n    public var count: Int\n    /// The top hit's value sits on the fact's partition.\n    public var partitionAt1: Float\n    /// The top hit's value is the answer's first token at its own position.\n    public var offsetAt1: Float\n    /// The top hit's value token is the answer's first token (anywhere).\n    public var answerAt1: Float\n    /// Any of the top k hits sits on the fact's partition.\n    public var partitionAtK: Float\n    /// Mean softmax(s/τ) mass on the answer's first token.\n    public var meanAnswerMass: Float\n}\n\npublic struct KeySweepArmReport: Codable, Sendable, Equatable {\n    public var scheme: String\n    public var keyDims: Int\n    public var entries: Int\n    public var buildSeconds: Double\n    public var probe: ProbeReport\n    public var prompt: RetrievalReport?\n    public var stem: RetrievalReport?\n    public var paraphrase: RetrievalReport?\n    /// T1–T3 of the trace bench for this variant, when its text sets exist. Nil = not run.\n    public var qualifies: Bool?\n}\n\npublic struct KeySweepReport: Codable, Sendable, Equatable {\n    public var bench = \"sweep-key\"\n    public var createdAt: Date\n    public var thread: String\n    public var source: String\n    public var pack: String\n    public var blocksSHA256: String\n    public var documents: Int\n    public var factsLocated: Int\n    public var factsUnaligned: Int\n    public var arms: [KeySweepArmReport]\n    public var defaultScheme: String\n    /// Highest prompt partition@1, ties by offset@1, then the earlier arm.\n    public var winner: String?\n    /// Winner ≠ default and its prompt partition@1 ≥ the default's + 0.02.\n    public var ships: Bool\n    public var rule: String\n    public var notes: [String]\n}\n\npublic enum KeySweep {\n    public static let rule = \"winner = highest prompt partition@1 (ties: offset@1, then arm order); ships only if ≥ +0.02 absolute over the default; a variant qualifies only when T1–T3 pass (pending the trace bench's text sets)\"\n\n    /// Runs every arm on `thread`, writing each arm's index under `directory/<scheme>/index`.\n    public static func run(thread: LoadedThread, pack: Pack, tokenizer: BraidTokenizer, snapshot: CorpusSnapshot, facts: [Fact], options: KeySweepOptions,\n                           into directory: URL, progress: (String) -> Void = { _ in }) throws -> KeySweepReport {\n        let corpus = TokenizedCorpus(snapshot: snapshot, tokenizer: tokenizer, paragraphBreak: tokenizer.paragraphBreak, threadID: thread.info.threadID)\n        let reed = pack.reed(tokens: tokenizer.vocabSize)\n        let (located, unaligned) = FactLocator.locate(facts, corpus: corpus, byteOffsets: { tokenizer.byteOffsets($0) })\n        let measured = options.factLimit > 0 ? Array(located.prefix(options.factLimit)) : located\n        var arms: [KeySweepArmReport] = []\n        var notes: [String] = []\n        if measured.isEmpty { notes.append(\"no facts located: the fact arms are absent\") }\n        for scheme in options.arms {\n            let armDirectory = directory.appendingPathComponent(scheme.description, isDirectory: true)\n            let indexDirectory = armDirectory.appendingPathComponent(\"index\", isDirectory: true)\n            try FileManager.default.createDirectory(at: indexDirectory, withIntermediateDirectories: true)\n            var build = IndexBuildOptions(scheme: scheme)\n            build.checkpoints.strideTokens = Int.max / 4                                               // no checkpoints: nothing replays here\n            progress(\"\\(scheme): indexing \\(corpus.documents.count) documents\")\n            let started = Date()\n            let built = try IndexBuilder.build(trunk: thread.node.trunk, reed: reed, corpus: corpus, pack: pack, blocksSHA256: thread.version.blocksSHA256,\n                                               threadID: thread.info.threadID, options: build, into: indexDirectory)\n            let seconds = Date().timeIntervalSince(started)\n            let index = try ProvenanceIndex(directory: indexDirectory)\n            progress(\"\\(scheme): \\(index.count) entries in \\(String(format: \"%.1f\", seconds)) s; probing\")\n            let probe = Self.probe(index: index, options: options)\n            var arm = KeySweepArmReport(scheme: scheme.description, keyDims: built.info.keyDims, entries: index.count, buildSeconds: seconds, probe: probe)\n            if !measured.isEmpty {\n                progress(\"\\(scheme): \\(measured.count) facts × 3 arms\")\n                arm.prompt = retrieval(index: index, trunk: thread.node.trunk, tokenizer: tokenizer, corpus: corpus, facts: measured, scheme: scheme, options: options) { $0.fact.prompt }\n                arm.stem = retrieval(index: index, trunk: thread.node.trunk, tokenizer: tokenizer, corpus: corpus, facts: measured, scheme: scheme, options: options) { $0.fact.questions?.first?.stem }\n                arm.paraphrase = retrieval(index: index, trunk: thread.node.trunk, tokenizer: tokenizer, corpus: corpus, facts: measured, scheme: scheme, options: options) { $0.fact.paraphrases.first }\n            }\n            arms.append(arm)\n            Memory.clearCache()\n        }\n        // The winner, by the rule.\n        func rank(_ a: KeySweepArmReport) -> (Float, Float) { (a.prompt?.partitionAt1 ?? -1, a.prompt?.offsetAt1 ?? -1) }\n        var winner: KeySweepArmReport? = nil\n        for arm in arms where arm.prompt != nil {\n            if let current = winner { if rank(arm) > rank(current) { winner = arm } } else { winner = arm }\n        }\n        let defaultArm = arms.first { $0.scheme == options.defaultScheme.description }\n        var ships = false\n        if let winner, let defaultArm, winner.scheme != defaultArm.scheme, let w = winner.prompt?.partitionAt1, let d = defaultArm.prompt?.partitionAt1 {\n            ships = w >= d + 0.02\n        }\n        if defaultArm == nil { notes.append(\"the default scheme \\(options.defaultScheme) was not among the arms; nothing ships against it\") }\n        notes.append(\"T1–T3 per variant not run: qualifies is nil for every arm\")\n        return KeySweepReport(createdAt: Date(), thread: thread.info.name, source: thread.info.source, pack: pack.sha256, blocksSHA256: thread.version.blocksSHA256,\n                              documents: corpus.documents.count, factsLocated: located.count, factsUnaligned: unaligned.count, arms: arms,\n                              defaultScheme: options.defaultScheme.description, winner: winner?.scheme, ships: ships, rule: rule, notes: notes)\n    }\n\n    /// The document-identity probe: an entry's own key against the index, its ±near same-document\n    /// neighbours and itself excluded; is the nearest remaining entry in the same document?\n    public static func probe(index: ProvenanceIndex, options: KeySweepOptions) -> ProbeReport {\n        guard index.count > 0 else { return ProbeReport(sampled: 0, sameDocument: 0, samePartition: 0, meanTopScore: 0) }\n        // Each entry's document, as an integer id.\n        var documentIDs: [String: Int] = [:]\n        let documentOf: [Int] = (0 ..< index.count).map { e in\n            let id = index.partition(row: Int(index.keyRow[e]))?.documentID ?? \"?\"\n            if let n = documentIDs[id] { return n }\n            documentIDs[id] = documentIDs.count\n            return documentIDs.count - 1\n        }\n        var rng = SplitMix64(seed: options.seed)\n        let sampled: [Int] = index.count <= options.sample ? Array(0 ..< index.count) : (0 ..< options.sample).map { _ in Int(rng.next() % UInt64(index.count)) }\n        var sameDocument = 0, samePartition = 0\n        var topScores: Double = 0\n        let batch = 256\n        var start = 0\n        while start < sampled.count {\n            let slice = Array(sampled[start ..< min(start + batch, sampled.count)])\n            let queries = index.keys[MLXArray(slice.map { Int32($0) })]\n            let hits = index.query(queries, k: 2 * options.near + options.k + 1)\n            for (i, e) in slice.enumerated() {\n                let own = documentOf[e]\n                guard let found = hits[i].first(where: { hit in\n                    let f = Int(hit.entry)\n                    return f != e && !(documentOf[f] == own && abs(f - e) <= options.near)\n                }) else { continue }\n                if documentOf[Int(found.entry)] == own { sameDocument += 1 }\n                if index.keyRow[Int(found.entry)] == index.keyRow[e] { samePartition += 1 }\n                topScores += Double(found.score)\n            }\n            start += batch\n        }\n        let n = max(1, sampled.count)\n        return ProbeReport(sampled: sampled.count, sameDocument: Float(sameDocument) / Float(n), samePartition: Float(samePartition) / Float(n), meanTopScore: Float(topScores / Double(n)))\n    }\n\n    /// Retrieval at a fact prompt's last token for the texts `text` yields (nil skips the fact).\n    static func retrieval(index: ProvenanceIndex, trunk: Trunk, tokenizer: BraidTokenizer, corpus: TokenizedCorpus, facts: [LocatedFact], scheme: KeyScheme,\n                          options: KeySweepOptions, text: (LocatedFact) -> String?) -> RetrievalReport? {\n        var count = 0\n        var partition1 = 0, offset1 = 0, answer1 = 0, partitionK = 0\n        var mass: Double = 0\n        for fact in facts {\n            guard let prompt = text(fact), !prompt.isEmpty else { continue }\n            let tokens: [Int32] = [tokenizer.eos] + tokenizer.encode(\" \" + prompt)\n            let key = SegmentKeys.lastKey(trunk: trunk, segment: tokens, state: nil, scheme: scheme, alpha: index.info.alpha)\n            let hits = index.query(key.reshaped([1, -1]), k: options.k)[0]\n            guard let top = hits.first else { continue }\n            count += 1\n            let answerToken = corpus.partitions[fact.row].tokens[fact.answerToken]\n            if Int(top.row) == fact.row { partition1 += 1 }\n            if Int(top.row) == fact.row && Int(top.offset) == fact.answerToken { offset1 += 1 }\n            if top.value == answerToken { answer1 += 1 }\n            if hits.contains(where: { Int($0.row) == fact.row }) { partitionK += 1 }\n            let scaled = hits.map { Double($0.score / options.tau) }\n            let peak = scaled.max() ?? 0\n            let weights = scaled.map { exp($0 - peak) }\n            let total = weights.reduce(0, +)\n            mass += zip(hits, weights).filter { $0.0.value == answerToken }.map { $0.1 }.reduce(0, +) / max(total, 1e-30)\n        }\n        guard count > 0 else { return nil }\n        let n = Float(count)\n        return RetrievalReport(count: count, partitionAt1: Float(partition1) / n, offsetAt1: Float(offset1) / n, answerAt1: Float(answer1) / n,\n                               partitionAtK: Float(partitionK) / n, meanAnswerMass: Float(mass / Double(count)))\n    }\n}\n"},{"path":"Sources/BraidKit/Tools/Bench/LiftBench.swift","lines":301,"bytes":16865,"header":{"lines":[1,15],"what":[8,13],"pin":[14,14],"in":null,"out":null},"marks":[[225,"The rule (pure)"]],"first":1532,"scopes":[["E","LiftSet",null,"public",20,20,[20,61],20,null,-1,8,[]],["S","LiftRow",null,"public",22,22,[22,52],73,null,-1,0],["i","init",["set","label","owner","expected","answer","exact","commonsLeads","largestThreadMemory","ownerLeads","threadShare","answerTokens","ownerShare","liftDefined","liftPositive","threadsCredit","bits","tokens","nllBraid","nllCommons"],"public",49,49,[52,42],72,null,1,0],["S","LiftReport",null,"public",75,75,[75,44],87,null,-1,0],["E","LiftBench",null,"public",89,89,[89,22],301,null,-1,0,[]],["S","Sizes",null,"public",90,90,[90,54],99,null,4,0],["i","init",[],"public",98,98,[98,22],98,null,5,8],["f","run",["braid","world","sizes","progress"],"public static",101,101,[101,147],203,null,4,0],["f","credit",["_"],"",110,110,[110,78],120,[109,109],7,4],["f","nll",["_"],"static",206,206,[206,76],214,[205,205],4,0],["f","rescore",["_"],"public static",216,216,[216,67],223,null,4,0],["f","evaluate",["rows"],"public static",233,233,[233,65],300,[227,232],4,0],["f","pct",["_"],"",235,235,[235,44],235,null,11,12],["f","num",["_"],"",236,236,[236,44],236,null,11,12]],"text":"//\n//  LiftBench.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid bench lift`: whether the commons and the lift gate earn their place. Fact prompts\n//        (a Thread's own facts, the corpus sentence before the answer), generic prose, general\n//        English the base model knows (commons prompts), subjects no Thread holds, and each Thread's\n//        unfed documents scored by the braid and by the commons alone. Rules L1, L2 and L4 are\n//        RaoLM's U3/U4 and Q4, fixed before any numbers (RaoLM Docs/ARCHITECTURE.md, \"bench-umbrella\");\n//        L3 (held-out NLL against the commons alone) is reported without a threshold.\n//  PIN:  Needs the commons in the braid. `evaluate` is pure over the saved rows.\n//\n\nimport BraidCore\nimport Foundation\n\npublic enum LiftSet: String, Codable, Sendable, CaseIterable { case facts, generic, commons, unknown, heldOut }\n\npublic struct LiftRow: Codable, Sendable, Equatable {\n    public var set: LiftSet\n    public var label: String\n    public var owner: String?\n    public var expected: String?\n    public var answer: String?\n    public var exact: Bool?\n    /// At the first generated token: the commons holds the largest memory; the largest Thread memory.\n    public var commonsLeads: Bool?\n    public var largestThreadMemory: Float?\n    public var ownerLeads: Bool?\n    /// Generic and commons prompts: the mean over generated tokens of the Threads' summed share.\n    public var threadShare: Float?\n    /// Facts: the answer tokens, the owner's mean share of them, and on how many its lift over the\n    /// commons was defined (both asked) and positive.\n    public var answerTokens: Int?\n    public var ownerShare: Float?\n    public var liftDefined: Int?\n    public var liftPositive: Int?\n    /// Σ bits·(the Threads' credit) and Σ bits over the generated tokens (form tokens are the commons').\n    public var threadsCredit: Float?\n    public var bits: Float?\n    /// Held-out: the scored tokens and Σ −ln p under the braid and under the commons alone.\n    public var tokens: Int?\n    public var nllBraid: Float?\n    public var nllCommons: Float?\n\n    public init(set: LiftSet, label: String, owner: String? = nil, expected: String? = nil, answer: String? = nil, exact: Bool? = nil, commonsLeads: Bool? = nil,\n                largestThreadMemory: Float? = nil, ownerLeads: Bool? = nil, threadShare: Float? = nil, answerTokens: Int? = nil, ownerShare: Float? = nil,\n                liftDefined: Int? = nil, liftPositive: Int? = nil, threadsCredit: Float? = nil, bits: Float? = nil, tokens: Int? = nil, nllBraid: Float? = nil,\n                nllCommons: Float? = nil) {\n        self.set = set\n        self.label = label\n        self.owner = owner\n        self.expected = expected\n        self.answer = answer\n        self.exact = exact\n        self.commonsLeads = commonsLeads\n        self.largestThreadMemory = largestThreadMemory\n        self.ownerLeads = ownerLeads\n        self.threadShare = threadShare\n        self.answerTokens = answerTokens\n        self.ownerShare = ownerShare\n        self.liftDefined = liftDefined\n        self.liftPositive = liftPositive\n        self.threadsCredit = threadsCredit\n        self.bits = bits\n        self.tokens = tokens\n        self.nllBraid = nllBraid\n        self.nllCommons = nllCommons\n    }\n}\n\npublic struct LiftReport: Codable, Sendable {\n    public var bench = \"lift\"\n    public var createdAt: Date\n    public var dataset: String\n    public var threads: [String: String]\n    public var gate: GateSettings\n    public var sizes: LiftBench.Sizes\n    public var rows: [LiftRow]\n    public var rules: [BenchRule]\n    public var reported: [String: Float]\n    public var summary: String\n    public var sessions: [String]? = nil\n}\n\npublic enum LiftBench {\n    public struct Sizes: Codable, Sendable, Equatable {\n        public var factsPerNode = 10\n        public var unknown = 10\n        public var heldOutPerNode = 8\n        /// Tokens generated after generic and commons prompts (RaoLM's 8), and after unknown prompts.\n        public var generalTokens = 8\n        public var unknownTokens = 4\n\n        public init() {}\n    }\n\n    public static func run(braid: BenchBraid, world: BenchWorld, sizes: Sizes = Sizes(), progress: ((String) -> Void)? = nil) throws -> LiftReport {\n        guard let commons = braid.commonsIndex else { throw BraidFailure.usage(\"bench lift needs the commons in the braid\") }\n        let threads = try braid.benchThreads(world: world) { progress?(\"warning: \\($0)\") }\n        let tokenizer = braid.tokenizer\n        try braid.keepSession()\n        defer { braid.finishSession() }\n        var rows: [LiftRow] = []\n\n        /// Σ bits·(Threads' credit) and Σ bits over the generated tokens.\n        func credit(_ generation: Generation) -> (credit: Float, bits: Float) {\n            var weighed: Float = 0\n            var bits: Float = 0\n            let shared = generation.steps.filter { $0.source != .ctx }\n            for (i, step) in shared.enumerated() where step.source == .gen {\n                guard i < generation.credits.count, let row = generation.credits[i], let b = row.bits else { continue }\n                weighed += b * row.credit.indices.filter { $0 != commons }.reduce(Float(0)) { $0 + row.credit[$1] }\n                bits += b\n            }\n            return (weighed, bits)\n        }\n\n        // Facts: a Thread's own, from each Thread in turn.\n        var ranked: [[BenchPrompts.FactPrompt]] = []\n        for thread in threads {\n            ranked.append(BenchPrompts.facts(thread: thread, world: world, tokenizer: tokenizer, byteOffsets: tokenizer.byteOffsets,\n                                             paragraphBreak: tokenizer.paragraphBreak, perNode: .max))\n        }\n        let facts = BenchPrompts.interleave(ranked.map { Array($0.prefix(sizes.factsPerNode)) })\n        progress?(\"facts: \\(facts.count) prompts\")\n        for fact in facts {\n            guard let owner = braid.index(of: fact.thread) else { continue }\n            let generation = try braid.generate(fact.tokens, maxTokens: fact.answerTokens + 2)\n            let answer = generation.generated.prefix(fact.answerTokens)\n            var share = 0.0\n            var defined = 0\n            var positive = 0\n            for step in answer {\n                guard let records = step.threads, owner < records.count, commons < records.count else { continue }\n                share += Double(records[owner].share)\n                if let own = records[owner].plm, let base = records[commons].plm {\n                    defined += 1\n                    if own > base { positive += 1 }\n                }\n            }\n            let first = FirstTokenGate(generation, commons: commons)\n            let (weighed, bits) = credit(generation)\n            rows.append(LiftRow(set: .facts, label: \"\\(fact.thread) · \\(fact.fact.subject) (\\(fact.fact.kind))\", owner: fact.thread, expected: fact.fact.answer,\n                                answer: generation.text, exact: generation.text.hasPrefix(fact.fact.answer), commonsLeads: first?.commonsLeads,\n                                largestThreadMemory: first?.largestThreadMemory, ownerLeads: first.map { $0.leader == owner }, answerTokens: answer.count,\n                                ownerShare: answer.isEmpty ? nil : Float(share / Double(answer.count)), liftDefined: defined, liftPositive: positive,\n                                threadsCredit: weighed, bits: bits))\n        }\n        braid.relax()\n\n        // Generic prose and general English: does the commons lead, and what do the Threads take?\n        for (set, prompts) in [(LiftSet.generic, BenchPrompts.generic), (.commons, BenchPrompts.commons)] {\n            progress?(\"\\(set.rawValue): \\(prompts.count) prompts\")\n            for prompt in prompts {\n                let generation = try braid.generate(tokenizer.encode(prompt), maxTokens: sizes.generalTokens)\n                let first = FirstTokenGate(generation, commons: commons)\n                let taken = generation.generated.compactMap { step -> Double? in\n                    guard let records = step.threads else { return nil }\n                    return records.indices.filter { $0 != commons }.reduce(0.0) { $0 + Double(records[$1].share) }\n                }\n                let (weighed, bits) = credit(generation)\n                rows.append(LiftRow(set: set, label: \"\\(set.rawValue) · \\(prompt)\", answer: generation.text, commonsLeads: first?.commonsLeads,\n                                    largestThreadMemory: first?.largestThreadMemory, threadShare: taken.isEmpty ? nil : Float(Stats.mean(taken)),\n                                    threadsCredit: weighed, bits: bits))\n            }\n        }\n        braid.relax()\n\n        // Subjects no Thread holds: each Thread's templates about nothing, a Thread in turn.\n        let unknown = BenchPrompts.interleave(ranked.map { BenchPrompts.unknown($0, count: sizes.unknown) }, total: sizes.unknown)\n        progress?(\"unknown: \\(unknown.count) prompts\")\n        for prompt in unknown {\n            let generation = try braid.generate(tokenizer.encode(prompt), maxTokens: sizes.unknownTokens)\n            let first = FirstTokenGate(generation, commons: commons)\n            let (weighed, bits) = credit(generation)\n            rows.append(LiftRow(set: .unknown, label: \"nowhere · \\(prompt)\", answer: generation.text, commonsLeads: first?.commonsLeads,\n                                largestThreadMemory: first?.largestThreadMemory, threadsCredit: weighed, bits: bits))\n        }\n        braid.relax()\n\n        // Held-out: each Thread's unfed exclusive documents, scored by the braid and by the commons alone.\n        for thread in threads {\n            let unfed = BenchTexts.exclusive(world.corpora[thread.node]?.documents ?? [], crosslinks: world.crosslinks).filter { !thread.present.contains($0.id) }\n            let documents = Array(unfed.prefix(sizes.heldOutPerNode))\n            progress?(\"held-out · \\(thread.name): \\(documents.count) unfed documents\")\n            for document in documents {\n                let tokens = BenchTexts.split(document, tokenizer: tokenizer, paragraphBreak: tokenizer.paragraphBreak).tokens\n                guard tokens.count > 1 else { continue }\n                let braided = nll(try braid.score(tokens))\n                let alone = nll(try braid.scoreCommonsAlone(tokens))\n                rows.append(LiftRow(set: .heldOut, label: \"\\(thread.name) · \\(document.name) (unfed)\", owner: thread.name, tokens: braided.tokens,\n                                    nllBraid: Float(braided.sum), nllCommons: Float(alone.sum)))\n            }\n            braid.relax()\n        }\n        let verdict = evaluate(rows: rows)\n        return LiftReport(createdAt: BenchFormat.wholeSecond(), dataset: world.name, threads: braid.threadRecords, gate: braid.settings.gate, sizes: sizes, rows: rows,\n                          rules: verdict.rules, reported: verdict.reported, summary: verdict.summary, sessions: braid.sessions.map(\\.path))\n    }\n\n    /// Σ −ln p(y) over a scoring's positions with strands, and how many.\n    static func nll(_ generation: Generation) -> (sum: Double, tokens: Int) {\n        var sum = 0.0\n        var tokens = 0\n        for step in generation.steps where step.threads != nil {\n            sum -= log(Double(max(step.prob, 1e-12)))\n            tokens += 1\n        }\n        return (sum, tokens)\n    }\n\n    public static func rescore(_ report: LiftReport) -> LiftReport {\n        var rescored = report\n        let verdict = evaluate(rows: report.rows)\n        rescored.rules = verdict.rules\n        rescored.reported = verdict.reported\n        rescored.summary = verdict.summary\n        return rescored\n    }\n\n    // MARK: - The rule (pure)\n\n    /// L1 nobody's text: the commons holds the largest memory at the first generated token on ≥ 90% of\n    /// generic and commons prompts, the largest Thread memory there ≤ 0.35 on average. L2 inherited\n    /// knowledge is not attributed: the Threads' summed share of commons prompts' tokens ≤ 0.10; on\n    /// facts the owner's share of answer tokens ≥ 0.90 and its lift over the commons positive on ≥ 95%\n    /// of them. L4 unknown subjects: the commons leads on ≥ 80%, the Threads' bits-weighted credit\n    /// ≤ 0.25. L3 (held-out NLL, braid against the commons alone) is reported without a threshold.\n    public static func evaluate(rows: [LiftRow]) -> BenchVerdict {\n        let share = BenchFormat.share\n        func pct(_ value: Double) -> String { BenchFormat.pct(value) }\n        func num(_ value: Double) -> String { BenchFormat.num(value) }\n        var rules: [BenchRule] = []\n        var reported: [String: Float] = [:]\n\n        let general = rows.filter { $0.set == .generic || $0.set == .commons }\n        let leads = share(general.map { $0.commonsLeads == true })\n        let gate = Stats.mean(general.compactMap { $0.largestThreadMemory.map(Double.init) })\n        rules.append(BenchRule(\n            id: \"L1 nobody's text\", passes: !general.isEmpty && leads >= 0.9 && gate <= 0.35,\n            detail: \"the commons leads at the first generated token on \\(pct(leads)) of \\(general.count) generic and commons prompts (needs 90%); \"\n                + \"largest Thread gate \\(num(gate)) on average (needs ≤ 0.35)\"))\n\n        let commonsRows = rows.filter { $0.set == .commons }\n        let taken = Stats.mean(commonsRows.compactMap { $0.threadShare.map(Double.init) })\n        let facts = rows.filter { $0.set == .facts }\n        var shareSum = 0.0\n        var answerTokens = 0\n        var defined = 0\n        var positive = 0\n        for row in facts {\n            if let s = row.ownerShare, let n = row.answerTokens {\n                shareSum += Double(s) * Double(n)\n                answerTokens += n\n            }\n            defined += row.liftDefined ?? 0\n            positive += row.liftPositive ?? 0\n        }\n        let ownerShare = answerTokens > 0 ? shareSum / Double(answerTokens) : 0\n        let liftRate = defined > 0 ? Double(positive) / Double(defined) : 0\n        rules.append(BenchRule(\n            id: \"L2 inherited knowledge is not attributed\",\n            passes: !commonsRows.isEmpty && answerTokens > 0 && taken <= 0.10 && ownerShare >= 0.90 && liftRate >= 0.95,\n            detail: \"Threads take \\(num(taken)) of \\(commonsRows.count) commons prompts' tokens (needs ≤ 0.10); the owner \\(num(ownerShare)) of \\(answerTokens) \"\n                + \"fact answer tokens (needs ≥ 0.90), its lift over the commons positive on \\(pct(liftRate)) of \\(defined) where both were asked (needs 95%)\"))\n        reported[\"facts: exact\"] = Float(share(facts.map { $0.exact == true }))\n        reported[\"facts: the owner leads at the first answer token\"] = Float(share(facts.map { $0.ownerLeads == true }))\n        reported[\"facts: answer tokens where the owner's lift is undefined\"] = Float(answerTokens - defined)\n\n        let unknown = rows.filter { $0.set == .unknown }\n        let unknownLeads = share(unknown.map { $0.commonsLeads == true })\n        let credit = unknown.reduce(0.0) { $0 + Double($1.threadsCredit ?? 0) }\n        let bits = unknown.reduce(0.0) { $0 + Double($1.bits ?? 0) }\n        let threadsCredit = bits > 0 ? credit / bits : 0\n        rules.append(BenchRule(\n            id: \"L4 unknown subjects\", passes: !unknown.isEmpty && unknownLeads >= 0.8 && threadsCredit <= 0.25,\n            detail: \"the commons leads at the first generated token on \\(pct(unknownLeads)) of \\(unknown.count) (needs 80%); \"\n                + \"the Threads' bits-weighted credit \\(num(threadsCredit)) over the generated tokens (needs ≤ 0.25)\"))\n        reported[\"unknown: largest Thread gate (mean)\"] = Float(Stats.mean(unknown.compactMap { $0.largestThreadMemory.map(Double.init) }))\n\n        let heldOut = rows.filter { $0.set == .heldOut }\n        let tokens = heldOut.reduce(0) { $0 + ($1.tokens ?? 0) }\n        var l3 = \"\"\n        if tokens > 0 {\n            let braid = heldOut.reduce(0.0) { $0 + Double($1.nllBraid ?? 0) } / Double(tokens)\n            let alone = heldOut.reduce(0.0) { $0 + Double($1.nllCommons ?? 0) } / Double(tokens)\n            reported[\"L3 held-out NLL: braid\"] = Float(braid)\n            reported[\"L3 held-out NLL: commons alone\"] = Float(alone)\n            reported[\"L3 held-out tokens\"] = Float(tokens)\n            l3 = String(format: \"; L3 (no threshold): held-out NLL %.4f under the braid, %.4f under the commons alone, over %d tokens of %d unfed documents\",\n                        braid, alone, tokens, heldOut.count)\n        }\n        let failed = rules.filter { !$0.passes }.map(\\.id)\n        let summary = (failed.isEmpty ? \"L1, L2 and L4 pass\" : \"failed: \" + failed.joined(separator: \", \")) + l3\n        return BenchVerdict(rules: rules, reported: reported, summary: summary)\n    }\n}\n"},{"path":"Sources/BraidKit/Tools/Bench/QuestionBench.swift","lines":465,"bytes":28630,"header":{"lines":[1,20],"what":[8,14],"pin":[15,19],"in":null,"out":null},"marks":[[353,"The rules (pure)"]],"first":1546,"scopes":[["E","QuestionSet",null,"public",25,25,[25,65],25,null,-1,8,[]],["E","QuestionArm",null,"public",27,27,[27,65],27,null,-1,8,[]],["S","QuestionRow",null,"public",29,29,[29,56],82,null,-1,0],["i","init",["set","arm","label","owner","question","storedStem","stem","answer"],"public",72,72,[72,152],81,null,2,0],["S","QuestionReport",null,"public",84,84,[84,48],97,null,-1,0],["E","QuestionBench",null,"public",99,99,[99,26],465,null,-1,0,[]],["S","Sizes",null,"public",100,100,[100,54],109,null,5,0],["i","init",[],"public",108,108,[108,22],108,null,6,8],["S","Question",null,"",114,114,[114,20],121,null,5,0],["S","Shared",null,"",123,123,[123,18],130,null,5,0],["f","run",["braid","world","sizes","copies","progress"],"public static",132,132,[132,178],302,null,5,0],["f","rewrite",["_"],"",175,175,[175,60],180,null,10,4],["f","turn",["_","question","stem","slice","paraphrase","in"],"",181,181,[181,153],196,null,10,4],["f","answer",["_","in"],"",197,197,[197,85],203,null,10,4],["f","row",["_","_","label","owner","question","storedStem","turn","generation","expected"],"",204,204,[205,75],220,null,10,4],["f","sharedFacts",["world","threads","perLink"],"static",306,306,[306,97],324,[304,305],5,0],["f","rescore",["_"],"public static",326,326,[326,75],333,null,5,0],["f","followedReading",["_"],"static",337,337,[337,137],351,[335,336],5,0],["f","evaluate",["rows"],"public static",363,363,[363,69],464,[355,362],5,0],["f","pct",["_"],"",365,365,[365,44],365,null,18,12],["f","num",["_"],"",366,366,[366,45],366,null,18,12],["f","of",["_","_"],"",367,367,[367,73],367,null,18,12],["f","exact",["_"],"",368,368,[368,52],368,null,18,12]],"text":"//\n//  QuestionBench.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid bench question`: whether the braid answers questions through the path `braid chat`\n//        uses (QuestionPath). Every fact's first question (≤ 150 per Thread, from its exclusive\n//        documents) goes through four arms: the commons' rewrite (the path), the question's stored\n//        stem, the corpus slice before the answer (the v1 prompt, the ceiling) and the fact's first\n//        paraphrase (reported). Negative questions (20 per Thread) ask about entities nobody holds;\n//        each agreeing retelling is asked once so the followed-credit rule can be read; on a copy\n//        braid (two Threads holding the same documents, trained apart) the copies' facts are asked.\n//  PIN:  RaoLM's rules (RaoLM Docs/ARCHITECTURE.md, \"bench-question\" and \"Context to credit\"), fixed\n//        before any numbers and read on the commons arm: Braid has no rules rewriter, the fallback is\n//        the question itself. The commons, stem and paraphrase arms look up each Thread's context at\n//        the 0.6 floor; the slice is the corpus's own context and gets none. Q4 (negatives) is\n//        reported without a threshold, as the plan's table has no Q4. Session logs are kept.\n//\n\nimport BraidCore\nimport Foundation\n\npublic enum QuestionSet: String, Codable, Sendable, CaseIterable { case questions, negatives, shared, copied }\n\npublic enum QuestionArm: String, Codable, Sendable, CaseIterable { case commons, stem, slice, paraphrase }\n\npublic struct QuestionRow: Codable, Sendable, Equatable {\n    public var set: QuestionSet\n    public var arm: QuestionArm\n    public var label: String\n    /// The fact's Thread (questions; copied: the first holder; shared: the target's Thread).\n    public var owner: String?\n    public var question: String\n    public var storedStem: String?\n    /// What the braid completed: the rewrite, the stored stem, the paraphrase or the slice's text.\n    public var stem: String\n    /// Commons arm: \"commons\" or \"none\" (the question itself), whether the rewrite is the stored stem, its token F1, its time.\n    public var rewriter: String?\n    public var rewriteMatches: Bool?\n    public var rewriteF1: Float?\n    public var adapterSeconds: Double?\n    public var expected: String?\n    public var answer: String\n    public var exact: Bool?\n    /// Some answer token's top citation is the fact's partition; the answer tokens, and those whose top citation is.\n    public var cited: Bool?\n    public var answerTokens: Int?\n    public var citedTokens: Int?\n    /// The Threads that found a context, and whether the fact's own Thread did.\n    public var contexts: [String] = []\n    public var ownerContext: Bool?\n    /// Negatives: the commons holds the largest memory at the first generated token; the Threads' mean\n    /// credit per generated content token.\n    public var commonsLeads: Bool?\n    public var threadsCredit: Float?\n    /// Shared: the link's kind, its two sides (the source's Thread, the target's), the answer\n    /// sentence's follow decision, each side's summed content credit, and the side not followed's\n    /// mean credit per content token (when one side was followed).\n    public var kind: String?\n    public var sides: [String]?\n    public var followed: String?\n    public var tied: [String]?\n    public var sideCredit: [Float]?\n    public var otherCredit: Float?\n    public var contentTokens: Int?\n    /// Copied: the holders and each one's summed content credit.\n    public var holders: [String]?\n    public var holderCredit: [Float]?\n\n    public init(set: QuestionSet, arm: QuestionArm, label: String, owner: String?, question: String, storedStem: String?, stem: String, answer: String) {\n        self.set = set\n        self.arm = arm\n        self.label = label\n        self.owner = owner\n        self.question = question\n        self.storedStem = storedStem\n        self.stem = stem\n        self.answer = answer\n    }\n}\n\npublic struct QuestionReport: Codable, Sendable {\n    public var bench = \"question\"\n    public var createdAt: Date\n    public var dataset: String\n    public var threads: [String: String]\n    public var gate: GateSettings\n    public var copyPair: [String]?\n    public var sizes: QuestionBench.Sizes\n    public var rows: [QuestionRow]\n    public var rules: [BenchRule]\n    public var reported: [String: Float]\n    public var summary: String\n    public var sessions: [String]? = nil\n}\n\npublic enum QuestionBench {\n    public struct Sizes: Codable, Sendable, Equatable {\n        /// Questions per Thread: every fact's first question, up to this many facts.\n        public var perNode = 150\n        public var negativesPerNode = 20\n        public var sharedPerLink = 1\n        public var maxTokens = 24\n        public var floor: Float = QuestionPath.floor\n\n        public init() {}\n    }\n\n    /// Q5a reads these link kinds (RaoLM's amended rule); excerpts and variants are reported.\n    public static let retold: Set<String> = [CrossKind.paraphrase.rawValue, CrossKind.summary.rawValue]\n\n    struct Question {\n        var thread: String\n        var fact: Fact\n        var text: String\n        var stem: String\n        var slice: [Int32]\n        var paraphrase: String\n    }\n\n    struct Shared {\n        var text: String\n        var stem: String\n        var expected: String\n        var kind: CrossKind\n        var sides: [String]\n        var subject: String\n    }\n\n    public static func run(braid: BenchBraid, world: BenchWorld, sizes: Sizes = Sizes(), copies: BenchBraid? = nil, progress: ((String) -> Void)? = nil) throws -> QuestionReport {\n        guard braid.hasCommons else { throw BraidFailure.usage(\"bench question needs the commons: it rewrites the questions\") }\n        let commonsNode = braid.commonsNode\n        let tokenizer = braid.tokenizer\n        let adapter = QuestionAdapter(trunk: commonsNode.trunk, reed: braid.reed, tokenizer: tokenizer)\n        let threads = try braid.benchThreads(world: world) { progress?(\"warning: \\($0)\") }\n\n        // The sets.\n        var questions: [Question] = []\n        var negatives: [(thread: String, question: FactQuestion)] = []\n        for thread in threads {\n            let facts = BenchPrompts.facts(thread: thread, world: world, tokenizer: tokenizer, byteOffsets: tokenizer.byteOffsets,\n                                           paragraphBreak: tokenizer.paragraphBreak, perNode: .max)\n            for fact in facts.prefix(sizes.perNode) {\n                guard let question = fact.fact.questions?.first else { continue }\n                questions.append(Question(thread: thread.name, fact: fact.fact, text: question.text, stem: question.stem, slice: fact.tokens,\n                                          paraphrase: fact.fact.paraphrases.first ?? question.stem))\n            }\n            var seen = Set<String>()\n            for fact in facts {\n                guard negatives.filter({ $0.thread == thread.name }).count < sizes.negativesPerNode, let negative = fact.fact.negativeQuestions?.first,\n                      !seen.contains(negative.text) else { continue }\n                seen.insert(negative.text)\n                negatives.append((thread.name, negative))\n            }\n        }\n        let shared = sharedFacts(world: world, threads: threads, perLink: sizes.sharedPerLink)\n        var copyPair: [String]? = nil\n        var copied: [Question] = []\n        if let copies {\n            guard let pair = GamingBench.copyPair(in: copies) else { throw BraidFailure.usage(\"the copy braid holds no two Threads with the same documents\") }\n            copyPair = pair\n            let copyThreads = try copies.benchThreads(world: world) { progress?(\"warning: \\($0)\") }\n            if let a = copyThreads.first(where: { $0.name == pair[0] }), let b = copyThreads.first(where: { $0.name == pair[1] }) {\n                copied = GamingBench.copiedFacts(a, b, world: world, tokenizer: tokenizer).compactMap { fact in\n                    fact.fact.questions?.first.map { Question(thread: a.name, fact: fact.fact, text: $0.text, stem: $0.stem, slice: fact.tokens, paraphrase: $0.stem) }\n                }\n            }\n        }\n        progress?(\"questions \\(questions.count), negatives \\(negatives.count), shared \\(shared.count), copied \\(copied.count)\")\n\n        // The asking.\n        var rewrites: [String: QuestionRewrite] = [:]\n        func rewrite(_ question: String) -> QuestionRewrite {\n            if let cached = rewrites[question] { return cached }\n            let made = adapter.rewrite(question, maxTokens: sizes.maxTokens)\n            rewrites[question] = made\n            return made\n        }\n        func turn(_ arm: QuestionArm, question: String, stem: String, slice: [Int32]?, paraphrase: String?, in braid: BenchBraid) throws -> QuestionTurn {\n            let nodes = braid.threads.map { (name: $0.info.name, node: $0.node) }\n            switch arm {\n            case .commons:\n                let made = rewrite(question)\n                return try QuestionPath.prepare(question: question, rewrite: made, stem: made.stem, nodes: nodes, tokenizer: tokenizer, k: braid.config.index.k, floor: sizes.floor)\n            case .stem:\n                return try QuestionPath.prepare(question: question, rewrite: nil, stem: stem, nodes: nodes, tokenizer: tokenizer, k: braid.config.index.k, floor: sizes.floor)\n            case .paraphrase:\n                return try QuestionPath.prepare(question: question, rewrite: nil, stem: paraphrase ?? stem, nodes: nodes, tokenizer: tokenizer, k: braid.config.index.k,\n                                                floor: sizes.floor)\n            case .slice:\n                let tokens = slice ?? []\n                return QuestionTurn(question: question, rewrite: nil, stem: tokenizer.decode(tokens), tokens: tokens, subject: nil, contexts: [:])\n            }\n        }\n        func answer(_ turn: QuestionTurn, in braid: BenchBraid) throws -> Generation {\n            var params = GenerationParameters()\n            params.maxTokens = sizes.maxTokens\n            params.tau = Float(braid.config.index.tau)\n            params.k = braid.config.index.k\n            return try QuestionPath.answer(turn, cluster: braid.cluster, params: params)\n        }\n        func row(_ set: QuestionSet, _ arm: QuestionArm, label: String, owner: String?, question: String, storedStem: String?, turn: QuestionTurn,\n                 generation: Generation, expected: String?) -> QuestionRow {\n            var made = QuestionRow(set: set, arm: arm, label: label, owner: owner, question: question, storedStem: storedStem, stem: turn.stem, answer: generation.text)\n            if let rewrite = turn.rewrite {\n                made.rewriter = rewrite.rewriter\n                made.adapterSeconds = rewrite.seconds\n                if let storedStem {\n                    made.rewriteMatches = QuestionPath.normalised(rewrite.stem) == QuestionPath.normalised(storedStem)\n                    made.rewriteF1 = Float(QuestionPath.tokenF1(rewrite.stem, storedStem))\n                }\n            }\n            made.expected = expected\n            made.exact = expected.map { generation.text.hasPrefix($0) }\n            made.contexts = turn.contexts.keys.sorted()\n            made.ownerContext = owner.map { turn.contexts[$0] != nil }\n            return made\n        }\n\n        try braid.keepSession()\n        defer { braid.finishSession() }\n        var rows: [QuestionRow] = []\n        let commonsName = braid.commonsIndex.map { braid.names[$0] }\n        for arm in QuestionArm.allCases {\n            progress?(\"questions · \\(arm.rawValue): \\(questions.count)\")\n            for question in questions {\n                let asked = try turn(arm, question: question.text, stem: question.stem, slice: question.slice, paraphrase: question.paraphrase, in: braid)\n                let generation = try answer(asked, in: braid)\n                var made = row(.questions, arm, label: \"\\(question.thread) · \\(question.fact.subject) (\\(question.fact.kind))\", owner: question.thread,\n                               question: question.text, storedStem: question.stem, turn: asked, generation: generation, expected: question.fact.answer)\n                let length = max(1, tokenizer.encode(question.fact.answer).count)\n                let tokens = generation.generatedTokens.prefix(length)\n                let hits = tokens.map { token -> Bool in\n                    guard let top = token.annotation?.citations.first else { return false }\n                    return top.address.documentID == question.fact.documentID && top.address.partitionIndex == question.fact.partitionIndex\n                }\n                made.answerTokens = tokens.count\n                made.citedTokens = hits.filter { $0 }.count\n                made.cited = hits.contains(true)\n                rows.append(made)\n            }\n            braid.relax()\n        }\n        for arm in [QuestionArm.commons, .stem] {\n            progress?(\"negatives · \\(arm.rawValue): \\(negatives.count)\")\n            for negative in negatives {\n                let asked = try turn(arm, question: negative.question.text, stem: negative.question.stem, slice: nil, paraphrase: nil, in: braid)\n                let generation = try answer(asked, in: braid)\n                var made = row(.negatives, arm, label: \"nowhere · \\(negative.question.text)\", owner: nil, question: negative.question.text,\n                               storedStem: negative.question.stem, turn: asked, generation: generation, expected: nil)\n                made.commonsLeads = FirstTokenGate(generation, commons: braid.commonsIndex)?.commonsLeads\n                let content = generation.generatedTokens.filter { $0.credit?.role == .content }\n                if !content.isEmpty {\n                    made.threadsCredit = Stats.mean(content.map { token in token.names.filter { $0 != commonsName }.reduce(Float(0)) { $0 + token.credit(of: $1) } })\n                }\n                rows.append(made)\n            }\n            progress?(\"shared · \\(arm.rawValue): \\(shared.count)\")\n            for fact in shared {\n                let asked = try turn(arm, question: fact.text, stem: fact.stem, slice: nil, paraphrase: nil, in: braid)\n                let generation = try answer(asked, in: braid)\n                var made = row(.shared, arm, label: \"\\(fact.sides[1]) ≈ \\(fact.sides[0]) · \\(fact.subject) (\\(fact.kind.rawValue))\", owner: fact.sides[1],\n                               question: fact.text, storedStem: fact.stem, turn: asked, generation: generation, expected: fact.expected)\n                let content = generation.generatedTokens.filter { $0.credit?.role == .content }\n                let decision = generation.decisions.first\n                made.kind = fact.kind.rawValue\n                made.sides = fact.sides\n                made.followed = decision?.followed\n                made.tied = decision?.tied\n                made.contentTokens = content.count\n                made.sideCredit = fact.sides.map { side in content.reduce(Float(0)) { $0 + $1.credit(of: side) } }\n                if let followed = decision?.followed, fact.sides.contains(followed), let other = fact.sides.first(where: { $0 != followed }), !content.isEmpty {\n                    made.otherCredit = Stats.mean(content.map { $0.credit(of: other) })\n                }\n                rows.append(made)\n            }\n            braid.relax()\n            if let copies, let copyPair {\n                if arm == .commons { try copies.keepSession() }\n                progress?(\"copied · \\(arm.rawValue): \\(copied.count)\")\n                for question in copied {\n                    let asked = try turn(arm, question: question.text, stem: question.stem, slice: nil, paraphrase: nil, in: copies)\n                    let generation = try answer(asked, in: copies)\n                    var made = row(.copied, arm, label: \"\\(copyPair.joined(separator: \" = \")) · \\(question.fact.subject) (\\(question.fact.kind))\", owner: copyPair[0],\n                                   question: question.text, storedStem: question.stem, turn: asked, generation: generation, expected: question.fact.answer)\n                    made.holders = copyPair\n                    made.holderCredit = CopyTie.credits(generation, holders: copyPair)\n                    made.followed = generation.decisions.first?.followed\n                    made.tied = generation.decisions.first?.tied\n                    rows.append(made)\n                }\n                copies.relax()\n            }\n        }\n        copies?.finishSession()\n        let verdict = evaluate(rows: rows)\n        return QuestionReport(createdAt: BenchFormat.wholeSecond(), dataset: world.name, threads: braid.threadRecords.merging(copies?.threadRecords ?? [:]) { a, _ in a },\n                              gate: braid.settings.gate, copyPair: copyPair, sizes: sizes, rows: rows, rules: verdict.rules, reported: verdict.reported,\n                              summary: verdict.summary, sessions: (braid.sessions + (copies?.sessions ?? [])).map(\\.path))\n    }\n\n    /// One agreeing fact per non-homonym link whose two documents its Threads hold: the target fact's\n    /// first question (else the source's), its answer, and the two sides.\n    static func sharedFacts(world: BenchWorld, threads: [BenchThread], perLink: Int) -> [Shared] {\n        var byNode: [String: BenchThread] = [:]\n        for thread in threads where byNode[thread.node] == nil { byNode[thread.node] = thread }\n        var shared: [Shared] = []\n        for link in world.crosslinks where link.kind != .homonym {\n            guard let origin = byNode[link.source.node], let teller = byNode[link.target.node], origin.name != teller.name,\n                  origin.present.contains(link.source.documentID), teller.present.contains(link.target.documentID),\n                  let source = world.document(id: link.source.documentID), let target = world.document(id: link.target.documentID) else { continue }\n            var count = 0\n            for pair in link.facts where pair.agrees && count < perLink {\n                guard let sourceFact = source.facts.first(where: { $0.id == pair.sourceFact }), let targetFact = target.facts.first(where: { $0.id == pair.targetFact }),\n                      let question = targetFact.questions?.first ?? sourceFact.questions?.first else { continue }\n                shared.append(Shared(text: question.text, stem: question.stem, expected: targetFact.answer, kind: link.kind, sides: [origin.name, teller.name],\n                                     subject: link.subject))\n                count += 1\n            }\n        }\n        return shared\n    }\n\n    public static func rescore(_ report: QuestionReport) -> QuestionReport {\n        var rescored = report\n        let verdict = evaluate(rows: report.rows)\n        rescored.rules = verdict.rules\n        rescored.reported = verdict.reported\n        rescored.summary = verdict.summary\n        return rescored\n    }\n\n    /// Of the decided shared rows (answered exactly, one side followed): those whose followed side\n    /// earned strictly the most, and the other side's mean credit.\n    static func followedReading(_ rows: [QuestionRow]) -> (asked: Int, decided: Int, followedMost: Int, otherCredit: Double?, ties: Int) {\n        var decided = 0\n        var most = 0\n        var other: [Double] = []\n        var ties = 0\n        for row in rows {\n            if (row.tied?.count ?? 0) >= 2 { ties += 1 }\n            guard row.exact == true, let followed = row.followed, let sides = row.sides, sides.contains(followed), let credit = row.sideCredit, credit.count == sides.count\n            else { continue }\n            decided += 1\n            if let f = sides.firstIndex(of: followed), credit.indices.allSatisfy({ $0 == f || credit[$0] < credit[f] }) { most += 1 }\n            if let value = row.otherCredit { other.append(Double(value)) }\n        }\n        return (rows.count, decided, most, other.isEmpty ? nil : Stats.mean(other), ties)\n    }\n\n    // MARK: - The rules (pure)\n\n    /// Read on the commons arm. Q1: the rewrite, normalised, is the stored stem on ≥ 0.50 of questions.\n    /// Q2: its exact answers ≥ the stem arm's − 0.05. Q2′: ≥ the slice arm's − 0.10 (the slice is the\n    /// ceiling; expected to fail). Q3: ≥ 0.90 of its exact answers cite the fact's partition (some\n    /// answer token's top citation). Q5a: on agreeing paraphrase and summary retellings, one shared\n    /// fact each, retrieval decides (the sentence followed one side, answered exactly) on ≥ 0.60 of\n    /// those asked; where it did, the followed side is the most credited on ≥ 0.90 and the other side's\n    /// mean credit ≤ 0.10. Q5b (a copy braid only): the copies tie within 0.10 on ≥ 0.90 of the exactly\n    /// answered copied questions, none taken whole.\n    public static func evaluate(rows: [QuestionRow]) -> BenchVerdict {\n        let share = BenchFormat.share\n        func pct(_ value: Double) -> String { BenchFormat.pct(value) }\n        func num(_ value: Double?) -> String { BenchFormat.num(value) }\n        func of(_ set: QuestionSet, _ arm: QuestionArm) -> [QuestionRow] { rows.filter { $0.set == set && $0.arm == arm } }\n        func exact(_ rows: [QuestionRow]) -> Double { share(rows.map { $0.exact == true }) }\n        var rules: [BenchRule] = []\n        var reported: [String: Float] = [:]\n\n        let commons = of(.questions, .commons)\n        let stem = of(.questions, .stem)\n        let slice = of(.questions, .slice)\n        let matches = share(commons.map { $0.rewriteMatches == true })\n        let f1 = Stats.mean(commons.compactMap { $0.rewriteF1.map(Double.init) })\n        let fallbacks = commons.filter { $0.rewriter == \"none\" }.count\n        rules.append(BenchRule(\n            id: \"Q1 rewrite fidelity\", passes: !commons.isEmpty && matches >= 0.5,\n            detail: \"the commons' stem is the stored stem on \\(pct(matches)) of \\(commons.count) (needs 50%); token F1 \\(num(f1)); \\(fallbacks) fell back to the question\"))\n        rules.append(BenchRule(\n            id: \"Q2 exact\", passes: !commons.isEmpty && !stem.isEmpty && exact(commons) >= exact(stem) - 0.05 - 1e-9,\n            detail: \"commons \\(pct(exact(commons))) exact against the stored stem's \\(pct(exact(stem))) (needs within 0.05)\"))\n        rules.append(BenchRule(\n            id: \"Q2′ context\", passes: !commons.isEmpty && !slice.isEmpty && exact(commons) >= exact(slice) - 0.10 - 1e-9,\n            detail: \"commons \\(pct(exact(commons))) exact against the slice's \\(pct(exact(slice))), the ceiling (needs within 0.10; expected to fail)\"))\n        let answered = commons.filter { $0.exact == true }\n        let cited = share(answered.map { $0.cited == true })\n        rules.append(BenchRule(\n            id: \"Q3 cited\", passes: !answered.isEmpty && cited >= 0.9,\n            detail: \"\\(answered.filter { $0.cited == true }.count) of \\(answered.count) exact answers cite the fact's partition (\\(pct(cited)), needs 90%)\"))\n\n        let retoldRows = of(.shared, .commons).filter { Self.retold.contains($0.kind ?? \"\") }\n        let q5a = followedReading(retoldRows)\n        let decidedRate = q5a.asked > 0 ? Double(q5a.decided) / Double(q5a.asked) : 0\n        let followedRate = q5a.decided > 0 ? Double(q5a.followedMost) / Double(q5a.decided) : 0\n        rules.append(BenchRule(\n            id: \"Q5a retold\", passes: q5a.asked > 0 && decidedRate >= 0.6 && followedRate >= 0.9 && (q5a.otherCredit ?? 1) <= 0.10,\n            detail: \"\\(q5a.decided) of \\(q5a.asked) paraphrase and summary facts decided by retrieval (\\(pct(decidedRate)), needs 60%); the followed Thread most \"\n                + \"credited on \\(q5a.followedMost) (\\(pct(followedRate)), needs 90%); the other side's credit \\(num(q5a.otherCredit)) (needs ≤ 0.10); ties \\(q5a.ties)\"))\n\n        let copied = of(.copied, .commons)\n        if copied.isEmpty {\n            rules.append(BenchRule(id: \"Q5b copied\", passes: false, detail: \"skipped: no copy braid\", skipped: true))\n        } else {\n            let exactCopies = copied.filter { $0.exact == true }\n            let tied = exactCopies.filter { CopyTie.tied($0.holderCredit ?? []) }.count\n            let taken = exactCopies.filter { CopyTie.takenWhole($0.holderCredit ?? []) }.count\n            let rate = exactCopies.isEmpty ? 0 : Double(tied) / Double(exactCopies.count)\n            rules.append(BenchRule(\n                id: \"Q5b copied\", passes: !exactCopies.isEmpty && rate >= 0.9 && taken == 0,\n                detail: \"\\(tied) of \\(exactCopies.count) exactly answered copied questions tie between the copies (\\(pct(rate)), needs 90%); \\(taken) taken whole (needs 0); \"\n                    + \"\\(copied.count - exactCopies.count) of \\(copied.count) not answered exactly\"))\n        }\n\n        // Reported, no threshold.\n        for arm in QuestionArm.allCases {\n            let mine = of(.questions, arm)\n            guard !mine.isEmpty else { continue }\n            reported[\"\\(arm.rawValue): exact\"] = Float(exact(mine))\n            let tokens = mine.reduce(0) { $0 + ($1.answerTokens ?? 0) }\n            if tokens > 0 { reported[\"\\(arm.rawValue): citation@1 per answer token\"] = Float(Double(mine.reduce(0) { $0 + ($1.citedTokens ?? 0) }) / Double(tokens)) }\n            if arm != .slice {\n                let found = mine.filter { $0.ownerContext == true }\n                reported[\"\\(arm.rawValue): the owner found a context\"] = Float(share(mine.map { $0.ownerContext == true }))\n                reported[\"\\(arm.rawValue): exact with the owner's context\"] = Float(exact(found))\n                reported[\"\\(arm.rawValue): exact without it\"] = Float(exact(mine.filter { $0.ownerContext != true }))\n            }\n        }\n        let latencies = commons.compactMap(\\.adapterSeconds)\n        if !latencies.isEmpty { reported[\"commons: adapter ms (mean)\"] = Float(Stats.mean(latencies) * 1000) }\n        reported[\"commons: rewrite token F1 (mean)\"] = Float(f1)\n        for arm in [QuestionArm.commons, .stem] {\n            let negatives = of(.negatives, arm)\n            guard !negatives.isEmpty else { continue }\n            reported[\"Q4 (reported) \\(arm.rawValue): the commons leads on negatives\"] = Float(share(negatives.map { $0.commonsLeads == true }))\n            reported[\"Q4 (reported) \\(arm.rawValue): Threads' credit per content token on negatives\"] = Float(Stats.mean(negatives.compactMap { $0.threadsCredit.map(Double.init) }))\n        }\n        let stemRetold = followedReading(of(.shared, .stem).filter { Self.retold.contains($0.kind ?? \"\") })\n        reported[\"Q5a (stem arm): decided\"] = stemRetold.asked > 0 ? Float(Double(stemRetold.decided) / Double(stemRetold.asked)) : 0\n        reported[\"Q5a (stem arm): followed most credited\"] = stemRetold.decided > 0 ? Float(Double(stemRetold.followedMost) / Double(stemRetold.decided)) : 0\n        if let other = stemRetold.otherCredit { reported[\"Q5a (stem arm): the other side's credit\"] = Float(other) }\n        let stemCopies = of(.copied, .stem)\n        if !stemCopies.isEmpty {\n            let exactCopies = stemCopies.filter { $0.exact == true }\n            reported[\"Q5b (stem arm): copied questions answered exactly\"] = Float(exactCopies.count)\n            reported[\"Q5b (stem arm): of those, the copies tie\"] = exactCopies.isEmpty ? 0 : Float(exactCopies.filter { CopyTie.tied($0.holderCredit ?? []) }.count) / Float(exactCopies.count)\n            reported[\"Q5b (stem arm): taken whole\"] = Float(exactCopies.filter { CopyTie.takenWhole($0.holderCredit ?? []) }.count)\n        }\n        reported[\"Q5a (commons arm): shared facts answered exactly\"] = Float(of(.shared, .commons).filter { $0.exact == true }.count)\n        for kind in [CrossKind.excerpt, .variant] {\n            let mine = of(.shared, .commons).filter { $0.kind == kind.rawValue }\n            guard !mine.isEmpty else { continue }\n            let reading = followedReading(mine)\n            reported[\"Q5c (reported) \\(kind.rawValue): asked\"] = Float(reading.asked)\n            reported[\"Q5c (reported) \\(kind.rawValue): decided\"] = Float(reading.decided) / Float(reading.asked)\n            reported[\"Q5c (reported) \\(kind.rawValue): ties\"] = Float(reading.ties)\n        }\n\n        let failed = rules.filter { !$0.passes && !$0.skipped }.map(\\.id)\n        var summary = failed.isEmpty ? \"every rule holds on the commons arm\" : \"commons arm fails \" + failed.joined(separator: \", \")\n        if rules.contains(where: { $0.skipped }) { summary += \"; Q5b skipped (no copy braid)\" }\n        return BenchVerdict(rules: rules, reported: reported, summary: summary)\n    }\n}\n"},{"path":"Sources/BraidKit/Tools/Bench/RaoLMPhaseA.swift","lines":348,"bytes":19029,"header":{"lines":[1,21],"what":[8,16],"pin":[17,20],"in":null,"out":null},"marks":[[113,"Readings"],[175,"The regate"],[236,"The whole of phase A"]],"first":1569,"scopes":[["E","RaoLMPhaseA",null,"public",26,26,[26,24],348,null,-1,0,[]],["S","ReadingAgreement",null,"public",32,32,[32,65],41,[31,31],0,0],["i","init",[],"public",40,40,[40,22],40,null,1,8],["S","Verdict",null,"public",43,43,[43,56],51,null,0,0],["v","agrees",null,"public",50,50,[50,32],50,null,3,8],["S","ArmRow",null,"public",54,54,[54,55],61,[53,53],0,0],["S","ArmChains",null,"public",66,66,[66,58],71,[63,65],0,0],["S","Regate",null,"public",74,74,[74,55],93,[73,73],0,0],["i","init",[],"public",92,92,[92,22],92,null,7,8],["S","Report",null,"public",95,95,[95,44],111,null,0,0],["f","traceValues",["_","rule","from","braidWindow"],"static",117,117,[117,105],123,[115,116],0,0],["f","result",["_","scored","rule","from","braidWindow","live","shadow","answerTokens"],"public static",126,126,[127,133],142,[125,125],0,0],["f","agreement",["_","report"],"static",144,144,[144,108],166,null,0,0],["f","verdicts",["_","report"],"static",168,168,[168,95],173,null,0,0],["S","TextRegate",null,"",179,179,[179,22],186,[177,178],0,0],["f","regate",["_","scored","rule","settings","lambda"],"static",188,188,[188,148],234,null,0,0],["f","run",["index","base","arms","report","rule","lambda","settings"],"public static",239,239,[240,143],347,[238,238],0,0]],"text":"//\n//  RaoLMPhaseA.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `bench trace` phase A: the trace bench's rules applied to RaoLM's own scorings. Each text's\n//        readings come from the dump's per-strand traces (RaoLM's trajectories; the chain after the\n//        text's last token, which the dump does not hold, from Braid's tracker over the record's\n//        hits), and TraceBench.evaluate's T1–T3 verdicts must equal RaoLM's for the same run. Then\n//        RaoLM's logs are regated under Braid's live gate — memory plus lift over the commons,\n//        Gate.observe at every prompt position with each strand's own probability of the token, the\n//        commons RaoLM's commons strand — and the holder's share of the told and source answer\n//        tokens must reproduce RaoLM's \"no agreement\" arm (1.000) within ±0.005. RaoLM's arms are\n//        recomputed from their records beside the numbers RaoLM reported.\n//  PIN:  Pure: no model, no GPU. Readings use RaoLM's window (the chain after each token from 24 to\n//        the last), so they can equal RaoLM's report; Braid's own window (the state that expected\n//        each token from 24, which is what the dump logs) is reported beside it. 0.938 is quoted\n//        from an older braid's report and never compared.\n//\n\nimport BraidCore\nimport Foundation\n\npublic enum RaoLMPhaseA {\n    /// The plan's rule on the regate.\n    public static let regateTolerance: Float = 0.005\n    public static let quoted = \"0.938: RaoLM's both β4 holder share in /Volumes/T9/rao/projects/raolm/db/braid/bench/trajectory.json (2026-09-30, a different braid: ambient v2, craft v2, veil v1); quoted, never compared\"\n\n    /// Braid's readings of a text against RaoLM's report.\n    public struct ReadingAgreement: Codable, Sendable, Equatable {\n        public var readings = 0\n        public var traceEqual = 0\n        public var maxTraceDifference: Float = 0\n        public var longestEqual = 0\n        public var wireLongestEqual = 0\n        public var unmatched: [String] = []\n\n        public init() {}\n    }\n\n    public struct Verdict: Codable, Sendable, Equatable {\n        public var rule: String\n        public var braid: Bool\n        public var raolm: Bool?\n        public var braidDetail: String\n        public var raolmDetail: String?\n\n        public var agrees: Bool { raolm == braid }\n    }\n\n    /// One of RaoLM's gate arms: what RaoLM reported and what its records give.\n    public struct ArmRow: Codable, Sendable, Equatable {\n        public var arm: String\n        public var reported: Float?\n        public var recomputed: Float?\n        public var answerTokens: Int\n        public var notAskedReported: Float?\n        public var notAskedRecomputed: Float?\n    }\n\n    /// An arm's logged chains against the base pass's for the same texts: the trajectory is the\n    /// node's and does not depend on the gate, so they must be equal (the replay of the base pass then\n    /// covers the arms too, whose records lack far more hits).\n    public struct ArmChains: Codable, Sendable, Equatable {\n        public var arm: String\n        public var records = 0\n        public var positions = 0\n        public var equal = 0\n    }\n\n    /// RaoLM's base pass regated under Braid's live gate.\n    public struct Regate: Codable, Sendable, Equatable {\n        public var texts = 0\n        public var positions = 0\n        public var answerTokens = 0\n        /// The holder's share of the answer tokens: live (memory), and under the shadow β4.\n        public var live: Float?\n        public var shadow: Float?\n        /// RaoLM's \"no agreement\" arm as reported, and the plan's ±0.005 about it.\n        public var reference: Float?\n        public var passes = false\n        /// Braid's Gate.observe against RaoLM's logged memory at every position of every text of the\n        /// base pass, and the live shares against the \"no agreement\" arm's logged shares.\n        public var memoryTexts = 0\n        public var memoryPositions = 0\n        public var maxMemoryDifference = 0.0\n        public var maxShareDifference: Double?\n        public var comparedShares = 0\n\n        public init() {}\n    }\n\n    public struct Report: Codable, Sendable {\n        public var rule: TraceRule\n        public var from: Int\n        public var verdicts: [Verdict]\n        public var readings: ReadingAgreement\n        /// Braid's window: the state that expected each token from 24 (the positions the dump logs).\n        public var braidWindowVerdicts: [Verdict]\n        public var arms: [ArmRow]\n        public var armChains: [ArmChains]\n        public var regate: Regate\n        /// TraceBench.arms over the regated readings (live gate and shadow β4).\n        public var braidArms: [TraceArmReading]\n        public var reported: [String: Float]\n        public var raolmSummary: String?\n        public var quoted: String\n        public var passes: Bool\n    }\n\n    // MARK: - Readings\n\n    /// The chain lengths of one strand, one per step, in RaoLM's window (after token j) or Braid's\n    /// (expecting token p: the state after token p − 1).\n    static func traceValues(_ lengths: [Int], rule: TraceRule, from: Int, braidWindow: Bool) -> [Double] {\n        if braidWindow {\n            // Step p's state expects token p: the chain after token p − 1, for p from `from` to n − 1.\n            return lengths.indices.compactMap { j in j + 1 >= from && j + 1 < lengths.count ? Double(rule.trace(length: lengths[j])) : nil }\n        }\n        return lengths.indices.compactMap { j in j >= from ? Double(rule.trace(length: lengths[j])) : nil }\n    }\n\n    /// A text's readings, Braid's TraceTextResult, from a scored text and the regate's holder shares.\n    public static func result(_ text: RaoLMDumpText, scored: RaoLMCheck.ScoredText, rule: TraceRule, from: Int = TraceBench.from, braidWindow: Bool = false,\n                              live: [String: Float] = [:], shadow: [String: Float] = [:], answerTokens: Int = 0) -> TraceTextResult? {\n        guard let kind = BenchTextKind(rawValue: text.kind) else { return nil }\n        var readings: [TraceReading] = []\n        for (t, name) in scored.strands.enumerated() where t != scored.commons {\n            guard let lengths = scored.lengths[t] else { continue }\n            let values = traceValues(lengths, rule: rule, from: from, braidWindow: braidWindow)\n            let later = scored.traceIndex.indices.filter { scored.traceIndex[$0] >= from }\n            let best = later.compactMap { scored.best[t][$0] }.map(Double.init)\n            readings.append(TraceReading(\n                thread: name, trace: Float(Stats.mean(values)), longest: lengths.max() ?? 0, partitionRun: scored.partitionRuns[t],\n                wireLongest: scored.wireLongest[t], meanPknn: Float(Stats.mean(later.map { Double(scored.pknn[t][$0]) })), meanBest: Float(Stats.mean(best)),\n                holderShare: live[name], shadowHolderShare: shadow[name]))\n        }\n        return TraceTextResult(kind: kind, label: text.label, owner: text.owner, near: text.near, tokens: scored.tokens.count, answerTokens: answerTokens,\n                               readings: readings)\n    }\n\n    static func agreement(_ results: [TraceTextResult], report: RaoLMTrajectoryReport?) -> ReadingAgreement {\n        var agreement = ReadingAgreement()\n        guard let report else { return agreement }\n        var byLabel: [String: [RaoLMTrajectoryReport.Text]] = [:]\n        for text in report.texts { byLabel[text.kind + \"|\" + text.label, default: []].append(text) }\n        var used: [String: Int] = [:]\n        for result in results {\n            let key = result.kind.rawValue + \"|\" + result.label\n            let n = used[key, default: 0]\n            used[key] = n + 1\n            guard let texts = byLabel[key], n < texts.count else { agreement.unmatched.append(result.label); continue }\n            let theirs = texts[n]\n            for reading in result.readings {\n                guard let other = theirs.readings.first(where: { $0.strand == reading.thread }) else { continue }\n                agreement.readings += 1\n                if reading.trace == other.trace { agreement.traceEqual += 1 }\n                agreement.maxTraceDifference = max(agreement.maxTraceDifference, abs(reading.trace - other.trace))\n                if reading.longest == other.longest { agreement.longestEqual += 1 }\n                if reading.wireLongest == other.wireLongest { agreement.wireLongestEqual += 1 }\n            }\n        }\n        return agreement\n    }\n\n    static func verdicts(_ verdict: BenchVerdict, report: RaoLMTrajectoryReport?) -> [Verdict] {\n        verdict.rules.map { rule in\n            let theirs = report?.evaluation.rules.first { $0.rule == rule.id }\n            return Verdict(rule: rule.id, braid: rule.passes, raolm: theirs?.passed, braidDetail: rule.detail, raolmDetail: theirs?.detail)\n        }\n    }\n\n    // MARK: - The regate\n\n    /// One told or source text regated: per strand its mean live and shadow share of the answer\n    /// tokens, and the positions and differences against RaoLM's records.\n    struct TextRegate {\n        var live: [String: Float] = [:]\n        var shadow: [String: Float] = [:]\n        var answerTokens = 0\n        var positions = 0\n        var liveShares: [[Double]] = []\n        var maxMemoryDifference = 0.0\n    }\n\n    static func regate(_ text: RaoLMDumpText, scored: RaoLMCheck.ScoredText, rule: TraceRule, settings: GateSettings, lambda: Double) -> TextRegate {\n        var out = TextRegate()\n        let n = scored.strands.count\n        guard n > 0 else { return out }\n        let answers = Set(text.answerPositions)\n        var state = GateState(strands: n, commons: scored.commons, prior: settings.commonsPrior)\n        let open = [Bool](repeating: true, count: n)\n        var live = [Double](repeating: 0, count: n), shadow = [Double](repeating: 0, count: n)\n        for (i, k) in scored.traceIndex.enumerated() {\n            let memory = state.memory\n            for t in 0..<n where t < scored.memory[i].count { out.maxMemoryDifference = max(out.maxMemoryDifference, abs(memory[t] - Double(scored.memory[i][t]))) }\n            // Each strand's own probability of the token; a strand not asked is charged what its retrieval alone gives it.\n            let likelihoods = (0..<n).map { t -> Double in\n                if let p = scored.alone[i][t] { return Double(p) }\n                return t == scored.commons ? 0 : lambda * Double(scored.pknn[t][i])\n            }\n            let weights = Gate.renormalised(memory, open: open)\n            let p = (0..<n).reduce(0.0) { $0 + weights[$1] * likelihoods[$1] }\n            let shares = (0..<n).map { p > 0 ? weights[$0] * likelihoods[$0] / p : weights[$0] }\n            var memoryState = GateState(strands: n, commons: scored.commons, prior: settings.commonsPrior)\n            memoryState.memory = memory\n            let traces = (0..<n).map { t -> Double in\n                guard let lengths = scored.lengths[t], k >= 1, k - 1 < lengths.count else { return 0 }\n                return Double(rule.trace(length: lengths[k - 1]))\n            }\n            let shadowWeights = Gate.renormalised(Gate.shadowWeights(memoryState, traces: traces, beta: settings.shadowBeta), open: open)\n            let shadowP = (0..<n).reduce(0.0) { $0 + shadowWeights[$1] * likelihoods[$1] }\n            let shadowShares = (0..<n).map { shadowP > 0 ? shadowWeights[$0] * likelihoods[$0] / shadowP : shadowWeights[$0] }\n            out.liveShares.append(shares)\n            out.positions += 1\n            if answers.contains(k) {\n                out.answerTokens += 1\n                for t in 0..<n {\n                    live[t] += shares[t]\n                    shadow[t] += shadowShares[t]\n                }\n            }\n            Gate.observe(&state, likelihoods: likelihoods, module: nil, settings: settings)\n        }\n        if out.answerTokens > 0 {\n            for (t, name) in scored.strands.enumerated() {\n                out.live[name] = Float(live[t] / Double(out.answerTokens))\n                out.shadow[name] = Float(shadow[t] / Double(out.answerTokens))\n            }\n        }\n        return out\n    }\n\n    // MARK: - The whole of phase A\n\n    /// `base`: the base pass's scored texts by file; `arms`: each arm's by file.\n    public static func run(index: RaoLMDumpIndex, base: [String: RaoLMCheck.ScoredText], arms: [String: [String: RaoLMCheck.ScoredText]],\n                           report: RaoLMTrajectoryReport?, rule: TraceRule, lambda: Double, settings: GateSettings = GateSettings()) -> Report {\n        let from = TraceBench.from\n        // Regate every text of the base pass (its memory against RaoLM's), and score the told and source\n        // texts with answers, the texts RaoLM's arms scored.\n        var regate = Regate()\n        var regates: [String: TextRegate] = [:]\n        var live = 0.0, shadow = 0.0\n        let noAgreement = arms[\"no agreement\"]\n        for text in index.texts {\n            guard let scored = base[text.file] else { continue }\n            let one = Self.regate(text, scored: scored, rule: rule, settings: settings, lambda: lambda)\n            regate.memoryTexts += 1\n            regate.memoryPositions += one.positions\n            regate.maxMemoryDifference = max(regate.maxMemoryDifference, one.maxMemoryDifference)\n            guard (text.kind == \"told\" || text.kind == \"source\") && !text.answers.isEmpty, let owner = text.owner else { continue }\n            regates[text.file] = one\n            regate.texts += 1\n            regate.positions += one.positions\n            regate.answerTokens += one.answerTokens\n            live += Double(one.live[owner] ?? 0) * Double(one.answerTokens)\n            shadow += Double(one.shadow[owner] ?? 0) * Double(one.answerTokens)\n            if let theirs = noAgreement?[text.file] {\n                var worst = regate.maxShareDifference ?? 0\n                for (i, shares) in one.liveShares.enumerated() where i < theirs.share.count {\n                    for t in shares.indices where t < theirs.share[i].count {\n                        worst = max(worst, abs(shares[t] - Double(theirs.share[i][t])))\n                        regate.comparedShares += 1\n                    }\n                }\n                regate.maxShareDifference = worst\n            }\n        }\n        if regate.answerTokens > 0 {\n            regate.live = Float(live / Double(regate.answerTokens))\n            regate.shadow = Float(shadow / Double(regate.answerTokens))\n        }\n        regate.reference = report?.arms.first { $0.arm == \"no agreement\" }?.holderShare\n        if let value = regate.live, let reference = regate.reference { regate.passes = abs(value - reference) <= regateTolerance }\n\n        // The readings, in RaoLM's window and in Braid's.\n        var results: [TraceTextResult] = []\n        var braidWindow: [TraceTextResult] = []\n        for text in index.texts {\n            guard let scored = base[text.file] else { continue }\n            let one = regates[text.file]\n            if let result = result(text, scored: scored, rule: rule, from: from, live: one?.live ?? [:], shadow: one?.shadow ?? [:],\n                                   answerTokens: one?.answerTokens ?? 0) { results.append(result) }\n            if let result = result(text, scored: scored, rule: rule, from: from, braidWindow: true) { braidWindow.append(result) }\n        }\n        let verdict = TraceBench.evaluate(texts: results)\n        let verdicts = verdicts(verdict, report: report)\n        let braidVerdicts = Self.verdicts(TraceBench.evaluate(texts: braidWindow), report: report)\n\n        // RaoLM's arms: as reported, and from their records.\n        var rows: [ArmRow] = []\n        let names = (report?.arms.map(\\.arm) ?? []) + arms.keys.sorted().filter { name in !(report?.arms.contains { $0.arm == name } ?? false) }\n        for name in names {\n            let theirs = report?.arms.first { $0.arm == name }\n            var row = ArmRow(arm: name, reported: theirs?.holderShare, recomputed: nil, answerTokens: 0, notAskedReported: theirs?.notAsked, notAskedRecomputed: nil)\n            if let records = arms[name] {\n                // RaoLM's own loop, in its order and in Float: answer by answer, position by position from 1.\n                var sum: Float = 0\n                var tokens = 0\n                var asked = 0, scoredThreads = 0\n                for text in index.texts where (text.kind == \"told\" || text.kind == \"source\") && !text.answers.isEmpty {\n                    guard let scored = records[text.file], let owner = text.owner, let t = scored.strands.firstIndex(of: owner) else { continue }\n                    let byIndex = Dictionary(scored.traceIndex.enumerated().map { ($1, $0) }, uniquingKeysWith: { first, _ in first })\n                    for answer in text.answers {\n                        for position in answer.start..<(answer.start + answer.count) where position >= 1 {\n                            guard let i = byIndex[position], t < scored.share[i].count else { continue }\n                            sum += scored.share[i][t]\n                            tokens += 1\n                        }\n                    }\n                    if let last = scored.open.last {\n                        asked += last.filter { $0 }.count\n                        scoredThreads += last.count\n                    }\n                }\n                row.recomputed = tokens > 0 ? sum / Float(tokens) : nil\n                row.answerTokens = tokens\n                row.notAskedRecomputed = scoredThreads > 0 ? 1 - Float(asked) / Float(scoredThreads) : nil\n            }\n            rows.append(row)\n        }\n        var chains: [ArmChains] = []\n        for (name, records) in arms.sorted(by: { $0.key < $1.key }) {\n            var row = ArmChains(arm: name)\n            for (file, scored) in records {\n                guard let own = base[file] else { continue }\n                row.records += 1\n                for t in scored.strands.indices where t < own.lengths.count {\n                    guard let mine = scored.lengths[t], let theirs = own.lengths[t] else { continue }\n                    // The last step is Braid's replay, not a logged chain.\n                    for j in 0..<(min(mine.count, theirs.count) - 1) {\n                        row.positions += 1\n                        if mine[j] == theirs[j] { row.equal += 1 }\n                    }\n                }\n            }\n            chains.append(row)\n        }\n        let readings = agreement(results, report: report)\n        let passes = !verdicts.isEmpty && verdicts.allSatisfy(\\.agrees) && regate.passes\n        return Report(rule: rule, from: from, verdicts: verdicts, readings: readings, braidWindowVerdicts: braidVerdicts, arms: rows, armChains: chains, regate: regate,\n                      braidArms: TraceBench.arms(texts: results), reported: verdict.reported, raolmSummary: report?.evaluation.summary, quoted: quoted,\n                      passes: passes)\n    }\n}\n"},{"path":"Sources/BraidKit/Tools/Bench/ReplacementBench.swift","lines":161,"bytes":10189,"header":{"lines":[1,17],"what":[8,14],"pin":[15,16],"in":null,"out":null},"marks":[[82,"The rule (pure)"]],"first":1586,"scopes":[["S","SessionVerification",null,"public",23,23,[23,64],51,[22,22],-1,0],["i","init",["session","verified","status","generations","issues"],"public",32,32,[32,108],38,null,0,0],["f","reportURL",["session"],"public static",41,41,[41,54],41,[40,40],0,8],["f","read",["session"],"public static",43,43,[43,65],50,null,0,0],["S","ReplacementReport",null,"public",53,53,[53,51],64,null,-1,0],["E","ReplacementBench",null,"public",66,66,[66,29],161,null,-1,0,[]],["f","run",["traceA","traceB","gamingA","gamingB","inputs"],"public static",69,69,[69,162],74,null,5,0],["f","guardReading",["_","_"],"static",77,77,[77,120],80,[76,76],5,0],["f","evaluate",["traceA","traceB","gamingA","gamingB","sessions"],"public static",84,84,[84,169],160,null,5,0],["f","num",["_","_"],"",85,85,[85,64],85,null,8,12]],"text":"//\n//  ReplacementBench.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid bench replacement`: the owner's replacement criterion, read from saved reports.\n//        Sessions A ran the live gate memory-only (κ 0) with the shadow β4 logged beside the module's\n//        e_t; sessions B ran κ > 0 (0.5) on the same prompts, braid and pack. R1: on the trace bench's\n//        told and source answer tokens, the holder's share in B ≥ the holder's share under the shadow\n//        β4 logged in A. R2: G1–G3 pass in B, with the largest gate within 0.05 and the all-asked rate\n//        within 5 points of A's. R3: `braid verify`'s memory-recursion replay passes on every B session\n//        (the logs carry `mod`, so the replay re-enters the module's evidence: the clamp held).\n//  PIN:  Fixed before any numbers (the plan, \"Replacement criterion\"). It reads; it decides nothing\n//        and deletes nothing. When R1–R3 hold the owner's rule is applied on main.\n//\n\nimport BraidCore\nimport Foundation\n\n/// What `braid verify` found on one session (read from `<session>.verify.json`).\npublic struct SessionVerification: Codable, Sendable, Equatable {\n    public var session: String\n    /// Whether the verify report was there.\n    public var verified: Bool\n    public var status: String?\n    public var generations: Int?\n    /// Issues by check (memory, shares, weights, p, Hknn, shadow, trace, body, …).\n    public var issues: [String: Int]\n\n    public init(session: String, verified: Bool, status: String?, generations: Int?, issues: [String: Int]) {\n        self.session = session\n        self.verified = verified\n        self.status = status\n        self.generations = generations\n        self.issues = issues\n    }\n\n    /// `X.jsonl` → `X.verify.json`, as `braid verify` writes it.\n    public static func reportURL(session: URL) -> URL { session.deletingPathExtension().appendingPathExtension(\"verify.json\") }\n\n    public static func read(session: URL) -> SessionVerification {\n        guard let report = try? JSONCoding.read(VerifyReport.self, from: reportURL(session: session)) else {\n            return SessionVerification(session: session.path, verified: false, status: nil, generations: nil, issues: [:])\n        }\n        var issues: [String: Int] = [:]\n        for issue in report.issues { issues[issue.check, default: 0] += 1 }\n        return SessionVerification(session: session.path, verified: true, status: report.status.rawValue, generations: report.generations, issues: issues)\n    }\n}\n\npublic struct ReplacementReport: Codable, Sendable {\n    public var bench = \"replacement\"\n    public var createdAt: Date\n    /// The reports read: trace A and B, gaming A and B.\n    public var inputs: [String: String]\n    public var moduleGainA: Double?\n    public var moduleGainB: Double?\n    public var sessions: [SessionVerification]\n    public var rules: [BenchRule]\n    public var reported: [String: Float]\n    public var summary: String\n}\n\npublic enum ReplacementBench {\n    public static let holderSet = \"holder · told+source\"\n\n    public static func run(traceA: TraceReport, traceB: TraceReport, gamingA: GamingReport, gamingB: GamingReport, inputs: [String: String]) -> ReplacementReport {\n        let sessions = ((traceB.sessions ?? []) + (gamingB.sessions ?? [])).map { SessionVerification.read(session: URL(fileURLWithPath: $0)) }\n        let verdict = evaluate(traceA: traceA, traceB: traceB, gamingA: gamingA, gamingB: gamingB, sessions: sessions)\n        return ReplacementReport(createdAt: BenchFormat.wholeSecond(), inputs: inputs, moduleGainA: traceA.gate?.moduleGain, moduleGainB: traceB.gate?.moduleGain,\n                                 sessions: sessions, rules: verdict.rules, reported: verdict.reported, summary: verdict.summary)\n    }\n\n    /// The share every Thread was open at the first generated token, and the mean largest Thread gate, of one gaming set.\n    static func guardReading(_ report: GamingReport, _ set: GamingSet) -> (open: Double, largest: Double, prompts: Int) {\n        let rows = report.rows.filter { $0.set == set }\n        return (BenchFormat.share(rows.map(\\.allOpen)), Stats.mean(rows.map { Double($0.largestGate) }), rows.count)\n    }\n\n    // MARK: - The rule (pure)\n\n    public static func evaluate(traceA: TraceReport, traceB: TraceReport, gamingA: GamingReport, gamingB: GamingReport, sessions: [SessionVerification]) -> BenchVerdict {\n        func num(_ value: Double?, _ digits: Int = 7) -> String { BenchFormat.num(value, digits) }\n        var rules: [BenchRule] = []\n        var reported: [String: Float] = [:]\n        // A is κ 0 and B is κ > 0 on the same braid and prompts.\n        var setup: [String] = []\n        let kappaA = traceA.gate?.moduleGain ?? -1\n        let kappaB = traceB.gate?.moduleGain ?? -1\n        if kappaA != 0 { setup.append(\"trace A ran κ \\(kappaA), not 0\") }\n        if kappaB <= 0 { setup.append(\"trace B ran κ \\(kappaB), not above 0\") }\n        if gamingA.gate.moduleGain != 0 { setup.append(\"gaming A ran κ \\(gamingA.gate.moduleGain), not 0\") }\n        if gamingB.gate.moduleGain <= 0 { setup.append(\"gaming B ran κ \\(gamingB.gate.moduleGain), not above 0\") }\n        if traceA.threads != traceB.threads || traceA.dataset != traceB.dataset { setup.append(\"trace A and B ran on different braids or datasets\") }\n        if gamingA.threads != gamingB.threads || gamingA.dataset != gamingB.dataset || gamingA.copyPair != gamingB.copyPair { setup.append(\"gaming A and B ran on different braids\") }\n        if traceA.texts.map(\\.label) != traceB.texts.map(\\.label) { setup.append(\"trace A and B scored different texts\") }\n        if gamingA.rows.map(\\.label) != gamingB.rows.map(\\.label) { setup.append(\"gaming A and B asked different prompts\") }\n        let consistent = setup.isEmpty\n\n        // R1.\n        let a = traceA.arms.first { $0.set == holderSet }\n        let b = traceB.arms.first { $0.set == holderSet }\n        let shadowA = a?.shadow.map(Double.init)\n        let liveB = b?.live.map(Double.init)\n        let r1 = consistent && shadowA != nil && liveB != nil && liveB! >= shadowA! && a?.answerTokens == b?.answerTokens\n        rules.append(BenchRule(\n            id: \"R1 the module amplifies as the shadow did\", passes: r1,\n            detail: \"the holder's share of \\(b?.answerTokens ?? 0) told and source answer tokens in B (κ \\(kappaB)) \\(num(liveB)) against the shadow β4's in A \\(num(shadowA)) \"\n                + \"(A's live \\(num(a?.live.map(Double.init))), B's shadow \\(num(b?.shadow.map(Double.init))))\" + (consistent ? \"\" : \"; \" + setup.joined(separator: \"; \"))))\n        if let shadowA, let liveB { reported[\"R1 B live − A shadow\"] = Float(liveB - shadowA) }\n\n        // R2.\n        let gamingRules = [\"G1 unknown subjects\", \"G2 generic text\", \"G3 copy braid\"]\n        var r2Failures: [String] = []\n        for id in gamingRules {\n            guard let rule = gamingB.rules.first(where: { $0.id == id }) else { r2Failures.append(\"\\(id) not in B\"); continue }\n            if rule.skipped { r2Failures.append(\"\\(id) skipped in B\") } else if !rule.passes { r2Failures.append(\"\\(id) fails in B\") }\n        }\n        var moves: [String] = []\n        for set in [GamingSet.unknown, .generic] {\n            let ra = guardReading(gamingA, set)\n            let rb = guardReading(gamingB, set)\n            let gateMove = abs(rb.largest - ra.largest)\n            let openMove = abs(rb.open - ra.open)\n            reported[\"R2 \\(set.rawValue): largest gate B − A\"] = Float(rb.largest - ra.largest)\n            reported[\"R2 \\(set.rawValue): every Thread open B − A\"] = Float(rb.open - ra.open)\n            if gateMove > 0.05 + 1e-9 { r2Failures.append(String(format: \"%@: the largest gate moved %.3f\", set.rawValue, gateMove)) }\n            if openMove > 0.05 + 1e-9 { r2Failures.append(String(format: \"%@: the all-asked rate moved %.0f points\", set.rawValue, openMove * 100)) }\n            moves.append(String(format: \"%@ largest gate %.3f → %.3f, all asked %.0f%% → %.0f%%\", set.rawValue, ra.largest, rb.largest, ra.open * 100, rb.open * 100))\n        }\n        if !consistent { r2Failures.append(contentsOf: setup) }\n        rules.append(BenchRule(\n            id: \"R2 the guards hold in B\", passes: r2Failures.isEmpty,\n            detail: moves.joined(separator: \"; \") + (r2Failures.isEmpty ? \"\" : \"; \" + r2Failures.joined(separator: \"; \"))))\n\n        // R3.\n        let missing = sessions.filter { !$0.verified }\n        let memory = sessions.reduce(0) { $0 + ($1.issues[\"memory\"] ?? 0) }\n        var other: [String: Int] = [:]\n        for session in sessions { for (check, count) in session.issues where check != \"memory\" { other[check, default: 0] += count } }\n        let r3 = !sessions.isEmpty && missing.isEmpty && memory == 0\n        var detail = \"\\(sessions.count - missing.count) of \\(sessions.count) B sessions verified; \\(memory) memory-recursion issues\"\n        if !missing.isEmpty { detail += \"; no verify report for \" + missing.map { URL(fileURLWithPath: $0.session).lastPathComponent }.joined(separator: \", \") + \" (run braid verify on it)\" }\n        if !other.isEmpty { detail += \"; other checks: \" + other.sorted { $0.key < $1.key }.map { \"\\($0.key) \\($0.value)\" }.joined(separator: \", \") }\n        rules.append(BenchRule(id: \"R3 the clamp held\", passes: r3, detail: detail))\n\n        // Trace is gate-independent: A's and B's readings must be the same.\n        var largest: Float = 0\n        for (x, y) in zip(traceA.texts, traceB.texts) {\n            for (u, v) in zip(x.readings, y.readings) where u.thread == v.thread { largest = max(largest, abs(u.trace - v.trace)) }\n        }\n        reported[\"trace readings: largest |A − B|\"] = largest\n\n        let failed = rules.filter { !$0.passes }.map(\\.id)\n        let summary = failed.isEmpty ? \"R1 to R3 hold: by the owner's rule the entropy path takes over steering and the shadow β4 is deleted (to be applied on main)\"\n            : \"failed: \\(failed.joined(separator: \", \")); the live gate stays memory-only and the shadow β4 stays logged\"\n        return BenchVerdict(rules: rules, reported: reported, summary: summary)\n    }\n}\n"},{"path":"Sources/BraidKit/Tools/Bench/StitchedBench.swift","lines":302,"bytes":17581,"header":{"lines":[1,20],"what":[8,16],"pin":[17,19],"in":null,"out":null},"marks":[[242,"The rule (pure)"]],"first":1596,"scopes":[["E","StitchedSet",null,"public",25,25,[25,65],36,null,-1,0,["withheld","withheldShuffled","control","unseen","unrelated"]],["S","StitchedReading",null,"public",39,39,[39,60],60,[38,38],-1,0],["i","init",["thread","detector","labels","trace","hlm","hknn","lift"],"public",51,51,[51,128],59,null,1,0],["S","StitchedText",null,"public",62,62,[62,57],81,null,-1,0],["i","init",["set","label","owner","document","tokens","readings"],"public",71,71,[71,126],78,null,3,0],["f","reading",["_"],"public",80,80,[80,62],80,null,3,8],["S","StitchedSizes",null,"public",83,83,[83,58],94,null,-1,0],["i","init",[],"public",93,93,[93,18],93,null,6,8],["S","StitchedReport",null,"public",96,96,[96,48],113,null,-1,0],["E","StitchedBench",null,"public",115,115,[115,26],302,null,-1,0,[]],["f","withheldThread",["in","named"],"public static",121,121,[121,105],134,[120,120],9,0],["f","run",["braid","world","sizes","thread","progress"],"public static",136,136,[137,89],161,null,9,0],["S","Text",null,"",163,163,[163,16],169,null,9,0],["f","buildTexts",["world","withheldThread","withheld","others","tokenizer","paragraphBreak","sizes"],"static",173,173,[174,84],212,[171,172],9,0],["f","fits",["_"],"",176,176,[176,49],176,null,13,12],["f","readings",["_","names","commons","settings"],"public static",215,215,[215,137],231,[214,214],9,0],["f","rescore",["_"],"public static",233,233,[233,75],240,null,9,0],["f","evaluate",["texts","withheldThread"],"public static",247,247,[247,100],301,[244,246],9,0],["f","of",["_"],"",248,248,[248,57],248,null,17,12],["f","detector",["_"],"",249,249,[249,57],249,null,17,12],["f","pct",["_"],"",251,251,[251,44],251,null,17,12],["f","num",["_"],"",252,252,[252,45],252,null,17,12]],"text":"//\n//  StitchedBench.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid bench stitched`: whether the trajectory module's stitched signature catches what a\n//        Thread absorbed parametrically that its index does not support. The Thread trains on every\n//        document but leaves P, a seeded fifth of them (`braid thread create … --withhold 0.2`), out\n//        of its index. Reading P its reed is sure (H_lm far below the commons') while its retrieval\n//        stays spread and its lift over the commons stays high. D = the share of positions from 24\n//        inside a stitched run: H_lm,t ≤ 0.5·H_lm,c ∧ H_knn,t ≥ 0.5·ln 16 ∧ lift ≥ ln 2 for ≥ 8\n//        positions. Nulls: its unfed documents in its own voice (N1), other Threads' documents and\n//        generic prose (N2). Control: its indexed held documents (C). P with its sentences shuffled\n//        is reported.\n//  PIN:  Rules fixed before any numbers (the plan's bench table, S1–S3). D is read on the withheld\n//        Thread; every Thread's D is kept. Texts are scored prompt-only with every strand asked and\n//        the session log kept. `evaluate` is pure over the saved readings.\n//\n\nimport BraidCore\nimport Foundation\n\npublic enum StitchedSet: String, Codable, Sendable, CaseIterable {\n    /// P: documents the Thread trained on but did not index.\n    case withheld\n    /// P with its sentences reordered so none keeps its successor (reported).\n    case withheldShuffled\n    /// C: the Thread's indexed held documents.\n    case control\n    /// N1: the Thread's unfed documents, in its own voice.\n    case unseen\n    /// N2: other Threads' held documents, and generic prose.\n    case unrelated\n}\n\n/// One Thread's reading of one text, from position `from` on.\npublic struct StitchedReading: Codable, Sendable, Equatable {\n    public var thread: String\n    /// D: the share of positions inside a stitched run.\n    public var detector: Float\n    /// The share of positions by the module's label (retrieval, stitched, unknown, commons, silent).\n    public var labels: [String: Float]\n    /// Means: the Thread's trace, its H_lm and H_knn, and its lift over the commons (ln p_t − ln p_c).\n    public var trace: Float\n    public var hlm: Float?\n    public var hknn: Float\n    public var lift: Float?\n\n    public init(thread: String, detector: Float, labels: [String: Float], trace: Float, hlm: Float?, hknn: Float, lift: Float?) {\n        self.thread = thread\n        self.detector = detector\n        self.labels = labels\n        self.trace = trace\n        self.hlm = hlm\n        self.hknn = hknn\n        self.lift = lift\n    }\n}\n\npublic struct StitchedText: Codable, Sendable, Equatable {\n    public var set: StitchedSet\n    public var label: String\n    /// Whose document it is (nil for generic prose).\n    public var owner: String?\n    public var document: String?\n    public var tokens: Int\n    public var readings: [StitchedReading]\n\n    public init(set: StitchedSet, label: String, owner: String?, document: String?, tokens: Int, readings: [StitchedReading]) {\n        self.set = set\n        self.label = label\n        self.owner = owner\n        self.document = document\n        self.tokens = tokens\n        self.readings = readings\n    }\n\n    public func reading(_ thread: String) -> StitchedReading? { readings.first { $0.thread == thread } }\n}\n\npublic struct StitchedSizes: Codable, Sendable, Equatable {\n    /// C and N1 texts.\n    public var perNode = 20\n    /// N2 texts per other Thread (beside the four generic passages).\n    public var unrelatedPerThread = 10\n    /// A document is read whole up to `maxTokens`, and only when it has at least `minTokens`.\n    public var minTokens = 64\n    public var maxTokens = 256\n    public var seed: UInt64 = 42\n\n    public init() {}\n}\n\npublic struct StitchedReport: Codable, Sendable {\n    public var bench = \"stitched\"\n    public var createdAt: Date\n    public var dataset: String\n    public var threads: [String: String]\n    public var gate: GateSettings\n    public var module: ModuleSettings\n    /// The Thread that trained on P but did not index it, and P.\n    public var withheldThread: String\n    public var withheld: [String]\n    public var from: Int\n    public var sizes: StitchedSizes\n    public var texts: [StitchedText]\n    public var rules: [BenchRule]\n    public var reported: [String: Float]\n    public var summary: String\n    public var sessions: [String]? = nil\n}\n\npublic enum StitchedBench {\n    public static let from = TraceBench.from\n    public static let fires: Float = 0.40\n    public static let silent: Float = 0.10\n\n    /// The Thread of `braid` whose index withholds documents (the named one, when several do).\n    public static func withheldThread(in braid: BenchBraid, named: String? = nil) throws -> LoadedThread {\n        let withholding = braid.threads.filter { !($0.node.index?.info.excluded ?? []).isEmpty }\n        if let named {\n            guard let thread = withholding.first(where: { $0.info.name == named }) else {\n                throw BraidFailure.usage(\"thread \\(named) withholds nothing from its index\", hint: \"create one: braid thread create <name> --corpus … --withhold 0.2\")\n            }\n            return thread\n        }\n        guard let thread = withholding.first else {\n            throw BraidFailure.usage(\"no Thread in the braid withholds documents from its index\",\n                                     hint: \"create one with braid thread create <name> --corpus dataset:<name>#<node> --limit 40 --withhold 0.2, and pass it in --threads\")\n        }\n        return thread\n    }\n\n    public static func run(braid: BenchBraid, world: BenchWorld, sizes: StitchedSizes = StitchedSizes(), thread named: String? = nil,\n                           progress: ((String) -> Void)? = nil) throws -> StitchedReport {\n        let holder = try withheldThread(in: braid, named: named)\n        let name = holder.info.name\n        let withheld = Set(holder.node.index?.info.excluded ?? [])\n        let threads = try braid.benchThreads(world: world) { progress?(\"warning: \\($0)\") }\n        guard let own = threads.first(where: { $0.name == name }) else { throw BraidFailure.data(\"thread \\(name) is not in the braid\") }\n        let texts = buildTexts(world: world, withheldThread: own, withheld: withheld, others: threads.filter { $0.name != name },\n                               tokenizer: braid.tokenizer, paragraphBreak: braid.tokenizer.paragraphBreak, sizes: sizes)\n        progress?(\"\\(name) withholds \\(withheld.count) documents; texts: \" + StitchedSet.allCases.map { set in \"\\(set.rawValue) \\(texts.filter { $0.set == set }.count)\" }.joined(separator: \" · \"))\n        try braid.keepSession()\n        defer { braid.finishSession() }\n        let module = braid.settings.module ?? ModuleSettings()\n        var results: [StitchedText] = []\n        for (i, text) in texts.enumerated() {\n            if i % 20 == 0 { progress?(\"scoring \\(i)/\\(texts.count)\") }\n            let generation = try braid.score(text.tokens)\n            results.append(StitchedText(set: text.set, label: text.label, owner: text.owner, document: text.document, tokens: text.tokens.count,\n                                        readings: readings(generation, names: braid.names, commons: braid.commonsIndex, settings: module)))\n            if i % 8 == 7 { braid.relax() }\n        }\n        let verdict = evaluate(texts: results, withheldThread: name)\n        return StitchedReport(createdAt: BenchFormat.wholeSecond(), dataset: world.name, threads: braid.threadRecords, gate: braid.settings.gate, module: module,\n                              withheldThread: name, withheld: withheld.sorted(), from: from, sizes: sizes, texts: results, rules: verdict.rules,\n                              reported: verdict.reported, summary: verdict.summary, sessions: braid.sessions.map(\\.path))\n    }\n\n    struct Text {\n        var set: StitchedSet\n        var label: String\n        var owner: String?\n        var document: String?\n        var tokens: [Int32]\n    }\n\n    /// P, P shuffled, C, N1 and N2, each document read as its Thread's index reads it (partitions\n    /// joined by the break), whole up to `maxTokens`, when it has at least `minTokens`.\n    static func buildTexts(world: BenchWorld, withheldThread own: BenchThread, withheld: Set<String>, others: [BenchThread], tokenizer: any Tokenizing,\n                           paragraphBreak: [Int32], sizes: StitchedSizes) -> [Text] {\n        var rng = SplitMix64(seed: sizes.seed)\n        func fits(_ tokens: [Int32]) -> [Int32]? { tokens.count >= sizes.minTokens ? Array(tokens.prefix(sizes.maxTokens)) : nil }\n        let documents = world.corpora[own.node]?.documents ?? []\n        var texts: [Text] = []\n        for document in documents where withheld.contains(document.id) && own.present.contains(document.id) {\n            let (tokens, units) = BenchTexts.split(document, tokenizer: tokenizer, paragraphBreak: paragraphBreak)\n            guard let read = fits(tokens) else { continue }\n            texts.append(Text(set: .withheld, label: \"\\(own.name) · \\(document.name) (withheld)\", owner: own.name, document: document.id, tokens: read))\n            if let units, let order = BenchTexts.shuffled(units, rng: &rng), let shuffled = fits(order.flatMap { $0 }) {\n                texts.append(Text(set: .withheldShuffled, label: \"\\(own.name) · \\(document.name) (withheld, shuffled)\", owner: own.name, document: document.id, tokens: shuffled))\n            }\n        }\n        var control = 0\n        for document in documents where control < sizes.perNode && own.present.contains(document.id) && !withheld.contains(document.id) {\n            guard let read = fits(BenchTexts.split(document, tokenizer: tokenizer, paragraphBreak: paragraphBreak).tokens) else { continue }\n            texts.append(Text(set: .control, label: \"\\(own.name) · \\(document.name) (indexed)\", owner: own.name, document: document.id, tokens: read))\n            control += 1\n        }\n        var unseen = 0\n        for document in BenchTexts.exclusive(documents, crosslinks: world.crosslinks) where unseen < sizes.perNode && !own.present.contains(document.id) {\n            guard let read = fits(BenchTexts.split(document, tokenizer: tokenizer, paragraphBreak: paragraphBreak).tokens) else { continue }\n            texts.append(Text(set: .unseen, label: \"\\(own.name) · \\(document.name) (unfed)\", owner: own.name, document: document.id, tokens: read))\n            unseen += 1\n        }\n        for other in others where other.node != own.node {\n            var count = 0\n            for document in BenchTexts.exclusive(world.corpora[other.node]?.documents ?? [], crosslinks: world.crosslinks)\n            where count < sizes.unrelatedPerThread && other.present.contains(document.id) {\n                guard let read = fits(BenchTexts.split(document, tokenizer: tokenizer, paragraphBreak: paragraphBreak).tokens) else { continue }\n                texts.append(Text(set: .unrelated, label: \"\\(other.name) · \\(document.name)\", owner: other.name, document: document.id, tokens: read))\n                count += 1\n            }\n        }\n        for (i, passage) in BenchTexts.generic.enumerated() {\n            texts.append(Text(set: .unrelated, label: \"generic \\(i + 1)\", owner: nil, document: nil, tokens: Array(tokenizer.encode(passage).prefix(sizes.maxTokens))))\n        }\n        return texts\n    }\n\n    /// Every Thread's reading of one scoring: the module over its series, from position `from`.\n    public static func readings(_ generation: Generation, names: [String], commons: Int?, settings: ModuleSettings) -> [StitchedReading] {\n        let series = TrajectoryModule.series(generation.steps, commons: commons)\n        return names.indices.compactMap { t -> StitchedReading? in\n            guard t != commons, t < series.count else { return nil }\n            let s = series[t]\n            let all = TrajectoryModule.readAll(s, settings: settings)\n            let tail = Array(all.indices.dropFirst(from))\n            var labels: [String: Float] = [:]\n            for i in tail { labels[all[i].label.rawValue, default: 0] += 1 }\n            if !tail.isEmpty { for key in labels.keys { labels[key]! /= Float(tail.count) } }\n            let hlm = tail.compactMap { s.hlm[$0] }\n            let lift = tail.compactMap { s.lift[$0] }\n            return StitchedReading(thread: names[t], detector: Float(TrajectoryModule.detectorScore(all, from: from)), labels: labels,\n                                   trace: Float(Stats.mean(tail.map { Double(s.trace[$0]) })), hlm: hlm.isEmpty ? nil : Float(Stats.mean(hlm)),\n                                   hknn: Float(Stats.mean(tail.map { s.hknn[$0] })), lift: lift.isEmpty ? nil : Float(Stats.mean(lift)))\n        }\n    }\n\n    public static func rescore(_ report: StitchedReport) -> StitchedReport {\n        var rescored = report\n        let verdict = evaluate(texts: report.texts, withheldThread: report.withheldThread)\n        rescored.rules = verdict.rules\n        rescored.reported = verdict.reported\n        rescored.summary = verdict.summary\n        return rescored\n    }\n\n    // MARK: - The rule (pure)\n\n    /// Read on the withheld Thread's D. S1: D ≥ 0.40 on ≥ 90% of P; D ≤ 0.10 on ≥ 90% of the nulls\n    /// (N1 ∪ N2); AUROC (P against the nulls) ≥ 0.95. S2: the control is labelled retrieval, D ≤ 0.10\n    /// on ≥ 95% of C. S3: P against C, Welch's z ≥ 3 and AUROC ≥ 0.95 (z against the nulls reported).\n    public static func evaluate(texts: [StitchedText], withheldThread name: String) -> BenchVerdict {\n        func of(_ sets: [StitchedSet]) -> [StitchedText] { texts.filter { sets.contains($0.set) } }\n        func detector(_ sets: [StitchedSet]) -> [Double] { of(sets).compactMap { $0.reading(name).map { Double($0.detector) } } }\n        let share = BenchFormat.share\n        func pct(_ value: Double) -> String { BenchFormat.pct(value) }\n        func num(_ value: Double?) -> String { BenchFormat.num(value) }\n        let p = detector([.withheld])\n        let nulls = detector([.unseen, .unrelated])\n        let c = detector([.control])\n        var rules: [BenchRule] = []\n        var reported: [String: Float] = [:]\n\n        let fires = share(p.map { $0 >= Double(Self.fires) })\n        let quiet = share(nulls.map { $0 <= Double(silent) })\n        let separation = BenchFormat.auroc(p, nulls)\n        rules.append(BenchRule(\n            id: \"S1 stitched, not unseen\", passes: !p.isEmpty && !nulls.isEmpty && fires >= 0.9 && quiet >= 0.9 && (separation ?? 0) >= 0.95,\n            detail: \"D ≥ 0.40 on \\(pct(fires)) of \\(p.count) withheld (needs 90%); ≤ 0.10 on \\(pct(quiet)) of \\(nulls.count) nulls (needs 90%); AUROC \\(num(separation)) (needs 0.95)\"))\n        let controlQuiet = share(c.map { $0 <= Double(silent) })\n        let retrieval = Stats.mean(of([.control]).compactMap { $0.reading(name).map { Double($0.labels[\"retrieval\"] ?? 0) } })\n        rules.append(BenchRule(\n            id: \"S2 the control is retrieval\", passes: !c.isEmpty && controlQuiet >= 0.95,\n            detail: \"D ≤ 0.10 on \\(pct(controlQuiet)) of \\(c.count) indexed held documents (needs 95%); positions labelled retrieval \\(pct(retrieval))\"))\n        let z = Stats.welchZ(p, c)\n        let pc = BenchFormat.auroc(p, c)\n        rules.append(BenchRule(\n            id: \"S3 withheld against indexed\", passes: (z ?? 0) >= 3 && (pc ?? 0) >= 0.95,\n            detail: \"Welch's z \\(num(z)) (needs 3), AUROC \\(num(pc)) (needs 0.95), withheld mean D \\(num(Stats.mean(p))) against indexed \\(num(Stats.mean(c)))\"))\n\n        if let zNulls = Stats.welchZ(p, nulls) { reported[\"S3 Welch z, withheld against the nulls\"] = Float(zNulls) }\n        let shuffled = detector([.withheldShuffled])\n        reported[\"withheld, shuffled: D ≥ 0.40\"] = Float(share(shuffled.map { $0 >= Double(Self.fires) }))\n        for set in StitchedSet.allCases {\n            let mine = of([set]).compactMap { $0.reading(name) }\n            guard !mine.isEmpty else { continue }\n            reported[\"\\(set.rawValue): mean D\"] = Float(Stats.mean(mine.map { Double($0.detector) }))\n            reported[\"\\(set.rawValue): mean trace\"] = Float(Stats.mean(mine.map { Double($0.trace) }))\n            reported[\"\\(set.rawValue): mean H_knn\"] = Float(Stats.mean(mine.map { Double($0.hknn) }))\n            let hlm = mine.compactMap(\\.hlm)\n            if !hlm.isEmpty { reported[\"\\(set.rawValue): mean H_lm\"] = Float(Stats.mean(hlm.map(Double.init))) }\n            let lift = mine.compactMap(\\.lift)\n            if !lift.isEmpty { reported[\"\\(set.rawValue): mean lift over the commons\"] = Float(Stats.mean(lift.map(Double.init))) }\n            for label in [\"retrieval\", \"stitched\", \"unknown\", \"commons\"] {\n                reported[\"\\(set.rawValue): positions labelled \\(label)\"] = Float(Stats.mean(mine.map { Double($0.labels[label] ?? 0) }))\n            }\n        }\n        // Any Thread's signature on the nulls, not only the withheld Thread's.\n        let anyThread = of([.unseen, .unrelated]).map { text in Double(text.readings.map(\\.detector).max() ?? 0) }\n        reported[\"nulls: every Thread's D ≤ 0.10\"] = Float(share(anyThread.map { $0 <= Double(silent) }))\n\n        let failed = rules.filter { !$0.passes }.map(\\.id)\n        let summary = failed.isEmpty ? \"S1 to S3 pass on \\(name)\"\n            : \"failed: \\(failed.joined(separator: \", \")); until S1 to S3 pass, the memorisation measure is a coverage lower bound\"\n        return BenchVerdict(rules: rules, reported: reported, summary: summary)\n    }\n}\n"},{"path":"Sources/BraidKit/Tools/Bench/TraceBench.swift","lines":289,"bytes":16606,"header":{"lines":[1,17],"what":[8,14],"pin":[15,16],"in":null,"out":null},"marks":[[217,"The rule (pure)"]],"first":1618,"scopes":[["S","TraceReading",null,"public",23,23,[23,57],52,[22,22],-1,0],["i","init",["thread","trace","longest","partitionRun","wireLongest","meanPknn","meanBest","holderShare","shadowHolderShare"],"public",40,40,[41,76],51,null,0,0],["S","TraceTextResult",null,"public",54,54,[54,60],77,null,-1,0],["i","init",["kind","label","owner","near","tokens","answerTokens","readings"],"public",63,63,[63,141],71,null,2,0],["f","reading",["_"],"public",73,73,[73,60],76,null,2,0],["S","TraceArmReading",null,"public",81,81,[81,60],87,[79,80],-1,0],["S","TraceReport",null,"public",89,89,[89,45],108,null,-1,0],["E","TraceBench",null,"public",110,110,[110,23],289,null,-1,0,[]],["f","run",["braid","world","sizes","progress"],"public static",117,117,[117,166],137,null,7,0],["f","rescore",["_"],"public static",140,140,[140,69],148,[139,139],7,0],["f","result",["_","generation","names","commons","eos","documentOfRow"],"public static",153,153,[153,170],191,[150,152],7,0],["f","arms",["texts"],"public static",194,194,[194,75],215,[193,193],7,0],["f","pooled",["_","set","of"],"",195,195,[195,119],207,null,11,4],["f","evaluate",["texts"],"public static",223,223,[223,74],288,[219,222],7,0],["f","of",["_"],"",224,224,[224,63],224,null,13,12],["f","pct",["_"],"",226,226,[226,44],226,null,13,12]],"text":"//\n//  TraceBench.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: `braid bench trace`: whether a Thread's trace tells its own text from a pastiche of it, and\n//        what the holder earns on told and source answers under the live gate and under the shadow β4.\n//        Every text is scored through the cluster with every Thread asked and nothing generated; per\n//        Thread per text: the mean trace from token 24, the longest chain, the token-local baselines,\n//        and its share of the answer tokens (live and shadow, from the same pass). Rules T1 to T3 are\n//        RaoLM's, fixed before any numbers (RaoLM Docs/BRAID.md, \"Choosing the trajectory\"); the arms\n//        carry no threshold. Manner is gone, so M1 to M4 are not here.\n//  PIN:  `evaluate` is pure over the saved readings, so `--rescore` re-applies the rules to a report\n//        without a model. Nothing is written to a node.\n//\n\nimport BraidCore\nimport Foundation\n\n/// One Thread's reading of one text.\npublic struct TraceReading: Codable, Sendable, Equatable {\n    public var thread: String\n    /// Mean trace from token `TraceBench.from` on.\n    public var trace: Float\n    /// The longest chain anywhere in the text, and the longest run that stayed inside one partition.\n    public var longest: Int\n    public var partitionRun: Int\n    /// The longest chain the hits alone show (any rank, no bridges).\n    public var wireLongest: Int\n    /// Token-local baselines from `from` on: the retrieval mass on the token that came, and the best cosine.\n    public var meanPknn: Float\n    public var meanBest: Float\n    /// This Thread's mean share of the text's answer tokens under the live gate and under the shadow\n    /// β4 (nil for a text without answers). The owner's reading is the holder's share.\n    public var holderShare: Float?\n    public var shadowHolderShare: Float?\n\n    public init(thread: String, trace: Float, longest: Int, partitionRun: Int, wireLongest: Int, meanPknn: Float, meanBest: Float,\n                holderShare: Float? = nil, shadowHolderShare: Float? = nil) {\n        self.thread = thread\n        self.trace = trace\n        self.longest = longest\n        self.partitionRun = partitionRun\n        self.wireLongest = wireLongest\n        self.meanPknn = meanPknn\n        self.meanBest = meanBest\n        self.holderShare = holderShare\n        self.shadowHolderShare = shadowHolderShare\n    }\n}\n\npublic struct TraceTextResult: Codable, Sendable, Equatable {\n    public var kind: BenchTextKind\n    public var label: String\n    public var owner: String?\n    public var near: String?\n    public var tokens: Int\n    public var answerTokens: Int\n    public var readings: [TraceReading]\n\n    public init(kind: BenchTextKind, label: String, owner: String?, near: String?, tokens: Int, answerTokens: Int, readings: [TraceReading]) {\n        self.kind = kind\n        self.label = label\n        self.owner = owner\n        self.near = near\n        self.tokens = tokens\n        self.answerTokens = answerTokens\n        self.readings = readings\n    }\n\n    public func reading(_ thread: String?) -> TraceReading? {\n        guard let thread else { return nil }\n        return readings.first { $0.thread == thread }\n    }\n}\n\n/// A Thread's share of told and source answer tokens under the live gate and under the shadow β4,\n/// pooled over tokens. No threshold.\npublic struct TraceArmReading: Codable, Sendable, Equatable {\n    public var set: String\n    public var texts: Int\n    public var answerTokens: Int\n    public var live: Float?\n    public var shadow: Float?\n}\n\npublic struct TraceReport: Codable, Sendable {\n    public var bench = \"trace\"\n    public var createdAt: Date\n    public var dataset: String\n    /// Per Thread, `v<version>/<index sha256>`.\n    public var threads: [String: String]\n    public var documents: [String: Int]\n    public var memorised: [String: Float]\n    public var rule: TraceRule\n    public var from: Int\n    public var sizes: BenchTextSizes\n    public var texts: [TraceTextResult]\n    public var rules: [BenchRule]\n    public var arms: [TraceArmReading]\n    public var reported: [String: Float]\n    public var summary: String\n    /// The gate the texts were scored under (κ included) and the session log the scoring wrote.\n    public var gate: GateSettings? = nil\n    public var sessions: [String]? = nil\n}\n\npublic enum TraceBench {\n    /// A text's value is its mean from this token on.\n    public static let from = 24\n    /// A holder traces its own text at least this; anyone else at most `low`.\n    public static let holderFloor: Float = 0.40\n    public static let low: Float = 0.10\n\n    public static func run(braid: BenchBraid, world: BenchWorld, sizes: BenchTextSizes = BenchTextSizes(), progress: ((String) -> Void)? = nil) throws -> TraceReport {\n        let threads = try braid.benchThreads(world: world) { progress?(\"warning: \\($0)\") }\n        let texts = BenchTexts.build(world: world, threads: threads, tokenizer: braid.tokenizer, byteOffsets: braid.tokenizer.byteOffsets,\n                                     paragraphBreak: braid.tokenizer.paragraphBreak, sizes: sizes)\n        progress?(\"texts: \" + BenchTexts.census(texts))\n        let documentOfRow = braid.documentOfRow\n        try braid.keepSession()\n        defer { braid.finishSession() }\n        var results: [TraceTextResult] = []\n        let started = Date()\n        for (i, text) in texts.enumerated() {\n            if i % 25 == 0 { progress?(String(format: \"scoring %d/%d (%.0f s)\", i, texts.count, Date().timeIntervalSince(started))) }\n            let generation = try braid.score(text.tokens)\n            results.append(result(text, generation: generation, names: braid.names, commons: braid.commonsIndex, eos: braid.tokenizer.eos, documentOfRow: documentOfRow))\n            if i % 8 == 7 { braid.relax() }\n        }\n        let verdict = evaluate(texts: results)\n        return TraceReport(createdAt: BenchFormat.wholeSecond(), dataset: world.name, threads: braid.threadRecords, documents: braid.documents, memorised: braid.memorised,\n                           rule: braid.settings.trace, from: from, sizes: sizes, texts: results, rules: verdict.rules, arms: arms(texts: results),\n                           reported: verdict.reported, summary: verdict.summary, gate: braid.settings.gate, sessions: braid.sessions.map(\\.path))\n    }\n\n    /// The rules re-applied to a saved report's readings.\n    public static func rescore(_ report: TraceReport) -> TraceReport {\n        var rescored = report\n        let verdict = evaluate(texts: report.texts)\n        rescored.rules = verdict.rules\n        rescored.reported = verdict.reported\n        rescored.summary = verdict.summary\n        rescored.arms = arms(texts: report.texts)\n        return rescored\n    }\n\n    /// One text's readings from its scoring. Step j of the generation holds token j of eos ‖ text (text\n    /// position j − 1), and per strand the chain state that expected it, its retrieval mass on it, and\n    /// its share of it under the live gate and under the shadow.\n    public static func result(_ text: BenchText, generation: Generation, names: [String], commons: Int?, eos: Int32, documentOfRow: [[Int32: String]]) -> TraceTextResult {\n        let answerPositions = Set(text.answers.flatMap { $0.start..<($0.start + $0.count) })\n        var readings: [TraceReading] = []\n        var answerTokens = 0\n        for t in names.indices where t != commons {\n            var traces: [Double] = [], pknn: [Double] = [], best: [Double] = []\n            var longest = 0\n            var partitionRun = 0\n            var share = 0.0, shadow = 0.0\n            var counted = 0\n            // hits[p]: the hits of the emission at position p (they expect token p + 1), for the wire audit.\n            var hits = [[Hit]](repeating: [], count: text.tokens.count + 1)\n            for step in generation.steps {\n                guard let records = step.threads, t < records.count else { continue }\n                let record = records[t]\n                let p = step.index - 1\n                if p >= from {\n                    traces.append(Double(record.trace?.trace ?? 0))\n                    pknn.append(Double(record.pknn))\n                    best.append(Double(record.hits.first?.score ?? 0))\n                }\n                longest = max(longest, record.trace?.length ?? 0)\n                partitionRun = max(partitionRun, record.trace?.partitionRun ?? 0)\n                if answerPositions.contains(p) {\n                    share += Double(record.share)\n                    shadow += Double(record.shadowShare)\n                    counted += 1\n                }\n                if p >= 0, p < hits.count { hits[p] = record.hits }\n            }\n            let wire = TraceAudit.wireLengths(tokens: [eos] + text.tokens, hits: hits, documentOfRow: t < documentOfRow.count ? documentOfRow[t] : [:]).max() ?? 0\n            answerTokens = max(answerTokens, counted)\n            readings.append(TraceReading(thread: names[t], trace: Float(Stats.mean(traces)), longest: longest, partitionRun: partitionRun, wireLongest: wire,\n                                         meanPknn: Float(Stats.mean(pknn)), meanBest: Float(Stats.mean(best)),\n                                         holderShare: counted > 0 ? Float(share / Double(counted)) : nil,\n                                         shadowHolderShare: counted > 0 ? Float(shadow / Double(counted)) : nil))\n        }\n        return TraceTextResult(kind: text.kind, label: text.label, owner: text.owner, near: text.near, tokens: text.tokens.count, answerTokens: answerTokens, readings: readings)\n    }\n\n    /// The holder's (and the near Thread's) share of told and source answer tokens, pooled over tokens.\n    public static func arms(texts: [TraceTextResult]) -> [TraceArmReading] {\n        func pooled(_ kinds: [BenchTextKind], set: String, of strand: (TraceTextResult) -> String?) -> TraceArmReading {\n            var live = 0.0, shadow = 0.0\n            var tokens = 0, count = 0\n            for text in texts where kinds.contains(text.kind) && text.answerTokens > 0 {\n                guard let reading = text.reading(strand(text)), let l = reading.holderShare, let s = reading.shadowHolderShare else { continue }\n                live += Double(l) * Double(text.answerTokens)\n                shadow += Double(s) * Double(text.answerTokens)\n                tokens += text.answerTokens\n                count += 1\n            }\n            return TraceArmReading(set: set, texts: count, answerTokens: tokens, live: tokens > 0 ? Float(live / Double(tokens)) : nil,\n                                   shadow: tokens > 0 ? Float(shadow / Double(tokens)) : nil)\n        }\n        return [\n            pooled([.told, .source], set: \"holder · told+source\", of: \\.owner),\n            pooled([.told], set: \"holder · told\", of: \\.owner),\n            pooled([.source], set: \"holder · source\", of: \\.owner),\n            pooled([.told], set: \"near · told\", of: \\.near),\n            pooled([.source], set: \"near · source\", of: \\.near),\n        ]\n    }\n\n    // MARK: - The rule (pure)\n\n    /// T1: the holder traces its own document as written (≥ 0.40 on ≥ 90% of held), not the same\n    /// sentences reordered or a collage (≤ 0.10 on ≥ 90%), AUROC ≥ 0.95. T2: on told and source texts\n    /// the holder ≥ 0.40 on ≥ 90%, near and other Threads ≤ 0.10 on ≥ 90%. T3: on voice, voice-shuffled\n    /// and generic texts every Thread ≤ 0.10 on ≥ 95% of texts and each class's mean ≤ 0.05.\n    public static func evaluate(texts: [TraceTextResult]) -> BenchVerdict {\n        func of(_ kinds: [BenchTextKind]) -> [TraceTextResult] { texts.filter { kinds.contains($0.kind) } }\n        let share = BenchFormat.share\n        func pct(_ value: Double) -> String { BenchFormat.pct(value) }\n        var rules: [BenchRule] = []\n        var reported: [String: Float] = [:]\n\n        // T1: arc, not phrase.\n        let held = of([.held]).compactMap { $0.reading($0.owner) }\n        let apart = of([.shuffled, .collage]).compactMap { $0.reading($0.owner) }\n        let t1Held = share(held.map { $0.trace >= holderFloor })\n        let t1Apart = share(apart.map { $0.trace <= low })\n        let t1AUROC = BenchFormat.auroc(held.map { Double($0.trace) }, apart.map { Double($0.trace) })\n        rules.append(BenchRule(\n            id: \"T1 arc, not phrase\", passes: !held.isEmpty && !apart.isEmpty && t1Held >= 0.9 && t1Apart >= 0.9 && (t1AUROC ?? 0) >= 0.95,\n            detail: \"holder ≥ 0.40 on \\(pct(t1Held)) of \\(held.count) held; ≤ 0.10 on \\(pct(t1Apart)) of \\(apart.count) shuffled and collage; AUROC \\(BenchFormat.num(t1AUROC))\"))\n        reported[\"T1 token-local: retrieval mass on the tokens, AUROC\"] = BenchFormat.auroc(held.map { Double($0.meanPknn) }, apart.map { Double($0.meanPknn) }).map(Float.init)\n        reported[\"T1 token-local: best cosine, AUROC\"] = BenchFormat.auroc(held.map { Double($0.meanBest) }, apart.map { Double($0.meanBest) }).map(Float.init)\n        reported[\"T1 held: holder mean trace\"] = Float(Stats.mean(held.map { Double($0.trace) }))\n        reported[\"T1 shuffled and collage: holder mean trace\"] = Float(Stats.mean(apart.map { Double($0.trace) }))\n        reported[\"T1 shuffled and collage: holder mean retrieval mass on the tokens\"] = Float(Stats.mean(apart.map { Double($0.meanPknn) }))\n\n        // T2: among Threads, the holder of a told or source text traces it and nobody else does.\n        let retold = of([.told, .source])\n        let holders = retold.compactMap { $0.reading($0.owner) }\n        let others = retold.flatMap { text in text.readings.filter { $0.thread != text.owner } }\n        let near = retold.compactMap { $0.reading($0.near) }\n        let t2Holders = share(holders.map { $0.trace >= holderFloor })\n        let t2Others = share(others.map { $0.trace <= low })\n        rules.append(BenchRule(\n            id: \"T2 holder among Threads\", passes: !holders.isEmpty && t2Holders >= 0.9 && t2Others >= 0.9,\n            detail: \"holder ≥ 0.40 on \\(pct(t2Holders)) of \\(holders.count) told and source; near and other ≤ 0.10 on \\(pct(t2Others)) of \\(others.count) \"\n                + \"(near alone \\(pct(share(near.map { $0.trace <= low }))))\"))\n        reported[\"T2 told and source: holder mean trace\"] = Float(Stats.mean(holders.map { Double($0.trace) }))\n        reported[\"T2 told and source: near mean trace\"] = Float(Stats.mean(near.map { Double($0.trace) }))\n\n        // T3: text in a Thread's voice that nobody holds earns no Thread a trace.\n        var t3 = true\n        var details: [String] = []\n        var falseChain = 0\n        for kind in [BenchTextKind.voice, .voiceShuffled, .generic] {\n            let group = of([kind])\n            let clean = share(group.map { $0.readings.allSatisfy { $0.trace <= low } })\n            let mean = Stats.mean(group.flatMap { $0.readings.map { Double($0.trace) } })\n            falseChain = max(falseChain, group.flatMap { $0.readings.map(\\.longest) }.max() ?? 0)\n            if group.isEmpty || clean < 0.95 || mean > 0.05 { t3 = false }\n            details.append(\"\\(kind.rawValue): every Thread ≤ 0.10 on \\(pct(clean)) of \\(group.count), mean \\(BenchFormat.num(mean))\")\n        }\n        rules.append(BenchRule(id: \"T3 voice earns nothing\", passes: t3, detail: details.joined(separator: \"; \")))\n        reported[\"T3 longest false chain (tokens)\"] = Float(falseChain)\n\n        let readings = texts.flatMap(\\.readings)\n        reported[\"wire chain ≤ node chain\"] = Float(share(readings.map { $0.wireLongest <= $0.longest }))\n        let nodeLongest = Stats.mean(readings.map { Double($0.longest) })\n        reported[\"wire chain / node chain (means)\"] = nodeLongest > 0 ? Float(Stats.mean(readings.map { Double($0.wireLongest) }) / nodeLongest) : 0\n        reported[\"held: longest chain (mean)\"] = Float(Stats.mean(held.map { Double($0.longest) }))\n        reported[\"held: longest partition-bounded run (mean)\"] = Float(Stats.mean(held.map { Double($0.partitionRun) }))\n\n        let failed = rules.filter { !$0.passes }.map(\\.id)\n        var summary = failed.isEmpty ? \"T1 to T3 pass\" : \"failed: \" + failed.joined(separator: \", \")\n        if let both = arms(texts: texts).first, both.answerTokens > 0 {\n            summary += String(format: \"; the holder's share of %d told and source answer tokens: live gate %.3f, shadow β4 %.3f (no threshold)\",\n                              both.answerTokens, both.live ?? 0, both.shadow ?? 0)\n        }\n        return BenchVerdict(rules: rules, reported: reported, summary: summary)\n    }\n}\n"},{"path":"Sources/BraidKit/Tools/Doctor/DoctorChecks.swift","lines":153,"bytes":9333,"header":{"lines":[1,14],"what":[8,12],"pin":[13,13],"in":null,"out":null},"marks":[],"first":1634,"scopes":[["S","DoctorCheck",null,"public",20,20,[20,47],33,null,-1,0],["i","init",["name","ok","detail"],"public",25,25,[25,56],29,null,0,0],["v","line",null,"public",32,32,[32,28],32,[31,31],0,8],["E","DoctorChecks",null,"public",35,35,[35,25],153,null,-1,0,[]],["f","findPack",["_","in"],"public static",37,37,[37,88],47,[36,36],3,0],["f","trunk",["pack","in"],"public static",51,51,[51,77],69,[49,50],3,0],["f","metallib",["besideExecutable"],"public static",72,72,[72,132],78,[71,71],3,0],["f","freeGB",["_"],"public static",80,80,[80,52],84,null,3,0],["f","aiiHome",["environment"],"public static",87,87,[87,110],89,[86,86],3,0],["f","aii",["environment","httpPort"],"public static",92,92,[92,142],102,[91,91],3,0],["f","aiiBlocking",["environment"],"public static",105,105,[105,121],107,[104,104],3,0],["f","run",["area","config","environment"],"public static",111,111,[112,119],152,[109,110],3,0],["f","report",["_","_"],"",114,114,[114,70],119,null,11,4]],"text":"//\n//  DoctorChecks.swift\n//  BraidKit\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The checks `braid doctor` runs and the studio's Doctor screen shows, from one place: the\n//        Metal library beside the binary, the work area and its free space, braid.toml, the pack\n//        and its tokenizer round trip, the trunk (the commons' seam, which every Thread's live\n//        version must name), the machine's AII (home, lanes, Thread health). Each check is a name,\n//        a verdict and a detail, so the CLI prints the list and the studio draws it.\n//  PIN:  A failed check says what is missing and how to fix it; nothing here writes anything.\n//\n\nimport BraidCore\nimport BraidThread\nimport Foundation\n\npublic struct DoctorCheck: Sendable, Equatable {\n    public var name: String\n    public var ok: Bool\n    public var detail: String\n\n    public init(name: String, ok: Bool, detail: String) {\n        self.name = name\n        self.ok = ok\n        self.detail = detail\n    }\n\n    /// `  ✓ name: detail`, as `braid doctor` prints it.\n    public var line: String { \"  \\(ok ? \"✓\" : \"✗\") \\(name): \\(detail)\" }\n}\n\npublic enum DoctorChecks {\n    /// The pack `braid.toml` names (by sha256, a prefix of it, or its name) among `packs/*/pack.json`; nil when none matches.\n    public static func findPack(_ reference: String, in area: WorkArea) throws -> Pack? {\n        guard FileManager.default.fileExists(atPath: area.packs.path) else { return nil }\n        let directories = try FileManager.default.contentsOfDirectory(at: area.packs, includingPropertiesForKeys: nil)\n            .filter { FileManager.default.fileExists(atPath: $0.appendingPathComponent(Pack.infoFile).path) }\n        let packs = try directories.map { ($0, try JSONCoding.read(PackInfo.self, from: $0.appendingPathComponent(Pack.infoFile))) }\n            .sorted { $0.1.createdAt < $1.1.createdAt }\n        for (directory, info) in packs where info.sha256.hasPrefix(reference.lowercased()) || info.name == reference {\n            return try Pack.load(from: directory)\n        }\n        return nil\n    }\n\n    /// The commons' trunk from the pack's record alone, no weights loaded: its seam, its size, and whether every\n    /// Thread's live version names that seam and cut, which `ThreadStore.load` will insist on.\n    public static func trunk(pack: Pack, in area: WorkArea) throws -> String {\n        let config = pack.config\n        var named = 0\n        var wrong: [String] = []\n        for info in try ThreadStore.list(in: area) {\n            guard let live = try ThreadStore.live(area.thread(info.name)) else { continue }\n            if live.seamSHA256 != pack.info.seamSHA256 {\n                wrong.append(\"\\(info.name) v\\(live.version) names seam \\(live.seamSHA256.prefix(12))\")\n            } else if live.cut != config.cut {\n                wrong.append(\"\\(info.name) v\\(live.version) is cut at \\(live.cut)\")\n            } else {\n                named += 1\n            }\n        }\n        let trunk = \"seam \\(pack.info.seamSHA256.prefix(12)): the commons' blocks \\(config.cut)–\\(config.numHiddenLayers - 1), the embedding and norm_f, \"\n            + String(format: \"%.0f MB\", Double(StorageMath(config: config).trunkBytes) / 1_000_000)\n        guard wrong.isEmpty else { throw BraidFailure.data(\"\\(trunk); not every Thread runs it: \\(wrong.joined(separator: \"; \"))\") }\n        return trunk + (named == 0 ? \"; no Thread yet\" : \"; \\(named) Thread version\\(named == 1 ? \" names\" : \"s name\") it\")\n    }\n\n    /// The Metal library beside the running binary (build-metallib.sh puts it there).\n    public static func metallib(besideExecutable executable: URL = URL(fileURLWithPath: CommandLine.arguments[0])) throws -> String {\n        let binary = executable.resolvingSymlinksInPath().deletingLastPathComponent()\n        for name in [\"mlx.metallib\", \"default.metallib\"] where FileManager.default.fileExists(atPath: binary.appendingPathComponent(name).path) {\n            return binary.appendingPathComponent(name).path\n        }\n        throw BraidFailure.configuration(\"no mlx.metallib beside \\(binary.path)\", hint: \"run ./build-metallib.sh (Scripts/cli.sh does it)\")\n    }\n\n    public static func freeGB(_ url: URL) -> String {\n        let values = try? url.resourceValues(forKeys: [.volumeAvailableCapacityKey, .volumeAvailableCapacityForImportantUsageKey])\n        let bytes = values?.volumeAvailableCapacityForImportantUsage.flatMap { $0 > 0 ? $0 : nil } ?? values?.volumeAvailableCapacity.map(Int64.init)\n        return bytes.map { String(format: \"%.0f\", Double($0) / 1_073_741_824) } ?? \"?\"\n    }\n\n    /// The machine's AII home: AII_HOME, else ~/.rao.\n    public static func aiiHome(environment: [String: String] = ProcessInfo.processInfo.environment) -> String {\n        ((environment[\"AII_HOME\"] ?? \"~/.rao\") as NSString).expandingTildeInPath\n    }\n\n    /// The machine's AII: its home, the lanes with a secret, and the Thread's health on its HTTP port.\n    public static func aii(environment: [String: String] = ProcessInfo.processInfo.environment, httpPort: Int = 47081) async throws -> String {\n        let home = aiiHome(environment: environment)\n        guard FileManager.default.fileExists(atPath: home + \"/layout.json\") else { throw BraidFailure.unavailable(\"no AII home at \\(home)\") }\n        let lanes = [\"ambient\", \"craft\", \"veil\"].filter { FileManager.default.fileExists(atPath: home + \"/secrets/\\($0)\") }\n        let request = URLRequest(url: URL(string: \"http://127.0.0.1:\\(httpPort)/health\")!, timeoutInterval: 3)\n        let (data, _) = try await URLSession.shared.data(for: request)\n        let health = String(decoding: data, as: UTF8.self)\n        guard health.contains(\"\\\"healthy\\\"\") else { throw BraidFailure.unavailable(\"Thread on \\(httpPort) is not healthy: \\(health.prefix(80))\") }\n        let stack = health.contains(\"\\\"stack\\\":\\\"proof\\\"\") ? \"proof\" : (health.contains(\"\\\"stack\\\":\\\"open\\\"\") ? \"open\" : \"?\")\n        return \"home \\(home), lanes \\(lanes.joined(separator: \"/\")), Thread healthy on \\(httpPort) (stack \\(stack))\"\n    }\n\n    /// `aii()` for synchronous callers (the CLI).\n    public static func aiiBlocking(environment: [String: String] = ProcessInfo.processInfo.environment) throws -> String {\n        try Blocking.run { try await aii(environment: environment) }\n    }\n\n    /// Every check, in the order `braid doctor` prints them. `area` is how the work area resolved\n    /// (or why it did not); `config` loads braid.toml from it.\n    public static func run(area: Result<WorkArea, Error>, config: (WorkArea) throws -> BraidConfig,\n                           environment: [String: String] = ProcessInfo.processInfo.environment) async -> [DoctorCheck] {\n        var checks: [DoctorCheck] = []\n        func report(_ name: String, _ outcome: Result<String, Error>) {\n            switch outcome {\n            case .success(let detail): checks.append(DoctorCheck(name: name, ok: true, detail: detail))\n            case .failure(let error): checks.append(DoctorCheck(name: name, ok: false, detail: \"\\(error)\"))\n            }\n        }\n        report(\"metal library\", Result { try metallib() })\n        report(\"work area\", area.map { \"\\($0.root.path) (\\(freeGB($0.root)) GB free)\" })\n        if case .success(let area) = area {\n            let loaded = Result { try config(area) }\n            report(\"braid.toml\", loaded.map { \"pack \\($0.pack?.name ?? \"none\") \\($0.pack?.sha256.prefix(12) ?? \"\")\" + ($0.attach.isEmpty ? \" · no Thread attached\" : \" · attach \\($0.attach.joined(separator: \", \"))\") })\n            if case .success(let config) = loaded, let packRecord = config.pack {\n                switch Result(catching: { try findPack(packRecord.sha256, in: area) }) {\n                case .success(let pack?):\n                    report(\"pack\", .success(\"\\(pack.info.name) loads; hashes re-derived\"))\n                    report(\"tokenizer\", Result {\n                        let tokenizer = try BraidTokenizer(folder: pack.tokenizerFolder)\n                        guard tokenizer.eos == 0 else { throw BraidFailure.data(\"eos is \\(tokenizer.eos)\") }\n                        guard tokenizer.decode(tokenizer.encode(\"Hello, braid.\")) == \"Hello, braid.\" else { throw BraidFailure.data(\"does not round-trip\") }\n                        return \"\\(tokenizer.vocabSize) tokens in \\(pack.config.vocabSize) rows, eos 0, break \\(tokenizer.paragraphBreak)\"\n                    })\n                    report(\"trunk\", Result { try trunk(pack: pack, in: area) })\n                case .success(nil): report(\"pack\", .failure(BraidFailure.missing(\"not in \\(area.packs.path)\")))\n                case .failure(let error): report(\"pack\", .failure(error))\n                }\n            }\n        }\n        do {\n            report(\"AII\", .success(try await aii(environment: environment)))\n        } catch {\n            report(\"AII\", .failure(error))\n        }\n        let demoRoot = AIIDetect.demoRoot(environment: environment)\n        let machine = await AIIDetect.status(aii: LaneAddress.machine, demoRoot: demoRoot)\n        report(\"AII contract\", Result { try AIIDetect.contract(serving: machine.health?.contract) })\n        report(\"AIIServer\", Result { try AIIDetect.server() })\n        report(\"demo AIIs\", .success(await AIIDetect.demoSummary(demoRoot: demoRoot)))\n        return checks\n    }\n}\n"}]};
